    fn require_bug769_one_line_delta_family(deck_path: &Path) -> Result<(), String> {
        let family = deck_path
            .parent()
            .ok_or_else(|| "BUG 769 record has no family directory".to_string())?;
        let members = [
            ("bug_769a.cir", ".param RVAL={76K+v(3)}"),
            ("bug_769b.cir", ".param RVAL={76K+i(v2)}"),
            ("bug_769c.cir", ".param RVAL={76K+i(c2)}"),
        ];
        let mut sources = Vec::with_capacity(members.len());
        for (file_name, expected_probe_line) in members {
            let path = family.join(file_name);
            let source = fs::read_to_string(&path).map_err(|error| {
                format!("failed to read BUG 769 family member {path:?}: {error}")
            })?;
            let lines = source.lines().map(str::to_string).collect::<Vec<_>>();
            if lines.len() != 82 {
                return Err(format!(
                    "BUG 769 family member {file_name} physical line count changed: expected 82, got {}",
                    lines.len()
                ));
            }
            if lines[68] != expected_probe_line {
                return Err(format!(
                    "BUG 769 family member {file_name} physical line 69 changed: expected {expected_probe_line:?}, got {:?}",
                    lines[68]
                ));
            }
            sources.push((file_name, lines));
        }
        for line_index in 0..82 {
            if line_index == 68 {
                continue;
            }
            let reference = &sources[0].1[line_index];
            for (file_name, lines) in &sources[1..] {
                if &lines[line_index] != reference {
                    return Err(format!(
                        "BUG 769 family must differ only at physical line 69; {file_name} differs at line {}",
                        line_index + 1
                    ));
                }
            }
        }
        Ok(())
    }

    fn observe_bug769_parameter_probe_failure(
        source: &str,
        deck_path: &Path,
        kind: XyceExpectedFailureKind,
    ) -> Result<XyceExpectedFailureObservation, String> {
        let (label, parameter_line, diagnostic, category, probe) = match kind {
            XyceExpectedFailureKind::Bug769ParameterNodeVoltage => (
                "BUG 769 node-voltage parameter",
                ".param RVAL={76K+v(3)}",
                "Node Voltage may not be used in parameter expression (RVAL): V(3)",
                XyceExpectedFailureCategory::ParameterNodeVoltage,
                "V(3)",
            ),
            XyceExpectedFailureKind::Bug769ParameterDeviceCurrent => (
                "BUG 769 device-current parameter",
                ".param RVAL={76K+i(v2)}",
                "Device Current may not be used in parameter expression (RVAL): I(V2)",
                XyceExpectedFailureCategory::ParameterDeviceCurrent,
                "I(V2)",
            ),
            XyceExpectedFailureKind::Bug769ParameterLeadCurrent => (
                "BUG 769 lead-current parameter",
                ".param RVAL={76K+i(c2)}",
                "Lead Current may not be used in parameter expression (RVAL): I(C2)",
                XyceExpectedFailureCategory::ParameterLeadCurrent,
                "I(C2)",
            ),
            _ => {
                return Err(format!(
                    "non-BUG 769 expected-failure kind passed to BUG 769 observer: {kind:?}"
                ));
            }
        };
        Self::require_bug769_one_line_delta_family(deck_path)?;
        Self::require_expected_failure_source_lines(
            label,
            source,
            82,
            &[
                (1, "UA555 Timer Circuit"),
                (66, ".ENDS"),
                (69, parameter_line),
                (71, "C1 1 0 2140P"),
                (72, "R2 3 1 {RVAL}"),
                (73, "C2 5 0 .01U"),
                (74, "X2 6 4 3 5 1 1 3 UA555"),
                (75, "V2 6 0 PULSE(0 15 0U .1U .1U 900U 1M)"),
                (78, ".TRAN 1U 5M"),
                (79, ".PRINT TRAN V(4)  V(1)  V(6)"),
                (81, ".END"),
                (82, ""),
            ],
        )?;
        Self::require_exact_syntax_failure(label, source, deck_path, 69, diagnostic)?;
        Ok(XyceExpectedFailureObservation {
            stage: XyceExpectedFailureStage::NetlistParse,
            category,
            identifiers: vec!["RVAL".to_string(), probe.to_string(), "line 69".to_string()],
        })
    }

    fn observe_bug67_behavioral_expression_failure(
        &self,
        source: &str,
        deck_path: &Path,
    ) -> Result<XyceExpectedFailureObservation, String> {
        let netlist = Self::parse_xyce_netlist(source, deck_path)
            .map_err(|err| format!("BUG 67 must parse before behavioral compilation: {err}"))?;
        if !netlist.diagnostics.is_empty() {
            return Err(format!(
                "BUG 67 parse produced unexpected diagnostics: {:?}",
                netlist.diagnostics
            ));
        }
        if netlist.elements.len() != 15
            || netlist.subcircuits.len() != 1
            || !netlist.subcircuits[0].name.eq_ignore_ascii_case("LM124N")
        {
            return Err(
                "BUG 67 must retain 15 top-level elements and one LM124N subcircuit".to_string(),
            );
        }
        let top_instances = netlist
            .elements
            .iter()
            .filter_map(|element| match &element.kind {
                ElementKind::Subcircuit { subckt_name, .. }
                    if subckt_name.eq_ignore_ascii_case("LM124N") =>
                {
                    Some(element.name.to_ascii_uppercase())
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        if top_instances != ["X1", "X2"] {
            return Err(format!(
                "BUG 67 must instantiate LM124N in exact X1, X2 order, got {top_instances:?}"
            ));
        }
        let malformed = netlist.subcircuits[0]
            .elements
            .iter()
            .filter_map(|element| match &element.kind {
                ElementKind::BehavioralCurrent { expression, .. }
                    if expression.eq_ignore_ascii_case("POLY I(V6) 300u 1") =>
                {
                    Some(element.name.to_ascii_uppercase())
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        if malformed != ["B6"] {
            return Err(format!(
                "BUG 67 must retain exactly malformed LM124N B6 expression 'POLY I(V6) 300u 1', got {malformed:?}"
            ));
        }
        let tran = Self::single_tran_analysis(&netlist)?;
        if (tran.step - 1.0e-6).abs() > 1.0e-21
            || (tran.stop - 1.0e-3).abs() > 1.0e-18
            || tran.start != Some(0.0)
            || tran
                .max_step
                .is_none_or(|max_step| (max_step - 5.0e-6).abs() > 1.0e-20)
            || tran.uic
        {
            return Err(format!("BUG 67 .TRAN tuple changed: {tran:?}"));
        }
        let print = Self::single_tran_print_output_request(source)?;
        if print.format.is_some() || print.file.is_some() || print.probes != ["V(7)", "V(8)"] {
            return Err(format!(
                "BUG 67 ordered .PRINT TRAN contract changed: {print:?}"
            ));
        }
        let flattened = crate::netlist::flatten_netlist_with_models(&netlist)
            .map_err(|err| format!("BUG 67 must flatten before behavioral compilation: {err}"))?;
        let flattened_b6 = flattened
            .elements
            .iter()
            .filter_map(|element| match &element.kind {
                ElementKind::BehavioralCurrent { expression, .. }
                    if element.name.ends_with(".B6") =>
                {
                    Some((element.name.clone(), expression.clone()))
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        if flattened_b6
            != [
                ("X1.B6".to_string(), "POLY I(X1.V6) 300u 1".to_string()),
                ("X2.B6".to_string(), "POLY I(X2.V6) 300u 1".to_string()),
            ]
        {
            return Err(format!(
                "BUG 67 flattened malformed B6 instances changed: {flattened_b6:?}"
            ));
        }

        match self.create_xyce_engine().build_circuit(&netlist) {
            Err(SimulationError::Circuit(message))
                if message.contains("Invalid behavioral expression")
                    && message.contains("POLY I(X1.V6) 300u 1")
                    && message.contains("Unknown identifier 'POLY'")
                    && message.contains("Ident(\"I\")") =>
            {
                Ok(XyceExpectedFailureObservation {
                    stage: XyceExpectedFailureStage::CircuitBuild,
                    category: XyceExpectedFailureCategory::BehavioralExpressionSyntax,
                    identifiers: vec!["X1.B6".to_string(), "X1.V6".to_string()],
                })
            }
            Err(error) => Err(format!(
                "BUG 67 produced the wrong typed circuit-build failure: {error}"
            )),
            Ok(_) => Err(
                "BUG 67 circuit built successfully; expected malformed behavioral expression"
                    .to_string(),
            ),
        }
    }

    fn observe_bug671_invalid_pwl_failure(
        &self,
        source: &str,
        deck_path: &Path,
    ) -> Result<XyceExpectedFailureObservation, String> {
        let netlist = Self::parse_xyce_netlist(source, deck_path)
            .map_err(|err| format!("BUG 671 must parse before PWL file loading: {err}"))?;
        if !netlist.diagnostics.is_empty()
            || netlist.elements.len() != 2
            || !netlist.subcircuits.is_empty()
        {
            return Err(
                "BUG 671 must parse diagnostic-free as exactly one source and one resistor"
                    .to_string(),
            );
        }
        let source_element = &netlist.elements[0];
        let ElementKind::VoltageSource(crate::netlist::SourceSpec::PwlFile {
            path,
            time_scale,
            value_scale,
            time_offset,
            value_offset,
            delay,
            repeat_from,
        }) = &source_element.kind
        else {
            return Err("BUG 671 VPWL must remain a file-backed PWL voltage source".to_string());
        };
        if !source_element.name.eq_ignore_ascii_case("VPWL")
            || source_element.nodes != ["1", "0"]
            || time_scale.to_bits() != 1.0_f64.to_bits()
            || value_scale.to_bits() != 1.0_f64.to_bits()
            || time_offset.to_bits() != 0.0_f64.to_bits()
            || value_offset.to_bits() != 0.0_f64.to_bits()
            || delay.to_bits() != 0.0_f64.to_bits()
            || repeat_from.is_some()
        {
            return Err(format!(
                "BUG 671 VPWL source shape changed: {} {:?}",
                source_element.name, source_element.nodes
            ));
        }
        let resistor = &netlist.elements[1];
        if !resistor.name.eq_ignore_ascii_case("R")
            || resistor.nodes != ["1", "0"]
            || !matches!(&resistor.kind, ElementKind::Resistor { value, .. } if value.to_bits() == 500.0_f64.to_bits())
        {
            return Err("BUG 671 must retain its 500-ohm shunt resistor".to_string());
        }
        let tran = Self::single_tran_analysis(&netlist)?;
        if tran.step.to_bits() != 0.01_f64.to_bits()
            || tran.stop.to_bits() != 11.0_f64.to_bits()
            || tran.start.is_some()
            || tran.max_step.is_some()
            || tran.uic
        {
            return Err(format!("BUG 671 .TRAN tuple changed: {tran:?}"));
        }
        let print = Self::single_tran_print_output_request(source)?;
        if print.format.is_some() || print.file.is_some() || print.probes != ["V(1)"] {
            return Err(format!(
                "BUG 671 ordered .PRINT TRAN contract changed: {print:?}"
            ));
        }
        let sibling = deck_path
            .parent()
            .ok_or_else(|| "BUG 671 deck has no parent directory".to_string())?
            .join("vpwl-word.csv");
        let resolved = Path::new(path).canonicalize().map_err(|err| {
            format!(
                "BUG 671 parsed PWL path '{}' cannot be canonicalized: {err}",
                path
            )
        })?;
        let expected_resolved = sibling.canonicalize().map_err(|err| {
            format!(
                "BUG 671 exact sibling fixture {} is missing: {err}",
                sibling.display()
            )
        })?;
        if resolved != expected_resolved {
            return Err(format!(
                "BUG 671 PWL path resolved to {}, expected exact sibling {}",
                resolved.display(),
                expected_resolved.display()
            ));
        }
        Self::validate_bug671_binary_fixture(&sibling)?;

        match crate::device::pwl_file::load_pwl_file(&sibling) {
            Err(crate::device::pwl_file::PwlFileError::IoError(error))
                if error.kind() == std::io::ErrorKind::InvalidData => {}
            Err(error) => {
                return Err(format!(
                    "BUG 671 direct PWL loader produced the wrong typed failure: {error}"
                ));
            }
            Ok(_) => {
                return Err(
                    "BUG 671 binary fixture loaded successfully as PWL data; expected invalid encoding"
                        .to_string(),
                );
            }
        }
        match self.create_xyce_engine().build_circuit(&netlist) {
            Err(SimulationError::Circuit(message))
                if message.contains("source 'VPWL'")
                    && message.contains("vpwl-word.csv")
                    && message.contains("failed to load PWL file")
                    && message.contains("valid UTF-8") =>
            {
                Ok(XyceExpectedFailureObservation {
                    stage: XyceExpectedFailureStage::ExternalDataLoad,
                    category: XyceExpectedFailureCategory::InvalidPwlFileEncoding,
                    identifiers: vec!["VPWL".to_string(), "vpwl-word.csv".to_string()],
                })
            }
            Err(error) => Err(format!(
                "BUG 671 produced the wrong typed circuit-build/loader failure: {error}"
            )),
            Ok(_) => Err(
                "BUG 671 circuit built successfully; expected its external PWL load to fail"
                    .to_string(),
            ),
        }
    }

    fn validate_bug671_binary_fixture(path: &Path) -> Result<(), String> {
        let metadata = fs::symlink_metadata(path).map_err(|err| {
            format!(
                "failed to inspect BUG 671 binary fixture {}: {err}",
                path.display()
            )
        })?;
        if !metadata.file_type().is_file() || metadata.file_type().is_symlink() {
            return Err(format!(
                "BUG 671 binary fixture {} must be a regular non-symlink file",
                path.display()
            ));
        }
        let bytes = fs::read(path).map_err(|err| {
            format!(
                "failed to read BUG 671 binary fixture {}: {err}",
                path.display()
            )
        })?;
        if bytes.len() != XYCE_BUG671_FIXTURE_BYTES {
            return Err(format!(
                "BUG 671 binary fixture size changed: expected {}, got {}",
                XYCE_BUG671_FIXTURE_BYTES,
                bytes.len()
            ));
        }
        if bytes.get(..XYCE_BUG671_OLE_MAGIC.len()) != Some(&XYCE_BUG671_OLE_MAGIC) {
            return Err("BUG 671 binary fixture lost its OLE compound-file magic".to_string());
        }
        let digest = blake3::hash(&bytes).to_hex().to_string();
        if digest != XYCE_BUG671_FIXTURE_BLAKE3 {
            return Err(format!(
                "BUG 671 binary fixture digest changed: expected {}, got {}",
                XYCE_BUG671_FIXTURE_BLAKE3, digest
            ));
        }
        Ok(())
    }

    fn observe_bug726_adjacent_coupling_failure(
        source: &str,
        deck_path: &Path,
    ) -> Result<XyceExpectedFailureObservation, String> {
        let physical_line = source
            .lines()
            .nth(12)
            .ok_or_else(|| "BUG 726 source has fewer than 13 physical lines".to_string())?;
        if physical_line != "K1 L1 L2 0.75 K2 L1 L3 0.8" {
            return Err(format!(
                "BUG 726 physical line 13 changed: expected concatenated K1/K2 statement, got {physical_line:?}"
            ));
        }
        for statement in [
            "VS 1 0 SIN(0 169.7 60HZ)",
            "R1 1 2 1K",
            "L1 2 0 1mH",
            "R2 3 0 1K",
            "L2 3 0 1mH",
            "R3 4 0 1K",
            "L3 4 0 1mH",
            ".TRAN 100US 25MS",
            ".OPTIONS TIMEINT METHOD=2",
            ".PRINT TRAN I(VS) V(2) V(3) V(4)",
        ] {
            if !source.lines().any(|line| line == statement) {
                return Err(format!(
                    "BUG 726 required statement changed or moved: {statement}"
                ));
            }
        }

        match Self::parse_xyce_netlist(source, deck_path) {
            Err(ParseError::Syntax { line, message })
                if line == 13
                    && message == "Unexpected trailing token in coupling specification: K2" =>
            {
                Ok(XyceExpectedFailureObservation {
                    stage: XyceExpectedFailureStage::NetlistParse,
                    category: XyceExpectedFailureCategory::AdjacentCouplingSyntax,
                    identifiers: vec!["K1".to_string(), "K2".to_string(), "line 13".to_string()],
                })
            }
            Err(error) => Err(format!(
                "BUG 726 produced the wrong typed parser failure: {error}"
            )),
            Ok(_) => Err(
                "BUG 726 parsed successfully; expected the adjacent K2 token to be rejected"
                    .to_string(),
            ),
        }
    }

    fn observe_bug744_dc_operating_point_failure(
        &self,
        source: &str,
        deck_path: &Path,
    ) -> Result<XyceExpectedFailureObservation, String> {
        let netlist = Self::parse_xyce_netlist(source, deck_path)
            .map_err(|err| format!("BUG 744 must parse before DC operating point: {err}"))?;
        if !netlist.diagnostics.is_empty()
            || netlist.elements.len() != 3
            || !netlist.subcircuits.is_empty()
        {
            return Err(
                "BUG 744 must parse diagnostic-free as exactly two sources and one resistor"
                    .to_string(),
            );
        }
        let expected_sources: [(&str, Value); 2] = [("Vsrc1", 5.0), ("Vsrc2", 2.0)];
        for (element, (name, value)) in netlist.elements[..2].iter().zip(expected_sources) {
            if !element.name.eq_ignore_ascii_case(name)
                || element.nodes != ["1", "0"]
                || !matches!(&element.kind, ElementKind::VoltageSource(spec) if extract_dc_value(spec).to_bits() == value.to_bits())
            {
                return Err(format!(
                    "BUG 744 conflicting source {name}={value} V topology changed"
                ));
            }
        }
        let resistor = &netlist.elements[2];
        if !resistor.name.eq_ignore_ascii_case("Rgrn")
            || resistor.nodes != ["1", "0"]
            || !matches!(&resistor.kind, ElementKind::Resistor { value, .. } if value.to_bits() == 1.0e6_f64.to_bits())
        {
            return Err("BUG 744 must retain its 1-megohm node-1 shunt".to_string());
        }
        let tran = Self::single_tran_analysis(&netlist)?;
        if tran.step.to_bits() != 0.0_f64.to_bits()
            || tran.stop.to_bits() != 1.0_f64.to_bits()
            || tran.start.is_some()
            || tran.max_step.is_some()
            || tran.uic
        {
            return Err(format!("BUG 744 .TRAN tuple changed: {tran:?}"));
        }
        let print = Self::single_tran_print_output_request(source)?;
        if print.format.is_some() || print.file.is_some() || print.probes != ["v(1)"] {
            return Err(format!(
                "BUG 744 ordered .PRINT TRAN contract changed: {print:?}"
            ));
        }
        let engine = self.create_xyce_engine();
        engine
            .build_circuit(&netlist)
            .map_err(|error| format!("BUG 744 must build before DC operating point: {error}"))?;
        match engine.run_dc_op(&netlist) {
            Err(SimulationError::Circuit(message))
                if message.contains("matrix is singular")
                    && message.contains("ideal voltage sources")
                    && message.contains("duplicate constraints") =>
            {
                Ok(XyceExpectedFailureObservation {
                    stage: XyceExpectedFailureStage::DcOperatingPoint,
                    category: XyceExpectedFailureCategory::ConflictingIdealVoltageConstraints,
                    identifiers: vec!["Vsrc1".to_string(), "Vsrc2".to_string(), "1".to_string()],
                })
            }
            Err(error) => Err(format!(
                "BUG 744 produced the wrong typed DC operating-point failure: {error}"
            )),
            Ok(_) => Err(
                "BUG 744 DC operating point succeeded; expected conflicting ideal constraints"
                    .to_string(),
            ),
        }
    }

    fn observe_bug75_undefined_mutual_inductor_reference_failure(
        source: &str,
        deck_path: &Path,
    ) -> Result<XyceExpectedFailureObservation, String> {
        const LABEL: &str = "BUG 75";
        Self::require_expected_failure_file_name(LABEL, deck_path, "bug75.cir")?;
        Self::require_expected_failure_source_lines(
            LABEL,
            source,
            15,
            &[
                (
                    1,
                    "Test error message capability when a mutual inductor references an undefined",
                ),
                (2, "*inductor"),
                (4, "R1 1 2 1"),
                (5, "L1 2 0 1"),
                (6, "*L2 2 3 1"),
                (7, "L3 2 0 1"),
                (8, "V1 1 0 DC 1"),
                (10, "K1 L1 L3 0.1"),
                (11, "K2 L1 L3 0"),
                (12, "K3 L1 L2 0"),
                (14, ".DC V1 1 1 0.1"),
                (15, ".end"),
            ],
        )?;

        let error = match Self::parse_xyce_netlist(source, deck_path) {
            Err(ParseError::UndefinedMutualInductorReference(error)) => error,
            Err(error) => {
                return Err(format!(
                    "{LABEL} produced the wrong typed parser failure: {error:?}"
                ));
            }
            Ok(_) => {
                return Err(format!(
                    "{LABEL} unexpectedly parsed; the undefined L2 reference is absent"
                ));
            }
        };

        let expected_path = deck_path.canonicalize().map_err(|error| {
            format!(
                "failed to canonicalize {LABEL} deck {}: {error}",
                deck_path.display()
            )
        })?;
        let origin_path = error
            .origin
            .path
            .as_deref()
            .ok_or_else(|| format!("{LABEL} typed failure lost its source path"))?
            .canonicalize()
            .map_err(|error| format!("failed to canonicalize {LABEL} error origin: {error}"))?;
        if origin_path != expected_path
            || error.origin.line != 12
            || error.authored_coupling_name != "K3"
            || error.canonical_coupling_name != "K3"
            || error.qualified_coupling_name != "K3"
            || error.authored_inductor_name != "L2"
            || error.canonical_inductor_name != "L2"
            || error.qualified_inductor_name != "L2"
            || error.scope_name.is_some()
            || error.reference_position != 2
            || error.to_string() != "Undefined inductor L2 in mutual inductor K3 definition."
        {
            return Err(format!(
                "{LABEL} typed undefined-mutual-inductor payload changed: {error:?}"
            ));
        }

        Ok(XyceExpectedFailureObservation {
            stage: XyceExpectedFailureStage::NetlistParse,
            category: XyceExpectedFailureCategory::UndefinedMutualInductorReference,
            identifiers: vec![
                error.authored_coupling_name.clone(),
                error.canonical_coupling_name.clone(),
                error.qualified_coupling_name.clone(),
                error.authored_inductor_name.clone(),
                error.canonical_inductor_name.clone(),
                error.qualified_inductor_name.clone(),
                "TOP_LEVEL".to_string(),
                error.reference_position.to_string(),
                format!("line {}", error.origin.line),
            ],
        })
    }

    fn observe_undefined_output_symbols_failure(
        source: &str,
        deck_path: &Path,
        kind: XyceExpectedFailureKind,
    ) -> Result<XyceExpectedFailureObservation, String> {
        let (label, file_name, line_count, required_lines): (&str, &str, usize, &[(usize, &str)]) =
            match kind {
                XyceExpectedFailureKind::Bug1148UndefinedPrintNode => (
                    "BUG 1148",
                    "bug_1148.cir",
                    6,
                    &[(2, "v1 1 0 1"), (5, ".print tran V(2)"), (6, ".end")],
                ),
                XyceExpectedFailureKind::Bug40UndefinedPrintNode => (
                    "BUG 40",
                    "bug_40.cir",
                    41,
                    &[
                        (29, "VDD 5 0 DC 18V "),
                        (39, ".PRINT DC V(bad) V(3,2) V(1,2)"),
                        (41, ".END"),
                    ],
                ),
                XyceExpectedFailureKind::Bug718InvalidPrintNodes => (
                    "BUG 718 invalid nodes",
                    "invalidNodes.cir",
                    22,
                    &[
                        (10, ".PRINT AC "),
                        (11, "+ {V(bogo1)} {V(bogo2,GND)} "),
                        (
                            13,
                            "+ {VR(bogo7)} {VI(bogo8)} {VP(bogo9)} {VM(bogo9)} {VDB(bogo10)}",
                        ),
                        (22, ".END"),
                    ],
                ),
                XyceExpectedFailureKind::MessagePrintBadNodeName => (
                    "Message Print bad node name",
                    "bad_nodename.cir",
                    9,
                    &[
                        (
                            8,
                            ".print ac V(A,C) VM(D,A) VP(A,B) VDB(A,B) VR(A,B) VI(A,B)",
                        ),
                        (9, ".end"),
                    ],
                ),
                XyceExpectedFailureKind::MessagePrintBadVariable => (
                    "Message Print bad variable",
                    "bad_variable.cir",
                    9,
                    &[
                        (
                            8,
                            ".print ac V(A,C) VM(D,B) VP(A,B) VDB(A,B) VR(A,B) VI(A,B) VQ(A,B)",
                        ),
                        (9, ".end"),
                    ],
                ),
                XyceExpectedFailureKind::LeadCurrentsInvalidDevice => (
                    "lead currents invalid device",
                    "lead_for_invalid_device.cir",
                    22,
                    &[
                        (14, "I1 1 0 sin(0 1 1KHz)"),
                        (20, ".PRINT TRAN V(2) I(RBogo)"),
                        (22, ".end"),
                    ],
                ),
                XyceExpectedFailureKind::MeasureInvalidNodes => (
                    "MEASURE invalid nodes",
                    "invalid_nodes.cir",
                    22,
                    &[
                        (14, ".MEASURE TRAN BOGONODEV MAX V(bogoNode)"),
                        (15, ".MEASURE TRAN BOGONODEN MAX N(missingNode)"),
                        (20, ".MEASURE TRAN NOREPLACEGROUND MAX V(GND)"),
                        (22, ".END"),
                    ],
                ),
                XyceExpectedFailureKind::FourierBadLine3OutputSymbols => (
                    "FOURIER bad line 3",
                    "bad_dot_four_line3.cir",
                    25,
                    &[
                        (
                            22,
                            ".FOUR 1KHZ I(BogoDevice1) P(BogoDevice2) W(BogoDevice3) V(2) N(3) V(GND)",
                        ),
                        (24, ".END"),
                    ],
                ),
                _ => {
                    return Err(format!(
                        "{} is not an output-symbol expected failure",
                        kind.record()
                    ));
                }
            };
        Self::require_expected_failure_file_name(label, deck_path, file_name)?;
        Self::require_expected_failure_source_lines(label, source, line_count, required_lines)?;

        // Parsing and semantic output validation are intentionally separate.
        // This proves each corpus record reaches the production post-parse
        // validator instead of being recognized by a parser/path special case.
        let netlist = Self::parse_xyce_netlist(source, deck_path).map_err(|error| {
            format!("{label} failed before output-symbol validation: {error:?}")
        })?;
        let error = match validate_output_symbols(&netlist) {
            Err(ParseError::OutputSymbolValidation(error)) => error,
            Err(error) => {
                return Err(format!(
                    "{label} produced the wrong typed validation failure: {error:?}"
                ));
            }
            Ok(()) => {
                return Err(format!(
                    "{label} unexpectedly passed output-symbol validation"
                ));
            }
        };
        let expected = kind
            .expected_output_symbols()
            .ok_or_else(|| format!("{label} has no typed output-symbol contract"))?;
        if error.unresolved.len() != expected.len() {
            return Err(format!(
                "{label} unresolved output-symbol count changed: expected {}, got {}: {:?}",
                expected.len(),
                error.unresolved.len(),
                error.unresolved
            ));
        }
        let expected_path = deck_path
            .canonicalize()
            .map_err(|error| format!("failed to canonicalize {label} deck: {error}"))?;
        for (index, (actual, expected)) in error.unresolved.iter().zip(expected).enumerate() {
            let actual_path = actual
                .origin
                .path
                .as_deref()
                .ok_or_else(|| format!("{label} unresolved item {index} lost its source path"))?
                .canonicalize()
                .map_err(|error| {
                    format!("failed to canonicalize {label} item {index} origin: {error}")
                })?;
            if actual.directive != expected.directive
                || actual.operator != expected.operator
                || actual.symbol != expected.symbol
                || actual.kind != expected.kind
                || actual.origin.line != expected.line
                || actual_path != expected_path
                || actual
                    .origin
                    .path
                    .as_deref()
                    .and_then(Path::file_name)
                    .and_then(|name| name.to_str())
                    != Some(expected.file_name)
            {
                return Err(format!(
                    "{label} unresolved output-symbol item {index} changed: expected {expected:?}, got {actual:?}"
                ));
            }
        }
        Ok(XyceExpectedFailureObservation {
            stage: XyceExpectedFailureStage::NetlistParse,
            category: XyceExpectedFailureCategory::UndefinedOutputSymbols,
            identifiers: expected
                .iter()
                .copied()
                .map(XyceExpectedOutputSymbol::identifier)
                .collect(),
        })
    }

    fn run_connectivity_diagnostic_contract(
        &self,
        deck: &XyceDeck,
        start: Instant,
    ) -> Option<XyceTestResult> {
        const CONTRACT: &str = "wrapper_expected_topology_warnings";
        if !self.requires_upstream_wrapper(&deck.relative_path) {
            return None;
        }
        let reference_path = self.static_output_reference_path(&deck.path, "err")?;
        if !reference_path.is_file() {
            return None;
        }
        let expected = match Self::parse_connectivity_diagnostic_reference(&reference_path) {
            Ok(Some(expected)) => expected,
            Ok(None) => return None,
            Err(error) => {
                return Some(self.failure_result(deck, start, CONTRACT, error, Vec::new()));
            }
        };

        let outcome = (|| -> Result<(), String> {
            if expected.one_device_terminal_nodes.len() != 1 || expected.no_dc_path_nodes.len() != 1
            {
                return Err(
                    "topology-warning wrapper currently requires exactly one expected node per warning category"
                        .to_string(),
                );
            }
            let source = fs::read_to_string(&deck.path)
                .map_err(|error| format!("failed to read connectivity deck: {error}"))?;
            for line in Self::logical_netlist_lines(&source) {
                let normalized = Self::strip_netlist_comment(&line)
                    .chars()
                    .filter(|character| !character.is_whitespace())
                    .flat_map(char::to_lowercase)
                    .collect::<String>();
                if normalized.starts_with(".optionstopology")
                    && normalized.contains("check_connectivity")
                {
                    return Err(
                        "topology-warning wrapper does not admit an explicit CHECK_CONNECTIVITY override"
                            .to_string(),
                    );
                }
            }
            let netlist = Self::parse_xyce_netlist(&source, &deck.path)
                .map_err(|error| format!("connectivity deck parse failed: {error}"))?;
            let flattened = crate::netlist::flatten_netlist_with_models(&netlist)
                .map_err(|error| format!("connectivity deck flattening failed: {error}"))?;
            let actual = crate::netlist::analyze_xyce_connectivity(&flattened.elements)
                .map_err(|error| error.to_string())?;
            if actual != expected {
                return Err(format!(
                    "topology diagnostics differ: expected one-terminal {:?} and no-DC-path {:?}, found one-terminal {:?} and no-DC-path {:?}",
                    expected.one_device_terminal_nodes,
                    expected.no_dc_path_nodes,
                    actual.one_device_terminal_nodes,
                    actual.no_dc_path_nodes
                ));
            }
            Ok(())
        })();

        Some(match outcome {
            Ok(()) => self.passed_result(deck, start, CONTRACT),
            Err(error) => self.failure_result(deck, start, CONTRACT, error, Vec::new()),
        })
    }

    fn parse_connectivity_diagnostic_reference(
        path: &Path,
    ) -> Result<Option<crate::netlist::ConnectivityDiagnostics>, String> {
        const PREFIX: &str = "User warning: Voltage Node (";
        const ONE_TERMINAL: &str = "connected to only 1 device Terminal";
        const NO_DC_PATH: &str = "does not have a DC path to ground";

        let source = fs::read_to_string(path).map_err(|error| {
            format!(
                "failed to read topology diagnostic reference {}: {error}",
                path.display()
            )
        })?;
        let lines = source
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .collect::<Vec<_>>();
        if lines.is_empty() || lines.iter().any(|line| !line.starts_with(PREFIX)) {
            return Ok(None);
        }

        let mut one_device_terminal_nodes = BTreeSet::new();
        let mut no_dc_path_nodes = BTreeSet::new();
        for line in lines {
            let remainder = line
                .strip_prefix(PREFIX)
                .expect("prefix was checked before parsing");
            let (node, message) = remainder
                .split_once(") ")
                .ok_or_else(|| format!("malformed topology diagnostic reference line '{line}'"))?;
            if node.is_empty() {
                return Err("topology diagnostic reference contains an empty node".to_string());
            }
            match message {
                ONE_TERMINAL => {
                    if !one_device_terminal_nodes.insert(node.to_string()) {
                        return Err(format!(
                            "duplicate one-device topology diagnostic for node '{node}'"
                        ));
                    }
                }
                NO_DC_PATH => {
                    if !no_dc_path_nodes.insert(node.to_string()) {
                        return Err(format!(
                            "duplicate no-DC-path topology diagnostic for node '{node}'"
                        ));
                    }
                }
                _ => return Ok(None),
            }
        }

        Ok(Some(crate::netlist::ConnectivityDiagnostics {
            one_device_terminal_nodes: one_device_terminal_nodes.into_iter().collect(),
            no_dc_path_nodes: no_dc_path_nodes.into_iter().collect(),
        }))
    }

    fn execution_plan(&self, deck: &XyceDeck) -> Result<XyceExecutionPlan, String> {
        let requires_wrapper = self.requires_upstream_wrapper(&deck.relative_path);
        let mut source =
            fs::read_to_string(&deck.path).map_err(|err| format!("failed to read deck: {err}"))?;
        source =
            Self::source_with_static_dc_wrapper_bindings(&source, &deck.path, requires_wrapper)?;

        let measurement_reference_paths = self.measurement_reference_paths(&deck.path, "ms")?;

        let wrapper_contract = if requires_wrapper {
            if measurement_reference_paths.is_empty() {
                Some(Self::native_static_prn_wrapper_contract(
                    &deck.relative_path,
                    &deck.path,
                    &source,
                )?)
            } else {
                Self::validate_scalar_dc_measurement_wrapper_source(&source)?;
                Some(XyceStaticDcContract::WrapperDefault)
            }
        } else {
            None
        };
        let (execution_deck_path, execution_dir) = if matches!(
            wrapper_contract,
            Some(XyceStaticDcContract::WrapperTopLevelExecutionDir)
        ) {
            (
                Self::top_level_execution_deck_path(&deck.path)?,
                Some(
                    deck.path
                        .parent()
                        .ok_or_else(|| "wrapper deck has no parent directory".to_string())?
                        .to_path_buf(),
                ),
            )
        } else {
            (deck.path.clone(), None)
        };

        let expression_dialect = if matches!(
            wrapper_contract,
            Some(XyceStaticDcContract::WrapperHspiceMath)
        ) {
            ExpressionDialect::Ngspice
        } else {
            ExpressionDialect::Xyce
        };
        let static_plan = if matches!(
            wrapper_contract,
            Some(XyceStaticDcContract::WrapperTopLevelExecutionDir)
        ) {
            self.static_dc_plan_for_path_with_execution_dir(
                &execution_deck_path,
                expression_dialect,
                execution_dir.as_deref(),
            )?
        } else {
            self.static_dc_plan_for_source_with_execution_dir(
                &execution_deck_path,
                source,
                expression_dialect,
                execution_dir.as_deref(),
            )?
        };
        let parsed_netlist = Self::parse_netlist_with_expression_dialect_and_execution_dir(
            &static_plan.source,
            &static_plan.deck_path,
            expression_dialect,
            static_plan.execution_dir.as_deref(),
        )
        .map_err(|err| format!("netlist parser failed after static DC validation: {err}"))?;
        let continuous_measurement_reference_paths =
            if parsed_netlist.options.measure_use_cont_files() {
                self.continuous_measurement_reference_paths(
                    &deck.path,
                    &parsed_netlist,
                    "DC_CONT",
                    "ms",
                )?
            } else {
                Vec::new()
            };
        let contract = if let Some(contract) = wrapper_contract {
            self.validate_native_static_prn_wrapper_contract(contract, &static_plan)?;
            contract
        } else {
            Self::static_dc_contract_for_print_format(false, static_plan.print_format.as_deref())?
        };
        if matches!(contract, XyceStaticDcContract::WrapperFilePrn) && !static_plan.steps.is_empty()
        {
            return Err(
                "wrapper-origin file-output contract does not cover .STEP DC decks yet".to_string(),
            );
        }
        let reference_path = self
            .static_output_reference_path(&deck.path, contract.reference_extension())
            .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
        if !reference_path.is_file()
            && measurement_reference_paths.is_empty()
            && continuous_measurement_reference_paths.is_empty()
            && !matches!(
                contract,
                XyceStaticDcContract::WrapperFilePrn | XyceStaticDcContract::WrapperNoOutput
            )
        {
            return Err(format!(
                "no checked-in static .{} oracle at {}",
                contract.reference_extension(),
                self.display_path(&reference_path)
            ));
        }

        Ok(XyceExecutionPlan {
            deck_path: static_plan.deck_path,
            execution_dir: static_plan.execution_dir,
            reference_path,
            measurement_reference_paths,
            continuous_measurement_reference_paths,
            measurement_tolerance: XyceFileCompareTolerance::MEASURE_COMMON_DEFAULT,
            source: static_plan.source,
            expression_dialect,
            print: static_plan.print,
            dc: static_plan.dc,
            dc_data: static_plan.dc_data,
            steps: static_plan.steps,
            contract,
        })
    }

    fn static_hb_plan_for_deck(&self, deck: &XyceDeck) -> Result<XyceStaticHbPlan, String> {
        let source =
            fs::read_to_string(&deck.path).map_err(|err| format!("failed to read deck: {err}"))?;
        if !self.requires_upstream_wrapper(&deck.relative_path) {
            return Err(
                "static HB currently implements the canonical three-file upstream-wrapper contract"
                    .to_string(),
            );
        }
        if Self::contains_control_block(&source) {
            return Err("HB deck uses a .control block; simulator scripting is not part of the static HB contract".to_string());
        }
        let requests = Self::print_output_requests(&source, "HB")?;
        if requests.len() != 1 {
            return Err(format!(
                "static HB requires exactly one .PRINT HB request, found {}",
                requests.len()
            ));
        }
        let request = requests.into_iter().next().expect("one HB print request");
        if request.file.is_some() {
            return Err("static HB does not combine the three canonical outputs with FILE= side destinations".to_string());
        }
        if !request
            .format
            .as_deref()
            .unwrap_or("STD")
            .eq_ignore_ascii_case("STD")
        {
            return Err(format!(
                "static HB currently requires PRN/STD output, found FORMAT={}",
                request.format.as_deref().unwrap_or("STD")
            ));
        }
        if source.lines().any(|line| {
            Self::strip_netlist_comment(line)
                .trim_start()
                .to_ascii_lowercase()
                .starts_with(".fft")
        }) {
            return Err("static HB wrapper contract does not admit .FFT output".to_string());
        }

        let mut print_count = 0usize;
        let mut option_lines = Vec::new();
        for line in Self::logical_netlist_lines(&source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") {
                print_count += 1;
            } else if command.eq_ignore_ascii_case(".probe") {
                return Err(
                    "static HB wrapper contract does not admit .PROBE directives".to_string(),
                );
            } else if command.eq_ignore_ascii_case(".options") {
                option_lines.push(trimmed);
            }
        }
        if print_count != 1 {
            return Err(format!(
                "static HB wrapper contract requires exactly one .PRINT directive, found {print_count}"
            ));
        }

        let netlist = Self::parse_xyce_netlist(&source, &deck.path)
            .map_err(|err| format!("HB netlist parse failed: {err}"))?;
        let [AnalysisCommand::Hb { frequencies }] = netlist.analyses.as_slice() else {
            return Err(
                "static HB requires exactly one .HB analysis and no other analysis cards"
                    .to_string(),
            );
        };
        let [frequency] = frequencies.as_slice() else {
            return Err(format!(
                "static HB currently supports one tone, found {}",
                frequencies.len()
            ));
        };
        if !frequency.is_finite() || *frequency <= 0.0 {
            return Err(format!(
                "static HB fundamental must be finite and positive, found {frequency}"
            ));
        }
        let [num_harmonics] = netlist.options.hb_num_frequencies.as_slice() else {
            return Err(format!(
                "static HB requires exactly one positive HBINT NUMFREQ value, found {}",
                netlist.options.hb_num_frequencies.len()
            ));
        };
        if *num_harmonics == 0 || *num_harmonics > 256 {
            return Err(format!(
                "static HB harmonic order must be in 1..=256, found {num_harmonics}"
            ));
        }
        let normalized_options = option_lines
            .iter()
            .map(|line| {
                line.chars()
                    .filter(|character| !character.is_whitespace())
                    .flat_map(char::to_lowercase)
                    .collect::<String>()
            })
            .collect::<Vec<_>>();
        let accepted_options = [
            format!(".optionshbintnumfreq={num_harmonics}"),
            format!(".optionshbintnumfreq[1]={num_harmonics}"),
        ];
        if normalized_options.len() != 1 || !accepted_options.contains(&normalized_options[0]) {
            return Err(
                "static HB wrapper contract currently admits only HBINT NUMFREQ; startup, output, and linear-solver options require distinct typed contracts"
                    .to_string(),
            );
        }

        for probe in &request.probes {
            let normalized = Self::normalize_probe(probe);
            let unsupported_device_probe = normalized.contains("i(")
                || ["id(", "ig(", "is(", "ib(", "ic(", "ie(", "p(", "w("]
                    .iter()
                    .any(|prefix| normalized.starts_with(prefix))
                || normalized.contains('@');
            if unsupported_device_probe {
                return Err(format!(
                    "static HB wrapper contract does not yet support branch, device-current, or device-parameter probe '{probe}'"
                ));
            }
        }

        if netlist.elements.iter().any(|element| {
            !matches!(
                &element.kind,
                crate::netlist::ElementKind::Resistor { .. }
                    | crate::netlist::ElementKind::Capacitor { .. }
                    | crate::netlist::ElementKind::Diode { .. }
                    | crate::netlist::ElementKind::VoltageSource(_)
            )
        }) {
            return Err(
                "static HB wrapper contract currently covers R/C/diode circuits driven by independent voltage sources"
                    .to_string(),
            );
        }

        let fd_reference_path = self
            .static_output_reference_path(&deck.path, "HB.FD.prn")
            .ok_or_else(|| "HB deck is not under tests/xyce/Netlists".to_string())?;
        let td_reference_path = self
            .static_output_reference_path(&deck.path, "HB.TD.prn")
            .ok_or_else(|| "HB deck is not under tests/xyce/Netlists".to_string())?;
        let ic_reference_path = self
            .static_output_reference_path(&deck.path, "hb_ic.prn")
            .ok_or_else(|| "HB deck is not under tests/xyce/Netlists".to_string())?;
        let startup_reference_path = self
            .static_output_reference_path(&deck.path, "startup.prn")
            .ok_or_else(|| "HB deck is not under tests/xyce/Netlists".to_string())?;
        if startup_reference_path.is_file() {
            return Err(
                "static HB wrapper contract does not yet implement the additional startup.prn artifact"
                    .to_string(),
            );
        }
        for (label, path) in [
            ("HB frequency-domain", &fd_reference_path),
            ("HB time-domain", &td_reference_path),
            ("HB startup transient", &ic_reference_path),
        ] {
            if !path.is_file() {
                return Err(format!(
                    "no checked-in {label} oracle at {}",
                    self.display_path(path)
                ));
            }
        }

        Ok(XyceStaticHbPlan {
            deck_path: deck.path.clone(),
            source,
            print: XycePrintRequest {
                probes: request.probes,
            },
            frequency: *frequency,
            num_harmonics: *num_harmonics,
            fd_reference_path,
            td_reference_path,
            ic_reference_path,
            wrapper: self.requires_upstream_wrapper(&deck.relative_path),
        })
    }

    fn static_tran_plan_for_deck(&self, deck: &XyceDeck) -> Result<XyceStaticTranPlan, String> {
        self.static_tran_plan_for_deck_with_purpose(deck, XyceStaticTranPlanPurpose::AbsoluteOracle)
    }

    fn static_tran_plan_for_deck_with_purpose(
        &self,
        deck: &XyceDeck,
        purpose: XyceStaticTranPlanPurpose,
    ) -> Result<XyceStaticTranPlan, String> {
        let requires_wrapper = self.requires_upstream_wrapper(&deck.relative_path);
        let analytic_wrapper = purpose == XyceStaticTranPlanPurpose::AnalyticOracle;
        let generated_reference_wrapper =
            purpose == XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily;
        if analytic_wrapper && !requires_wrapper {
            return Err(
                "analytic transient oracle purpose requires wrapper provenance".to_string(),
            );
        }
        if generated_reference_wrapper && !requires_wrapper {
            return Err(
                "generated-reference relational transient purpose requires wrapper provenance"
                    .to_string(),
            );
        }
        let source =
            fs::read_to_string(&deck.path).map_err(|err| format!("failed to read deck: {err}"))?;
        if Self::contains_control_block(&source) {
            return Err(
                "deck uses a .control block; Xyce adapter does not interpret simulator scripting"
                    .to_string(),
            );
        }
        Self::reject_unsupported_source_directives(&source)?;
        let source =
            Self::source_with_wrapper_paramfile_bindings(&source, &deck.path, requires_wrapper)?;

        let output_override = requires_wrapper
            && Self::is_native_output_override_wrapper_candidate_path(&deck.relative_path);
        let noindex_header_wrapper = requires_wrapper
            && Self::is_native_noindex_header_tran_wrapper_candidate(&deck.relative_path, &source);
        let has_static_tran_oracle = self.has_static_tran_reference_oracle(&deck.path);
        if requires_wrapper
            && !output_override
            && !noindex_header_wrapper
            && !has_static_tran_oracle
            && !Self::source_may_have_pwl_repeat_option(&source)
            && !analytic_wrapper
            && !generated_reference_wrapper
        {
            return Err(Self::upstream_wrapper_required_reason().to_string());
        }
        let print_output = if output_override {
            Self::output_override_print_output_request(&source, "TRAN")?.ok_or_else(|| {
                "output override deck has no .PRINT TRAN statement with static columns".to_string()
            })?
        } else {
            Self::single_tran_print_output_request(&source)?
        };
        let print = XycePrintRequest {
            probes: print_output.probes.clone(),
        };
        let netlist = Self::parse_xyce_netlist(&source, &deck.path)
            .map_err(|err| format!("netlist parser does not yet accept this Xyce deck: {err}"))?;
        let tran = Self::single_tran_analysis(&netlist)?;
        let steps = Self::step_commands(&netlist)?;
        let has_prn_oracle = self
            .static_output_reference_path(
                &deck.path,
                XyceStaticTranContract::WrapperStatic.reference_extension(),
            )
            .is_some_and(|path| path.is_file());
        let native_static_prn_wrapper = if analytic_wrapper {
            None
        } else if requires_wrapper {
            if output_override {
                Self::native_output_override_prn_tran_wrapper_contract(&source)
                    .map(Some)
                    .map_err(|_| Self::upstream_wrapper_required_reason().to_string())?
            } else {
                Self::native_static_prn_tran_wrapper_contract(
                    &deck.path,
                    &deck.relative_path,
                    &source,
                    has_prn_oracle,
                )
            }
        } else {
            None
        };
        if steps.is_empty()
            && requires_wrapper
            && native_static_prn_wrapper.is_none()
            && !analytic_wrapper
            && !generated_reference_wrapper
        {
            return Err(Self::upstream_wrapper_required_reason().to_string());
        }
        let contract = if analytic_wrapper {
            XyceStaticTranContract::WrapperStatic
        } else if requires_wrapper {
            native_static_prn_wrapper.unwrap_or(XyceStaticTranContract::WrapperStatic)
        } else {
            Self::static_tran_contract_for_print_format(false, print_output.format.as_deref())?
        };
        let primary_reference_path = self
            .static_output_reference_path(&deck.path, contract.reference_extension())
            .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
        let reference_path = if primary_reference_path.is_file() {
            primary_reference_path
        } else if matches!(contract, XyceStaticTranContract::WrapperCsd) {
            Self::tran_gsfile_reference_path(&deck.path).ok_or_else(|| {
                format!(
                    "no checked-in static .{} oracle at {}",
                    contract.reference_extension(),
                    self.display_path(&primary_reference_path)
                )
            })?
        } else {
            primary_reference_path
        };
        Self::validate_static_tran_reference_requirement(purpose, contract, &reference_path)?;
        if !steps.is_empty() {
            Self::validate_static_step_tran_contract(&netlist)?;
        }
        if requires_wrapper {
            if analytic_wrapper {
                Self::validate_native_static_prn_tran_wrapper_contract(&source)?;
            } else {
                match contract {
                    XyceStaticTranContract::WrapperCsd => {
                        Self::validate_native_static_csd_tran_wrapper_contract(&source)?;
                    }
                    XyceStaticTranContract::WrapperCsv => {
                        Self::validate_native_static_csv_tran_wrapper_contract(&source)?;
                    }
                    XyceStaticTranContract::WrapperStatic => {
                        if output_override {
                            Self::validate_native_output_override_prn_tran_wrapper_contract(
                                &source,
                            )?;
                        } else {
                            Self::validate_native_static_prn_tran_wrapper_contract_with_format_mode(
                            &source,
                            has_prn_oracle,
                        )?;
                        }
                    }
                    XyceStaticTranContract::WrapperStaticExpectedError => {
                        Self::validate_native_static_prn_tran_wrapper_contract(&source)?;
                    }
                    XyceStaticTranContract::WrapperNoIndexHeader => {
                        Self::validate_native_noindex_header_tran_wrapper_contract(&source)?;
                    }
                    _ => Self::validate_native_static_prn_tran_wrapper_contract(&source)?,
                }
            }
        }
        Self::validate_static_tran_analysis_contract(&netlist, &tran, &print)?;
        let timeint_conststep = Self::source_enables_constant_time_step_output(&source);
        let mut plan = XyceStaticTranPlan {
            deck_path: deck.path.clone(),
            reference_path,
            source,
            print,
            output_override,
            timeint_conststep,
            tran,
            steps,
            wrapper_tolerance: Self::native_default_prn_tran_wrapper_tolerance(&deck.relative_path),
            contract,
            comparison_mode: XyceStaticTranComparisonMode::Pointwise,
        };
        plan.comparison_mode =
            Self::select_static_tran_comparison_mode(&plan, &netlist, purpose, requires_wrapper)?;
        let validation_purpose = if plan.steps.is_empty()
            && matches!(
                plan.comparison_mode,
                XyceStaticTranComparisonMode::Release710IntegratedRms { .. }
            ) {
            XyceStaticTranPlanPurpose::DefaultLevel9XyceVerifyOracle
        } else {
            purpose
        };
        if validation_purpose.validates_absolute_device_contract()
            || matches!(
                validation_purpose,
                XyceStaticTranPlanPurpose::ScopedModelRelationalFamily
                    | XyceStaticTranPlanPurpose::AgeCapRelationalFamily
            )
        {
            Self::validate_native_transient_contract_for_purpose(&netlist, validation_purpose)?;
        } else {
            Self::validate_native_relational_transient_contract(&netlist)?;
        }

        Ok(plan)
    }

    fn static_tran_family_plan_for_path(
        &self,
        deck_path: &Path,
        purpose: XyceStaticTranPlanPurpose,
    ) -> Result<XyceStaticTranPlan, String> {
        self.static_tran_plan_for_path_with_purpose(deck_path, purpose)
    }

    fn static_tran_plan_for_path_with_purpose(
        &self,
        deck_path: &Path,
        purpose: XyceStaticTranPlanPurpose,
    ) -> Result<XyceStaticTranPlan, String> {
        let relative_path = self.relative_key(deck_path);
        let deck = XyceDeck {
            path: deck_path.to_path_buf(),
            section: Self::section_for_relative_path(&relative_path),
            relative_path,
        };
        self.static_tran_plan_for_deck_with_purpose(&deck, purpose)
    }

    fn has_static_tran_reference_oracle(&self, deck_path: &Path) -> bool {
        [
            XyceStaticTranContract::WrapperStatic.reference_extension(),
            XyceStaticTranContract::WrapperCsv.reference_extension(),
            XyceStaticTranContract::WrapperCsd.reference_extension(),
        ]
        .into_iter()
        .any(|extension| {
            self.static_output_reference_path(deck_path, extension)
                .is_some_and(|path| path.is_file())
        })
    }

    fn validate_static_tran_reference_requirement(
        purpose: XyceStaticTranPlanPurpose,
        contract: XyceStaticTranContract,
        reference_path: &Path,
    ) -> Result<(), String> {
        if purpose.requires_reference_file()
            && contract.requires_reference_file()
            && !reference_path.is_file()
        {
            return Err(format!(
                "no checked-in static .{} oracle at {}",
                contract.reference_extension(),
                reference_path.display()
            ));
        }
        Ok(())
    }

    fn select_static_tran_comparison_mode(
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        purpose: XyceStaticTranPlanPurpose,
        requires_wrapper: bool,
    ) -> Result<XyceStaticTranComparisonMode, String> {
        let pointwise = XyceStaticTranComparisonMode::Pointwise;
        if purpose == XyceStaticTranPlanPurpose::DefaultLevel9XyceVerifyOracle {
            return Err(
                "the default LEVEL=9 xyce_verify purpose is derived internally only after the strict integrated-RMS selector succeeds"
                    .to_string(),
            );
        }
        if purpose == XyceStaticTranPlanPurpose::AbsoluteOracle
            && !requires_wrapper
            && plan.contract == XyceStaticTranContract::PlainStatic
            && !plan.output_override
            && !plan.timeint_conststep
            && !plan.steps.is_empty()
            && plan.wrapper_tolerance.is_none()
            && plan.reference_path.is_file()
            && Self::native_transient_uses_standard_startup(netlist)
            && netlist.diagnostics.is_empty()
        {
            let scientific_precision =
                Self::xyce_verify_step_tran_scientific_precision(&plan.source)?;
            if Self::source_has_comp_directive(&plan.source) {
                match Self::xyce_verify_comp_tolerances(&plan.source, &plan.print.probes) {
                    Ok(tolerances) => {
                        return Ok(XyceStaticTranComparisonMode::Release710IntegratedRmsComp {
                            scientific_precision,
                            error_bounds: if tolerances
                                .into_iter()
                                .any(XyceVerifyTransientTolerance::has_nondefault_error_bounds)
                            {
                                XyceVerifyCompErrorBounds::DeckOverrides
                            } else {
                                XyceVerifyCompErrorBounds::Release710Default
                            },
                        });
                    }
                    Err(error) if error == XYCE_VERIFY_COMP_NO_PRINTED_PROBE => {
                        // Release 7.10 stores valid *COMP entries for TIME,
                        // Index, and other unprinted probes without applying
                        // them to a dependent column. The transient waveform
                        // therefore retains the default integrated-RMS bounds.
                        return Ok(XyceStaticTranComparisonMode::Release710IntegratedRms {
                            scientific_precision,
                        });
                    }
                    Err(_) => {}
                }
            } else {
                return Ok(XyceStaticTranComparisonMode::Release710IntegratedRms {
                    scientific_precision,
                });
            }
        }
        if purpose == XyceStaticTranPlanPurpose::AbsoluteOracle
            && !requires_wrapper
            && plan.contract == XyceStaticTranContract::PlainStatic
            && !plan.output_override
            && !plan.timeint_conststep
            && plan.steps.is_empty()
            && plan.wrapper_tolerance.is_none()
            && plan.reference_path.is_file()
            && Self::source_has_comp_directive(&plan.source)
            && Self::native_transient_uses_standard_startup(netlist)
            && netlist.diagnostics.is_empty()
            && Self::validate_native_transient_contract_for_purpose(
                netlist,
                XyceStaticTranPlanPurpose::AbsoluteOracle,
            )
            .is_ok()
        {
            if let Ok(tolerances) =
                Self::xyce_verify_comp_tolerances(&plan.source, &plan.print.probes)
            {
                return Ok(XyceStaticTranComparisonMode::Release710IntegratedRmsComp {
                    scientific_precision: XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION,
                    error_bounds: if tolerances
                        .into_iter()
                        .any(XyceVerifyTransientTolerance::has_nondefault_error_bounds)
                    {
                        XyceVerifyCompErrorBounds::DeckOverrides
                    } else {
                        XyceVerifyCompErrorBounds::Release710Default
                    },
                });
            }
        }
        if purpose != XyceStaticTranPlanPurpose::AbsoluteOracle
            || requires_wrapper
            || plan.contract != XyceStaticTranContract::PlainStatic
            || plan.output_override
            || plan.timeint_conststep
            || !plan.steps.is_empty()
            || plan.wrapper_tolerance.is_some()
            || !plan.reference_path.is_file()
            || Self::source_has_comp_directive(&plan.source)
            || !Self::native_transient_uses_standard_startup(netlist)
            || !netlist.diagnostics.is_empty()
            || !netlist.subcircuits.is_empty()
            || netlist
                .elements
                .iter()
                .any(|element| matches!(element.kind, ElementKind::Subcircuit { .. }))
        {
            return Ok(pointwise);
        }

        if Self::netlist_is_native_exact_is_diode_xyce_verify_envelope(netlist) {
            return Ok(XyceStaticTranComparisonMode::Release710IntegratedRms {
                scientific_precision: XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION,
            });
        }

        let mosfets = netlist
            .elements
            .iter()
            .filter(|element| matches!(element.kind, ElementKind::Mosfet { .. }))
            .collect::<Vec<_>>();
        if mosfets.is_empty()
            || mosfets.iter().any(|element| {
                !Self::netlist_element_is_native_absolute_transient_level9_bsim3(netlist, element)
            })
            || netlist.elements.iter().any(|element| {
                !Self::netlist_element_is_native_level9_xyce_verify_supported(element)
            })
        {
            return Ok(pointwise);
        }

        let referenced_models = mosfets
            .iter()
            .filter_map(|element| match &element.kind {
                ElementKind::Mosfet { model, .. } => Some(model.to_ascii_lowercase()),
                _ => None,
            })
            .collect::<BTreeSet<_>>();
        if netlist.models.len() != referenced_models.len()
            || netlist.models.iter().any(|model| {
                !referenced_models.contains(&model.name.to_ascii_lowercase())
                    || !Self::model_is_native_absolute_transient_level9_bsim3(model)
            })
        {
            return Ok(pointwise);
        }

        let Some(scientific_precision) =
            Self::strict_level9_xyce_verify_source_precision(&plan.source, netlist.models.len())?
        else {
            return Ok(pointwise);
        };
        Ok(XyceStaticTranComparisonMode::Release710IntegratedRms {
            scientific_precision,
        })
    }

    /// Resolve the precision used by Xyce's primary indexed STD transient
    /// output for a stepped run. `xyce_verify.pl` compares each sweep using
    /// the values serialized at this precision, so the verifier boundary must
    /// not be evaluated with the in-memory `f64` values.
    fn xyce_verify_step_tran_scientific_precision(source: &str) -> Result<usize, String> {
        let mut primary_precision = None;
        for line in Self::logical_netlist_lines(source) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            if stripped.is_empty() {
                continue;
            }
            let fields = Self::split_print_fields(stripped)?;
            if fields.len() < 2
                || !fields[0].eq_ignore_ascii_case(".PRINT")
                || !fields[1].eq_ignore_ascii_case("TRAN")
            {
                continue;
            }

            let field_refs = fields.iter().map(String::as_str).collect::<Vec<_>>();
            let mut precision = XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION;
            let mut format = "STD";
            let mut has_file = false;
            let mut has_probe = false;
            let mut index = 2usize;
            while index < fields.len() {
                if let Some((raw_key, raw_value, consumed)) =
                    Self::print_option_assignment(&field_refs, index)
                {
                    let key = raw_key.trim().to_ascii_lowercase();
                    let value = raw_value.trim().trim_matches(['"', '\'']);
                    match key.as_str() {
                        "file" => has_file = true,
                        "format" => format = value,
                        "precision" => {
                            let parsed = crate::netlist::lexer::parse_spice_value(value).map_err(
                                |err| {
                                    format!(
                                        "stepped xyce_verify .PRINT TRAN PRECISION must be numeric: '{value}': {err}"
                                    )
                                },
                            )?;
                            if !parsed.is_finite()
                                || parsed < f64::from(i32::MIN)
                                || parsed > f64::from(i32::MAX)
                            {
                                return Err(format!(
                                    "stepped xyce_verify .PRINT TRAN PRECISION must be a finite Xyce integer value, got {parsed}"
                                ));
                            }
                            let effective = parsed as i32;
                            if !(1..=XYCE_MAX_IEEE754_PRN_SCIENTIFIC_PRECISION as i32)
                                .contains(&effective)
                            {
                                return Err(format!(
                                    "stepped xyce_verify .PRINT TRAN PRECISION must resolve from 1 through {XYCE_MAX_IEEE754_PRN_SCIENTIFIC_PRECISION}, got {effective}"
                                ));
                            }
                            precision = effective as usize;
                        }
                        _ => {}
                    }
                    index += consumed;
                    continue;
                }

                let normalized = field_refs[index].to_ascii_lowercase();
                if normalized == "noindex" {
                    return Err(
                        "stepped xyce_verify primary .PRINT TRAN must retain its Index column"
                            .to_string(),
                    );
                }
                if !Self::is_print_option_token(&normalized) {
                    has_probe = true;
                }
                index += 1;
            }
            if has_file || !has_probe {
                continue;
            }
            if !format.eq_ignore_ascii_case("STD") {
                return Err(format!(
                    "stepped xyce_verify primary .PRINT TRAN requires indexed FORMAT=STD, got FORMAT={format}"
                ));
            }
            if primary_precision.replace(precision).is_some() {
                return Err(
                    "stepped xyce_verify requires exactly one primary .PRINT TRAN output"
                        .to_string(),
                );
            }
        }

        primary_precision.ok_or_else(|| {
            "stepped xyce_verify requires one primary indexed .PRINT TRAN output".to_string()
        })
    }

    fn source_has_comp_directive(source: &str) -> bool {
        !Self::logical_comp_directives(source).is_empty()
    }

    fn logical_comp_directives(source: &str) -> Vec<String> {
        let mut directives = Vec::new();
        let mut current: Option<String> = None;
        for raw in source.lines() {
            let line = raw.split_once(';').map_or(raw, |(head, _)| head).trim_end();
            if line.trim_start().starts_with('+') {
                if let Some(directive) = current.as_mut() {
                    directive.push(' ');
                    directive.push_str(line.trim_start().trim_start_matches('+').trim_start());
                }
                continue;
            }
            if let Some(directive) = current.take() {
                directives.push(directive);
            }
            if Self::comp_directive_body(line).is_some() {
                current = Some(line.trim_start().to_string());
            }
        }
        if let Some(directive) = current {
            directives.push(directive);
        }
        directives
    }

    fn comp_directive_body(line: &str) -> Option<&str> {
        let trimmed = line
            .split_once(';')
            .map_or(line, |(head, _)| head)
            .trim_start();
        let prefix = trimmed.get(..5)?;
        let body = trimmed.get(5..)?;
        (prefix.eq_ignore_ascii_case("*COMP")
            && body.chars().next().is_none_or(char::is_whitespace))
        .then(|| body.trim_start())
    }

    fn strict_level9_xyce_verify_source_precision(
        source: &str,
        expected_model_count: usize,
    ) -> Result<Option<usize>, String> {
        let lines = Self::logical_netlist_lines(source);
        if lines.is_empty() {
            return Ok(None);
        }
        let mut model_count = 0usize;
        let mut tran_count = 0usize;
        let mut print_count = 0usize;
        let mut end_count = 0usize;
        let mut scientific_precision = None;
        let mut saw_end = false;
        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            if stripped.is_empty() {
                continue;
            }
            if saw_end {
                return Ok(None);
            }
            let fields = Self::split_print_fields(stripped)?;
            let Some(command) = fields.first() else {
                continue;
            };
            if !command.starts_with('.') {
                continue;
            }
            match command.to_ascii_lowercase().as_str() {
                ".model" => model_count += 1,
                ".tran" => {
                    tran_count += 1;
                    if fields.len() != 3 {
                        return Ok(None);
                    }
                }
                ".print" => {
                    print_count += 1;
                    scientific_precision =
                        Some(Self::strict_level9_xyce_verify_print_precision(&fields)?);
                }
                ".end" => {
                    end_count += 1;
                    if fields.len() != 1 {
                        return Ok(None);
                    }
                    saw_end = true;
                }
                _ => return Ok(None),
            }
        }
        if model_count != expected_model_count
            || tran_count != 1
            || print_count != 1
            || end_count != 1
        {
            return Ok(None);
        }
        Ok(scientific_precision)
    }

    fn strict_level9_xyce_verify_print_precision(fields: &[String]) -> Result<usize, String> {
        if fields.len() < 3
            || !fields[0].eq_ignore_ascii_case(".PRINT")
            || !fields[1].eq_ignore_ascii_case("TRAN")
        {
            return Err(
                "integrated-RMS output requires one ordinary .PRINT TRAN statement".to_string(),
            );
        }
        let field_refs = fields.iter().map(String::as_str).collect::<Vec<_>>();
        let mut precision = None;
        let mut width = None;
        let mut format = None;
        let mut filter = None;
        let mut time_scale_factor = None;
        let mut saw_probe = false;
        let mut index = 2usize;
        while index < fields.len() {
            if let Some((raw_key, raw_value, consumed)) =
                Self::print_option_assignment(&field_refs, index)
            {
                if saw_probe {
                    return Err(format!(
                        "integrated-RMS .PRINT TRAN does not admit option assignment '{raw_key}' after the first probe"
                    ));
                }
                let key = raw_key.trim().to_ascii_lowercase();
                let verifier_value = raw_value.trim();
                if !verifier_value
                    .chars()
                    .next()
                    .is_some_and(|first| first.is_ascii_alphanumeric() || first == '_')
                {
                    return Err(format!(
                        "integrated-RMS .PRINT TRAN option '{raw_key}' is not consumable by Release 7.10 xyce_verify.pl: '{raw_value}'"
                    ));
                }
                let value = verifier_value;
                match key.as_str() {
                    "precision" => precision = Some(value.to_string()),
                    "width" => width = Some(value.to_string()),
                    "format" => {
                        format = Some(value.to_string());
                    }
                    "filter" => filter = Some(value.to_string()),
                    "timescalefactor" => time_scale_factor = Some(value.to_string()),
                    _ => {
                        return Err(format!(
                            "integrated-RMS .PRINT TRAN does not admit output option '{raw_key}'"
                        ));
                    }
                }
                index += consumed;
                continue;
            }

            let normalized = field_refs[index].to_ascii_lowercase();
            if Self::is_print_option_token(&normalized)
                || matches!(
                    normalized.as_str(),
                    "file"
                        | "format"
                        | "width"
                        | "precision"
                        | "delimiter"
                        | "noindex"
                        | "index"
                        | "filter"
                        | "timescalefactor"
                )
            {
                return Err(format!(
                    "integrated-RMS .PRINT TRAN does not admit output option '{}'",
                    fields[index]
                ));
            }
            saw_probe = true;
            index += 1;
        }

        if !saw_probe {
            return Err("integrated-RMS .PRINT TRAN contains no probes".to_string());
        }
        let parse_effective_integer_option = |name: &str,
                                              raw: Option<&str>|
         -> Result<Option<i32>, String> {
            raw.map(|value| {
                    let parsed = crate::netlist::lexer::parse_spice_value(value).map_err(|err| {
                        format!(
                            "integrated-RMS .PRINT TRAN {name} must be numeric: '{value}': {err}"
                        )
                    })?;
                    if !parsed.is_finite()
                        || parsed < f64::from(i32::MIN)
                        || parsed > f64::from(i32::MAX)
                    {
                        return Err(format!(
                            "integrated-RMS .PRINT TRAN {name} must be a finite Xyce integer value in the i32 range: '{value}'"
                        ));
                    }
                    Ok(parsed as i32)
                })
                .transpose()
        };
        let effective_precision =
            parse_effective_integer_option("PRECISION", precision.as_deref())?;
        if effective_precision != Some(12) {
            return Err(format!(
                "integrated-RMS .PRINT TRAN requires explicit effective PRECISION=12, got {effective_precision:?}"
            ));
        }
        let _effective_width = parse_effective_integer_option("WIDTH", width.as_deref())?;
        if format
            .as_deref()
            .is_some_and(|value| !value.eq_ignore_ascii_case("STD"))
        {
            return Err(format!(
                "integrated-RMS .PRINT TRAN requires effective FORMAT=STD, got {format:?}"
            ));
        }
        let parse_finite_option =
            |name: &str, raw: Option<&str>| -> Result<Option<Value>, String> {
                raw.map(|value| {
                    let parsed = crate::netlist::lexer::parse_spice_value(value).map_err(|err| {
                    format!("integrated-RMS .PRINT TRAN {name} must be numeric: '{value}': {err}")
                })?;
                    if !parsed.is_finite() {
                        return Err(format!("integrated-RMS .PRINT TRAN {name} must be finite"));
                    }
                    Ok(parsed)
                })
                .transpose()
            };
        let effective_filter = parse_finite_option("FILTER", filter.as_deref())?;
        if effective_filter.is_some_and(|value| value != 0.0) {
            return Err(format!(
                "integrated-RMS .PRINT TRAN requires effective FILTER=0, got {effective_filter:?}"
            ));
        }
        let effective_time_scale =
            parse_finite_option("TIMESCALEFACTOR", time_scale_factor.as_deref())?;
        if effective_time_scale.is_some_and(|value| value != 1.0) {
            return Err(format!(
                "integrated-RMS .PRINT TRAN requires effective TIMESCALEFACTOR=1, got {effective_time_scale:?}"
            ));
        }
        Ok(12)
    }

    fn static_ac_plan_for_deck(&self, deck: &XyceDeck) -> Result<XyceStaticAcPlan, String> {
        let requires_wrapper = self.requires_upstream_wrapper(&deck.relative_path);
        let output_override = requires_wrapper
            && Self::is_native_output_override_wrapper_candidate_path(&deck.relative_path);
        let source =
            fs::read_to_string(&deck.path).map_err(|err| format!("failed to read deck: {err}"))?;
        if Self::contains_control_block(&source) {
            return Err(
                "deck uses a .control block; Xyce adapter does not interpret simulator scripting"
                    .to_string(),
            );
        }
        Self::reject_unsupported_source_directives(&source)?;
        if requires_wrapper {
            Self::validate_native_static_fd_ac_wrapper_contract(&source, output_override)?;
        }

        let primary_ac_output = if output_override {
            Self::output_override_print_output_request(&source, "AC")?
        } else {
            Self::canonical_print_output_request(&source, "AC", requires_wrapper)?
        };
        let primary_ac_ic_output = if output_override {
            Self::output_override_print_output_request(&source, "AC_IC")?
        } else {
            Self::canonical_print_output_request(&source, "AC_IC", requires_wrapper)?
        };
        if primary_ac_output.is_none() && primary_ac_ic_output.is_none() {
            return Err(
                "deck has no primary .PRINT AC or .PRINT AC_IC statement with static columns"
                    .to_string(),
            );
        }

        let (netlist, frequency_bound) = match Self::parse_xyce_netlist(&source, &deck.path) {
            Ok(netlist) if Self::parsed_netlist_has_ac_frequency_dependent_global(&netlist) => {
                let frequency_bound_source = Self::source_with_ac_frequency_bindings(&source, 1.0);
                let netlist = Self::parse_xyce_netlist(&frequency_bound_source, &deck.path)
                    .map_err(|retry_err| {
                        format!(
                            "netlist parser does not accept this Xyce deck with AC frequency bindings: {retry_err}"
                        )
                    })?;
                (netlist, true)
            }
            Ok(netlist) => (netlist, false),
            Err(err) if Self::parse_error_is_unbound_ac_frequency_dependency(&source, &err) => {
                let frequency_bound_source = Self::source_with_ac_frequency_bindings(&source, 1.0);
                let netlist = Self::parse_xyce_netlist(&frequency_bound_source, &deck.path)
                    .map_err(|retry_err| {
                        format!(
                            "netlist parser does not yet accept this Xyce deck even with AC frequency bindings: {retry_err}"
                        )
                    })?;
                (netlist, true)
            }
            Err(err) => {
                return Err(format!(
                    "netlist parser does not yet accept this Xyce deck: {err}"
                ));
            }
        };
        let ac = Self::single_ac_analysis(&netlist)?;
        let steps = Self::step_commands(&netlist)?;
        if ac.data_points().is_some() && !steps.is_empty() {
            return Err(
                ".STEP combined with .AC DATA is not implemented in the native Xyce oracle"
                    .to_string(),
            );
        }
        if frequency_bound && !steps.is_empty() {
            return Err(
                ".STEP combined with AC frequency-dependent parameters is not implemented in the native Xyce oracle"
                    .to_string(),
            );
        }
        if frequency_bound && ac.data_points().is_some() {
            return Err(
                ".AC DATA combined with AC frequency-dependent parameters is not implemented in the native Xyce oracle"
                    .to_string(),
            );
        }

        let use_continuous_files = netlist.options.measure_use_cont_files();
        let measurement_reference_paths = if netlist.measurements.iter().any(|measurement| {
            measurement.print_policy == crate::analysis::MeasurePrintPolicy::All
                && (measurement.analysis.eq_ignore_ascii_case("AC")
                    || (!use_continuous_files
                        && measurement.analysis.eq_ignore_ascii_case("AC_CONT")))
        }) {
            self.measurement_reference_paths(&deck.path, "ma")?
        } else {
            Vec::new()
        };
        let continuous_measurement_reference_paths = if use_continuous_files {
            self.continuous_measurement_reference_paths(&deck.path, &netlist, "AC_CONT", "ma")?
        } else {
            Vec::new()
        };
        let measurement_tolerance = if netlist.measurements.iter().any(|measurement| {
            measurement.analysis.eq_ignore_ascii_case("AC")
                && matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Integ { .. }
                )
        }) {
            XyceFileCompareTolerance::MEASURE_COMMON_AC_INTEGRATION
        } else {
            XyceFileCompareTolerance::MEASURE_COMMON_DEFAULT
        };

        let primary_ac_ic_file = primary_ac_ic_output
            .as_ref()
            .and_then(|request| request.file.clone());
        let (contract, reference_path, print, primary_ac_file) =
            if let Some(print_output) = primary_ac_output {
                let primary_ac_file = print_output.file.clone();
                let contract = Self::static_ac_contract_for_print_format(
                    requires_wrapper,
                    print_output.format.as_deref(),
                )?;
                let reference_path = self
                    .static_output_reference_path(&deck.path, contract.reference_extension())
                    .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
                if !reference_path.is_file()
                    && measurement_reference_paths.is_empty()
                    && continuous_measurement_reference_paths.is_empty()
                {
                    return Err(format!(
                        "no checked-in static .{} or AC measurement oracle at {}",
                        contract.reference_extension(),
                        self.display_path(&reference_path)
                    ));
                }
                let print = XycePrintRequest {
                    probes: print_output.probes,
                };
                Self::validate_static_ac_contract(&netlist, &ac, &print)?;
                (
                    contract,
                    reference_path.is_file().then_some(reference_path),
                    Some(print),
                    primary_ac_file,
                )
            } else if let Some(print_output) = primary_ac_ic_output {
                if !steps.is_empty() {
                    return Err(
                    ".STEP AC_IC-only comparison is not implemented for wrapper-origin AC output"
                        .to_string(),
                );
                }
                let contract = Self::static_ac_ic_contract_for_print_format(
                    requires_wrapper,
                    print_output.format.as_deref(),
                )?;
                let reference_path = self
                    .static_output_reference_path(&deck.path, contract.reference_extension())
                    .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
                if !reference_path.is_file() {
                    return Err(format!(
                        "no checked-in static .{} oracle at {}",
                        contract.reference_extension(),
                        self.display_path(&reference_path)
                    ));
                }
                (contract, None, None, None)
            } else {
                unreachable!("AC output request presence was checked before parsing");
            };

        Ok(XyceStaticAcPlan {
            deck_path: deck.path.clone(),
            reference_path,
            measurement_reference_paths,
            continuous_measurement_reference_paths,
            measurement_tolerance,
            source,
            print,
            primary_ac_file,
            primary_ac_ic_file,
            output_override,
            ac,
            frequency_bound,
            steps,
            contract,
        })
    }

    fn relational_ac_plan_for_path(&self, path: &Path) -> Result<XyceRelationalAcPlan, String> {
        let source = fs::read_to_string(path)
            .map_err(|err| format!("failed to read relational AC deck: {err}"))?;
        if Self::contains_control_block(&source) {
            return Err(
                "relational AC comparison does not interpret simulator control blocks".to_string(),
            );
        }
        Self::reject_unsupported_source_directives(&source)?;
        let output = Self::canonical_print_output_request(&source, "AC", false)?
            .ok_or_else(|| "deck has no .PRINT AC statement with static columns".to_string())?;
        if output.format.is_some() || output.file.is_some() || output.probes.is_empty() {
            return Err(
                "relational AC comparison requires one nonempty primary .PRINT AC using default PRN output"
                    .to_string(),
            );
        }
        let print = XycePrintRequest {
            probes: output.probes,
        };
        let netlist = Self::parse_xyce_netlist(&source, path)
            .map_err(|err| format!("netlist parser rejected relational AC deck: {err}"))?;
        let ac = Self::single_ac_analysis(&netlist)?;
        if ac.data_points().is_some() || !Self::step_commands(&netlist)?.is_empty() {
            return Err("relational AC comparison does not admit .AC DATA or .STEP".to_string());
        }
        Self::validate_static_ac_contract(&netlist, &ac, &print)?;
        Ok(XyceRelationalAcPlan {
            deck_path: path.to_path_buf(),
            source,
            print,
            ac,
        })
    }

    fn validate_measure_cont_step_noise_deriv_provenance(
        &self,
        deck: &XyceDeck,
    ) -> Result<Vec<u8>, String> {
        if deck.section != XyceDeckSection::Netlists
            || Self::normalize_manifest_key(&deck.relative_path)
                != XYCE_MEASURE_CONT_STEP_NOISE_DERIV_RECORD
            || !self.requires_upstream_wrapper(&deck.relative_path)
        {
            return Err(
                "MEASURE_CONT STEP NOISE derivative record lost exact wrapper ownership".into(),
            );
        }
        let canonical_deck = deck.path.canonicalize().map_err(|error| {
            format!("failed to canonicalize MEASURE_CONT STEP NOISE record: {error}")
        })?;
        let canonical_expected = self
            .root
            .join("Netlists/MEASURE_CONT/STEP/DerivTestNoise.cir")
            .canonicalize()
            .map_err(|error| {
                format!("canonical MEASURE_CONT STEP NOISE record is missing: {error}")
            })?;
        if canonical_deck != canonical_expected {
            return Err(
                "MEASURE_CONT STEP NOISE record resolved outside its canonical corpus path".into(),
            );
        }

        self.validate_measure_cont_manifest_family()?;
        self.validate_measure_cont_family_census(
            "Netlists/MEASURE_CONT",
            XYCE_MEASURE_CONT_TRAN_SOURCE_FAMILY_COUNT,
            XYCE_MEASURE_CONT_TRAN_SOURCE_FAMILY_NAMES_BLAKE3,
            XYCE_MEASURE_CONT_TRAN_SOURCE_FAMILY_CONTENT_BLAKE3,
        )?;
        self.validate_measure_cont_family_census(
            "OutputData/MEASURE_CONT",
            XYCE_MEASURE_CONT_TRAN_OUTPUT_FAMILY_COUNT,
            XYCE_MEASURE_CONT_TRAN_OUTPUT_FAMILY_NAMES_BLAKE3,
            XYCE_MEASURE_CONT_TRAN_OUTPUT_FAMILY_CONTENT_BLAKE3,
        )?;
        self.validate_measure_cont_step_case_sensitive_census()?;

        let source = Self::validate_measure_cont_regular_text_identity(
            &canonical_expected,
            (
                XYCE_MEASURE_CONT_STEP_NOISE_DERIV_SOURCE_BYTES,
                XYCE_MEASURE_CONT_STEP_NOISE_DERIV_SOURCE_BLAKE3,
            ),
            "MEASURE_CONT STEP NOISE derivative source",
        )?;
        for (relative, identity, label) in [
            (
                "Netlists/MEASURE_CONT/STEP/DerivTestNoiseGSfile",
                (
                    XYCE_MEASURE_CONT_STEP_NOISE_DERIV_GS_BYTES,
                    XYCE_MEASURE_CONT_STEP_NOISE_DERIV_GS_BLAKE3,
                ),
                "MEASURE_CONT STEP NOISE derivative GS",
            ),
            (
                "OutputData/MEASURE_CONT/STEP/DerivTestNoise.cir.ma0",
                (
                    XYCE_MEASURE_CONT_STEP_NOISE_DERIV_MA0_BYTES,
                    XYCE_MEASURE_CONT_STEP_NOISE_DERIV_MA0_BLAKE3,
                ),
                "MEASURE_CONT STEP NOISE derivative ma0",
            ),
            (
                "OutputData/MEASURE_CONT/STEP/DerivTestNoise.cir.ma1",
                (
                    XYCE_MEASURE_CONT_STEP_NOISE_DERIV_MA1_BYTES,
                    XYCE_MEASURE_CONT_STEP_NOISE_DERIV_MA1_BLAKE3,
                ),
                "MEASURE_CONT STEP NOISE derivative ma1",
            ),
        ] {
            Self::validate_measure_cont_regular_text_identity(
                &self.root.join(relative),
                identity,
                label,
            )?;
        }

        let manifest_path = self.root.join(HARNESS_MANIFEST_FILE);
        let manifest_bytes = fs::read(&manifest_path)
            .map_err(|error| format!("failed to read {}: {error}", manifest_path.display()))?;
        let canonical_manifest =
            Self::canonical_lf_text_identity("MEASURE_CONT STEP NOISE manifest", &manifest_bytes)?;
        let manifest = std::str::from_utf8(&canonical_manifest)
            .map_err(|error| format!("MEASURE_CONT STEP NOISE manifest is not UTF-8: {error}"))?;
        let owner = "Netlists/MEASURE_CONT/STEP/DerivTestNoise.cir\trequires_upstream_wrapper";
        if manifest.lines().filter(|line| *line == owner).count() != 1 {
            return Err(
                "MEASURE_CONT STEP NOISE manifest lost its exact case-sensitive owner row".into(),
            );
        }

        // Release-7.10.0's 4,973-byte wrapper (SHA-256
        // f9c11614...5d605465) invokes MeasureCommon.pm and file_compare.pl.
        // The latter owns the strict 1e-5/1e-3/1e-10 comparison contract;
        // it does not invoke xyce_verify or perform a remeasure pass.
        Ok(source)
    }

    fn validate_measure_cont_step_noise_deriv_plan(
        netlist: &Netlist,
        print: Option<&XycePrintRequest>,
        frequencies: &[Value],
    ) -> Result<(), String> {
        let steps = Self::step_commands(netlist)?;
        let exact_step = matches!(steps.as_slice(), [StepCommand {
            target: StepTarget::Device,
            name,
            param_name: None,
            sweep: StepSweep::Linear { start, stop, step },
        }] if name.eq_ignore_ascii_case("RL")
            && start.to_bits() == 1.0f64.to_bits()
            && stop.to_bits() == 1.5f64.to_bits()
            && step.to_bits() == 0.5f64.to_bits());
        let probes = print
            .map(|request| {
                request
                    .probes
                    .iter()
                    .map(|probe| Self::normalize_probe(probe))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let expected_probes = [
            "vm(3)",
            "vm(b)",
            "vm(c)",
            "vm(d)",
            "vm(e)",
            "derivcrossconttest2",
            "derivcrossconttest3",
            "derivcrossconttest4",
            "derivcrossneg2",
            "derivcrosscontneg2",
            "derivcrossneg6",
            "derivcrosscontneg6",
        ];
        if !exact_step
            || probes != expected_probes
            || frequencies.len() != 61
            || frequencies.first().map(|value| value.to_bits()) != Some(1.0e-2f64.to_bits())
            || frequencies
                .last()
                .is_none_or(|value| (*value - 10.0).abs() > 1.0e-12)
            || netlist.options.measure_use_cont_files != Some(false)
            || netlist.analyses.len() != 2
            || netlist.output_requests.len() != netlist.measurements.len() + 1
            || !netlist.diagnostics.is_empty()
            || !netlist.models.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.data_tables.is_empty()
            || netlist.elements.len() != 13
        {
            return Err(format!(
                "MEASURE_CONT STEP NOISE exact analysis/step/print/topology contract changed: step={steps:?}, probes={probes:?}, frequencies={:?}/{:?}/{}, use_cont={:?}, analyses={}, outputs={}, measurements={}, diagnostics={}, models={}, subcircuits={}, data={}, elements={}",
                frequencies.first(),
                frequencies.last(),
                frequencies.len(),
                netlist.options.measure_use_cont_files,
                netlist.analyses.len(),
                netlist.output_requests.len(),
                netlist.measurements.len(),
                netlist.diagnostics.len(),
                netlist.models.len(),
                netlist.subcircuits.len(),
                netlist.data_tables.len(),
                netlist.elements.len()
            ));
        }
        let scalar = netlist
            .measurements
            .iter()
            .filter(|statement| statement.analysis.eq_ignore_ascii_case("NOISE"))
            .count();
        let continuous = netlist
            .measurements
            .iter()
            .filter(|statement| statement.analysis.eq_ignore_ascii_case("NOISE_CONT"))
            .count();
        let derivative = netlist
            .measurements
            .iter()
            .filter(|statement| {
                matches!(
                    statement.measure_type,
                    crate::analysis::MeasureType::Derivative { .. }
                )
            })
            .count();
        let last = netlist.measurements.last();
        if scalar != 13
            || continuous != 32
            || scalar + continuous != netlist.measurements.len()
            || derivative != 44
            || !last.is_some_and(|statement| {
                statement.analysis.eq_ignore_ascii_case("NOISE")
                    && statement.name.eq_ignore_ascii_case("lastMeasure")
                    && matches!(
                        statement.measure_type,
                        crate::analysis::MeasureType::Max { .. }
                    )
            })
            || netlist
                .measurements
                .iter()
                .any(|statement| statement.print_policy != crate::analysis::MeasurePrintPolicy::All)
        {
            return Err(format!(
                "MEASURE_CONT STEP NOISE measurement census changed: NOISE={scalar}/13, NOISE_CONT={continuous}/32, DERIV={derivative}/44"
            ));
        }
        Ok(())
    }

    fn static_noise_plan_for_deck(&self, deck: &XyceDeck) -> Result<XyceStaticNoisePlan, String> {
        let qualified_step_cont_derivative = Self::normalize_manifest_key(&deck.relative_path)
            == XYCE_MEASURE_CONT_STEP_NOISE_DERIV_RECORD;
        let source = if qualified_step_cont_derivative {
            let bytes = self.validate_measure_cont_step_noise_deriv_provenance(deck)?;
            String::from_utf8(bytes)
                .map_err(|error| format!("MEASURE_CONT STEP NOISE source is not UTF-8: {error}"))?
        } else {
            fs::read_to_string(&deck.path).map_err(|err| format!("failed to read deck: {err}"))?
        };
        // The static-contract probes run in sequence for every corpus deck.
        // Fail closed before parsing an unrelated deck: some upstream stress
        // fixtures intentionally describe enormous circuits and must only be
        // materialized by the contract that actually owns them.
        if !Self::source_has_analysis(&source, "NOISE") {
            return Err("deck has no .NOISE analysis".to_string());
        }
        if Self::contains_control_block(&source) {
            return Err(
                "deck uses a .control block; Xyce adapter does not interpret simulator scripting"
                    .to_string(),
            );
        }
        Self::reject_unsupported_source_directives(&source)?;
        let print_output = Self::canonical_print_output_request(&source, "NOISE", false)?;
        let print = print_output.as_ref().map(|request| XycePrintRequest {
            probes: request.probes.clone(),
        });
        if print_output
            .as_ref()
            .and_then(|request| request.format.as_deref())
            .is_some_and(|format| !format.eq_ignore_ascii_case("STD"))
        {
            return Err("native NOISE oracle currently requires FORMAT=STD".to_string());
        }

        let netlist = Self::parse_xyce_netlist(&source, &deck.path)
            .map_err(|err| format!("netlist parser does not yet accept this Xyce deck: {err}"))?;
        #[cfg(not(feature = "veriloga-builtins"))]
        if let Some(print) = print.as_ref() {
            if Self::noise_print_requires_generated_vbic_mechanisms(print, &netlist)? {
                return Err(
                    "NOISE output requests a named VBIC mechanism supplied by the canonical generated Verilog-A device; rebuild with the 'veriloga-builtins' feature"
                        .to_string(),
                );
            }
        }
        let (output_node, reference_node, input_source, frequencies) =
            Self::noise_analysis_for_netlist(&netlist)?;
        let steps = Self::step_commands(&netlist)?;
        let has_scalar_derivative = netlist.measurements.iter().any(|measurement| {
            measurement.analysis.eq_ignore_ascii_case("NOISE")
                && matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Derivative { .. }
                )
        });
        let has_continuous_derivative = netlist.measurements.iter().any(|measurement| {
            measurement.analysis.eq_ignore_ascii_case("NOISE_CONT")
                && matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Derivative { .. }
                )
        });
        if !steps.is_empty() && has_scalar_derivative && !has_continuous_derivative {
            return Err(
                "native scalar-only .STEP NOISE DERIV measurements are not yet qualified to Xyce precision"
                    .to_string(),
            );
        }
        if qualified_step_cont_derivative {
            Self::validate_measure_cont_step_noise_deriv_plan(
                &netlist,
                print.as_ref(),
                &frequencies,
            )?;
        }
        let use_continuous_files = netlist.options.measure_use_cont_files();
        let measurement_reference_paths = if netlist.measurements.iter().any(|measurement| {
            measurement.print_policy == crate::analysis::MeasurePrintPolicy::All
                && (measurement.analysis.eq_ignore_ascii_case("NOISE")
                    || (!use_continuous_files
                        && measurement.analysis.eq_ignore_ascii_case("NOISE_CONT")))
        }) {
            self.measurement_reference_paths(&deck.path, "ma")?
        } else {
            Vec::new()
        };
        let continuous_measurement_reference_paths = if use_continuous_files {
            self.continuous_measurement_reference_paths(&deck.path, &netlist, "NOISE_CONT", "ma")?
        } else {
            Vec::new()
        };
        if !steps.is_empty() && !continuous_measurement_reference_paths.is_empty() {
            return Err(
                ".STEP NOISE_CONT comparison requires a stepped continuous sidecar contract"
                    .to_string(),
            );
        }
        let measurement_tolerance = if qualified_step_cont_derivative {
            // Both the aggregate measurement files and the captured stdout
            // were checked by Release 7.10's file_compare.pl contract.
            XyceFileCompareTolerance::MEASURE_COMMON_DEFAULT
        } else if netlist.measurements.iter().any(|measurement| {
            (measurement.analysis.eq_ignore_ascii_case("NOISE")
                || measurement.analysis.eq_ignore_ascii_case("NOISE_CONT"))
                && matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Integ { .. }
                )
        }) {
            XyceFileCompareTolerance::MEASURE_COMMON_AC_INTEGRATION
        } else if netlist.measurements.iter().any(|measurement| {
            (measurement.analysis.eq_ignore_ascii_case("NOISE")
                || measurement.analysis.eq_ignore_ascii_case("NOISE_CONT"))
                && matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Derivative { .. }
                )
        }) {
            XyceFileCompareTolerance::MEASURE_COMMON_DERIVATIVE
        } else {
            XyceFileCompareTolerance::MEASURE_COMMON_DEFAULT
        };
        let reference_path = self
            .static_output_reference_path(&deck.path, "NOISE.prn")
            .filter(|path| path.is_file());
        if reference_path.is_none()
            && measurement_reference_paths.is_empty()
            && continuous_measurement_reference_paths.is_empty()
        {
            return Err("deck has no checked-in NOISE waveform or measurement oracle".to_string());
        }
        if reference_path.is_some() && print.is_none() {
            return Err(
                "NOISE waveform oracle requires a primary .PRINT NOISE request".to_string(),
            );
        }
        if reference_path.is_some() && !steps.is_empty() {
            return Err(
                "native .STEP NOISE waveform comparison requires a stepped waveform artifact contract"
                    .to_string(),
            );
        }

        Ok(XyceStaticNoisePlan {
            deck_path: deck.path.clone(),
            source,
            print,
            reference_path,
            measurement_reference_paths,
            continuous_measurement_reference_paths,
            gs_reference_path: qualified_step_cont_derivative.then(|| {
                self.root
                    .join("Netlists/MEASURE_CONT/STEP/DerivTestNoiseGSfile")
            }),
            measurement_tolerance,
            output_node,
            reference_node,
            input_source,
            frequencies,
            steps,
        })
    }

    #[cfg_attr(feature = "veriloga-builtins", allow(dead_code))]
    fn noise_print_requires_generated_vbic_mechanisms(
        print: &XycePrintRequest,
        netlist: &Netlist,
    ) -> Result<bool, String> {
        let device_uses_vbic = |device: &str| {
            netlist.elements.iter().any(|element| {
                if !element.name.eq_ignore_ascii_case(device) {
                    return false;
                }
                let ElementKind::Bjt { model, .. } = &element.kind else {
                    return false;
                };
                Self::find_model(&netlist.models, model).is_some_and(Self::model_is_native_vbic_bjt)
            })
        };

        for printed_probe in &print.probes {
            let mut contribution_calls = Vec::new();
            if crate::analysis::NoiseContributionProbe::parse(printed_probe).is_ok() {
                contribution_calls.push(printed_probe.clone());
            } else if let Some(expression) = Self::print_expression_inner(printed_probe) {
                let normalized_expression = expression.to_ascii_lowercase();
                if !normalized_expression.contains("dno(")
                    && !normalized_expression.contains("dni(")
                {
                    continue;
                }
                let mut collect = |call: &str| {
                    if call.get(..3).is_some_and(|prefix| {
                        prefix.eq_ignore_ascii_case("dno") || prefix.eq_ignore_ascii_case("dni")
                    }) {
                        contribution_calls.push(call.to_string());
                    }
                    Ok(1.0)
                };
                Self::evaluate_print_expression_with_probe_calls(
                    expression,
                    netlist.params.clone(),
                    &mut collect,
                )
                .map_err(|err| {
                    format!(
                        "failed to inspect NOISE print expression '{printed_probe}' for generated-device mechanisms: {err}"
                    )
                })?;
            }

            for call in contribution_calls {
                let contribution = crate::analysis::NoiseContributionProbe::parse(&call)
                    .map_err(|err| err.to_string())?;
                if contribution.mechanism.is_some() && device_uses_vbic(&contribution.device) {
                    return Ok(true);
                }
            }
        }
        Ok(false)
    }

    fn static_dc_plan_for_path(
        &self,
        deck_path: &Path,
        expression_dialect: ExpressionDialect,
    ) -> Result<XyceStaticDcPlan, String> {
        self.static_dc_plan_for_path_with_execution_dir(deck_path, expression_dialect, None)
    }

    fn static_dc_plan_for_path_with_redefinition_policy(
        &self,
        deck_path: &Path,
        expression_dialect: ExpressionDialect,
        parameter_redefinition_policy: ParameterRedefinitionPolicy,
    ) -> Result<XyceStaticDcPlan, String> {
        let source =
            fs::read_to_string(deck_path).map_err(|err| format!("failed to read deck: {err}"))?;
        self.static_dc_plan_for_source_with_execution_dir_and_redefinition_policy(
            deck_path,
            source,
            expression_dialect,
            parameter_redefinition_policy,
            None,
        )
    }

    fn static_dc_plan_for_path_with_execution_dir(
        &self,
        deck_path: &Path,
        expression_dialect: ExpressionDialect,
        execution_dir: Option<&Path>,
    ) -> Result<XyceStaticDcPlan, String> {
        let source =
            fs::read_to_string(deck_path).map_err(|err| format!("failed to read deck: {err}"))?;
        self.static_dc_plan_for_source_with_execution_dir(
            deck_path,
            source,
            expression_dialect,
            execution_dir,
        )
    }

    fn static_dc_plan_for_source_with_execution_dir(
        &self,
        deck_path: &Path,
        source: String,
        expression_dialect: ExpressionDialect,
        execution_dir: Option<&Path>,
    ) -> Result<XyceStaticDcPlan, String> {
        self.static_dc_plan_for_source_with_execution_dir_and_redefinition_policy(
            deck_path,
            source,
            expression_dialect,
            ParameterRedefinitionPolicy::UseLast,
            execution_dir,
        )
    }

    fn static_dc_plan_for_source_with_execution_dir_and_redefinition_policy(
        &self,
        deck_path: &Path,
        source: String,
        expression_dialect: ExpressionDialect,
        parameter_redefinition_policy: ParameterRedefinitionPolicy,
        execution_dir: Option<&Path>,
    ) -> Result<XyceStaticDcPlan, String> {
        if Self::contains_control_block(&source) {
            return Err(
                "deck uses a .control block; Xyce adapter does not interpret simulator scripting"
                    .to_string(),
            );
        }
        Self::reject_unsupported_source_directives(&source)?;

        let print_output = Self::single_dc_or_file_output_request(&source).or_else(|err| {
            if Self::validate_no_output_dc_wrapper_source(&source).is_ok() {
                Ok(XycePrintOutputRequest {
                    format: None,
                    file: None,
                    probes: Vec::new(),
                })
            } else {
                Err(err)
            }
        })?;
        let print = XycePrintRequest {
            probes: print_output.probes,
        };
        let netlist = Self::parse_netlist_with_expression_dialect_policy_and_execution_dir(
            &source,
            deck_path,
            expression_dialect,
            parameter_redefinition_policy,
            execution_dir,
        )
        .map_err(|err| format!("netlist parser does not yet accept this Xyce deck: {err}"))?;
        let diagnostics = netlist.diagnostics.clone();
        let dc_data = Self::dc_data_sweep_for_source(&source, &netlist)?;
        let dc = match &dc_data {
            Some(dc_data) => Self::synthetic_dc_data_sweep(dc_data)?,
            None => Self::single_dc_sweep(&netlist)?,
        };
        let steps = Self::step_commands(&netlist)?;
        if let Some(dc_data) = &dc_data {
            Self::validate_static_dc_data_contract(&netlist, dc_data, &print)?;
        } else {
            Self::validate_static_dc_contract(&netlist, &dc, &print)?;
        }

        Ok(XyceStaticDcPlan {
            deck_path: deck_path.to_path_buf(),
            execution_dir: execution_dir.map(Path::to_path_buf),
            source,
            expression_dialect,
            parameter_redefinition_policy,
            print,
            print_format: print_output.format,
            dc,
            dc_data,
            steps,
            diagnostics,
        })
    }

    fn validate_native_static_prn_wrapper_contract(
        &self,
        contract: XyceStaticDcContract,
        plan: &XyceStaticDcPlan,
    ) -> Result<(), String> {
        if matches!(contract, XyceStaticDcContract::WrapperResistorDefault) {
            Self::validate_resistor_default_wrapper_diagnostics(plan)?;
        }

        Ok(())
    }

    fn validate_resistor_default_wrapper_diagnostics(
        plan: &XyceStaticDcPlan,
    ) -> Result<(), String> {
        let default_warning_count = plan
            .diagnostics
            .iter()
            .filter(|diagnostic| {
                diagnostic
                    .code
                    .eq_ignore_ascii_case("xyce_resistor_missing_value")
                    || diagnostic
                        .code
                        .eq_ignore_ascii_case("xyce_resistor_model_missing_value")
            })
            .count();
        if default_warning_count == 0 {
            return Err(
                "wrapper-origin resistor default contract requires native value-default diagnostics"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn native_static_prn_wrapper_contract(
        relative_path: &str,
        deck_path: &Path,
        source: &str,
    ) -> Result<XyceStaticDcContract, String> {
        if Self::is_native_gnuplot_splot_wrapper_candidate(source) {
            return Ok(XyceStaticDcContract::WrapperGnuplotSplot);
        }

        if Self::is_native_csv_dc_wrapper_candidate(relative_path, source) {
            Self::validate_csv_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperCsv);
        }

        if Self::is_native_csd_dc_wrapper_candidate(relative_path, source) {
            Self::validate_csd_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperCsd);
        }

        if Self::is_native_file_only_prn_wrapper_candidate(relative_path, source) {
            Self::validate_file_only_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperFilePrn);
        }

        if Self::is_native_raw_wrapper_candidate_path(relative_path) {
            Self::validate_raw_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperRaw);
        }

        if Self::is_native_no_output_dc_wrapper_candidate(relative_path, source) {
            Self::validate_no_output_dc_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperNoOutput);
        }

        if Self::is_native_default_prn_wrapper_candidate_path(relative_path)
            || Self::is_native_multiplicity_static_prn_wrapper_candidate_path(relative_path)
        {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_hspice_math_wrapper_candidate(relative_path, source) {
            Self::validate_hspice_math_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperHspiceMath);
        }

        if Self::is_native_hspice_random_wrapper_candidate(relative_path, source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_resistor_default_wrapper_candidate(relative_path, source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperResistorDefault);
        }

        if Self::is_native_resistor_temperature_step_wrapper_candidate(relative_path, source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_semiconductor_resistor_step_wrapper_candidate(relative_path, source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_top_level_execution_dir_wrapper_candidate(deck_path, source) {
            return Ok(XyceStaticDcContract::WrapperTopLevelExecutionDir);
        }

        if Self::is_native_absolute_inc_lib_wrapper_candidate(deck_path, source) {
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_step_data_wrapper_candidate(source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_dc_data_table_wrapper_candidate(source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_empty_wildcard_lead_current_wrapper_candidate(deck_path, source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_subcircuit_node_probe_wrapper_candidate(source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        if Self::is_native_voltage_accessor_wrapper_candidate(source) {
            Self::validate_default_prn_wrapper_source(source)?;
            return Ok(XyceStaticDcContract::WrapperVoltageAccessor);
        }

        if Self::is_native_plain_static_dc_prn_wrapper_candidate(deck_path, source) {
            return Ok(XyceStaticDcContract::WrapperDefault);
        }

        Err(Self::upstream_wrapper_required_reason().to_string())
    }

    fn is_native_default_prn_wrapper_candidate_path(relative_path: &str) -> bool {
        Self::normalize_manifest_key(relative_path).starts_with("netlists/output/dc/")
    }

    fn is_native_csv_dc_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        if !Self::normalize_manifest_key(relative_path).starts_with("netlists/output/dc/") {
            return false;
        }
        Self::dc_print_output_requests(source).is_ok_and(|requests| {
            requests.into_iter().any(|request| {
                request.file.is_none()
                    && request
                        .format
                        .as_deref()
                        .is_some_and(|format| format.eq_ignore_ascii_case("CSV"))
            })
        })
    }

    fn is_native_csd_dc_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        if !Self::normalize_manifest_key(relative_path).starts_with("netlists/output/dc/") {
            return false;
        }
        Self::dc_print_output_requests(source).is_ok_and(|requests| {
            requests.into_iter().any(|request| {
                request.file.is_none()
                    && request
                        .format
                        .as_deref()
                        .is_some_and(|format| format.eq_ignore_ascii_case("PROBE"))
            })
        })
    }

    fn is_native_no_output_dc_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        matches!(
            Self::normalize_manifest_key(relative_path).as_str(),
            "netlists/output/dc/dc-noprn.cir"
        ) && Self::validate_no_output_dc_wrapper_source(source).is_ok()
    }

    fn is_native_file_only_prn_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        if !Self::normalize_manifest_key(relative_path).starts_with("netlists/output/dc/") {
            return false;
        }
        Self::dc_print_output_requests(source).is_ok_and(|requests| {
            !requests.is_empty()
                && requests.iter().all(|request| {
                    request.file.is_some()
                        && Self::dc_print_format_is_prn_compatible(
                            request.format.as_deref().unwrap_or("STD"),
                        )
                })
        })
    }

    fn is_native_raw_wrapper_candidate_path(relative_path: &str) -> bool {
        let relative_path = Self::normalize_manifest_key(relative_path);
        relative_path.starts_with("netlists/output/dc/")
            && relative_path
                .rsplit('/')
                .next()
                .is_some_and(|file_name| file_name.contains("-raw"))
    }

    fn is_native_output_override_wrapper_candidate_path(relative_path: &str) -> bool {
        Self::normalize_manifest_key(relative_path).starts_with("netlists/output/dasho/")
    }

    fn is_native_multiplicity_static_prn_wrapper_candidate_path(relative_path: &str) -> bool {
        Self::normalize_manifest_key(relative_path).starts_with("netlists/multiplicity_factor/")
    }

    fn is_native_hspice_math_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        let relative_path = Self::normalize_manifest_key(relative_path);
        let normalized_source = source.to_ascii_lowercase();
        relative_path.starts_with("netlists/parser/")
            && normalized_source.contains("-hspice-ext math")
            && normalized_source.contains("-hspice-ext all")
    }

    fn is_native_hspice_random_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        let relative_path = Self::normalize_manifest_key(relative_path);
        let normalized_source = source.to_ascii_lowercase();
        relative_path.starts_with("netlists/parser/")
            && ["agauss(", "gauss(", "aunif(", "unif(", "rand("]
                .iter()
                .any(|operator| normalized_source.contains(operator))
    }

    fn is_native_resistor_default_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        let relative_path = Self::normalize_manifest_key(relative_path);
        let normalized_source = source.to_ascii_lowercase();
        relative_path.starts_with("netlists/resistor/")
            && normalized_source.contains("default to 1000")
            && normalized_source.contains("warning")
    }

    fn is_native_resistor_temperature_step_wrapper_candidate(
        relative_path: &str,
        source: &str,
    ) -> bool {
        let relative_path = Self::normalize_manifest_key(relative_path);
        if !relative_path.starts_with("netlists/resistor_td/") {
            return false;
        }

        let mut has_step_temp = false;
        let mut has_tce = false;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line)
                .trim()
                .to_ascii_lowercase();
            if trimmed.starts_with(".step ") && trimmed.contains("temp") {
                has_step_temp = true;
            }
            if trimmed.contains("tce") {
                has_tce = true;
            }
        }
        has_step_temp && has_tce
    }

    fn is_native_semiconductor_resistor_step_wrapper_candidate(
        relative_path: &str,
        source: &str,
    ) -> bool {
        let relative_path = Self::normalize_manifest_key(relative_path);
        if relative_path != "netlists/semic_resistor/semic_resistor_step.cir" {
            return false;
        }

        let mut has_resistor_geometry_step = false;
        let mut has_resistor_default_step = false;
        let mut has_resistor_model = false;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line)
                .trim()
                .to_ascii_lowercase();
            if trimmed.starts_with(".step ") {
                has_resistor_geometry_step |= trimmed.contains("r1:l") || trimmed.contains("r2:l");
                has_resistor_default_step |= trimmed
                    .split_whitespace()
                    .nth(1)
                    .is_some_and(|target| target.eq_ignore_ascii_case("r3"));
            }
            if trimmed.starts_with(".model ")
                && trimmed
                    .split_whitespace()
                    .nth(2)
                    .is_some_and(|model_type| model_type.eq_ignore_ascii_case("r"))
            {
                has_resistor_model = true;
            }
        }

        has_resistor_geometry_step && has_resistor_default_step && has_resistor_model
    }

    fn is_native_top_level_execution_dir_wrapper_candidate(deck_path: &Path, source: &str) -> bool {
        Self::logical_netlist_lines(source)
            .iter()
            .all(|line| Self::strip_netlist_comment(line).trim().is_empty())
            && Self::top_level_execution_deck_path(deck_path).is_ok_and(|path| path.is_file())
    }

    fn top_level_execution_deck_path(deck_path: &Path) -> Result<PathBuf, String> {
        let file_name = deck_path
            .file_name()
            .ok_or_else(|| "wrapper deck has no filename".to_string())?;
        let parent = deck_path
            .parent()
            .ok_or_else(|| "wrapper deck has no parent directory".to_string())?;
        Ok(parent.join("top_level").join(file_name))
    }

    fn is_native_absolute_inc_lib_wrapper_candidate(deck_path: &Path, source: &str) -> bool {
        if !Self::source_has_absolute_inc_lib_wrapper_bindings(source) {
            return false;
        }
        let Ok(print) = Self::single_dc_print_request(source) else {
            return false;
        };
        let Ok(netlist) = Self::parse_xyce_netlist(source, deck_path) else {
            return false;
        };
        let Ok(dc) = Self::single_dc_sweep(&netlist) else {
            return false;
        };
        Self::validate_static_dc_contract(&netlist, &dc, &print).is_ok()
    }

    fn source_has_absolute_inc_lib_wrapper_bindings(source: &str) -> bool {
        let mut has_absolute_include = false;
        let mut has_absolute_library = false;
        for line in Self::logical_netlist_lines(source) {
            let stripped = Self::strip_netlist_comment(&line);
            let trimmed = stripped.trim();
            if let Some(filename) = crate::netlist::parse_include_directive(trimmed)
                && Path::new(&filename).is_absolute()
            {
                has_absolute_include = true;
            }
            if let Some((filename, section)) = crate::netlist::parse_lib_directive(trimmed)
                && Path::new(&filename).is_absolute()
                && section.is_some_and(|section| section.eq_ignore_ascii_case("LIB_ABS"))
            {
                has_absolute_library = true;
            }
        }
        has_absolute_include && has_absolute_library
    }

    fn is_native_step_data_wrapper_candidate(source: &str) -> bool {
        let mut has_data_table = false;
        let mut has_step_data = false;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line)
                .trim()
                .to_ascii_lowercase();
            if trimmed.starts_with(".data ") {
                has_data_table = true;
            }
            if trimmed.starts_with(".step ") && trimmed.contains("data") && trimmed.contains('=') {
                has_step_data = true;
            }
        }
        has_data_table && has_step_data
    }

    fn is_native_dc_data_table_wrapper_candidate(source: &str) -> bool {
        Self::dc_data_table_names(source).is_ok_and(|names| !names.is_empty())
    }

    fn is_native_gnuplot_splot_wrapper_candidate(source: &str) -> bool {
        if Self::wrapper_source_has_extra_output_analysis(source) {
            return false;
        }
        let Ok((primary, side)) = Self::gnuplot_splot_print_pair(source) else {
            return false;
        };
        primary.probes == side.probes
    }

    fn is_native_empty_wildcard_lead_current_wrapper_candidate(
        deck_path: &Path,
        source: &str,
    ) -> bool {
        if Self::validate_default_prn_wrapper_source(source).is_err() {
            return false;
        }
        let Ok(print) = Self::single_dc_print_request(source) else {
            return false;
        };
        let wildcard_probes = print
            .probes
            .iter()
            .filter_map(|probe| Self::parse_lead_current_probe(probe))
            .filter(|probe| probe.element_name == "*")
            .collect::<Vec<_>>();
        if wildcard_probes.is_empty() {
            return false;
        }
        let Ok(netlist) = Self::parse_xyce_netlist(source, deck_path) else {
            return false;
        };

        wildcard_probes
            .iter()
            .all(|probe| Self::lead_current_probe_is_omitted_empty_wildcard(&netlist, probe))
    }

    fn is_native_subcircuit_node_probe_wrapper_candidate(source: &str) -> bool {
        if Self::validate_default_prn_wrapper_source(source).is_err() {
            return false;
        }
        let Ok(print) = Self::single_dc_print_request(source) else {
            return false;
        };

        print
            .probes
            .iter()
            .any(|probe| Self::print_probe_contains_subcircuit_node_voltage_probe(probe))
    }

    fn print_probe_contains_subcircuit_node_voltage_probe(probe: &str) -> bool {
        let expression = Self::print_expression_inner(probe).unwrap_or(probe);
        let normalized = Self::normalize_probe(expression);
        if Self::voltage_probe_targets_subcircuit_node(&normalized) {
            return true;
        }

        let context = crate::netlist::ParamContext::new();
        let mut found = false;
        let _ = Self::rewrite_print_expression_calls_maybe(expression, context, |call| {
            if Self::voltage_probe_targets_subcircuit_node(&Self::normalize_probe(call)) {
                found = true;
            }
            Ok(0.0)
        });
        found
    }

    fn voltage_probe_targets_subcircuit_node(normalized_probe: &str) -> bool {
        Self::parse_voltage_probe(normalized_probe).is_some_and(|probe| {
            Self::node_name_targets_subcircuit_node(&probe.node_pos)
                || probe
                    .node_neg
                    .as_deref()
                    .is_some_and(Self::node_name_targets_subcircuit_node)
        })
    }

    fn node_name_targets_subcircuit_node(node: &str) -> bool {
        node.contains(':') || Self::node_name_uses_period_hierarchy(node)
    }

    fn node_name_uses_period_hierarchy(node: &str) -> bool {
        let Some((first_segment, _)) = node.split_once('.') else {
            return false;
        };
        first_segment.len() > 1 && first_segment.starts_with('x')
    }

    fn is_native_voltage_accessor_wrapper_candidate(source: &str) -> bool {
        if Self::validate_default_prn_wrapper_source(source).is_err() {
            return false;
        }
        let Ok(print) = Self::single_dc_print_request(source) else {
            return false;
        };

        print.probes.iter().any(|probe| {
            let expression = Self::print_expression_inner(probe).unwrap_or(probe);
            let normalized = Self::normalize_probe(expression);
            Self::parse_voltage_probe(&normalized)
                .is_some_and(|probe| probe.accessor != XyceVoltageAccessor::Value)
                || Self::print_expression_contains_voltage_accessor_call(expression)
        })
    }

    fn is_native_plain_static_dc_prn_wrapper_candidate(deck_path: &Path, source: &str) -> bool {
        if Self::validate_plain_static_dc_prn_wrapper_source(source).is_err() {
            return false;
        }
        let Ok(print) = Self::single_dc_print_request(source) else {
            return false;
        };
        let Ok(netlist) = Self::parse_xyce_netlist(source, deck_path) else {
            return false;
        };
        if Self::validate_plain_static_dc_prn_wrapper_netlist(&netlist).is_err() {
            return false;
        }
        let Ok(dc) = Self::single_dc_sweep(&netlist) else {
            return false;
        };
        Self::validate_static_dc_contract(&netlist, &dc, &print).is_ok()
    }

    fn validate_plain_static_dc_prn_wrapper_source(source: &str) -> Result<(), String> {
        Self::validate_default_prn_wrapper_source_with_format_mode(source, true)?;

        let print = Self::single_dc_print_request(source)?;
        for probe in &print.probes {
            let normalized = Self::normalize_probe(probe);
            if normalized.contains('*') || normalized.starts_with("w(") {
                return Err(format!(
                    "wrapper-origin plain static DC contract does not cover wildcard or power-style probe '{probe}'"
                ));
            }
        }

        let mut dc_count = 0usize;
        let mut subckt_count = 0usize;
        let mut ends_count = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if !command.starts_with('.') {
                continue;
            }
            match command.to_ascii_lowercase().as_str() {
                ".dc" => dc_count += 1,
                ".model" => {
                    Self::validate_plain_static_dc_prn_wrapper_model_type(&trimmed)?;
                }
                ".subckt" => subckt_count += 1,
                ".ends" => ends_count += 1,
                ".print" | ".measure" | ".meas" | ".op" | ".step" | ".param" | ".global_param"
                | ".func" | ".options" | ".end" => {}
                other => {
                    return Err(format!(
                        "wrapper-origin plain static DC contract does not cover {other} directives"
                    ));
                }
            }
        }

        match dc_count {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin plain static DC contract requires exactly one .DC statement, found none"
                    .to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin plain static DC contract requires exactly one .DC statement, found {dc_count}"
            )),
        }?;

        if subckt_count > 1 {
            return Err(format!(
                "wrapper-origin plain static DC contract currently covers at most one .SUBCKT statement, found {subckt_count}"
            ));
        }
        if subckt_count != ends_count {
            return Err(format!(
                "wrapper-origin plain static DC contract requires balanced .SUBCKT/.ENDS statements, found {subckt_count}/{ends_count}"
            ));
        }
        Ok(())
    }

    fn validate_plain_static_dc_prn_wrapper_model_type(model_line: &str) -> Result<(), String> {
        let Some(model_type) = model_line.split_whitespace().nth(2) else {
            return Err(
                "wrapper-origin plain static DC contract requires .MODEL statements to include a model type"
                    .to_string(),
            );
        };
        let normalized = model_type
            .trim_matches(|ch| matches!(ch, '(' | ')' | ','))
            .to_ascii_uppercase();
        if matches!(
            normalized.as_str(),
            "NMOS" | "PMOS" | "D" | "DIODE" | "R" | "RES" | "RESISTOR"
        ) {
            return Ok(());
        }
        Err(format!(
            "wrapper-origin plain static DC contract does not yet cover .MODEL type {model_type}"
        ))
    }

    fn validate_plain_static_dc_prn_wrapper_netlist(netlist: &Netlist) -> Result<(), String> {
        for model in &netlist.models {
            if !matches!(
                model.model_type.to_ascii_uppercase().as_str(),
                "NMOS" | "PMOS" | "D" | "DIODE" | "R" | "RES" | "RESISTOR"
            ) {
                return Err(format!(
                    "wrapper-origin plain static DC contract does not yet cover parsed model type {}",
                    model.model_type
                ));
            }
            if matches!(
                model.model_type.to_ascii_uppercase().as_str(),
                "D" | "DIODE"
            ) && !Self::model_is_native_legacy_diode(model)
            {
                return Err(format!(
                    "wrapper-origin plain static DC contract does not yet cover advanced diode model type {}",
                    model.model_type
                ));
            }
            if matches!(
                model.model_type.to_ascii_uppercase().as_str(),
                "R" | "RES" | "RESISTOR"
            ) && !Self::model_is_native_legacy_resistor(model)
            {
                return Err(format!(
                    "wrapper-origin plain static DC contract does not yet cover advanced resistor model type {}",
                    model.model_type
                ));
            }
        }
        if netlist.models.len() > 1
            && !Self::models_form_single_binned_native_mos_family(&netlist.models)
            && !netlist
                .models
                .iter()
                .all(Self::model_is_native_legacy_resistor)
        {
            return Err(format!(
                "wrapper-origin plain static DC contract currently covers at most one parsed model unless all models form one binned native MOS model family, found {}",
                netlist.models.len()
            ));
        }
        if netlist.subcircuits.len() > 1 {
            return Err(format!(
                "wrapper-origin plain static DC contract currently covers at most one parsed subcircuit, found {}",
                netlist.subcircuits.len()
            ));
        }
        Ok(())
    }

    fn models_form_single_binned_native_mos_family(models: &[crate::netlist::ModelDef]) -> bool {
        if models.len() < 2 {
            return false;
        }
        let Some(first_base) = Self::binned_model_base_name(&models[0].name) else {
            return false;
        };
        let first_type = models[0].model_type.to_ascii_uppercase();
        if !matches!(first_type.as_str(), "NMOS" | "PMOS") {
            return false;
        }
        models.iter().all(|model| {
            model.model_type.eq_ignore_ascii_case(&first_type)
                && Self::binned_model_base_name(&model.name)
                    .is_some_and(|base| base.eq_ignore_ascii_case(first_base))
                && Self::model_has_numeric_geometry_bin_range(model)
        })
    }

    fn binned_model_base_name(name: &str) -> Option<&str> {
        let (base, suffix) = name.split_once('.')?;
        (!base.is_empty() && !suffix.is_empty()).then_some(base)
    }

    fn model_has_numeric_geometry_bin_range(model: &crate::netlist::ModelDef) -> bool {
        const BIN_PARAMS: [&str; 6] = ["LMIN", "LMAX", "WMIN", "WMAX", "NFINMIN", "NFINMAX"];
        model
            .params
            .iter()
            .any(|(name, _)| BIN_PARAMS.iter().any(|bin| name.eq_ignore_ascii_case(bin)))
    }

    fn upstream_wrapper_required_reason() -> &'static str {
        "upstream wrapper semantics are required; RSPICE-HARNESS-MANIFEST.tsv records the removed .cir.sh sidecar contract"
    }

    fn validate_hspice_math_wrapper_source(source: &str) -> Result<(), String> {
        Self::validate_default_prn_wrapper_source(source)?;
        let checks = [
            ("**", "HSPICE exponentiation operator '**'"),
            ("^", "HSPICE exponentiation operator '^'"),
            ("&&", "HSPICE logical AND operator '&&'"),
            ("||", "HSPICE logical OR operator '||'"),
            ("?", "ternary conditional operator '?'"),
            (":", "ternary conditional separator ':'"),
        ];
        for (needle, label) in checks {
            if !source.contains(needle) {
                return Err(format!(
                    "wrapper-origin HSPICE math contract requires {label}"
                ));
            }
        }
        Ok(())
    }

    fn validate_default_prn_wrapper_source(source: &str) -> Result<(), String> {
        Self::validate_default_prn_wrapper_source_with_format_mode(source, false)
    }

    fn validate_scalar_dc_measurement_wrapper_source(source: &str) -> Result<(), String> {
        let mut primary_print_count = 0usize;
        let mut dc_measurement_count = 0usize;
        let mut dc_continuous_measurement_count = 0usize;
        let mut use_continuous_files = None;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") {
                let tokens = Self::split_print_fields(&trimmed)?;
                let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
                if !Self::validate_default_prn_print_tokens(&token_refs, false)? {
                    primary_print_count += 1;
                }
                continue;
            }
            if command.eq_ignore_ascii_case(".measure") || command.eq_ignore_ascii_case(".meas") {
                let fields = Self::split_print_fields(&trimmed)?;
                let analysis = fields.get(1).map(String::as_str).unwrap_or_default();
                if !analysis.eq_ignore_ascii_case("DC") && !analysis.eq_ignore_ascii_case("DC_CONT")
                {
                    return Err(format!(
                        "scalar DC measurement artifact contract does not cover directive '{trimmed}'"
                    ));
                }
                if analysis.eq_ignore_ascii_case("DC") {
                    dc_measurement_count += 1;
                } else {
                    dc_continuous_measurement_count += 1;
                }
                continue;
            }
            if command.eq_ignore_ascii_case(".options") || command.eq_ignore_ascii_case(".option") {
                let fields = Self::split_print_fields(&trimmed)?;
                if fields
                    .get(1)
                    .is_some_and(|group| group.eq_ignore_ascii_case("MEASURE"))
                {
                    for (index, field) in fields.iter().enumerate().skip(2) {
                        let (name, value) = if let Some((name, value)) = field.split_once('=') {
                            (name, Some(value))
                        } else if field.eq_ignore_ascii_case("USE_CONT_FILES")
                            && fields.get(index + 1).is_some_and(|field| field == "=")
                        {
                            (field.as_str(), fields.get(index + 2).map(String::as_str))
                        } else {
                            (field.as_str(), None)
                        };
                        if name.eq_ignore_ascii_case("USE_CONT_FILES") {
                            use_continuous_files = match value {
                                Some("0") => Some(false),
                                Some("1") => Some(true),
                                _ => None,
                            };
                        }
                    }
                }
                continue;
            }
            // Xyce parses .FFT in every deck but activates it only for
            // transient analysis. The typed netlist parser below remains
            // responsible for validating the complete directive.
            if command.eq_ignore_ascii_case(".fft") {
                continue;
            }
            if Self::is_extra_wrapper_output_analysis_command(command) {
                return Err(format!(
                    "scalar DC measurement artifact contract does not cover {command} directives"
                ));
            }
        }
        if primary_print_count != 1 {
            return Err(format!(
                "scalar DC measurement artifact contract requires one primary .PRINT DC statement, found {primary_print_count}"
            ));
        }
        if dc_measurement_count == 0
            && !(dc_continuous_measurement_count > 0 && use_continuous_files == Some(false))
        {
            return Err(
                "DC measurement artifact contract requires a .MEASURE DC statement or an explicit USE_CONT_FILES=0 aggregate with at least one .MEASURE DC_CONT statement"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn validate_no_output_dc_wrapper_source(source: &str) -> Result<(), String> {
        let mut has_dc_or_op = false;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") || command.eq_ignore_ascii_case(".probe") {
                return Err(format!(
                    "wrapper-origin no-output DC contract does not cover {command} directives"
                ));
            }
            if command.eq_ignore_ascii_case(".dc") || command.eq_ignore_ascii_case(".op") {
                has_dc_or_op = true;
                continue;
            }
            if Self::is_extra_wrapper_output_analysis_command(command) {
                return Err(format!(
                    "wrapper-origin no-output DC contract does not cover {command} directives"
                ));
            }
        }

        if has_dc_or_op {
            Ok(())
        } else {
            Err("wrapper-origin no-output DC contract requires a .DC or .OP analysis".to_string())
        }
    }

    fn validate_default_prn_wrapper_source_with_format_mode(
        source: &str,
        allow_wrapper_probe_primary_prn: bool,
    ) -> Result<(), String> {
        let mut primary_print_count = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") {
                let tokens = Self::split_print_fields(&trimmed)?;
                let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
                if !Self::validate_default_prn_print_tokens(
                    &token_refs,
                    allow_wrapper_probe_primary_prn,
                )? {
                    primary_print_count += 1;
                }
                continue;
            }
            if command.eq_ignore_ascii_case(".measure") || command.eq_ignore_ascii_case(".meas") {
                let fields = Self::split_print_fields(&trimmed)?;
                if fields
                    .get(1)
                    .is_some_and(|field| field.eq_ignore_ascii_case("DC"))
                    && fields.get(3).is_some_and(|field| {
                        field.eq_ignore_ascii_case("EQN")
                            || field.eq_ignore_ascii_case("PARAM")
                            || field.to_ascii_uppercase().starts_with("PARAM=")
                    })
                {
                    continue;
                }
                return Err(format!(
                    "wrapper-origin default .prn contract does not cover {command} directive '{trimmed}'"
                ));
            }
            if Self::is_extra_wrapper_output_analysis_command(command) {
                return Err(format!(
                    "wrapper-origin default .prn contract does not cover {command} directives"
                ));
            }
        }

        match primary_print_count {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin default .prn contract requires one primary .PRINT statement"
                    .to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin default .prn contract requires one primary .PRINT statement, found {primary_print_count}"
            )),
        }
    }

    fn validate_default_prn_print_tokens(
        tokens: &[&str],
        allow_wrapper_probe_primary_prn: bool,
    ) -> Result<bool, String> {
        let Some(analysis) = tokens.get(1) else {
            return Err("wrapper-origin .PRINT statement has no analysis type".to_string());
        };
        if !analysis.eq_ignore_ascii_case("DC") {
            return Err(format!(
                "wrapper-origin default .prn contract only covers .PRINT DC, got .PRINT {analysis}"
            ));
        }

        let mut index = 2usize;
        let mut has_file_output = false;
        while index < tokens.len() {
            if let Some((raw_key, raw_value, consumed)) =
                Self::print_option_assignment(tokens, index)
            {
                let key = raw_key.trim().to_ascii_lowercase();
                let value = raw_value.trim().trim_matches(['"', '\'']);
                match key.as_str() {
                    "file" => {
                        has_file_output = true;
                    }
                    "format" if Self::dc_print_format_is_prn_compatible(value) => {}
                    "format"
                        if allow_wrapper_probe_primary_prn
                            && value.eq_ignore_ascii_case("PROBE") => {}
                    "format" => {
                        return Err(format!(
                            "wrapper-origin default .prn contract does not cover FORMAT={value}"
                        ));
                    }
                    _ => {}
                }
                index += consumed;
                continue;
            }
            index += 1;
        }

        Ok(has_file_output)
    }

    fn validate_csv_wrapper_source(source: &str) -> Result<(), String> {
        let mut primary_print_count = 0usize;
        for request in Self::dc_print_output_requests(source)? {
            let format = request.format.as_deref().unwrap_or("STD");
            if request.file.is_some() {
                return Err(format!(
                    "wrapper-origin CSV contract does not cover FILE= side output with FORMAT={format}"
                ));
            }
            if !format.eq_ignore_ascii_case("CSV") {
                return Err(format!(
                    "wrapper-origin CSV contract does not cover primary .PRINT DC FORMAT={format}"
                ));
            }
            primary_print_count += 1;
        }

        match primary_print_count {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin CSV contract requires one primary .PRINT DC statement".to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin CSV contract requires one primary .PRINT DC statement, found {primary_print_count}"
            )),
        }
    }

    fn validate_csd_wrapper_source(source: &str) -> Result<(), String> {
        let mut primary_print_count = 0usize;
        for request in Self::dc_print_output_requests(source)? {
            let format = request.format.as_deref().unwrap_or("STD");
            if request.file.is_some() {
                return Err(format!(
                    "wrapper-origin CSDF contract does not cover FILE= side output with FORMAT={format}"
                ));
            }
            if !format.eq_ignore_ascii_case("PROBE") {
                return Err(format!(
                    "wrapper-origin CSDF contract does not cover primary .PRINT DC FORMAT={format}"
                ));
            }
            primary_print_count += 1;
        }

        match primary_print_count {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin CSDF contract requires one primary .PRINT DC statement".to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin CSDF contract requires one primary .PRINT DC statement, found {primary_print_count}"
            )),
        }
    }

    fn validate_file_only_prn_wrapper_source(source: &str) -> Result<(), String> {
        let requests = Self::dc_print_output_requests(source)?;
        if requests.is_empty() {
            return Err(
                "wrapper-origin file-output contract requires at least one .PRINT DC statement"
                    .to_string(),
            );
        }

        for request in requests {
            let format = request.format.as_deref().unwrap_or("STD");
            if request.file.is_none() {
                return Err(format!(
                    "wrapper-origin file-output contract does not cover primary .PRINT DC FORMAT={format}"
                ));
            }
            if !Self::dc_print_format_is_prn_compatible(format) {
                return Err(format!(
                    "wrapper-origin file-output contract does not cover FILE= side output with FORMAT={format}"
                ));
            }
        }

        Ok(())
    }

    fn validate_raw_wrapper_source(source: &str) -> Result<(), String> {
        let mut primary_print_count = 0usize;
        for request in Self::dc_print_output_requests(source)? {
            let format = request.format.as_deref().unwrap_or("STD");
            if request.file.is_some() {
                return Err(format!(
                    "wrapper-origin RAW contract does not cover FILE= side output with FORMAT={format}"
                ));
            }
            let supported_format =
                format.eq_ignore_ascii_case("RAW") || format.eq_ignore_ascii_case("STD");
            if !supported_format {
                return Err(format!(
                    "wrapper-origin RAW contract does not cover primary .PRINT DC FORMAT={format}"
                ));
            }
            primary_print_count += 1;
        }

        match primary_print_count {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin RAW contract requires one primary .PRINT DC statement".to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin RAW contract requires one primary .PRINT DC statement, found {primary_print_count}"
            )),
        }
    }

    fn validate_native_static_prn_tran_wrapper_contract(source: &str) -> Result<(), String> {
        Self::validate_native_static_prn_tran_wrapper_contract_with_format_mode(source, false)
    }

    fn validate_native_noindex_header_tran_wrapper_contract(source: &str) -> Result<(), String> {
        Self::validate_native_static_prn_tran_wrapper_contract(source)?;
        let request = Self::single_tran_print_output_request(source)?;
        let format = request.format.as_deref().ok_or_else(|| {
            "wrapper-origin NOINDEX header contract requires .PRINT TRAN FORMAT=NOINDEX".to_string()
        })?;
        if !format.eq_ignore_ascii_case("NOINDEX") {
            return Err(format!(
                "wrapper-origin NOINDEX header contract requires .PRINT TRAN FORMAT=NOINDEX, got FORMAT={format}"
            ));
        }
        Ok(())
    }

    fn validate_native_static_prn_tran_wrapper_contract_with_format_mode(
        source: &str,
        allow_wrapper_probe_primary_prn: bool,
    ) -> Result<(), String> {
        let mut primary_tran_print_count = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") {
                let tokens = Self::split_print_fields(&trimmed)?;
                let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
                let Some(analysis) = token_refs.get(1).copied() else {
                    return Err("wrapper-origin .PRINT statement has no analysis type".to_string());
                };
                if !analysis.eq_ignore_ascii_case("TRAN") {
                    return Err(format!(
                        "wrapper-origin transient .prn contract does not cover .PRINT {analysis}"
                    ));
                }
                let mut has_file_output = false;
                let mut has_probe = false;
                let mut index = 2usize;
                while index < token_refs.len() {
                    if let Some((raw_key, raw_value, consumed)) =
                        Self::print_option_assignment(&token_refs, index)
                    {
                        let value = raw_value.trim().trim_matches(['"', '\'']);
                        match raw_key.trim().to_ascii_lowercase().as_str() {
                            "file" => has_file_output = true,
                            "format" => {
                                if !(Self::tran_print_format_is_prn_compatible(value)
                                    || allow_wrapper_probe_primary_prn
                                        && value.eq_ignore_ascii_case("PROBE"))
                                {
                                    return Err(format!(
                                        "wrapper-origin transient .prn contract does not cover .PRINT TRAN FORMAT={value}"
                                    ));
                                }
                            }
                            _ => {}
                        }
                        index += consumed;
                        continue;
                    }
                    let normalized = token_refs[index].to_ascii_lowercase();
                    if !Self::is_print_option_token(&normalized) {
                        has_probe = true;
                    }
                    index += 1;
                }
                if has_probe && !has_file_output {
                    primary_tran_print_count += 1;
                }
                continue;
            }
            if command.eq_ignore_ascii_case(".measure") || command.eq_ignore_ascii_case(".meas") {
                if Self::is_ignorable_wrapper_tran_measure_side_output(&trimmed)? {
                    continue;
                }
                let fields = Self::split_print_fields(&trimmed)?;
                if fields
                    .get(1)
                    .is_some_and(|field| field.eq_ignore_ascii_case("TRAN"))
                    && fields.get(3).is_some_and(|field| {
                        field.eq_ignore_ascii_case("EQN")
                            || field.eq_ignore_ascii_case("PARAM")
                            || field.to_ascii_uppercase().starts_with("PARAM=")
                    })
                {
                    continue;
                }
                return Err(format!(
                    "wrapper-origin transient .prn contract does not cover {command} directives"
                ));
            }
            if Self::is_extra_wrapper_tran_output_analysis_command(command) {
                return Err(format!(
                    "wrapper-origin transient .prn contract does not cover {command} directives"
                ));
            }
        }

        match primary_tran_print_count {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin transient .prn contract requires one primary .PRINT TRAN statement"
                    .to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin transient .prn contract requires one primary .PRINT TRAN statement, found {primary_tran_print_count}"
            )),
        }
    }

    fn validate_native_static_csv_tran_wrapper_contract(source: &str) -> Result<(), String> {
        let mut primary_tran_print_count = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") {
                let tokens = Self::split_print_fields(&trimmed)?;
                let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
                let Some(analysis) = token_refs.get(1).copied() else {
                    return Err("wrapper-origin .PRINT statement has no analysis type".to_string());
                };
                if !analysis.eq_ignore_ascii_case("TRAN") {
                    return Err(format!(
                        "wrapper-origin transient CSV contract does not cover .PRINT {analysis}"
                    ));
                }

                let mut format = None;
                let mut has_file_output = false;
                let mut index = 2usize;
                while index < token_refs.len() {
                    if let Some((raw_key, raw_value, consumed)) =
                        Self::print_option_assignment(&token_refs, index)
                    {
                        let value = raw_value.trim().trim_matches(['"', '\'']);
                        match raw_key.trim().to_ascii_lowercase().as_str() {
                            "file" => has_file_output = true,
                            "format" => format = Some(value),
                            _ => {}
                        }
                        index += consumed;
                        continue;
                    }
                    index += 1;
                }

                if has_file_output {
                    return Err(
                        "wrapper-origin transient CSV contract does not cover FILE= side outputs"
                            .to_string(),
                    );
                }
                match format {
                    Some(format) if format.eq_ignore_ascii_case("CSV") => {
                        primary_tran_print_count += 1;
                    }
                    Some(format) => {
                        return Err(format!(
                            "wrapper-origin transient CSV contract does not cover .PRINT TRAN FORMAT={format}"
                        ));
                    }
                    None => {
                        return Err(
                            "wrapper-origin transient CSV contract requires FORMAT=CSV".to_string()
                        );
                    }
                }
                continue;
            }
            if Self::is_extra_wrapper_tran_output_analysis_command(command) {
                return Err(format!(
                    "wrapper-origin transient CSV contract does not cover {command} directives"
                ));
            }
        }

        match primary_tran_print_count {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin transient CSV contract requires one primary .PRINT TRAN statement"
                    .to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin transient CSV contract requires one primary .PRINT TRAN statement, found {primary_tran_print_count}"
            )),
        }
    }

    fn validate_native_static_fd_ac_wrapper_contract(
        source: &str,
        output_override: bool,
    ) -> Result<(), String> {
        let mut primary_ac_print_count = 0usize;
        let mut side_ac_print_count = 0usize;
        let mut side_ac_print_formats = Vec::new();
        let mut primary_ac_ic_print_count = 0usize;
        let mut side_ac_ic_print_count = 0usize;
        let has_op_analysis = Self::source_has_op_analysis(source);
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") {
                let tokens = Self::split_print_fields(&trimmed)?;
                let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
                let Some(analysis) = token_refs.get(1).copied() else {
                    return Err("wrapper-origin .PRINT statement has no analysis type".to_string());
                };
                if !analysis.eq_ignore_ascii_case("AC") {
                    if analysis.eq_ignore_ascii_case("AC_IC") {
                        if !has_op_analysis {
                            continue;
                        }
                        let mut index = 2usize;
                        let mut has_file_output = false;
                        let mut print_format = "STD".to_string();
                        while index < token_refs.len() {
                            if let Some((raw_key, raw_value, consumed)) =
                                Self::print_option_assignment(&token_refs, index)
                            {
                                let value = raw_value.trim().trim_matches(['"', '\'']);
                                match raw_key.trim().to_ascii_lowercase().as_str() {
                                    "file" => has_file_output = true,
                                    "format" => {
                                        print_format = value.to_string();
                                        if !Self::ac_ic_print_format_is_supported(value) {
                                            return Err(format!(
                                                "wrapper-origin frequency-domain static output contract does not cover .PRINT AC_IC FORMAT={value}"
                                            ));
                                        }
                                    }
                                    _ => {}
                                }
                                index += consumed;
                                continue;
                            }
                            index += 1;
                        }
                        if has_file_output {
                            side_ac_ic_print_count += 1;
                            if !Self::ac_ic_print_format_is_supported(&print_format) {
                                return Err(format!(
                                    "wrapper-origin frequency-domain static output contract does not cover AC_IC FILE= side output FORMAT={print_format}"
                                ));
                            }
                        } else {
                            primary_ac_ic_print_count += 1;
                        }
                        continue;
                    }
                    return Err(format!(
                        "wrapper-origin frequency-domain static output contract does not cover .PRINT {analysis}"
                    ));
                }
                let mut index = 2usize;
                let mut has_file_output = false;
                let mut print_format = "STD".to_string();
                while index < token_refs.len() {
                    if let Some((raw_key, raw_value, consumed)) =
                        Self::print_option_assignment(&token_refs, index)
                    {
                        let value = raw_value.trim().trim_matches(['"', '\'']);
                        match raw_key.trim().to_ascii_lowercase().as_str() {
                            "file" => has_file_output = true,
                            "format" => {
                                print_format = value.to_string();
                                let supported_format =
                                    Self::ac_print_format_is_prn_compatible(value)
                                        || value.eq_ignore_ascii_case("CSV")
                                        || value.eq_ignore_ascii_case("PROBE");
                                if !supported_format {
                                    return Err(format!(
                                        "wrapper-origin frequency-domain static output contract does not cover .PRINT AC FORMAT={value}"
                                    ));
                                }
                            }
                            _ => {}
                        }
                        index += consumed;
                        continue;
                    }
                    index += 1;
                }
                if has_file_output {
                    side_ac_print_count += 1;
                    side_ac_print_formats.push(print_format);
                } else {
                    primary_ac_print_count += 1;
                }
                continue;
            }
            if Self::is_extra_wrapper_ac_output_analysis_command(command) {
                return Err(format!(
                    "wrapper-origin frequency-domain static output contract does not cover {command} directives"
                ));
            }
        }

        if output_override {
            if primary_ac_print_count == 0
                && side_ac_print_count == 0
                && primary_ac_ic_print_count == 0
                && side_ac_ic_print_count == 0
            {
                return Err(
                    "wrapper-origin frequency-domain output override contract requires one .PRINT AC or .PRINT AC_IC statement"
                        .to_string(),
                );
            }
            return Ok(());
        }

        if primary_ac_print_count == 0 {
            if side_ac_print_count > 1 {
                return Err(
                    "wrapper-origin frequency-domain static output contract does not cover multiple .PRINT AC FILE= outputs without a primary .PRINT AC"
                        .to_string(),
                );
            }
            if let Some(format) = side_ac_print_formats.first() {
                let supported_format = Self::ac_print_format_is_prn_compatible(format)
                    || format.eq_ignore_ascii_case("CSV")
                    || format.eq_ignore_ascii_case("PROBE");
                if !supported_format {
                    return Err(format!(
                        "wrapper-origin frequency-domain static output contract does not cover primary FILE= .PRINT AC FORMAT={format}"
                    ));
                }
            }
            if primary_ac_ic_print_count == 0
                && side_ac_ic_print_count == 0
                && side_ac_print_count == 0
            {
                return Err(
                    "wrapper-origin frequency-domain static output contract requires one primary .PRINT AC or .PRINT AC_IC statement"
                        .to_string(),
                );
            }
        } else {
            for format in side_ac_print_formats {
                if !Self::ac_print_format_is_prn_compatible(&format) {
                    return Err(format!(
                        "wrapper-origin frequency-domain static output contract does not cover FILE= side output FORMAT={format}"
                    ));
                }
            }
        }
        if primary_ac_ic_print_count == 0 && side_ac_ic_print_count > 1 {
            return Err(
                "wrapper-origin frequency-domain static output contract does not cover multiple .PRINT AC_IC FILE= outputs without a primary .PRINT AC_IC"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn validate_native_static_csd_tran_wrapper_contract(source: &str) -> Result<(), String> {
        let mut primary_tran_print_count = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") {
                let tokens = Self::split_print_fields(&trimmed)?;
                let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
                let Some(analysis) = token_refs.get(1).copied() else {
                    return Err("wrapper-origin .PRINT statement has no analysis type".to_string());
                };
                if !analysis.eq_ignore_ascii_case("TRAN") {
                    return Err(format!(
                        "wrapper-origin transient CSDF contract does not cover .PRINT {analysis}"
                    ));
                }
                let mut format = None;
                let mut index = 2usize;
                while index < token_refs.len() {
                    if let Some((raw_key, raw_value, consumed)) =
                        Self::print_option_assignment(&token_refs, index)
                    {
                        let value = raw_value.trim().trim_matches(['"', '\'']);
                        match raw_key.trim().to_ascii_lowercase().as_str() {
                            "file" => {
                                return Err(
                                    "wrapper-origin transient CSDF contract does not cover FILE= side outputs"
                                        .to_string(),
                                );
                            }
                            "format" => format = Some(value),
                            _ => {}
                        }
                        index += consumed;
                        continue;
                    }
                    index += 1;
                }
                match format {
                    Some(format) if format.eq_ignore_ascii_case("PROBE") => {
                        primary_tran_print_count += 1;
                    }
                    Some(format) => {
                        return Err(format!(
                            "wrapper-origin transient CSDF contract does not cover .PRINT TRAN FORMAT={format}"
                        ));
                    }
                    None => {
                        return Err(
                            "wrapper-origin transient CSDF contract requires FORMAT=PROBE"
                                .to_string(),
                        );
                    }
                }
                continue;
            }
            if Self::is_extra_wrapper_tran_output_analysis_command(command) {
                return Err(format!(
                    "wrapper-origin transient CSDF contract does not cover {command} directives"
                ));
            }
        }

        match primary_tran_print_count {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin transient CSDF contract requires one primary .PRINT TRAN statement"
                    .to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin transient CSDF contract requires one primary .PRINT TRAN statement, found {primary_tran_print_count}"
            )),
        }
    }

    fn native_static_prn_tran_wrapper_contract(
        deck_path: &Path,
        relative_path: &str,
        source: &str,
        has_prn_oracle: bool,
    ) -> Option<XyceStaticTranContract> {
        if Self::is_native_noindex_header_tran_wrapper_candidate(relative_path, source) {
            return Some(XyceStaticTranContract::WrapperNoIndexHeader);
        }

        if Self::validate_native_pwl_repeat_error_tran_wrapper_contract(deck_path, source).is_ok() {
            return Some(XyceStaticTranContract::WrapperStaticExpectedError);
        }

        if Self::is_native_csd_tran_wrapper_candidate(relative_path, source) {
            return Some(XyceStaticTranContract::WrapperCsd);
        }

        if Self::is_native_csv_tran_wrapper_candidate(relative_path, source) {
            return Some(XyceStaticTranContract::WrapperCsv);
        }

        if Self::is_native_default_prn_tran_wrapper_candidate(relative_path, source)
            || Self::is_native_output_other_prn_tran_wrapper_candidate(relative_path, source)
            || Self::is_native_output_initial_interval_tran_wrapper_candidate(source)
            || Self::is_native_generic_static_prn_tran_wrapper_candidate(
                relative_path,
                source,
                has_prn_oracle,
            )
        {
            return Some(XyceStaticTranContract::WrapperStatic);
        }

        None
    }

    fn is_native_noindex_header_tran_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        // Release 7.10's removed BUG_61 wrapper does not compare waveform
        // values. It runs this deck and inspects only the first default-PRN
        // header line for TIME without Index.
        Self::normalize_manifest_key(relative_path)
            == "netlists/certification_tests/bug_61/capacitor.cir"
            && Self::validate_native_noindex_header_tran_wrapper_contract(source).is_ok()
    }

    fn native_output_override_prn_tran_wrapper_contract(
        source: &str,
    ) -> Result<XyceStaticTranContract, String> {
        Self::validate_native_output_override_prn_tran_wrapper_contract(source)?;
        Ok(XyceStaticTranContract::WrapperStatic)
    }

    fn is_native_csd_tran_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        Self::normalize_manifest_key(relative_path).starts_with("netlists/output/tran/")
            && Self::validate_native_static_csd_tran_wrapper_contract(source).is_ok()
    }

    fn is_native_csv_tran_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        Self::normalize_manifest_key(relative_path).starts_with("netlists/output/tran/")
            && Self::validate_native_static_csv_tran_wrapper_contract(source).is_ok()
    }

    fn is_native_default_prn_tran_wrapper_candidate(relative_path: &str, source: &str) -> bool {
        matches!(
            Self::normalize_manifest_key(relative_path).as_str(),
            "netlists/output/tran/op-prn.cir"
                | "netlists/output/tran/tran-gnuplot.cir"
                | "netlists/output/tran/tran-prn-comma.cir"
                | "netlists/output/tran/tran-prn.cir"
                | "netlists/output/tran/tran-prn-filter.cir"
                | "netlists/output/tran/tran-prn-noindex.cir"
                | "netlists/output/tran/tran-prn-precision.cir"
                | "netlists/output/tran/tran-prn-timescalefactor.cir"
                | "netlists/output/tran/tran-prn-width.cir"
                | "netlists/output/tran/tran-splot.cir"
                | "netlists/output/tran/tran-touchstone-defaults-to-prn.cir"
        ) && Self::validate_native_static_prn_tran_wrapper_contract(source).is_ok()
    }

    fn is_native_output_other_prn_tran_wrapper_candidate(
        relative_path: &str,
        source: &str,
    ) -> bool {
        Self::normalize_manifest_key(relative_path).starts_with("netlists/output/other/")
            && Self::validate_native_static_prn_tran_wrapper_contract(source).is_ok()
    }

    fn is_native_output_initial_interval_tran_wrapper_candidate(source: &str) -> bool {
        Self::validate_native_output_initial_interval_tran_wrapper_contract(source).is_ok()
    }

    fn is_native_generic_static_prn_tran_wrapper_candidate(
        relative_path: &str,
        source: &str,
        has_prn_oracle: bool,
    ) -> bool {
        let normalized_path = Self::normalize_manifest_key(relative_path);
        if normalized_path.starts_with("netlists/output/") {
            return false;
        }
        Self::validate_native_static_prn_tran_wrapper_contract(source).is_ok()
            || (has_prn_oracle
                && Self::validate_native_static_prn_tran_wrapper_contract_with_format_mode(
                    source, true,
                )
                .is_ok())
    }

    fn source_enables_constant_time_step_output(source: &str) -> bool {
        Self::logical_netlist_lines(source).iter().any(|line| {
            let normalized = Self::strip_netlist_comment(line)
                .chars()
                .filter(|ch| !ch.is_whitespace())
                .collect::<String>()
                .to_ascii_lowercase();
            normalized.starts_with(".options")
                && normalized.contains("timeint")
                && normalized.contains("conststep")
        })
    }

    fn source_requests_ac_phase_output_radians(source: &str) -> bool {
        let mut enabled = false;
        for line in Self::logical_netlist_lines(source) {
            let normalized = Self::strip_netlist_comment(&line)
                .chars()
                .filter(|ch| !ch.is_whitespace())
                .collect::<String>()
                .to_ascii_lowercase();
            if !normalized.starts_with(".options") || !normalized.contains("phase_output_radians") {
                continue;
            }
            if normalized.contains("phase_output_radians=false")
                || normalized.contains("phase_output_radians=0")
                || normalized.contains("phase_output_radians=no")
            {
                enabled = false;
                continue;
            }
            enabled = true;
        }
        enabled
    }

    fn static_tran_contract_for_print_format(
        requires_wrapper: bool,
        format: Option<&str>,
    ) -> Result<XyceStaticTranContract, String> {
        let normalized = format.unwrap_or("STD").trim();
        if Self::tran_print_format_is_prn_compatible(normalized) {
            return Ok(if requires_wrapper {
                XyceStaticTranContract::WrapperStatic
            } else {
                XyceStaticTranContract::PlainStatic
            });
        }
        if normalized.eq_ignore_ascii_case("CSV") {
            return Ok(if requires_wrapper {
                XyceStaticTranContract::WrapperCsv
            } else {
                XyceStaticTranContract::PlainCsv
            });
        }
        if normalized.eq_ignore_ascii_case("PROBE") {
            return Ok(if requires_wrapper {
                XyceStaticTranContract::WrapperCsd
            } else {
                XyceStaticTranContract::PlainCsd
            });
        }
        Err(format!(
            "native static .PRINT TRAN comparison does not cover FORMAT={normalized}"
        ))
    }

    fn validate_native_output_initial_interval_tran_wrapper_contract(
        source: &str,
    ) -> Result<(), String> {
        Self::validate_native_static_prn_tran_wrapper_contract(source)?;

        let tran_prints = Self::print_output_requests(source, "TRAN")?;
        if tran_prints.iter().any(|request| request.file.is_some()) {
            return Err(
                "wrapper-origin initial-interval transient .prn contract does not cover FILE= side outputs"
                    .to_string(),
            );
        }
        let Some(primary_print) = tran_prints.iter().find(|request| request.file.is_none()) else {
            return Err(
                "wrapper-origin initial-interval transient .prn contract requires one primary .PRINT TRAN statement"
                    .to_string(),
            );
        };
        if primary_print.probes.len() != 1 {
            return Err(format!(
                "wrapper-origin initial-interval transient .prn contract currently covers one primary probe, found {}",
                primary_print.probes.len()
            ));
        }

        let mut initial_interval_options = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let normalized = Self::strip_netlist_comment(&line)
                .trim()
                .to_ascii_lowercase();
            if normalized.is_empty() {
                continue;
            }
            let Some(command) = normalized.split_whitespace().next() else {
                continue;
            };
            if !command.eq_ignore_ascii_case(".options") {
                continue;
            }
            if normalized.contains("output") && normalized.contains("initial_interval") {
                initial_interval_options += 1;
            } else {
                return Err(format!(
                    "wrapper-origin initial-interval transient .prn contract does not cover {command} directives without OUTPUT INITIAL_INTERVAL"
                ));
            }
        }

        match initial_interval_options {
            1 => Ok(()),
            0 => Err(
                "wrapper-origin initial-interval transient .prn contract requires .OPTIONS OUTPUT INITIAL_INTERVAL"
                    .to_string(),
            ),
            _ => Err(format!(
                "wrapper-origin initial-interval transient .prn contract requires one .OPTIONS OUTPUT INITIAL_INTERVAL directive, found {initial_interval_options}"
            )),
        }
    }

    fn validate_native_output_override_prn_tran_wrapper_contract(
        source: &str,
    ) -> Result<(), String> {
        let mut print_count = 0usize;
        let mut probe_count = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".print") {
                let tokens = Self::split_print_fields(&trimmed)?;
                let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
                let Some(analysis) = token_refs.get(1).copied() else {
                    return Err("output override .PRINT statement has no analysis type".to_string());
                };
                if !analysis.eq_ignore_ascii_case("TRAN") {
                    return Err(format!(
                        "wrapper-origin transient output override contract does not cover .PRINT {analysis}"
                    ));
                }

                print_count += 1;
                let mut index = 2usize;
                while index < token_refs.len() {
                    if let Some((raw_key, raw_value, consumed)) =
                        Self::print_option_assignment(&token_refs, index)
                    {
                        let value = raw_value.trim().trim_matches(['"', '\'']);
                        if raw_key.trim().eq_ignore_ascii_case("FORMAT") {
                            Self::static_tran_contract_for_print_format(true, Some(value))
                                .map_err(|err| {
                                    format!(
                                        "wrapper-origin transient output override contract does not cover {err}"
                                    )
                                })?;
                        }
                        index += consumed;
                        continue;
                    }
                    let normalized = token_refs[index].to_ascii_lowercase();
                    if !Self::is_print_option_token(&normalized) {
                        probe_count += 1;
                    }
                    index += 1;
                }
                continue;
            }
            if Self::is_extra_wrapper_tran_output_analysis_command(command) {
                return Err(format!(
                    "wrapper-origin transient output override contract does not cover {command} directives"
                ));
            }
        }

        if print_count == 0 || probe_count == 0 {
            return Err(
                "wrapper-origin transient output override contract requires .PRINT TRAN probes"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn validate_native_pwl_repeat_error_tran_wrapper_contract(
        deck_path: &Path,
        source: &str,
    ) -> Result<(), String> {
        Self::validate_native_static_prn_tran_wrapper_contract(source)?;
        if !Self::source_may_have_pwl_repeat_option(source) {
            return Err(
                "wrapper-origin PWL repeat error contract requires a primary PWL repeat deck"
                    .to_string(),
            );
        }

        let stem = deck_path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .ok_or_else(|| {
                "wrapper-origin PWL repeat error contract requires a .cir filename".to_string()
            })?;
        let sibling_path = deck_path.with_file_name(format!("{stem}RepeatFail.cir"));
        let sibling_source = fs::read_to_string(&sibling_path).map_err(|err| {
            format!(
                "wrapper-origin PWL repeat error contract requires sibling expected-error deck '{}': {err}",
                sibling_path.display()
            )
        })?;

        Self::validate_expected_pwl_repeat_value_error_source(&sibling_source, &sibling_path)
    }

    fn is_expected_missing_inductor_value_error_deck(relative_path: &str, source: &str) -> bool {
        matches!(
            Self::normalize_manifest_key(relative_path).as_str(),
            "netlists/inductor/errormessagetest.cir"
        ) && source
            .to_ascii_lowercase()
            .contains("l value missing from instance line")
    }

    fn validate_expected_missing_inductor_value_error_source(
        source: &str,
        deck_path: &Path,
    ) -> Result<(), String> {
        match Self::parse_xyce_netlist(source, deck_path) {
            Ok(_) => Err(
                "expected missing-inductor-value deck parsed successfully; expected a fatal parser diagnostic"
                    .to_string(),
            ),
            Err(err) => {
                let message = err.to_string();
                if message.contains("Inductor requires either a value or a model") {
                    Ok(())
                } else {
                    Err(format!(
                        "expected missing-inductor-value diagnostic, got parser error: {message}"
                    ))
                }
            }
        }
    }

    fn validate_expected_pwl_repeat_value_error_source(
        source: &str,
        deck_path: &Path,
    ) -> Result<(), String> {
        if !Self::source_may_have_pwl_repeat_option(source) {
            return Err(
                "expected PWL repeat-value error deck has no PWL repeat option".to_string(),
            );
        }

        match Self::parse_xyce_netlist(source, deck_path) {
            Ok(_) => Err(format!(
                "expected {XYCE_PWL_REPEAT_VALUE_ERROR}, but deck parsed successfully"
            )),
            Err(err) => {
                let message = err.to_string();
                if message.contains(XYCE_PWL_REPEAT_VALUE_ERROR) {
                    Ok(())
                } else {
                    Err(format!(
                        "expected {XYCE_PWL_REPEAT_VALUE_ERROR}, got {message}"
                    ))
                }
            }
        }
    }

    fn source_may_have_pwl_repeat_option(source: &str) -> bool {
        Self::logical_netlist_lines(source).iter().any(|line| {
            let compact = Self::strip_netlist_comment(line)
                .chars()
                .filter(|ch| !ch.is_whitespace())
                .collect::<String>()
                .to_ascii_lowercase();
            compact.contains("pwl") && (compact.contains("r=") || compact.contains("repeat="))
        })
    }

    fn native_default_prn_tran_wrapper_tolerance(
        relative_path: &str,
    ) -> Option<XyceComparisonTolerance> {
        match Self::normalize_manifest_key(relative_path).as_str() {
            "netlists/output/tran/tran-prn-noindex.cir"
            | "netlists/output/tran/tran-step-gnuplot.cir"
            | "netlists/output/tran/tran-stepnum-col.cir" => Some(XyceComparisonTolerance {
                relative: 1.0e-3,
                absolute: 1.0e-5,
                zero: Some(1.0e-8),
            }),
            _ => None,
        }
    }

    fn static_ac_contract_for_print_format(
        requires_wrapper: bool,
        format: Option<&str>,
    ) -> Result<XyceStaticAcContract, String> {
        let normalized = format.unwrap_or("STD").trim();
        if Self::ac_print_format_is_prn_compatible(normalized) {
            return Ok(if requires_wrapper {
                XyceStaticAcContract::WrapperStatic
            } else {
                XyceStaticAcContract::PlainStatic
            });
        }
        if normalized.eq_ignore_ascii_case("CSV") {
            return Ok(if requires_wrapper {
                XyceStaticAcContract::WrapperCsv
            } else {
                XyceStaticAcContract::PlainCsv
            });
        }
        if normalized.eq_ignore_ascii_case("PROBE") {
            return Ok(if requires_wrapper {
                XyceStaticAcContract::WrapperCsd
            } else {
                XyceStaticAcContract::PlainCsd
            });
        }
        Err(format!(
            "native static .PRINT AC comparison does not cover FORMAT={normalized}"
        ))
    }

    fn static_ac_ic_contract_for_print_format(
        requires_wrapper: bool,
        format: Option<&str>,
    ) -> Result<XyceStaticAcContract, String> {
        let normalized = format.unwrap_or("STD").trim();
        if Self::ac_print_format_is_prn_compatible(normalized) {
            return Ok(if requires_wrapper {
                XyceStaticAcContract::WrapperIcPrn
            } else {
                XyceStaticAcContract::PlainIcPrn
            });
        }
        if normalized.eq_ignore_ascii_case("CSV") {
            return Ok(if requires_wrapper {
                XyceStaticAcContract::WrapperIcCsv
            } else {
                XyceStaticAcContract::PlainIcCsv
            });
        }
        if normalized.eq_ignore_ascii_case("PROBE") {
            return Ok(if requires_wrapper {
                XyceStaticAcContract::WrapperIcCsd
            } else {
                XyceStaticAcContract::PlainIcCsd
            });
        }
        Err(format!(
            "native static .PRINT AC_IC comparison does not cover FORMAT={normalized}"
        ))
    }

    fn static_dc_contract_for_print_format(
        requires_wrapper: bool,
        format: Option<&str>,
    ) -> Result<XyceStaticDcContract, String> {
        let normalized = format.unwrap_or("STD").trim();
        if Self::dc_print_format_is_prn_compatible(normalized) {
            return Ok(if requires_wrapper {
                XyceStaticDcContract::WrapperDefault
            } else {
                XyceStaticDcContract::PlainStatic
            });
        }
        if normalized.eq_ignore_ascii_case("CSV") {
            return Ok(if requires_wrapper {
                XyceStaticDcContract::WrapperCsv
            } else {
                XyceStaticDcContract::PlainCsv
            });
        }
        if normalized.eq_ignore_ascii_case("PROBE") {
            return Ok(if requires_wrapper {
                XyceStaticDcContract::WrapperCsd
            } else {
                XyceStaticDcContract::PlainCsd
            });
        }
        Err(format!(
            "native static .PRINT DC comparison does not cover FORMAT={normalized}"
        ))
    }

    fn dc_print_format_is_prn_compatible(format: &str) -> bool {
        matches!(
            format.to_ascii_lowercase().as_str(),
            "std" | "tecplot" | "touchstone" | "touchstone2" | "noindex" | "gnuplot" | "splot"
        )
    }

    fn tran_print_format_is_prn_compatible(format: &str) -> bool {
        matches!(
            format.to_ascii_lowercase().as_str(),
            "std" | "tecplot" | "touchstone" | "touchstone2" | "noindex" | "gnuplot" | "splot"
        )
    }

    fn ac_print_format_is_prn_compatible(format: &str) -> bool {
        matches!(
            format.to_ascii_lowercase().as_str(),
            "std" | "tecplot" | "touchstone" | "touchstone2" | "noindex" | "gnuplot" | "splot"
        )
    }

    fn ac_ic_print_format_is_supported(format: &str) -> bool {
        Self::ac_print_format_is_prn_compatible(format)
            || format.eq_ignore_ascii_case("CSV")
            || format.eq_ignore_ascii_case("PROBE")
    }

    fn ac_initial_condition_reference_extension(
        format: Option<&str>,
    ) -> Result<&'static str, String> {
        let normalized = format.unwrap_or("STD").trim();
        if Self::ac_print_format_is_prn_compatible(normalized) {
            return Ok("TD.prn");
        }
        if normalized.eq_ignore_ascii_case("CSV") {
            return Ok("TD.csv");
        }
        if normalized.eq_ignore_ascii_case("PROBE") {
            return Ok("TD.csd");
        }
        Err(format!(
            "native AC_IC comparison does not cover FORMAT={normalized}"
        ))
    }

    fn is_extra_wrapper_ac_output_analysis_command(command: &str) -> bool {
        matches!(
            command.to_ascii_lowercase().as_str(),
            ".dc" | ".four" | ".hb" | ".noise" | ".probe" | ".save" | ".sens" | ".tran"
        )
    }

    fn is_extra_wrapper_tran_output_analysis_command(command: &str) -> bool {
        matches!(
            command.to_ascii_lowercase().as_str(),
            ".ac"
                | ".dc"
                | ".four"
                | ".fft"
                | ".hb"
                | ".measure"
                | ".meas"
                | ".noise"
                | ".probe"
                | ".save"
                | ".sens"
        )
    }

    fn is_ignorable_wrapper_tran_measure_side_output(line: &str) -> Result<bool, String> {
        let tokens = Self::split_grouped_whitespace_fields(line, ".MEASURE statement")?;
        if tokens.len() < 5 {
            return Ok(false);
        }
        if !matches!(
            tokens[0].to_ascii_lowercase().as_str(),
            ".measure" | ".meas"
        ) || !tokens[1].eq_ignore_ascii_case("TRAN")
        {
            return Ok(false);
        }
        if !matches!(tokens[3].to_ascii_lowercase().as_str(), "max" | "min") {
            return Ok(false);
        }

        let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
        let mut index = 4usize;
        while index < token_refs.len() {
            if Self::print_option_assignment(&token_refs, index).is_some() {
                return Ok(false);
            }
            let normalized = token_refs[index]
                .trim()
                .trim_matches(['"', '\''])
                .to_ascii_lowercase();
            if matches!(
                normalized.as_str(),
                "error"
                    | "four"
                    | "fft"
                    | "file"
                    | "failvalue"
                    | "comp_function"
                    | "indepvarcol"
                    | "depvarcol"
            ) {
                return Ok(false);
            }
            index += 1;
        }

        Ok(true)
    }

    fn print_option_assignment<'a>(
        tokens: &'a [&'a str],
        index: usize,
    ) -> Option<(&'a str, &'a str, usize)> {
        let token = tokens.get(index).copied()?;
        if let Some((key, value)) = token.split_once('=') {
            if value.is_empty() && token.ends_with('=') {
                return Some((key, tokens.get(index + 1).copied()?, 2));
            }
            return Some((key, value, 1));
        }
        if token.ends_with('=') {
            return Some((
                token.trim_end_matches('='),
                tokens.get(index + 1).copied()?,
                2,
            ));
        }
        if tokens.get(index + 1).copied() == Some("=") {
            return Some((token, tokens.get(index + 2).copied()?, 3));
        }
        None
    }

    fn is_extra_wrapper_output_analysis_command(command: &str) -> bool {
        matches!(
            command.to_ascii_lowercase().as_str(),
            ".ac"
                | ".four"
                | ".fft"
                | ".hb"
                | ".measure"
                | ".meas"
                | ".noise"
                | ".probe"
                | ".save"
                | ".sens"
                | ".tran"
        )
    }

    fn wrapper_source_has_extra_output_analysis(source: &str) -> bool {
        Self::logical_netlist_lines(source).into_iter().any(|line| {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            let Some(command) = trimmed.split_whitespace().next() else {
                return false;
            };
            Self::is_extra_wrapper_output_analysis_command(command)
        })
    }

    fn run_static_prn_hb_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticHbPlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = if plan.wrapper {
            "wrapper_static_prn_hb"
        } else {
            "static_prn_hb"
        };
        let netlist = match Self::parse_xyce_netlist(&plan.source, &plan.deck_path) {
            Ok(netlist) => netlist,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("parse failed after HB contract validation: {err}"),
                    Vec::new(),
                );
            }
        };
        let fd_reference = match Self::parse_ac_comparator_prn_file(&plan.fd_reference_path) {
            Ok(reference) => reference,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("failed to parse HB.FD oracle: {err}"),
                    Vec::new(),
                );
            }
        };
        let td_reference =
            match Self::parse_xyce_verify_tran_reference_file(&plan.td_reference_path) {
                Ok(reference) => reference,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("failed to parse HB.TD oracle: {err}"),
                        Vec::new(),
                    );
                }
            };
        let ic_reference =
            match Self::parse_xyce_verify_tran_reference_file(&plan.ic_reference_path) {
                Ok(reference) => reference,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("failed to parse HB startup oracle: {err}"),
                        Vec::new(),
                    );
                }
            };

        let hb_config = crate::analysis::HbConfig::new(plan.frequency)
            .with_harmonics(plan.num_harmonics)
            .with_collocation_points(2 * plan.num_harmonics + 1);
        let hb = match self.create_xyce_engine().run_hb(&netlist, hb_config) {
            Ok(result) => result,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("native HB simulation failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let fd_actual = match Self::hb_frequency_result_to_prn_table(
            &fd_reference,
            &plan.print,
            &netlist,
            &hb.result,
        ) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("HB.FD output construction failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let mut mismatches = match self.compare_ac_comparator_tables(&fd_reference, &fd_actual) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("HB.FD ACComparator comparison failed: {err}"),
                    Vec::new(),
                );
            }
        };

        let td_result = Self::hb_result_to_transient_result(&hb.result);
        let td_actual =
            match Self::hb_transient_result_to_prn_table(&plan.print, &netlist, &td_result) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("HB.TD output construction failed: {err}"),
                        Vec::new(),
                    );
                }
            };
        match self.compare_xyce_verify_transient_tables_with_uniform_tolerance(
            &td_reference,
            &td_actual,
            XyceVerifyTransientTolerance::release_7_10_default(),
            XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION,
        ) {
            Ok(td_mismatches) => mismatches.extend(td_mismatches),
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("HB.TD xyce_verify comparison failed: {err}"),
                    Vec::new(),
                );
            }
        }

        let period = plan.frequency.recip();
        let mut startup_config = self.xyce_engine_config(None);
        startup_config.integration_method = crate::analysis::IntegrationMethod::BackwardEuler;
        startup_config.transient_initial_timestep = Some(period / 1.0e6);
        let startup = match Engine::new(startup_config).run_tran(&netlist, period, period / 1000.0)
        {
            Ok(result) => result,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("HB startup transient failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let ic_actual =
            match Self::hb_transient_result_to_prn_table(&plan.print, &netlist, &startup) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("HB startup output construction failed: {err}"),
                        Vec::new(),
                    );
                }
            };
        match self.compare_xyce_verify_transient_tables_with_uniform_tolerance(
            &ic_reference,
            &ic_actual,
            XyceVerifyTransientTolerance::release_7_10_default(),
            XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION,
        ) {
            Ok(ic_mismatches) => mismatches.extend(ic_mismatches),
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("HB startup xyce_verify comparison failed: {err}"),
                    Vec::new(),
                );
            }
        }

        mismatches.truncate(self.config.max_mismatches);
        if mismatches.is_empty() {
            self.passed_result(deck, start, contract)
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!("{} HB oracle mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn run_static_fd_prn_ac_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticAcPlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = if plan.reference_path.is_none()
            && (!plan.measurement_reference_paths.is_empty()
                || !plan.continuous_measurement_reference_paths.is_empty())
        {
            "wrapper_scalar_measure_ac"
        } else {
            plan.contract.result_contract(!plan.steps.is_empty())
        };
        let frequencies = plan.ac.frequencies();
        if frequencies.is_empty() {
            return self.failure_result(
                deck,
                start,
                contract,
                "AC analysis produced no frequency points".to_string(),
                Vec::new(),
            );
        }

        let frequency_bound_source;
        let parse_source = if plan.frequency_bound {
            frequency_bound_source =
                Self::source_with_ac_frequency_bindings(&plan.source, frequencies[0]);
            frequency_bound_source.as_str()
        } else {
            plan.source.as_str()
        };
        let netlist = match Self::parse_xyce_netlist(parse_source, &plan.deck_path) {
            Ok(netlist) => netlist,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("parse failed after contract validation: {err}"),
                    Vec::new(),
                );
            }
        };

        if plan.reference_path.is_none() && plan.print.is_some() {
            if !plan.steps.is_empty() {
                return self.run_static_step_ac_measurement_plan(
                    deck,
                    plan,
                    netlist,
                    frequencies,
                    start,
                );
            }
            if plan.ac.data_points().is_some() || plan.frequency_bound {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_contract",
                    "measurement-only AC oracle comparison currently requires an ordinary, unstepped frequency sweep",
                );
            }
            let engine = self.create_xyce_engine();
            let results = match engine.run_ac(&netlist, &frequencies) {
                Ok(results) => results,
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this static AC deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error: {err}"),
                        Vec::new(),
                    );
                }
            };
            let measurements =
                crate::analysis::advanced::evaluate_ac_measurements(&netlist, &results);
            let continuous =
                crate::analysis::advanced::evaluate_ac_continuous_measurements(&netlist, &results);
            let mismatches = match self.compare_analysis_measurement_outputs(
                &plan.measurement_reference_paths,
                &plan.continuous_measurement_reference_paths,
                &measurements,
                &continuous,
                plan.measurement_tolerance,
                netlist.options.measure_fail_output,
                netlist.options.measure_default_value,
                netlist.options.measure_use_cont_files(),
                &netlist.measurements,
                "AC",
                "AC_CONT",
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("AC measurement reference comparison error: {err}"),
                        Vec::new(),
                    );
                }
            };
            return if mismatches.is_empty() {
                self.passed_result(deck, start, contract)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("{} Xyce AC measurement mismatch(es)", mismatches.len()),
                    mismatches,
                )
            };
        }

        let Some(primary_reference_path) = plan.reference_path.as_ref() else {
            let ac_ic_mismatches = match self.compare_ac_initial_condition_outputs(&plan, &netlist)
            {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("AC initial-condition output comparison error: {err}"),
                        Vec::new(),
                    );
                }
            };
            return if ac_ic_mismatches.is_empty() {
                self.passed_result(deck, start, contract)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce AC initial-condition output mismatch(es)",
                        ac_ic_mismatches.len()
                    ),
                    ac_ic_mismatches,
                )
            };
        };
        let Some(primary_print) = plan.print.as_ref() else {
            return self.failure_result(
                deck,
                start,
                contract,
                "AC plan has a primary reference without a primary print request".to_string(),
                Vec::new(),
            );
        };
        let reference = match Self::parse_ac_reference_file(plan.contract, primary_reference_path) {
            Ok(reference) => reference,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("failed to parse Xyce AC oracle: {err}"),
                    Vec::new(),
                );
            }
        };

        if !plan.steps.is_empty() {
            return self.run_static_step_ac_plan(
                deck,
                plan,
                netlist,
                reference,
                frequencies,
                start,
            );
        }
        if plan.ac.data_points().is_some() {
            return self.run_static_ac_data_plan(deck, plan, netlist, reference, start);
        }
        if plan.frequency_bound {
            return self.run_static_frequency_bound_ac_plan(
                deck,
                plan,
                reference,
                frequencies,
                start,
            );
        }

        let engine = self.create_xyce_engine();
        let results = match engine.run_ac(&netlist, &frequencies) {
            Ok(results) => results,
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this static AC deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("simulation error: {err}"),
                    Vec::new(),
                );
            }
        };

        let mismatches = match self.compare_ac_prn_reference(
            &reference,
            primary_print,
            &netlist,
            &plan.source,
            &results,
        ) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("reference comparison error: {err}"),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            if !plan.measurement_reference_paths.is_empty()
                || !plan.continuous_measurement_reference_paths.is_empty()
            {
                let measurements =
                    crate::analysis::advanced::evaluate_ac_measurements(&netlist, &results);
                let continuous = crate::analysis::advanced::evaluate_ac_continuous_measurements(
                    &netlist, &results,
                );
                let measurement_mismatches = match self.compare_analysis_measurement_outputs(
                    &plan.measurement_reference_paths,
                    &plan.continuous_measurement_reference_paths,
                    &measurements,
                    &continuous,
                    plan.measurement_tolerance,
                    netlist.options.measure_fail_output,
                    netlist.options.measure_default_value,
                    netlist.options.measure_use_cont_files(),
                    &netlist.measurements,
                    "AC",
                    "AC_CONT",
                ) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("AC measurement reference comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
                if !measurement_mismatches.is_empty() {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "{} Xyce AC measurement mismatch(es)",
                            measurement_mismatches.len()
                        ),
                        measurement_mismatches,
                    );
                }
            }
            let side_mismatches = match self.compare_ac_side_outputs(&plan, &netlist, &results) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("AC side-output comparison error: {err}"),
                        Vec::new(),
                    );
                }
            };
            if side_mismatches.is_empty() {
                let ac_ic_mismatches =
                    match self.compare_ac_initial_condition_outputs(&plan, &netlist) {
                        Ok(mismatches) => mismatches,
                        Err(err) => {
                            return self.failure_result(
                                deck,
                                start,
                                contract,
                                format!("AC initial-condition output comparison error: {err}"),
                                Vec::new(),
                            );
                        }
                    };
                if ac_ic_mismatches.is_empty() {
                    self.passed_result(deck, start, contract)
                } else {
                    self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "{} Xyce AC initial-condition output mismatch(es)",
                            ac_ic_mismatches.len()
                        ),
                        ac_ic_mismatches,
                    )
                }
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("{} Xyce AC side-output mismatch(es)", side_mismatches.len()),
                    side_mismatches,
                )
            }
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!("{} Xyce AC reference mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn run_static_noise_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticNoisePlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = if plan.reference_path.is_some() {
            "static_prn_noise"
        } else {
            "wrapper_scalar_measure_noise"
        };
        let netlist = match Self::parse_xyce_netlist(&plan.source, &plan.deck_path) {
            Ok(netlist) => netlist,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("parse failed after NOISE contract validation: {err}"),
                    Vec::new(),
                );
            }
        };
        if !plan.steps.is_empty() {
            return self.run_static_step_noise_measurement_plan(deck, plan, netlist, start);
        }
        let temperature = netlist.options.temp.unwrap_or(27.0) + 273.15;
        if !temperature.is_finite() || temperature <= 0.0 {
            return self.failure_result(
                deck,
                start,
                contract,
                format!("NOISE temperature must be positive Kelvin, got {temperature}"),
                Vec::new(),
            );
        }
        let engine = self.create_xyce_engine();
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let results = match engine.run_noise_named_with_input_source_and_abort(
            &netlist,
            &plan.output_node,
            plan.reference_node.as_deref(),
            &plan.input_source,
            &plan.frequencies,
            temperature,
            &abort,
        ) {
            Ok(results) => results,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this NOISE deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("NOISE simulation error: {err}"),
                    Vec::new(),
                );
            }
        };

        let mut mismatches = Vec::new();
        if let Some(reference_path) = plan.reference_path.as_ref() {
            let Some(print) = plan.print.as_ref() else {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    "NOISE reference has no print request".to_string(),
                    Vec::new(),
                );
            };
            let reference = match Self::parse_prn_file(reference_path) {
                Ok(reference) => reference,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("failed to parse Xyce NOISE oracle: {err}"),
                        Vec::new(),
                    );
                }
            };
            match self.compare_noise_prn_reference(
                &reference,
                print,
                &netlist,
                &plan.source,
                &results,
            ) {
                Ok(waveform_mismatches) => mismatches.extend(waveform_mismatches),
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("NOISE waveform reference comparison error: {err}"),
                        Vec::new(),
                    );
                }
            }
        }
        if mismatches.is_empty()
            && (!plan.measurement_reference_paths.is_empty()
                || !plan.continuous_measurement_reference_paths.is_empty())
        {
            let scalar = crate::analysis::advanced::evaluate_noise_measurements(&netlist, &results);
            let continuous = crate::analysis::advanced::evaluate_noise_continuous_measurements(
                &netlist, &results,
            );
            match self.compare_analysis_measurement_outputs(
                &plan.measurement_reference_paths,
                &plan.continuous_measurement_reference_paths,
                &scalar,
                &continuous,
                plan.measurement_tolerance,
                netlist.options.measure_fail_output,
                netlist.options.measure_default_value,
                netlist.options.measure_use_cont_files(),
                &netlist.measurements,
                "NOISE",
                "NOISE_CONT",
            ) {
                Ok(measurement_mismatches) => mismatches.extend(measurement_mismatches),
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("NOISE measurement reference comparison error: {err}"),
                        Vec::new(),
                    );
                }
            }
        }
        mismatches.truncate(self.config.max_mismatches);
        if mismatches.is_empty() {
            self.passed_result(deck, start, contract)
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!("{} Xyce NOISE mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn run_static_step_noise_measurement_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticNoisePlan,
        netlist: Netlist,
        start: Instant,
    ) -> XyceTestResult {
        let contract = "wrapper_scalar_measure_step_noise";
        if plan.measurement_reference_paths.is_empty() {
            return self.failure_result(
                deck,
                start,
                contract,
                ".STEP NOISE comparison requires contiguous scalar measurement artifacts"
                    .to_string(),
                Vec::new(),
            );
        }

        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let expansion_engine = self.create_xyce_engine();
        let step_runs = match Self::nested_step_runs_for_commands_with_limits_and_abort(
            &expansion_engine,
            &netlist,
            &plan.steps,
            xyce_step_plan_limits(),
            &abort,
        ) {
            Ok(runs) => runs,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        ".STEP expansion exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this .STEP NOISE deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".STEP expansion error: {err}"),
                    Vec::new(),
                );
            }
        };
        if step_runs.len() != plan.measurement_reference_paths.len() {
            return self.failure_result(
                deck,
                start,
                contract,
                format!(
                    ".STEP expansion produced {} batches but {} contiguous measurement artifacts exist",
                    step_runs.len(),
                    plan.measurement_reference_paths.len()
                ),
                Vec::new(),
            );
        }

        let gs_rows = match plan.gs_reference_path.as_deref() {
            Some(path) => match Self::parse_measure_cont_gs_file(path) {
                Ok(rows) => Some(rows),
                Err(error) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("stepped NOISE GS oracle is invalid: {error}"),
                        Vec::new(),
                    );
                }
            },
            None => None,
        };
        let mut gs_offset = 0usize;

        let engine = self.create_xyce_engine();
        let mut all_mismatches = Vec::new();
        for (step_index, (run, reference_path)) in step_runs
            .iter()
            .zip(&plan.measurement_reference_paths)
            .enumerate()
        {
            let temperature = run.netlist.options.temp.unwrap_or(27.0) + 273.15;
            if !temperature.is_finite() || temperature <= 0.0 {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "NOISE temperature in step {} must be positive Kelvin, got {temperature}",
                        step_index + 1
                    ),
                    Vec::new(),
                );
            }
            let (output_node, reference_node, input_source, frequencies) =
                match Self::noise_analysis_for_netlist(&run.netlist) {
                    Ok(analysis) => analysis,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "NOISE analysis in step {} is invalid: {err}",
                                step_index + 1
                            ),
                            Vec::new(),
                        );
                    }
                };
            let results = match engine.run_noise_named_with_input_source_and_abort(
                &run.netlist,
                &output_node,
                reference_node.as_deref(),
                &input_source,
                &frequencies,
                temperature,
                &abort,
            ) {
                Ok(results) => results,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "simulation exceeded timeout ({}ms) in NOISE step {}",
                            self.config.max_time_per_test_ms,
                            step_index + 1
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!(
                            "RSpice runtime does not yet support this .STEP NOISE deck: {err}"
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error in NOISE step {}: {err}", step_index + 1),
                        Vec::new(),
                    );
                }
            };
            let measurements =
                crate::analysis::advanced::evaluate_noise_measurements(&run.netlist, &results);
            let comparison = if run.netlist.options.measure_use_cont_files() {
                self.compare_measurement_references(
                    std::slice::from_ref(reference_path),
                    &measurements,
                    plan.measurement_tolerance,
                    run.netlist.options.measure_fail_output,
                    run.netlist.options.measure_default_value,
                    "NOISE",
                    &run.netlist.measurements,
                )
            } else {
                let continuous = crate::analysis::advanced::evaluate_noise_continuous_measurements(
                    &run.netlist,
                    &results,
                );
                let comparison = self.compare_mixed_measurement_references(
                    std::slice::from_ref(reference_path),
                    &measurements,
                    &continuous,
                    plan.measurement_tolerance,
                    &run.netlist.measurements,
                    "NOISE",
                    "NOISE_CONT",
                );
                if let (Ok(_), Some(gs)) = (&comparison, gs_rows.as_deref()) {
                    match Self::compare_noise_step_gs_semantics(
                        gs,
                        gs_offset,
                        &run.netlist,
                        &measurements,
                        &continuous,
                        plan.measurement_tolerance,
                    ) {
                        Ok(consumed) => gs_offset += consumed,
                        Err(error) => {
                            return self.failure_result(
                                deck,
                                start,
                                contract,
                                format!(
                                    "NOISE step {} GS comparison error: {error}",
                                    step_index + 1
                                ),
                                Vec::new(),
                            );
                        }
                    }
                }
                comparison
            };
            let mut mismatches = match comparison {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "NOISE step {} measurement comparison error: {err}",
                            step_index + 1
                        ),
                        Vec::new(),
                    );
                }
            };
            for mismatch in &mut mismatches {
                mismatch.probe = format!("step {step_index}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }

        if let Some(gs) = gs_rows.as_deref()
            && gs_offset != gs.len()
        {
            return self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "stepped NOISE GS oracle left rows unclaimed: consumed {gs_offset}/{}",
                    gs.len()
                ),
                Vec::new(),
            );
        }

        if all_mismatches.is_empty() {
            self.passed_result(deck, start, contract)
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce stepped NOISE measurement mismatch(es)",
                    all_mismatches.len()
                ),
                all_mismatches,
            )
        }
    }

    fn noise_analysis_for_netlist(
        netlist: &Netlist,
    ) -> Result<(String, Option<String>, String, Vec<Value>), String> {
        let analyses = netlist
            .analyses
            .iter()
            .filter_map(|analysis| match analysis {
                AnalysisCommand::Noise {
                    output_node,
                    reference_node,
                    input_source,
                    variation,
                    points,
                    start_freq,
                    stop_freq,
                } => Some((
                    output_node.clone(),
                    reference_node.clone(),
                    input_source.clone(),
                    ac_sweep_frequencies(*variation, *points, *start_freq, *stop_freq),
                )),
                _ => None,
            })
            .collect::<Vec<_>>();
        let analysis = match analyses.as_slice() {
            [analysis] => analysis.clone(),
            [] => return Err("deck has no .NOISE analysis".to_string()),
            _ => return Err("deck has multiple .NOISE analyses".to_string()),
        };
        if analysis.3.is_empty() {
            return Err(".NOISE analysis produced no frequency points".to_string());
        }
        Ok(analysis)
    }

    fn run_static_frequency_bound_ac_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticAcPlan,
        reference: XycePrnTable,
        frequencies: Vec<Value>,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.contract.result_contract(false);
        let Some(primary_print) = plan.print.as_ref() else {
            return self.failure_result(
                deck,
                start,
                contract,
                "frequency-bound AC comparison requires a primary .PRINT AC request".to_string(),
                Vec::new(),
            );
        };

        let engine = self.create_xyce_engine();
        let mut point_results = Vec::with_capacity(frequencies.len());
        for (row_index, frequency) in frequencies.iter().copied().enumerate() {
            let point_source = Self::source_with_ac_frequency_bindings(&plan.source, frequency);
            let point_netlist = match Self::parse_xyce_netlist(&point_source, &plan.deck_path) {
                Ok(netlist) => netlist,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "frequency-bound AC row {} parse error at FREQ={frequency}: {err}",
                            row_index + 1
                        ),
                        Vec::new(),
                    );
                }
            };
            let mut results = match engine.run_ac(&point_netlist, &[frequency]) {
                Ok(results) => results,
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!(
                            "RSpice runtime does not yet support this frequency-bound AC deck: {err}"
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "simulation error in frequency-bound AC row {}: {err}",
                            row_index + 1
                        ),
                        Vec::new(),
                    );
                }
            };
            let Some(result) = results.pop() else {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "frequency-bound AC row {} produced no AC result",
                        row_index + 1
                    ),
                    Vec::new(),
                );
            };
            point_results.push(XyceAcDataPointResult {
                netlist: point_netlist,
                result,
            });
        }

        let mismatches = match self.compare_ac_data_prn_reference(
            &reference,
            primary_print,
            &plan.source,
            &point_results,
        ) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("reference comparison error: {err}"),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            let side_mismatches = match self.compare_ac_data_side_outputs(&plan, &point_results) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("AC side-output comparison error: {err}"),
                        Vec::new(),
                    );
                }
            };
            if side_mismatches.is_empty() {
                self.passed_result(deck, start, contract)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("{} Xyce AC side-output mismatch(es)", side_mismatches.len()),
                    side_mismatches,
                )
            }
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!("{} Xyce AC reference mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn run_static_ac_data_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticAcPlan,
        netlist: Netlist,
        reference: XycePrnTable,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.contract.result_contract(false);
        let Some(primary_print) = plan.print.as_ref() else {
            return self.failure_result(
                deck,
                start,
                contract,
                ".AC DATA comparison requires a primary .PRINT AC request".to_string(),
                Vec::new(),
            );
        };
        let Some(data_points) = plan.ac.data_points() else {
            return self.failure_result(
                deck,
                start,
                contract,
                ".AC DATA comparison has no data rows".to_string(),
                Vec::new(),
            );
        };

        let engine = self.create_xyce_engine();
        let mut point_results = Vec::with_capacity(data_points.len());
        for (row_index, point) in data_points.iter().enumerate() {
            let row_netlist =
                match Engine::create_perturbed_netlist_multi(&netlist, &point.overrides) {
                    Ok((row_netlist, _)) => row_netlist,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                ".AC DATA row {} parameter override error: {err}",
                                row_index + 1
                            ),
                            Vec::new(),
                        );
                    }
                };
            let mut results = match engine.run_ac(&row_netlist, &[point.frequency]) {
                Ok(results) => results,
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this .AC DATA deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error in .AC DATA row {}: {err}", row_index + 1),
                        Vec::new(),
                    );
                }
            };
            let Some(result) = results.pop() else {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".AC DATA row {} produced no AC result", row_index + 1),
                    Vec::new(),
                );
            };
            point_results.push(XyceAcDataPointResult {
                netlist: row_netlist,
                result,
            });
        }

        let mismatches = match self.compare_ac_data_prn_reference(
            &reference,
            primary_print,
            &plan.source,
            &point_results,
        ) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("reference comparison error: {err}"),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            let side_mismatches = match self.compare_ac_data_side_outputs(&plan, &point_results) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("AC side-output comparison error: {err}"),
                        Vec::new(),
                    );
                }
            };
            if side_mismatches.is_empty() {
                self.passed_result(deck, start, contract)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("{} Xyce AC side-output mismatch(es)", side_mismatches.len()),
                    side_mismatches,
                )
            }
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!("{} Xyce AC reference mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn run_static_step_ac_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticAcPlan,
        netlist: Netlist,
        reference: XycePrnTable,
        frequencies: Vec<Value>,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.contract.result_contract(true);
        let Some(primary_print) = plan.print.as_ref() else {
            return self.failure_result(
                deck,
                start,
                contract,
                ".STEP AC comparison requires a primary .PRINT AC request".to_string(),
                Vec::new(),
            );
        };
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let expansion_engine = self.create_xyce_engine();
        let step_runs = match Self::nested_step_runs_for_commands_with_limits_and_abort(
            &expansion_engine,
            &netlist,
            &plan.steps,
            xyce_step_plan_limits(),
            &abort,
        ) {
            Ok(runs) => runs,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        ".STEP expansion exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this .STEP AC deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".STEP expansion error: {err}"),
                    Vec::new(),
                );
            }
        };

        let engine = self.create_xyce_engine();
        let mut batches = Vec::with_capacity(step_runs.len());
        for (step_index, run) in step_runs.iter().enumerate() {
            let results = match engine.run_ac(&run.netlist, &frequencies) {
                Ok(results) => results,
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this .STEP AC deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error in AC step {}: {err}", step_index + 1),
                        Vec::new(),
                    );
                }
            };
            batches.push(XyceAcResultBatch {
                netlist: run.netlist.clone(),
                results,
            });
        }

        let mismatches = match self.compare_step_ac_reference_batches(
            &reference,
            primary_print,
            &plan.source,
            frequencies.len(),
            &batches,
        ) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("reference comparison error: {err}"),
                    Vec::new(),
                );
            }
        };

        if mismatches.is_empty() {
            let side_mismatches =
                match self.compare_step_ac_side_outputs(&plan, frequencies.len(), &batches) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("AC side-output comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
            if side_mismatches.is_empty() {
                self.passed_result(deck, start, contract)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce stepped AC side-output mismatch(es)",
                        side_mismatches.len()
                    ),
                    side_mismatches,
                )
            }
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce stepped AC reference mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            )
        }
    }

    fn run_static_step_ac_measurement_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticAcPlan,
        netlist: Netlist,
        frequencies: Vec<Value>,
        start: Instant,
    ) -> XyceTestResult {
        let contract = "wrapper_scalar_measure_step_ac";
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let expansion_engine = self.create_xyce_engine();
        let step_runs = match Self::nested_step_runs_for_commands_with_limits_and_abort(
            &expansion_engine,
            &netlist,
            &plan.steps,
            xyce_step_plan_limits(),
            &abort,
        ) {
            Ok(runs) => runs,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        ".STEP expansion exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this .STEP AC deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".STEP expansion error: {err}"),
                    Vec::new(),
                );
            }
        };
        if step_runs.len() != plan.measurement_reference_paths.len() {
            return self.failure_result(
                deck,
                start,
                contract,
                format!(
                    ".STEP expansion produced {} batches but {} contiguous measurement artifacts exist",
                    step_runs.len(),
                    plan.measurement_reference_paths.len()
                ),
                Vec::new(),
            );
        }

        let engine = self.create_xyce_engine();
        let mut all_mismatches = Vec::new();
        for (step_index, (run, reference_path)) in step_runs
            .iter()
            .zip(&plan.measurement_reference_paths)
            .enumerate()
        {
            let results = match engine.run_ac(&run.netlist, &frequencies) {
                Ok(results) => results,
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this .STEP AC deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error in AC step {}: {err}", step_index + 1),
                        Vec::new(),
                    );
                }
            };
            let measurements =
                crate::analysis::advanced::evaluate_ac_measurements(&run.netlist, &results);
            let continuous = crate::analysis::advanced::evaluate_ac_continuous_measurements(
                &run.netlist,
                &results,
            );
            let mut mismatches = match self.compare_analysis_measurement_outputs(
                std::slice::from_ref(reference_path),
                &[],
                &measurements,
                &continuous,
                plan.measurement_tolerance,
                run.netlist.options.measure_fail_output,
                run.netlist.options.measure_default_value,
                run.netlist.options.measure_use_cont_files(),
                &run.netlist.measurements,
                "AC",
                "AC_CONT",
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("AC step {step_index} measurement comparison error: {err}"),
                        Vec::new(),
                    );
                }
            };
            for mismatch in &mut mismatches {
                mismatch.probe = format!("step {step_index}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }

        if all_mismatches.is_empty() {
            self.passed_result(deck, start, contract)
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce stepped AC measurement mismatch(es)",
                    all_mismatches.len()
                ),
                all_mismatches,
            )
        }
    }

    fn compare_ac_initial_condition_outputs(
        &self,
        plan: &XyceStaticAcPlan,
        netlist: &Netlist,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if !Self::source_has_op_analysis(&plan.source) {
            return Ok(Vec::new());
        }
        let requests = if plan.output_override {
            Self::output_override_print_output_request(&plan.source, "AC_IC")?
                .into_iter()
                .collect::<Vec<_>>()
        } else {
            Self::aggregate_print_output_requests(
                Self::print_output_requests(&plan.source, "AC_IC")?,
                "AC_IC",
            )?
        };
        if requests.is_empty() {
            return Ok(Vec::new());
        }

        let dc = Self::synthetic_op_dc_sweep(netlist)?;
        let (result, device_op_report) = self
            .create_dc_engine()
            .run_dc_op_with_report(netlist)
            .map_err(|err| format!(".OP solve for AC_IC output failed: {err}"))?;
        let op_result = DcSweepPointResult {
            sweep_value: dc.start,
            result,
            device_op_report,
        };

        let mut all_mismatches = Vec::new();
        for request in requests {
            let reference_path = self.ac_initial_condition_reference_path(plan, &request)?;
            let reference =
                Self::parse_ac_initial_condition_reference_file(&request, &reference_path)
                    .map_err(|err| {
                        format!(
                            "failed to parse AC_IC oracle {}: {err}",
                            self.display_path(&reference_path)
                        )
                    })?;
            let print = XycePrintRequest {
                probes: request.probes.clone(),
            };
            let mut mismatches = self.compare_ac_initial_condition_reference(
                &reference,
                &print,
                netlist,
                &plan.source,
                &dc,
                &op_result,
            )?;
            if let Some(file) = request.file.as_deref()
                && Some(file) != plan.primary_ac_ic_file.as_deref()
            {
                for mismatch in &mut mismatches {
                    mismatch.probe = format!("{file}:{}", mismatch.probe);
                }
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(all_mismatches)
    }

    fn ac_initial_condition_reference_path(
        &self,
        plan: &XyceStaticAcPlan,
        request: &XycePrintOutputRequest,
    ) -> Result<PathBuf, String> {
        if request.file.as_deref() == plan.primary_ac_ic_file.as_deref() {
            let extension =
                Self::ac_initial_condition_reference_extension(request.format.as_deref())?;
            let path = self
                .static_output_reference_path(&plan.deck_path, extension)
                .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
            if !path.is_file() {
                return Err(format!(
                    "missing checked-in AC_IC oracle {}",
                    self.display_path(&path)
                ));
            }
            return Ok(path);
        }
        if let Some(file) = request.file.as_deref() {
            return self.side_output_reference_path_for_deck(&plan.deck_path, file);
        }

        let extension = Self::ac_initial_condition_reference_extension(request.format.as_deref())?;
        let path = self
            .static_output_reference_path(&plan.deck_path, extension)
            .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
        if !path.is_file() {
            return Err(format!(
                "missing checked-in AC_IC oracle {}",
                self.display_path(&path)
            ));
        }
        Ok(path)
    }

    fn parse_ac_initial_condition_reference_file(
        request: &XycePrintOutputRequest,
        path: &Path,
    ) -> Result<XycePrnTable, String> {
        match request.format.as_deref().unwrap_or("STD").trim() {
            format if format.eq_ignore_ascii_case("CSV") => Self::parse_csv_file(path),
            format if format.eq_ignore_ascii_case("PROBE") => Self::parse_tran_csd_file(path),
            _ => Self::parse_prn_file(path),
        }
    }

    fn compare_ac_initial_condition_reference(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        netlist: &Netlist,
        source: &str,
        dc: &XyceDcSweep,
        result: &DcSweepPointResult,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let layout = Self::transient_reference_layout(reference)?;
        if reference.rows.len() != 1 {
            return Err(format!(
                "AC_IC reference row count ({}) does not match .OP point count (1)",
                reference.rows.len()
            ));
        }

        let row = &reference.rows[0];
        if row.len() != reference.columns.len() {
            return Err(format!(
                "row 0 has {} values, expected {}",
                row.len(),
                reference.columns.len()
            ));
        }

        let mut mismatches = Vec::new();
        if let Some(stepnum_column) = layout.stepnum_column {
            let expected_stepnum = row[stepnum_column];
            if let Some(relative_error) = self.value_mismatch(
                expected_stepnum,
                0.0,
                self.default_comparison_tolerance("stepnum"),
            ) {
                mismatches.push(XyceValueMismatch {
                    row: 0,
                    probe: "STEPNUM".to_string(),
                    expected: expected_stepnum,
                    actual: 0.0,
                    relative_error,
                });
            }
        }
        if let Some(index_column) = layout.index_column {
            let expected_index = row[index_column];
            if let Some(relative_error) = self.value_mismatch(
                expected_index,
                0.0,
                self.default_comparison_tolerance("index"),
            ) {
                mismatches.push(XyceValueMismatch {
                    row: 0,
                    probe: "Index".to_string(),
                    expected: expected_index,
                    actual: 0.0,
                    relative_error,
                });
            }
        }

        let expected_time = row[layout.time_column];
        if let Some(relative_error) = self.value_mismatch(
            expected_time,
            0.0,
            self.default_comparison_tolerance("time"),
        ) {
            mismatches.push(XyceValueMismatch {
                row: 0,
                probe: "TIME".to_string(),
                expected: expected_time,
                actual: 0.0,
                relative_error,
            });
        }
        if mismatches.len() >= self.config.max_mismatches {
            mismatches.truncate(self.config.max_mismatches);
            return Ok(mismatches);
        }

        let data_columns = self.reference_data_columns(
            reference,
            print,
            netlist,
            layout.data_column_offset,
            true,
        )?;
        let comp_tolerances = self.comp_tolerances(source, &data_columns)?;
        let sweep_point = XyceDcSweepPoint {
            primary: dc.start,
            secondary: None,
        };
        for (column_index, column) in data_columns.iter().enumerate() {
            let expected = row[column_index + layout.data_column_offset];
            let (probe, actual) = match column {
                XyceReferenceColumn::PrimarySweep { name } => (name.as_str(), dc.start),
                XyceReferenceColumn::Probe { name } => (
                    name.as_str(),
                    Self::evaluate_dc_probe(
                        name,
                        netlist,
                        dc,
                        sweep_point,
                        &result.result,
                        &result.device_op_report,
                    )?,
                ),
            };
            let normalized_probe = Self::normalize_probe(probe);
            let tolerance = comp_tolerances
                .get(&normalized_probe)
                .copied()
                .unwrap_or_else(|| self.default_comparison_tolerance(&normalized_probe));
            if let Some(relative_error) = self.value_mismatch(expected, actual, tolerance) {
                mismatches.push(XyceValueMismatch {
                    row: 0,
                    probe: probe.to_string(),
                    expected,
                    actual,
                    relative_error,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    mismatches.truncate(self.config.max_mismatches);
                    break;
                }
            }
        }
        Ok(mismatches)
    }

    fn compare_step_ac_reference_batches(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        source: &str,
        points_per_step: usize,
        batches: &[XyceAcResultBatch],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let step_references =
            Self::split_ac_step_reference(reference, batches.len(), points_per_step)?;
        let mut mismatches = Vec::new();
        let mut row_offset = 0usize;
        for (step_index, (batch, step_reference)) in
            batches.iter().zip(step_references.iter()).enumerate()
        {
            let mut step_mismatches = self.compare_ac_prn_reference_with_step(
                step_reference,
                print,
                &batch.netlist,
                source,
                &batch.results,
                Some(step_index),
            )?;
            for mismatch in &mut step_mismatches {
                mismatch.row += row_offset;
            }
            row_offset += step_reference.rows.len();
            mismatches.extend(step_mismatches);
            if mismatches.len() >= self.config.max_mismatches {
                mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(mismatches)
    }

    fn compare_ac_side_outputs(
        &self,
        plan: &XyceStaticAcPlan,
        netlist: &Netlist,
        results: &[AcResult],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if plan.output_override {
            return Ok(Vec::new());
        }
        let Some(primary_reference_path) = plan.reference_path.as_ref() else {
            return Err(
                "AC side-output comparison requires a primary .PRINT AC oracle".to_string(),
            );
        };
        let side_outputs = Self::prn_compatible_ac_side_output_requests(&plan.source)?;
        let mut all_mismatches = Vec::new();
        for request in side_outputs {
            let file = request
                .file
                .as_deref()
                .expect("side output request has FILE= set");
            if Some(file) == plan.primary_ac_file.as_deref() {
                continue;
            }
            let reference_path =
                Self::ac_side_output_reference_path(primary_reference_path, &request, file)?;
            let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
                format!(
                    "failed to parse AC side-output oracle {}: {err}",
                    self.display_path(&reference_path)
                )
            })?;
            let print = XycePrintRequest {
                probes: request.probes,
            };
            let mut mismatches =
                self.compare_ac_prn_reference(&reference, &print, netlist, &plan.source, results)?;
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{file}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(all_mismatches)
    }

