    fn run_static_prn_dc_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceExecutionPlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = if !plan.reference_path.is_file()
            && (!plan.measurement_reference_paths.is_empty()
                || !plan.continuous_measurement_reference_paths.is_empty())
        {
            "wrapper_scalar_measure_dc"
        } else {
            plan.contract.result_contract(false)
        };
        let netlist = match Self::parse_netlist_with_expression_dialect_and_execution_dir(
            &plan.source,
            &plan.deck_path,
            plan.expression_dialect,
            plan.execution_dir.as_deref(),
        ) {
            Ok(netlist) => netlist,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("parse failed after contract validation: {err}"),
                    Vec::new(),
                );
            }
        };

        let reference = if !plan.reference_path.is_file()
            || matches!(
                plan.contract,
                XyceStaticDcContract::WrapperFilePrn | XyceStaticDcContract::WrapperNoOutput
            ) {
            None
        } else {
            match Self::parse_dc_reference_file(plan.contract, &plan.reference_path) {
                Ok(reference) => Some(reference),
                Err(err) if Self::is_parameter_sweep_summary_reference(&plan.reference_path) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_oracle",
                        &format!(
                            "checked-in Xyce sidecar is a parameter-sweep summary, not a numeric .PRINT table: {err}"
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("failed to parse Xyce reference oracle: {err}"),
                        Vec::new(),
                    );
                }
            }
        };

        if !plan.steps.is_empty() {
            return if let Some(reference) = reference {
                self.run_static_prn_step_dc_plan(deck, plan, netlist, reference, start)
            } else if !plan.measurement_reference_paths.is_empty() {
                self.run_static_step_dc_measurement_plan(deck, plan, netlist, start)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    "file-output-only .STEP DC comparison is not implemented".to_string(),
                    Vec::new(),
                )
            };
        }

        if let Some(dc_data) = &plan.dc_data {
            let results = match self.run_static_dc_data_results(&netlist, dc_data, start) {
                Ok(results) => results,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "simulation exceeded timeout ({}ms)",
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error: {err}"),
                        Vec::new(),
                    );
                }
            };
            let mut mismatches = if let Some(reference) = reference.as_ref() {
                match self.compare_dc_data_prn_reference(
                    reference,
                    &plan.print,
                    &plan.source,
                    &plan.dc,
                    &results,
                ) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("reference comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                }
            } else {
                Vec::new()
            };
            if mismatches.is_empty() && !plan.measurement_reference_paths.is_empty() {
                let measurement_sweep = results
                    .iter()
                    .map(|row| (row.point.sweep_value, row.point.result.clone()))
                    .collect::<Vec<_>>();
                let point_params = results
                    .iter()
                    .map(|row| row.netlist.params.clone())
                    .collect::<Vec<_>>();
                let measurements =
                    crate::analysis::advanced::evaluate_dc_measurements_with_parameter_contexts(
                        &netlist,
                        &measurement_sweep,
                        &point_params,
                    );
                match self.compare_measurement_references(
                    &plan.measurement_reference_paths,
                    &measurements,
                    plan.measurement_tolerance,
                    netlist.options.measure_fail_output,
                    netlist.options.measure_default_value,
                    "DC",
                    &netlist.measurements,
                ) {
                    Ok(measurement_mismatches) => mismatches.extend(measurement_mismatches),
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("DC DATA measurement reference comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                }
            }
            return if mismatches.is_empty() {
                self.passed_result(deck, start, contract)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("{} Xyce reference mismatch(es)", mismatches.len()),
                    mismatches,
                )
            };
        }

        let engine = self.create_dc_engine();
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let results = match engine.run_dc_sweep2_spec_with_report_and_abort(
            &netlist,
            &plan.dc.source,
            &plan.dc.primary_spec(),
            plan.dc.sweep2.as_ref(),
            &abort,
        ) {
            Ok(results) => results,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("simulation error: {err}"),
                    Vec::new(),
                );
            }
        };

        let mismatches = if let Some(reference) = &reference {
            match self.compare_dc_prn_reference(
                reference,
                &plan.print,
                &netlist,
                &plan.source,
                &plan.dc,
                &results,
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("reference comparison error: {err}"),
                        Vec::new(),
                    );
                }
            }
        } else {
            Vec::new()
        };

        if mismatches.is_empty()
            && (!plan.measurement_reference_paths.is_empty()
                || !plan.continuous_measurement_reference_paths.is_empty())
        {
            let measurement_sweep = results
                .iter()
                .map(|point| (point.sweep_value, point.result.clone()))
                .collect::<Vec<_>>();
            let measurements = if netlist
                .analyses
                .iter()
                .any(|analysis| matches!(analysis, AnalysisCommand::Dc { .. }))
            {
                crate::analysis::advanced::evaluate_dc_measurements(&netlist, &measurement_sweep)
            } else {
                crate::analysis::advanced::unevaluated_measurements(
                    &netlist,
                    "DC",
                    "DC measurement requires an explicit .DC analysis",
                )
            };
            let continuous = crate::analysis::advanced::evaluate_dc_continuous_measurements(
                &netlist,
                &measurement_sweep,
            );
            let measurement_mismatches = match self.compare_analysis_measurement_outputs(
                &plan.measurement_reference_paths,
                &plan.continuous_measurement_reference_paths,
                &measurements,
                &continuous,
                plan.measurement_tolerance,
                netlist.options.measure_fail_output,
                netlist.options.measure_default_value,
                netlist.options.measure_use_cont_files(),
                &netlist.measurements,
                "DC",
                "DC_CONT",
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("DC measurement reference comparison error: {err}"),
                        Vec::new(),
                    );
                }
            };
            if !measurement_mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce DC measurement mismatch(es)",
                        measurement_mismatches.len()
                    ),
                    measurement_mismatches,
                );
            }
        }

        if mismatches.is_empty()
            && matches!(plan.contract, XyceStaticDcContract::WrapperGnuplotSplot)
        {
            let batches = [XyceDcResultBatch {
                netlist: netlist.clone(),
                results: results.clone(),
            }];
            let side_mismatches =
                match self.compare_gnuplot_splot_side_output_batches(&plan, &batches) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("GNUPLOT/SPLOT side-output comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
            if !side_mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce GNUPLOT/SPLOT side-output mismatch(es)",
                        side_mismatches.len()
                    ),
                    side_mismatches,
                );
            }
        }

        if mismatches.is_empty()
            && !matches!(plan.contract, XyceStaticDcContract::WrapperGnuplotSplot)
        {
            let batches = [XyceDcResultBatch {
                netlist: netlist.clone(),
                results: results.clone(),
            }];
            let side_mismatches =
                match self.compare_prn_compatible_side_output_batches(&plan, &batches) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("PRN-compatible side-output comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
            if !side_mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce PRN-compatible side-output mismatch(es)",
                        side_mismatches.len()
                    ),
                    side_mismatches,
                );
            }
        }

        if mismatches.is_empty() {
            self.passed_result(deck, start, contract)
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!("{} Xyce reference mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn run_noindex_header_tran_wrapper_plan(
        &self,
        deck: &XyceDeck,
        plan: &XyceStaticTranPlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.result_contract();
        if !plan.steps.is_empty() {
            return self.failure_result(
                deck,
                start,
                contract,
                "NOINDEX header-only transient wrapper contract does not cover .STEP output"
                    .to_string(),
                Vec::new(),
            );
        }

        // The authoritative wrapper still requires a successful simulator run,
        // but deliberately ignores every numeric output row.
        match self.run_transient_family_plan(plan, start, None) {
            Ok((_netlist, _result)) => {}
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this transient deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("simulation error: {err}"),
                    Vec::new(),
                );
            }
        }

        let header = Self::transient_prn_header_columns(&plan.print, false).join("   ");
        if let Err(err) = Self::validate_noindex_tran_prn_header(&header) {
            return self.failure_result(
                deck,
                start,
                contract,
                format!("NOINDEX transient output header error: {err}"),
                Vec::new(),
            );
        }

        self.passed_result(deck, start, contract)
    }

    fn run_static_prn_tran_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticTranPlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.result_contract();
        if matches!(plan.contract, XyceStaticTranContract::WrapperNoIndexHeader) {
            return self.run_noindex_header_tran_wrapper_plan(deck, &plan, start);
        }
        let netlist = match Self::parse_xyce_netlist(&plan.source, &plan.deck_path) {
            Ok(netlist) => netlist,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("parse failed after contract validation: {err}"),
                    Vec::new(),
                );
            }
        };

        let reference_result = match plan.comparison_mode {
            XyceStaticTranComparisonMode::Release710IntegratedRms { .. }
            | XyceStaticTranComparisonMode::Release710IntegratedRmsComp { .. } => {
                Self::parse_xyce_verify_tran_reference_file(&plan.reference_path)
            }
            XyceStaticTranComparisonMode::Pointwise => {
                Self::parse_tran_reference_file(plan.contract, &plan.reference_path)
            }
        };
        let reference = match reference_result {
            Ok(reference) => reference,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("failed to parse Xyce transient oracle: {err}"),
                    Vec::new(),
                );
            }
        };
        if !plan.steps.is_empty() {
            return self.run_static_prn_step_tran_plan(deck, plan, netlist, reference, start);
        }
        let reference_time_grid_result = match plan.comparison_mode {
            XyceStaticTranComparisonMode::Release710IntegratedRms {
                scientific_precision,
            }
            | XyceStaticTranComparisonMode::Release710IntegratedRmsComp {
                scientific_precision,
                ..
            } => Self::xyce_verify_reference_time_grid(&plan, &reference, scientific_precision),
            XyceStaticTranComparisonMode::Pointwise => Self::reference_time_grid(&reference),
        };
        let reference_time_grid = match reference_time_grid_result {
            Ok(grid) => grid,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("reference time-grid error: {err}"),
                    Vec::new(),
                );
            }
        };
        let tran = Self::tran_analysis_for_reference_stop(
            plan.contract,
            plan.tran,
            reference_time_grid.as_slice(),
        );

        let max_step =
            match Self::transient_max_step_for_static_plan(&plan, &netlist, &tran, &reference) {
                Ok(max_step) => max_step,
                Err(err)
                    if !plan.comparison_mode.uses_integrated_rms_verifier()
                        && err.contains("transient harness execution envelope") =>
                {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_contract",
                        &err,
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("transient maximum-step or execution-envelope error: {err}"),
                        Vec::new(),
                    );
                }
            };

        let initial_step = Self::xyce_initial_timestep_for_tran(&plan.tran);
        let engine = self.create_xyce_static_tran_engine(None, initial_step);
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let mut best_mismatches = None;
        let mut simulation_error = None;
        match engine.run_tran_with_abort(&netlist, tran.stop, max_step, &abort) {
            Ok(result) => {
                let mismatches = match self
                    .compare_static_tran_primary_reference(&reference, &plan, &netlist, &result)
                {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("reference comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
                if mismatches.is_empty() {
                    return self.passed_or_tran_side_output_failure(
                        deck, start, contract, &plan, &netlist, &result,
                    );
                }

                best_mismatches = Some(mismatches);
            }
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err)
                if !plan.comparison_mode.uses_integrated_rms_verifier()
                    && Self::is_expected_unsupported_runtime_error(&err) =>
            {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this transient deck: {err}"),
                );
            }
            Err(err) => {
                simulation_error = Some(format!("simulation error: {err}"));
            }
        }

        if plan.comparison_mode.uses_integrated_rms_verifier() {
            if let Some(mismatches) = best_mismatches {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce integrated-RMS transient reference mismatch(es)",
                        mismatches.len()
                    ),
                    mismatches,
                );
            }
            return self.failure_result(
                deck,
                start,
                contract,
                simulation_error.unwrap_or_else(|| {
                    "integrated-RMS transient execution produced no comparable result".to_string()
                }),
                Vec::new(),
            );
        }

        let capacitor_branch_print =
            Self::transient_print_requests_linear_capacitor_branch_quantity(&netlist, &plan.print);
        let mut fallback_errors = Vec::new();

        let locked_engine =
            self.create_xyce_static_tran_engine(Some(reference_time_grid.clone()), initial_step);
        match locked_engine.run_tran_with_abort(&netlist, tran.stop, max_step, &abort) {
            Ok(locked_result) => {
                match self.compare_tran_prn_reference(
                    &reference,
                    &plan.print,
                    &netlist,
                    &plan.source,
                    &locked_result,
                    plan.wrapper_tolerance,
                ) {
                    Ok(locked_mismatches) => {
                        if locked_mismatches.is_empty() {
                            return self.passed_or_tran_side_output_failure(
                                deck,
                                start,
                                contract,
                                &plan,
                                &netlist,
                                &locked_result,
                            );
                        }
                        if Self::candidate_mismatches_are_better(
                            best_mismatches.as_deref(),
                            &locked_mismatches,
                        ) {
                            best_mismatches = Some(locked_mismatches);
                        }
                    }
                    Err(err) => {
                        fallback_errors.push(format!(
                            "locked time-grid reference comparison error: {err}"
                        ));
                    }
                }
            }
            Err(SimulationError::Aborted) => {
                fallback_errors.push(format!(
                    "locked time-grid simulation exceeded timeout ({}ms)",
                    self.config.max_time_per_test_ms
                ));
            }
            Err(err) => {
                fallback_errors.push(format!("locked time-grid simulation error: {err}"));
            }
        }

        if !capacitor_branch_print {
            let backward_euler_engine = self
                .create_xyce_static_tran_engine_with_integration_method(
                    Some(reference_time_grid.clone()),
                    crate::analysis::IntegrationMethod::BackwardEuler,
                    initial_step,
                );
            match backward_euler_engine.run_tran_with_abort(&netlist, tran.stop, max_step, &abort) {
                Ok(backward_euler_result) => {
                    match self.compare_tran_prn_reference(
                        &reference,
                        &plan.print,
                        &netlist,
                        &plan.source,
                        &backward_euler_result,
                        plan.wrapper_tolerance,
                    ) {
                        Ok(backward_euler_mismatches) => {
                            if backward_euler_mismatches.is_empty() {
                                return self.passed_or_tran_side_output_failure(
                                    deck,
                                    start,
                                    contract,
                                    &plan,
                                    &netlist,
                                    &backward_euler_result,
                                );
                            }
                            if Self::candidate_mismatches_are_better(
                                best_mismatches.as_deref(),
                                &backward_euler_mismatches,
                            ) {
                                best_mismatches = Some(backward_euler_mismatches);
                            }
                        }
                        Err(err) => {
                            fallback_errors
                                .push(format!("backward-Euler reference comparison error: {err}"));
                        }
                    }
                }
                Err(SimulationError::Aborted) => {
                    fallback_errors.push(format!(
                        "backward-Euler simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ));
                }
                Err(err) => {
                    fallback_errors.push(format!("backward-Euler simulation error: {err}"));
                }
            }
        }

        if plan.timeint_conststep && !capacitor_branch_print {
            let gear12_engine = self.create_xyce_static_tran_engine_with_integration_method(
                Some(reference_time_grid),
                crate::analysis::IntegrationMethod::Gear2,
                initial_step,
            );
            match gear12_engine.run_tran_with_abort(&netlist, tran.stop, max_step, &abort) {
                Ok(gear12_result) => {
                    match self.compare_tran_prn_reference(
                        &reference,
                        &plan.print,
                        &netlist,
                        &plan.source,
                        &gear12_result,
                        plan.wrapper_tolerance,
                    ) {
                        Ok(gear12_mismatches) => {
                            if gear12_mismatches.is_empty() {
                                return self.passed_or_tran_side_output_failure(
                                    deck,
                                    start,
                                    contract,
                                    &plan,
                                    &netlist,
                                    &gear12_result,
                                );
                            }
                            if Self::candidate_mismatches_are_better(
                                best_mismatches.as_deref(),
                                &gear12_mismatches,
                            ) {
                                best_mismatches = Some(gear12_mismatches);
                            }
                        }
                        Err(err) => {
                            fallback_errors
                                .push(format!("Xyce Gear12 reference comparison error: {err}"));
                        }
                    }
                }
                Err(SimulationError::Aborted) => {
                    fallback_errors.push(format!(
                        "Xyce Gear12 simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ));
                }
                Err(err) => {
                    fallback_errors.push(format!("Xyce Gear12 simulation error: {err}"));
                }
            }
        }

        if let Some(best_mismatches) = best_mismatches {
            self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce transient reference mismatch(es)",
                    best_mismatches.len()
                ),
                best_mismatches,
            )
        } else {
            let mut message = simulation_error.unwrap_or_else(|| {
                "transient simulation produced no comparable result".to_string()
            });
            if !fallback_errors.is_empty() {
                message.push_str("; ");
                message.push_str(&fallback_errors.join("; "));
            }
            self.failure_result(deck, start, contract, message, Vec::new())
        }
    }

    fn run_static_prn_step_tran_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticTranPlan,
        netlist: Netlist,
        reference: XycePrnTable,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.result_contract();
        let uses_integrated_rms = plan.comparison_mode.uses_integrated_rms_verifier();
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let expansion_engine = self.create_xyce_engine();
        let step_runs = match Self::nested_step_runs_for_commands_with_limits_and_abort(
            &expansion_engine,
            &netlist,
            &plan.steps,
            xyce_step_plan_limits(),
            &abort,
        ) {
            Ok(runs) => runs,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        ".STEP expansion exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this .STEP TRAN deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".STEP expansion error: {err}"),
                    Vec::new(),
                );
            }
        };

        let step_references =
            match Self::split_transient_step_reference(&reference, step_runs.len()) {
                Ok(references) => references,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("stepped transient oracle error: {err}"),
                        Vec::new(),
                    );
                }
            };

        let mismatches =
            match self.compare_step_tran_runs(&plan, &step_runs, &step_references, &abort, false) {
                Ok(mismatches) => {
                    if mismatches.is_empty() {
                        return self.passed_or_step_tran_side_output_failure(
                            deck, start, contract, &plan, &step_runs, &abort, false,
                        );
                    }
                    if uses_integrated_rms {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "{} Xyce integrated-RMS stepped transient reference mismatch(es)",
                                mismatches.len()
                            ),
                            mismatches,
                        );
                    }
                    Some(mismatches)
                }
                Err(err) if err.starts_with("UNSUPPORTED:") => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        err.trim_start_matches("UNSUPPORTED:").trim(),
                    );
                }
                Err(err) => {
                    if uses_integrated_rms {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "integrated-RMS stepped transient reference comparison error: {err}"
                            ),
                            Vec::new(),
                        );
                    }
                    let locked_result = self.compare_step_tran_runs(
                        &plan,
                        &step_runs,
                        &step_references,
                        &abort,
                        true,
                    );
                    return match locked_result {
                        Ok(locked_mismatches) if locked_mismatches.is_empty() => self
                            .passed_or_step_tran_side_output_failure(
                                deck, start, contract, &plan, &step_runs, &abort, true,
                            ),
                        Ok(locked_mismatches) => self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "{} Xyce stepped transient reference mismatch(es)",
                                locked_mismatches.len()
                            ),
                            locked_mismatches,
                        ),
                        Err(locked_err) => self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("{err}; locked time-grid retry failed: {locked_err}"),
                            Vec::new(),
                        ),
                    };
                }
            };

        let mismatches = mismatches.expect("non-empty adaptive mismatches");

        if let Ok(locked_mismatches) =
            self.compare_step_tran_runs(&plan, &step_runs, &step_references, &abort, true)
        {
            if locked_mismatches.is_empty() {
                return self.passed_or_step_tran_side_output_failure(
                    deck, start, contract, &plan, &step_runs, &abort, true,
                );
            }
            if Self::candidate_mismatches_are_better(Some(&mismatches), &locked_mismatches) {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce stepped transient reference mismatch(es)",
                        locked_mismatches.len()
                    ),
                    locked_mismatches,
                );
            }
        }

        self.failure_result(
            deck,
            start,
            contract,
            format!(
                "{} Xyce stepped transient reference mismatch(es)",
                mismatches.len()
            ),
            mismatches,
        )
    }

    fn candidate_mismatches_are_better(
        current_best: Option<&[XyceValueMismatch]>,
        candidate: &[XyceValueMismatch],
    ) -> bool {
        let Some(best) = current_best else {
            return true;
        };
        if candidate.len() != best.len() {
            return candidate.len() < best.len();
        }

        let candidate_max = Self::mismatch_max_relative_error(candidate);
        let best_max = Self::mismatch_max_relative_error(best);
        if candidate_max != best_max {
            return candidate_max < best_max;
        }

        Self::mismatch_relative_error_sum(candidate) < Self::mismatch_relative_error_sum(best)
    }

    fn mismatch_max_relative_error(mismatches: &[XyceValueMismatch]) -> f64 {
        mismatches
            .iter()
            .map(|mismatch| mismatch.relative_error)
            .filter(|value| value.is_finite())
            .fold(0.0, f64::max)
    }

    fn mismatch_relative_error_sum(mismatches: &[XyceValueMismatch]) -> f64 {
        mismatches
            .iter()
            .map(|mismatch| mismatch.relative_error)
            .filter(|value| value.is_finite())
            .sum()
    }

    fn compare_step_tran_runs(
        &self,
        plan: &XyceStaticTranPlan,
        step_runs: &[XyceStepRun],
        step_references: &[XycePrnTable],
        abort: &dyn AbortSignal,
        locked_time_grid: bool,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_step_tran_runs_with_print(
            plan,
            &plan.print,
            step_runs,
            step_references,
            abort,
            locked_time_grid,
            true,
        )
    }

    fn compare_step_tran_runs_with_print(
        &self,
        plan: &XyceStaticTranPlan,
        print: &XycePrintRequest,
        step_runs: &[XyceStepRun],
        step_references: &[XycePrnTable],
        abort: &dyn AbortSignal,
        locked_time_grid: bool,
        use_plan_comparison_mode: bool,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let uses_integrated_rms =
            use_plan_comparison_mode && plan.comparison_mode.uses_integrated_rms_verifier();
        if uses_integrated_rms && locked_time_grid {
            return Err(
                "integrated-RMS stepped transient verification does not admit a locked-grid retry"
                    .to_string(),
            );
        }
        let mut mismatches = Vec::new();
        let mut row_offset = 0usize;
        for (step_index, (run, reference)) in
            step_runs.iter().zip(step_references.iter()).enumerate()
        {
            let max_step = if uses_integrated_rms {
                Self::transient_max_step_for_static_plan(plan, &run.netlist, &plan.tran, reference)
            } else {
                Self::transient_max_step_for_reference(&run.netlist, &plan.tran, reference)
            }
            .map_err(|err| {
                if err.contains("transient harness execution envelope") {
                    format!("UNSUPPORTED: {err}")
                } else {
                    format!("reference time-grid error: step {}: {err}", step_index + 1)
                }
            })?;
            let engine = if uses_integrated_rms {
                self.create_xyce_static_tran_engine(
                    None,
                    Self::xyce_initial_timestep_for_tran(&plan.tran),
                )
            } else if locked_time_grid {
                self.create_xyce_engine_with_locked_time_grid(Some(Self::reference_time_grid(
                    reference,
                )?))
            } else {
                self.create_xyce_engine()
            };
            let result = match engine.run_tran_with_abort(
                &run.netlist,
                plan.tran.stop,
                max_step,
                abort,
            ) {
                Ok(result) => result,
                Err(SimulationError::Aborted) => {
                    return Err(format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ));
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return Err(format!(
                        "UNSUPPORTED: RSpice runtime does not yet support this .STEP TRAN deck: {err}"
                    ));
                }
                Err(err) => {
                    return Err(format!("simulation error: step {}: {err}", step_index + 1));
                }
            };

            let mut step_mismatches = if uses_integrated_rms {
                self.compare_static_tran_primary_reference(reference, plan, &run.netlist, &result)
            } else {
                self.compare_tran_prn_reference(
                    reference,
                    print,
                    &run.netlist,
                    &plan.source,
                    &result,
                    plan.wrapper_tolerance,
                )
            }
            .map_err(|err| format!("reference comparison error: step {}: {err}", step_index + 1))?;
            for mismatch in &mut step_mismatches {
                mismatch.row += row_offset;
            }
            mismatches.extend(step_mismatches);
            if mismatches.len() >= self.config.max_mismatches {
                mismatches.truncate(self.config.max_mismatches);
                return Ok(mismatches);
            }
            row_offset += reference.rows.len();
        }
        Ok(mismatches)
    }

    fn passed_or_tran_side_output_failure(
        &self,
        deck: &XyceDeck,
        start: Instant,
        contract: &str,
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> XyceTestResult {
        match self.compare_tran_side_outputs(plan, netlist, result) {
            Ok(mismatches) if mismatches.is_empty() => self.passed_result(deck, start, contract),
            Ok(mismatches) => self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce transient side-output mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            ),
            Err(err) => self.failure_result(
                deck,
                start,
                contract,
                format!("transient side-output comparison error: {err}"),
                Vec::new(),
            ),
        }
    }

    fn passed_or_step_tran_side_output_failure(
        &self,
        deck: &XyceDeck,
        start: Instant,
        contract: &str,
        plan: &XyceStaticTranPlan,
        step_runs: &[XyceStepRun],
        abort: &dyn AbortSignal,
        locked_time_grid: bool,
    ) -> XyceTestResult {
        match self.compare_step_tran_side_outputs(plan, step_runs, abort, locked_time_grid) {
            Ok(mismatches) if mismatches.is_empty() => self.passed_result(deck, start, contract),
            Ok(mismatches) => self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce stepped transient side-output mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            ),
            Err(err) => self.failure_result(
                deck,
                start,
                contract,
                format!("stepped transient side-output comparison error: {err}"),
                Vec::new(),
            ),
        }
    }

    fn compare_tran_side_outputs(
        &self,
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if plan.output_override {
            return Ok(Vec::new());
        }
        let side_outputs = Self::prn_compatible_tran_side_output_requests(&plan.source)?;
        let mut all_mismatches = Vec::new();
        for request in side_outputs {
            let file = request
                .file
                .as_deref()
                .expect("side output request has FILE= set");
            let reference_path = Self::side_output_reference_path(&plan.reference_path, file)?;
            let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
                format!(
                    "failed to parse transient side-output oracle {}: {err}",
                    self.display_path(&reference_path)
                )
            })?;
            let print = XycePrintRequest {
                probes: request.probes,
            };
            let mut mismatches = self.compare_tran_prn_reference(
                &reference,
                &print,
                netlist,
                &plan.source,
                result,
                plan.wrapper_tolerance,
            )?;
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{file}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(all_mismatches)
    }

    fn compare_step_tran_side_outputs(
        &self,
        plan: &XyceStaticTranPlan,
        step_runs: &[XyceStepRun],
        abort: &dyn AbortSignal,
        locked_time_grid: bool,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if plan.output_override {
            return Ok(Vec::new());
        }
        let side_outputs = Self::prn_compatible_tran_side_output_requests(&plan.source)?;
        let mut all_mismatches = Vec::new();
        for request in side_outputs {
            let file = request
                .file
                .as_deref()
                .expect("side output request has FILE= set");
            let reference_path = Self::side_output_reference_path(&plan.reference_path, file)?;
            let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
                format!(
                    "failed to parse transient side-output oracle {}: {err}",
                    self.display_path(&reference_path)
                )
            })?;
            let step_references = Self::split_transient_step_reference(&reference, step_runs.len())
                .map_err(|err| format!("{file}: {err}"))?;
            let print = XycePrintRequest {
                probes: request.probes,
            };
            let mut mismatches = self.compare_step_tran_runs_with_print(
                plan,
                &print,
                step_runs,
                &step_references,
                abort,
                locked_time_grid,
                false,
            )?;
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{file}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(all_mismatches)
    }

    fn split_transient_step_reference(
        reference: &XycePrnTable,
        expected_steps: usize,
    ) -> Result<Vec<XycePrnTable>, String> {
        if expected_steps == 0 {
            return Err(".STEP expansion produced no runs".to_string());
        }
        if expected_steps == 1 {
            return Ok(vec![reference.clone()]);
        }
        let time_column = Self::reference_time_column_index(reference)
            .ok_or_else(|| "stepped transient reference table has no TIME column".to_string())?;
        let mut starts = vec![0usize];
        let mut previous_time = None;
        for (row_index, row) in reference.rows.iter().enumerate() {
            let time = *row.get(time_column).ok_or_else(|| {
                format!("row {row_index} has no TIME column at index {time_column}")
            })?;
            if !time.is_finite() {
                return Err(format!("row {row_index} has non-finite TIME value {time}"));
            }
            if let Some(previous) = previous_time
                && time < previous
            {
                starts.push(row_index);
            }
            previous_time = Some(time);
        }
        starts.push(reference.rows.len());
        let actual_steps = starts.len().saturating_sub(1);
        if actual_steps != expected_steps {
            return Err(format!(
                "reference contains {actual_steps} transient step table(s), but .STEP expansion produced {expected_steps} run(s)"
            ));
        }

        let mut references = Vec::with_capacity(expected_steps);
        for range in starts.windows(2) {
            let start = range[0];
            let end = range[1];
            if start == end {
                return Err("stepped transient reference contains an empty step table".to_string());
            }
            let reference = XycePrnTable {
                columns: reference.columns.clone(),
                rows: reference.rows[start..end].to_vec(),
            };
            Self::validate_transient_stepnum_column(&reference, references.len())?;
            references.push(reference);
        }
        Ok(references)
    }

    fn split_ac_step_reference(
        reference: &XycePrnTable,
        expected_steps: usize,
        points_per_step: usize,
    ) -> Result<Vec<XycePrnTable>, String> {
        if expected_steps == 0 {
            return Err(".STEP expansion produced no runs".to_string());
        }
        if points_per_step == 0 {
            return Err("AC analysis produced no frequency points".to_string());
        }
        if expected_steps == 1 {
            return Ok(vec![reference.clone()]);
        }
        let expected_rows = expected_steps
            .checked_mul(points_per_step)
            .ok_or_else(|| "stepped AC row count overflow".to_string())?;
        if reference.rows.len() != expected_rows {
            return Err(format!(
                "reference contains {} AC row(s), but .STEP expansion produced {expected_steps} run(s) with {points_per_step} frequency point(s) each",
                reference.rows.len()
            ));
        }

        let mut references = Vec::with_capacity(expected_steps);
        for step_index in 0..expected_steps {
            let start = step_index * points_per_step;
            let end = start + points_per_step;
            references.push(XycePrnTable {
                columns: reference.columns.clone(),
                rows: reference.rows[start..end].to_vec(),
            });
        }
        Ok(references)
    }

    fn validate_transient_stepnum_column(
        reference: &XycePrnTable,
        expected_step_index: usize,
    ) -> Result<(), String> {
        let layout = Self::transient_reference_layout(reference)?;
        let Some(stepnum_column) = layout.stepnum_column else {
            return Ok(());
        };
        let expected_step_index = expected_step_index as Value;
        for (row_index, row) in reference.rows.iter().enumerate() {
            let stepnum = *row.get(stepnum_column).ok_or_else(|| {
                format!("row {row_index} has no STEPNUM column at index {stepnum_column}")
            })?;
            if !stepnum.is_finite() {
                return Err(format!(
                    "row {row_index} has non-finite STEPNUM value {stepnum}"
                ));
            }
            if (stepnum - expected_step_index).abs() > f64::EPSILON {
                return Err(format!(
                    "row {row_index} has STEPNUM {stepnum}, expected {expected_step_index}"
                ));
            }
        }
        Ok(())
    }

    fn compare_gnuplot_splot_side_output_batches(
        &self,
        plan: &XyceExecutionPlan,
        batches: &[XyceDcResultBatch],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let (_, side) = Self::gnuplot_splot_print_pair(&plan.source)?;
        if side.probes != plan.print.probes {
            return Err("SPLOT side-output probes differ from primary GNUPLOT probes".to_string());
        }
        let file = side
            .file
            .as_deref()
            .ok_or_else(|| "SPLOT side-output request has no FILE= target".to_string())?;
        let side_reference_path =
            Self::side_output_reference_candidate(&plan.reference_path, file)?;
        let reference_path = if side_reference_path.is_file() {
            side_reference_path
        } else {
            plan.reference_path.clone()
        };
        let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
            format!(
                "failed to parse SPLOT side-output oracle {}: {err}",
                self.display_path(&reference_path)
            )
        })?;
        let side_print = XycePrintRequest {
            probes: side.probes,
        };
        let mut mismatches = self.compare_dc_prn_reference_batches(
            &reference,
            &side_print,
            &plan.source,
            &plan.dc,
            batches,
        )?;
        for mismatch in &mut mismatches {
            mismatch.probe = format!("{file}:{}", mismatch.probe);
        }
        Ok(mismatches)
    }

    fn compare_prn_compatible_side_output_batches(
        &self,
        plan: &XyceExecutionPlan,
        batches: &[XyceDcResultBatch],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let side_outputs = Self::prn_compatible_side_output_requests(&plan.source)?;
        let mut all_mismatches = Vec::new();
        for request in side_outputs {
            let file = request
                .file
                .as_deref()
                .expect("side output request has FILE= set");
            let reference_path = Self::side_output_reference_path(&plan.reference_path, file)?;
            let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
                format!(
                    "failed to parse side-output oracle {}: {err}",
                    self.display_path(&reference_path)
                )
            })?;
            let print = XycePrintRequest {
                probes: request.probes,
            };
            let mut mismatches = self.compare_dc_prn_reference_batches(
                &reference,
                &print,
                &plan.source,
                &plan.dc,
                batches,
            )?;
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{file}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(all_mismatches)
    }

    fn prn_compatible_side_output_requests(
        source: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        Ok(Self::dc_print_output_requests(source)?
            .into_iter()
            .filter(|request| {
                request.file.is_some()
                    && Self::dc_print_format_is_prn_compatible(
                        request.format.as_deref().unwrap_or("STD"),
                    )
            })
            .collect())
    }

    fn prn_compatible_tran_side_output_requests(
        source: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        Ok(Self::aggregate_print_output_requests(
            Self::print_output_requests(source, "TRAN")?,
            "TRAN",
        )?
        .into_iter()
        .filter(|request| {
            request.file.is_some()
                && Self::tran_print_format_is_prn_compatible(
                    request.format.as_deref().unwrap_or("STD"),
                )
        })
        .collect())
    }

    fn prn_compatible_ac_side_output_requests(
        source: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        Ok(
            Self::aggregate_print_output_requests(
                Self::print_output_requests(source, "AC")?,
                "AC",
            )?
            .into_iter()
            .filter(|request| {
                request.file.is_some()
                    && Self::ac_print_format_is_prn_compatible(
                        request.format.as_deref().unwrap_or("STD"),
                    )
            })
            .collect(),
        )
    }

    fn side_output_reference_path(reference_path: &Path, file: &str) -> Result<PathBuf, String> {
        let candidate = Self::side_output_reference_candidate(reference_path, file)?;
        if !candidate.is_file() {
            return Err(format!(
                "missing checked-in side-output oracle {}",
                candidate.display()
            ));
        }
        Ok(candidate)
    }

    fn side_output_reference_path_for_deck(
        &self,
        deck_path: &Path,
        file: &str,
    ) -> Result<PathBuf, String> {
        let anchor = self
            .static_output_reference_path(deck_path, "anchor")
            .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
        Self::side_output_reference_path(&anchor, file)
    }

    fn ac_side_output_reference_path(
        reference_path: &Path,
        request: &XycePrintOutputRequest,
        file: &str,
    ) -> Result<PathBuf, String> {
        let candidate = Self::side_output_reference_candidate(reference_path, file)?;
        if candidate.is_file() {
            return Ok(candidate);
        }
        let format = request.format.as_deref().unwrap_or("STD");
        if format.eq_ignore_ascii_case("GNUPLOT") || format.eq_ignore_ascii_case("SPLOT") {
            return Ok(reference_path.to_path_buf());
        }
        Err(format!(
            "missing checked-in side-output oracle {}",
            candidate.display()
        ))
    }

    fn side_output_reference_candidate(
        reference_path: &Path,
        file: &str,
    ) -> Result<PathBuf, String> {
        let side_path = Path::new(file);
        if side_path.is_absolute() {
            return Err(format!(
                "absolute FILE= side-output path '{}' cannot be mapped into the vendored OutputData tree",
                file
            ));
        }
        let parent = reference_path
            .parent()
            .ok_or_else(|| "primary reference path has no parent directory".to_string())?;
        Ok(parent.join(side_path))
    }

    fn run_numbered_redefinition_dc_family_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceNumberedRedefinitionDcFamilyContract,
        start: Instant,
    ) -> XyceTestResult {
        let contract_name = contract.role.contract();
        if contract
            .member_paths
            .first()
            .is_none_or(|path| !Self::same_path(path, &contract.baseline_path))
            || contract.member_paths.len() != 3
            || !contract.owner_path.is_file()
        {
            return self.failure_result(
                deck,
                start,
                contract_name,
                "numbered redefinition family lost its qualified owner/baseline/member invariants"
                    .to_string(),
                Vec::new(),
            );
        }

        let baseline_plan = match self.static_dc_plan_for_path_with_redefinition_policy(
            &contract.baseline_path,
            ExpressionDialect::Xyce,
            contract.parameter_redefinition_policy,
        ) {
            Ok(plan) => plan,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract_name,
                    format!(
                        "family '{}' baseline no longer plans: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };
        let (baseline_netlist, baseline_results) =
            match self.run_static_dc_results(&baseline_plan, start) {
                Ok(run) => run,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract_name,
                        format!(
                            "family '{}' baseline failed after qualification: {err}",
                            contract.family
                        ),
                        Vec::new(),
                    );
                }
            };
        let baseline_table = match self.dc_results_to_prn_table(
            &baseline_plan,
            &baseline_netlist,
            &baseline_results,
        ) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract_name,
                    format!(
                        "family '{}' baseline output conversion failed: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };

        let targets = match contract.role {
            XyceNumberedRedefinitionDcFamilyRole::Owner
            | XyceNumberedRedefinitionDcFamilyRole::Baseline => {
                contract.member_paths.iter().skip(1).cloned().collect()
            }
            XyceNumberedRedefinitionDcFamilyRole::Member(index) => {
                let Some(path) = contract.member_paths.get(index) else {
                    return self.failure_result(
                        deck,
                        start,
                        contract_name,
                        "qualified member index is outside the family".to_string(),
                        Vec::new(),
                    );
                };
                vec![path.clone()]
            }
        };
        let mut all_mismatches = Vec::new();
        for target_path in targets {
            let target_plan = match self.static_dc_plan_for_path_with_redefinition_policy(
                &target_path,
                ExpressionDialect::Xyce,
                contract.parameter_redefinition_policy,
            ) {
                Ok(plan) => plan,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract_name,
                        format!(
                            "family '{}' member '{}' no longer plans: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            let (target_netlist, target_results) =
                match self.run_static_dc_results(&target_plan, start) {
                    Ok(run) => run,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract_name,
                            format!(
                                "family '{}' member '{}' failed after qualification: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                };
            let target_table = match self.dc_results_to_prn_table(
                &target_plan,
                &target_netlist,
                &target_results,
            ) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract_name,
                        format!(
                            "family '{}' member '{}' output conversion failed: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            let mut mismatches =
                match self.compare_serialized_default_prn_tables(&baseline_table, &target_table) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract_name,
                            format!(
                                "family '{}' member '{}' exact comparison failed: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                };
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{} {}", self.display_path(&target_path), mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        if all_mismatches.is_empty() {
            self.passed_result(deck, start, contract_name)
        } else {
            self.failure_result(
                deck,
                start,
                contract_name,
                format!(
                    "{} exact default-PRN mismatch(es) in family '{}'",
                    all_mismatches.len(),
                    contract.family
                ),
                all_mismatches,
            )
        }
    }

    fn run_shared_stepped_dc_family_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceSharedSteppedDcFamilyContract,
        start: Instant,
    ) -> XyceTestResult {
        let contract_name = contract.role.contract();
        if contract
            .member_paths
            .first()
            .is_none_or(|path| !Self::same_path(path, &contract.baseline_path))
            || contract.prn_reference_path.with_extension("res") != contract.res_reference_path
            || !contract.owner_path.is_file()
        {
            return self.failure_result(
                deck,
                start,
                contract_name,
                "shared stepped-DC family contract lost its qualified owner/baseline/oracle invariants".to_string(),
                Vec::new(),
            );
        }
        let targets = if matches!(contract.role, XyceSharedSteppedDcFamilyRole::Owner) {
            contract.member_paths.clone()
        } else {
            vec![deck.path.clone()]
        };
        for target in targets {
            let static_plan = match self.static_dc_plan_for_path(&target, ExpressionDialect::Xyce) {
                Ok(plan) => plan,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract_name,
                        format!(
                            "qualified family '{}' member '{}' no longer plans: {err}",
                            contract.family,
                            self.display_path(&target)
                        ),
                        Vec::new(),
                    );
                }
            };
            let plan = XyceExecutionPlan {
                deck_path: static_plan.deck_path,
                execution_dir: static_plan.execution_dir,
                reference_path: contract.prn_reference_path.clone(),
                measurement_reference_paths: Vec::new(),
                continuous_measurement_reference_paths: Vec::new(),
                measurement_tolerance: XyceFileCompareTolerance::MEASURE_COMMON_DEFAULT,
                source: static_plan.source,
                expression_dialect: static_plan.expression_dialect,
                print: static_plan.print,
                dc: static_plan.dc,
                dc_data: static_plan.dc_data,
                steps: static_plan.steps,
                contract: XyceStaticDcContract::SharedStepOracle,
            };
            let mut result = self.run_static_prn_dc_plan(deck, plan, start);
            if !result.passed || result.expected_unsupported {
                result.passed = false;
                result.expected_unsupported = false;
                result.contract = contract_name.to_string();
                result.error = Some(format!(
                    "family '{}' member '{}' failed its direct shared .prn/.res oracle contract: {}",
                    contract.family,
                    self.display_path(&target),
                    result
                        .error
                        .as_deref()
                        .unwrap_or("unknown comparison failure")
                ));
                return result;
            }
        }
        self.passed_result(deck, start, contract_name)
    }

    fn run_static_prn_step_dc_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceExecutionPlan,
        netlist: Netlist,
        reference: XycePrnTable,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.contract.result_contract(true);
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let engine = self.create_dc_engine();
        let step_runs = match Self::nested_step_runs_for_commands_with_limits_and_abort(
            &engine,
            &netlist,
            &plan.steps,
            xyce_step_plan_limits(),
            &abort,
        ) {
            Ok(runs) => runs,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        ".STEP expansion exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this .STEP deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".STEP expansion error: {err}"),
                    Vec::new(),
                );
            }
        };

        if plan.contract.compares_step_res_reference() {
            if let Some(res_reference_path) =
                Self::step_res_reference_path(&plan.deck_path, &plan.reference_path)
            {
                if let Err(err) = self.compare_step_res_reference(
                    &res_reference_path,
                    &netlist,
                    &plan.steps,
                    &step_runs,
                ) {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("Xyce .STEP result summary comparison error: {err}"),
                        Vec::new(),
                    );
                }
            }
        }

        let mut batches = Vec::with_capacity(step_runs.len());
        for run in step_runs {
            let results = match engine.run_dc_sweep2_spec_with_report_and_abort(
                &run.netlist,
                &plan.dc.source,
                &plan.dc.primary_spec(),
                plan.dc.sweep2.as_ref(),
                &abort,
            ) {
                Ok(results) => results,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "simulation exceeded timeout ({}ms)",
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this .STEP deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error: {err}"),
                        Vec::new(),
                    );
                }
            };
            batches.push(XyceDcResultBatch {
                netlist: run.netlist,
                results,
            });
        }

        let mismatches = match self.compare_dc_prn_reference_batches(
            &reference,
            &plan.print,
            &plan.source,
            &plan.dc,
            &batches,
        ) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("reference comparison error: {err}"),
                    Vec::new(),
                );
            }
        };

        if mismatches.is_empty()
            && matches!(plan.contract, XyceStaticDcContract::WrapperGnuplotSplot)
        {
            let side_mismatches =
                match self.compare_gnuplot_splot_side_output_batches(&plan, &batches) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("GNUPLOT/SPLOT side-output comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
            if !side_mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce GNUPLOT/SPLOT side-output mismatch(es)",
                        side_mismatches.len()
                    ),
                    side_mismatches,
                );
            }
        }

        if mismatches.is_empty() {
            if !matches!(plan.contract, XyceStaticDcContract::WrapperGnuplotSplot) {
                let side_mismatches =
                    match self.compare_prn_compatible_side_output_batches(&plan, &batches) {
                        Ok(mismatches) => mismatches,
                        Err(err) => {
                            return self.failure_result(
                                deck,
                                start,
                                contract,
                                format!("PRN-compatible side-output comparison error: {err}"),
                                Vec::new(),
                            );
                        }
                    };
                if !side_mismatches.is_empty() {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "{} Xyce PRN-compatible side-output mismatch(es)",
                            side_mismatches.len()
                        ),
                        side_mismatches,
                    );
                }
            }
            return self.passed_result(deck, start, contract);
        }

        self.failure_result(
            deck,
            start,
            contract,
            format!("{} Xyce reference mismatch(es)", mismatches.len()),
            mismatches,
        )
    }

    fn run_static_step_dc_measurement_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceExecutionPlan,
        netlist: Netlist,
        start: Instant,
    ) -> XyceTestResult {
        let contract = "wrapper_scalar_measure_step_dc";
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let engine = self.create_dc_engine();
        let step_runs = match Self::nested_step_runs_for_commands_with_limits_and_abort(
            &engine,
            &netlist,
            &plan.steps,
            xyce_step_plan_limits(),
            &abort,
        ) {
            Ok(runs) => runs,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        ".STEP expansion exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this .STEP DC deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".STEP expansion error: {err}"),
                    Vec::new(),
                );
            }
        };
        if step_runs.len() != plan.measurement_reference_paths.len() {
            return self.failure_result(
                deck,
                start,
                contract,
                format!(
                    ".STEP expansion produced {} batches but {} contiguous measurement artifacts exist",
                    step_runs.len(),
                    plan.measurement_reference_paths.len()
                ),
                Vec::new(),
            );
        }

        let mut all_mismatches = Vec::new();
        for (step_index, (run, reference_path)) in step_runs
            .iter()
            .zip(&plan.measurement_reference_paths)
            .enumerate()
        {
            let (measurement_sweep, point_params) = if let Some(dc_data) = &plan.dc_data {
                match self.run_static_dc_data_results(&run.netlist, dc_data, start) {
                    Ok(results) => (
                        results
                            .iter()
                            .map(|row| (row.point.sweep_value, row.point.result.clone()))
                            .collect::<Vec<_>>(),
                        results
                            .iter()
                            .map(|row| row.netlist.params.clone())
                            .collect::<Vec<_>>(),
                    ),
                    Err(SimulationError::Aborted) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "simulation exceeded timeout ({}ms)",
                                self.config.max_time_per_test_ms
                            ),
                            Vec::new(),
                        );
                    }
                    Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                        return self.expected_unsupported_result(
                            deck,
                            start,
                            "unsupported_xyce_runtime",
                            &format!(
                                "RSpice runtime does not yet support DC DATA step {}: {err}",
                                step_index + 1
                            ),
                        );
                    }
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("simulation error in DC DATA step {}: {err}", step_index + 1),
                            Vec::new(),
                        );
                    }
                }
            } else {
                match engine.run_dc_sweep2_spec_with_report_and_abort(
                    &run.netlist,
                    &plan.dc.source,
                    &plan.dc.primary_spec(),
                    plan.dc.sweep2.as_ref(),
                    &abort,
                ) {
                    Ok(results) => (
                        results
                            .iter()
                            .map(|point| (point.sweep_value, point.result.clone()))
                            .collect::<Vec<_>>(),
                        Vec::new(),
                    ),
                    Err(SimulationError::Aborted) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "simulation exceeded timeout ({}ms)",
                                self.config.max_time_per_test_ms
                            ),
                            Vec::new(),
                        );
                    }
                    Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                        return self.expected_unsupported_result(
                            deck,
                            start,
                            "unsupported_xyce_runtime",
                            &format!(
                                "RSpice runtime does not yet support DC step {}: {err}",
                                step_index + 1
                            ),
                        );
                    }
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("simulation error in DC step {}: {err}", step_index + 1),
                            Vec::new(),
                        );
                    }
                }
            };
            let measurements = if plan.dc_data.is_some()
                || run
                    .netlist
                    .analyses
                    .iter()
                    .any(|analysis| matches!(analysis, AnalysisCommand::Dc { .. }))
            {
                if point_params.is_empty() {
                    crate::analysis::advanced::evaluate_dc_measurements(
                        &run.netlist,
                        &measurement_sweep,
                    )
                } else {
                    crate::analysis::advanced::evaluate_dc_measurements_with_parameter_contexts(
                        &run.netlist,
                        &measurement_sweep,
                        &point_params,
                    )
                }
            } else {
                crate::analysis::advanced::unevaluated_measurements(
                    &run.netlist,
                    "DC",
                    "DC measurement requires an explicit .DC analysis",
                )
            };
            let continuous = if point_params.is_empty() {
                crate::analysis::advanced::evaluate_dc_continuous_measurements(
                    &run.netlist,
                    &measurement_sweep,
                )
            } else {
                crate::analysis::advanced::evaluate_dc_continuous_measurements_with_parameter_contexts(
                    &run.netlist,
                    &measurement_sweep,
                    &point_params,
                )
            };
            let mut mismatches = match self.compare_analysis_measurement_outputs(
                std::slice::from_ref(reference_path),
                &[],
                &measurements,
                &continuous,
                plan.measurement_tolerance,
                run.netlist.options.measure_fail_output,
                run.netlist.options.measure_default_value,
                run.netlist.options.measure_use_cont_files(),
                &run.netlist.measurements,
                "DC",
                "DC_CONT",
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "DC measurement comparison error in step {}: {err}",
                            step_index + 1
                        ),
                        Vec::new(),
                    );
                }
            };
            for mismatch in &mut mismatches {
                mismatch.probe = format!("step[{}]:{}", step_index + 1, mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }

        if all_mismatches.is_empty() {
            self.passed_result(deck, start, contract)
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce stepped DC measurement mismatch(es)",
                    all_mismatches.len()
                ),
                all_mismatches,
            )
        }
    }

    #[cfg(test)]
    fn nested_step_runs_for_commands(
        engine: &Engine,
        netlist: &Netlist,
        steps: &[StepCommand],
    ) -> Result<Vec<XyceStepRun>, SimulationError> {
        Self::nested_step_runs_for_commands_with_limits_and_abort(
            engine,
            netlist,
            steps,
            xyce_step_plan_limits(),
            &crate::abort_signal::NoAbort,
        )
    }

    fn nested_step_runs_for_commands_with_limits_and_abort(
        engine: &Engine,
        netlist: &Netlist,
        steps: &[StepCommand],
        limits: StepPlanLimits,
        abort: &dyn AbortSignal,
    ) -> Result<Vec<XyceStepRun>, SimulationError> {
        let plan = engine.plan_step_commands_with_abort(netlist, steps, limits, abort)?;
        let mut runs = Vec::with_capacity(plan.total_runs());
        for run_index in 0..plan.total_runs() {
            let materialized = engine.materialize_step_run_with_abort(&plan, run_index, abort)?;
            debug_assert_eq!(materialized.run_index(), run_index);
            let (step_values, netlist) = materialized.into_parts();
            runs.push(XyceStepRun {
                step_values,
                netlist,
            });
        }
        Ok(runs)
    }

    fn baseline_family_analysis_for_path(
        &self,
        baseline_path: &Path,
    ) -> Result<XyceBaselineFamilyAnalysis, String> {
        let source = fs::read_to_string(baseline_path)
            .map_err(|err| format!("failed to read baseline deck: {err}"))?;
        let ac_outputs = Self::print_output_requests(&source, "AC")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .count();
        let dc_outputs = Self::print_output_requests(&source, "DC")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .count();
        let tran_outputs = Self::print_output_requests(&source, "TRAN")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .count();

        match (ac_outputs, dc_outputs, tran_outputs) {
            (1, 0, 0) => Ok(XyceBaselineFamilyAnalysis::Ac),
            (0, 1, 0) => Ok(XyceBaselineFamilyAnalysis::Dc),
            (0, 0, 1) => Ok(XyceBaselineFamilyAnalysis::Tran),
            (0, 0, 0) => Err(
                "deck has neither one primary .PRINT AC, one primary .PRINT DC, nor one primary .PRINT TRAN output"
                    .to_string(),
            ),
            (ac, dc, tran) => Err(format!(
                "deck has {ac} primary .PRINT AC output(s), {dc} primary .PRINT DC output(s), and {tran} primary .PRINT TRAN output(s); family analysis selection requires exactly one unambiguous primary output"
            )),
        }
    }

    fn baseline_family_targets(contract: &XyceBaselineFamilyContract) -> (Vec<PathBuf>, bool) {
        let baseline_record = contract
            .target_path
            .as_ref()
            .is_some_and(|target| Self::same_path(target, &contract.baseline_path));
        let targets = if let Some(target_path) = contract.target_path.as_ref()
            && !baseline_record
        {
            vec![target_path.clone()]
        } else {
            contract
                .member_paths
                .iter()
                .filter(|path| !Self::same_path(path, &contract.baseline_path))
                .cloned()
                .collect()
        };
        (targets, baseline_record)
    }

    fn transient_family_plan_purpose_for_path(
        &self,
        kind: XyceBaselineFamilyKind,
        path: &Path,
    ) -> XyceStaticTranPlanPurpose {
        if kind == XyceBaselineFamilyKind::TransientAnalysisExpression
            && self.requires_upstream_wrapper(&self.relative_key(path))
        {
            XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily
        } else {
            kind.transient_plan_purpose()
        }
    }

    fn baseline_family_tran_contracts_compatible(
        kind: XyceBaselineFamilyKind,
        baseline: XyceStaticTranContract,
        target: XyceStaticTranContract,
    ) -> bool {
        match kind {
            XyceBaselineFamilyKind::ScopedModel => matches!(
                (baseline, target),
                (
                    XyceStaticTranContract::PlainStatic,
                    XyceStaticTranContract::WrapperStatic
                )
            ),
            XyceBaselineFamilyKind::AcAnalysisExpression
            | XyceBaselineFamilyKind::BjtExternalNode
            | XyceBaselineFamilyKind::DcAnalysisExpression
            | XyceBaselineFamilyKind::DelimitedExpression
            | XyceBaselineFamilyKind::NestedIncludeIdentity
            | XyceBaselineFamilyKind::PassiveResPrimaryValue
            | XyceBaselineFamilyKind::SubcktParameterPrecedence
            | XyceBaselineFamilyKind::SubcktParameterResolution => false,
            XyceBaselineFamilyKind::AgeCap
            | XyceBaselineFamilyKind::DiodeModelAlias
            | XyceBaselineFamilyKind::SwitchStateCase
            | XyceBaselineFamilyKind::SinExpression
            | XyceBaselineFamilyKind::ParamExpression
            | XyceBaselineFamilyKind::PassiveCapPrimaryValue
            | XyceBaselineFamilyKind::PassiveTemperatureOverride
            | XyceBaselineFamilyKind::Subckt
            | XyceBaselineFamilyKind::Supernode => baseline == target,
            XyceBaselineFamilyKind::TransientAnalysisExpression => matches!(
                (baseline, target),
                (
                    XyceStaticTranContract::PlainStatic,
                    XyceStaticTranContract::WrapperStatic
                )
            ),
        }
    }

    fn tran_analyses_match_exactly(baseline: &XyceTranAnalysis, target: &XyceTranAnalysis) -> bool {
        baseline.step.to_bits() == target.step.to_bits()
            && baseline.stop.to_bits() == target.stop.to_bits()
            && baseline.start.map(Value::to_bits) == target.start.map(Value::to_bits)
            && baseline.max_step.map(Value::to_bits) == target.max_step.map(Value::to_bits)
            && baseline.uic == target.uic
    }

    fn ac_analyses_match_exactly(baseline: &Netlist, target: &Netlist) -> bool {
        match (baseline.analyses.as_slice(), target.analyses.as_slice()) {
            (
                [
                    AnalysisCommand::Ac {
                        variation: baseline_variation,
                        points: baseline_points,
                        start_freq: baseline_start,
                        stop_freq: baseline_stop,
                    },
                ],
                [
                    AnalysisCommand::Ac {
                        variation: target_variation,
                        points: target_points,
                        start_freq: target_start,
                        stop_freq: target_stop,
                    },
                ],
            ) => {
                baseline_variation == target_variation
                    && baseline_points == target_points
                    && baseline_start.is_finite()
                    && baseline_stop.is_finite()
                    && target_start.is_finite()
                    && target_stop.is_finite()
                    && baseline_start.to_bits() == target_start.to_bits()
                    && baseline_stop.to_bits() == target_stop.to_bits()
            }
            _ => false,
        }
    }

    fn baseline_family_qualification_result(
        &self,
        deck: &XyceDeck,
        start: Instant,
        result_contract: &str,
        comparison: XyceBaselineFamilyComparison,
        reason: String,
    ) -> XyceTestResult {
        if comparison.strict_qualification() {
            self.failure_result(deck, start, result_contract, reason, Vec::new())
        } else {
            self.expected_unsupported_result(deck, start, result_contract, &reason)
        }
    }

    fn run_passive_primary_value_composite_contract(
        &self,
        deck: &XyceDeck,
        contract: XycePassivePrimaryCompositeContract,
        start: Instant,
    ) -> XyceTestResult {
        const COMPOSITE_CONTRACT: &str = "passive_primary_value_composite_wrapper";

        if let Some(target_path) = contract.target_path.as_ref() {
            let pair = if contract
                .capacitor_tran
                .member_paths
                .iter()
                .any(|path| Self::same_path(path, target_path))
            {
                contract.capacitor_tran
            } else if contract
                .resistor_dc
                .member_paths
                .iter()
                .any(|path| Self::same_path(path, target_path))
            {
                contract.resistor_dc
            } else {
                return self.failure_result(
                    deck,
                    start,
                    COMPOSITE_CONTRACT,
                    format!(
                        "passive primary-value family '{}' target {} is not one of its four qualified members",
                        contract.family,
                        self.display_path(target_path)
                    ),
                    Vec::new(),
                );
            };
            return self.run_baseline_family_contract(deck, pair, start);
        }

        if !Self::same_path(&deck.path, &contract.owner_path) {
            return self.failure_result(
                deck,
                start,
                COMPOSITE_CONTRACT,
                format!(
                    "passive primary-value family '{}' owner routing does not match {}",
                    contract.family,
                    self.display_path(&contract.owner_path)
                ),
                Vec::new(),
            );
        }

        for pair in [contract.capacitor_tran, contract.resistor_dc] {
            let result = self.run_baseline_family_contract(deck, pair, start);
            if result.expected_unsupported {
                return self.failure_result(
                    deck,
                    start,
                    COMPOSITE_CONTRACT,
                    format!(
                        "passive primary-value composite family '{}' did not execute a required pair: {}",
                        contract.family,
                        result
                            .error
                            .as_deref()
                            .unwrap_or("pair returned expected-unsupported without a reason")
                    ),
                    result.mismatches,
                );
            }
            if !result.passed {
                return XyceTestResult {
                    contract: COMPOSITE_CONTRACT.to_string(),
                    error: result.error.map(|error| {
                        format!(
                            "passive primary-value composite family '{}' failed: {error}",
                            contract.family
                        )
                    }),
                    ..result
                };
            }
        }

        self.passed_result(deck, start, COMPOSITE_CONTRACT)
    }

    fn analytic_rc_reference_table(
        actual: &XycePrnTable,
        specification: &XyceAnalyticRcSpecification,
    ) -> Result<XycePrnTable, String> {
        const LABEL: &str = "analytic first-order RC";
        if !specification.source_value.is_finite()
            || !specification.initial_voltage.is_finite()
            || !specification.resistance.is_finite()
            || specification.resistance <= 0.0
            || !specification.capacitance.is_finite()
            || specification.capacitance <= 0.0
            || !specification.time_constant.is_finite()
            || specification.time_constant <= 0.0
            || (specification.resistance * specification.capacitance).to_bits()
                != specification.time_constant.to_bits()
        {
            return Err(format!(
                "{LABEL} specification is nonfinite or inconsistent"
            ));
        }
        if actual.columns.len() != 3
            || actual.columns[0] != "Index"
            || actual.columns[1] != "TIME"
            || Self::normalize_probe(&actual.columns[2])
                != format!("v({})", specification.output_node).to_ascii_lowercase()
        {
            return Err(format!(
                "{LABEL} generator requires Index, TIME, and V(output), got {:?}",
                actual.columns
            ));
        }
        if actual.rows.is_empty() {
            return Err(format!("{LABEL} simulator output contains no rows"));
        }

        let mut rows = Vec::with_capacity(actual.rows.len());
        for (row_index, row) in actual.rows.iter().enumerate() {
            if row.len() != actual.columns.len()
                || row[0].to_bits() != (row_index as Value).to_bits()
                || row.iter().any(|value| !value.is_finite())
            {
                return Err(format!(
                    "{LABEL} simulator row {row_index} is malformed, nonfinite, or has a noncanonical index"
                ));
            }
            // Release 7.10's Perl generator consumes the TIME token from the
            // already-written default PRN, not the simulator's raw f64 time.
            let printed_time = Self::xyce_default_prn_roundtrip(row[1])?;
            if printed_time < 0.0 {
                return Err(format!(
                    "{LABEL} simulator row {row_index} has negative printed time {printed_time}"
                ));
            }
            let decay = (-printed_time / specification.time_constant).exp();
            let analytic_value = specification.source_value
                + (specification.initial_voltage - specification.source_value) * decay;
            if !analytic_value.is_finite() {
                return Err(format!(
                    "{LABEL} produced nonfinite value at printed time {printed_time}"
                ));
            }
            rows.push(vec![row[0], printed_time, analytic_value]);
        }
        Ok(XycePrnTable {
            columns: actual.columns.clone(),
            rows,
        })
    }

    fn validate_analytic_rc_initial_sample(
        actual: &XycePrnTable,
        specification: &XyceAnalyticRcSpecification,
    ) -> Result<(), String> {
        const LABEL: &str = "analytic first-order RC";
        let first = actual
            .rows
            .first()
            .ok_or_else(|| format!("{LABEL} simulator output contains no initial sample"))?;
        if actual.columns.len() != 3 || first.len() != actual.columns.len() {
            return Err(format!(
                "{LABEL} initial-sample validation requires one Index/TIME/probe row"
            ));
        }
        if first[0].to_bits() != 0.0f64.to_bits() {
            return Err(format!(
                "{LABEL} first sample has noncanonical index {}",
                first[0]
            ));
        }
        let printed_time = Self::xyce_default_prn_roundtrip(first[1])?;
        let printed_value = Self::xyce_default_prn_roundtrip(first[2])?;
        let printed_initial = Self::xyce_default_prn_roundtrip(specification.initial_voltage)?;
        let normalized_error =
            Self::xyce_verify_normalized_error(printed_initial, printed_value).abs();
        if printed_time != 0.0 || !normalized_error.is_finite() || normalized_error > 1.0 {
            return Err(format!(
                "{LABEL} requires the first serialized sample to be TIME=0 and V(output) within the default xyce_verify bound around {printed_initial}; got TIME={printed_time}, V(output)={printed_value}, normalized error={normalized_error}"
            ));
        }
        Ok(())
    }

    fn validate_analytic_rc_complete_time_domain(
        actual: &XycePrnTable,
        stop_time: Value,
    ) -> Result<(), String> {
        const LABEL: &str = "analytic first-order RC";
        if !stop_time.is_finite() || stop_time <= 0.0 {
            return Err(format!("{LABEL} has invalid planned stop time {stop_time}"));
        }
        if actual.columns.len() != 3 || actual.rows.len() < 2 {
            return Err(format!(
                "{LABEL} output domain requires at least two Index/TIME/probe rows"
            ));
        }
        let first = actual.rows.first().expect("row count was checked");
        let last = actual.rows.last().expect("row count was checked");
        if first.len() != actual.columns.len() || last.len() != actual.columns.len() {
            return Err(format!(
                "{LABEL} output domain boundary rows do not match the output columns"
            ));
        }
        let printed_first = Self::xyce_default_prn_roundtrip(first[1])?;
        let printed_last = Self::xyce_default_prn_roundtrip(last[1])?;
        let printed_stop = Self::xyce_default_prn_roundtrip(stop_time)?;
        if printed_first != 0.0 || printed_last.to_bits() != printed_stop.to_bits() {
            return Err(format!(
                "{LABEL} output domain must span serialized TIME=0 through .TRAN stop {printed_stop}, got {printed_first} through {printed_last}"
            ));
        }
        Ok(())
    }

    fn run_analytic_integer_dc_wrapper_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceAnalyticIntegerDcContract,
        start: Instant,
    ) -> XyceTestResult {
        let result_contract = contract.kind.result_contract();
        let (netlist, results) = match self.run_static_dc_results(&contract.plan, start) {
            Ok(run) => run,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!(
                        "analytic integer DC execution exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!("analytic integer DC execution failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let actual = match self.dc_results_to_prn_table(&contract.plan, &netlist, &results) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!("analytic integer DC output conversion failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let mismatches = match self.compare_analytic_integer_dc_table(&actual, contract.kind) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!("analytic integer DC exact comparison failed: {err}"),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            self.passed_result(deck, start, result_contract)
        } else {
            self.failure_result(
                deck,
                start,
                result_contract,
                format!("{} analytic integer DC mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn run_resistor_dtemp_relational_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceResistorDtempContract,
        start: Instant,
    ) -> XyceTestResult {
        let result_contract = contract.role.result_contract();
        // Preserve the upstream wrapper's execution order: res_ref.cir is the
        // independently simulated good data and res_dtemp.cir is the test.
        let reference = match self.simulate_resistor_dtemp_step_plan(
            &contract.reference_plan,
            start,
            "reference",
        ) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!("resistor DTEMP reference execution failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let owner = match self.simulate_resistor_dtemp_step_plan(
            &contract.owner_plan,
            start,
            "DTEMP owner",
        ) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!("resistor DTEMP owner execution failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let mismatches = match self.compare_resistor_dtemp_tables(&reference, &owner) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!("resistor DTEMP relational comparison failed: {err}"),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            self.passed_result(deck, start, result_contract)
        } else {
            self.failure_result(
                deck,
                start,
                result_contract,
                format!(
                    "{} resistor DTEMP relational mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            )
        }
    }

    fn simulate_resistor_dtemp_step_plan(
        &self,
        plan: &XyceStaticDcPlan,
        start: Instant,
        role: &str,
    ) -> Result<XycePrnTable, String> {
        let netlist = Self::parse_netlist_with_expression_dialect_policy_and_execution_dir(
            &plan.source,
            &plan.deck_path,
            plan.expression_dialect,
            plan.parameter_redefinition_policy,
            plan.execution_dir.as_deref(),
        )
        .map_err(|err| format!("{role} parse failed: {err}"))?;
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let engine = self.create_dc_engine();
        let step_runs = Self::nested_step_runs_for_commands_with_limits_and_abort(
            &engine,
            &netlist,
            &plan.steps,
            xyce_step_plan_limits(),
            &abort,
        )
        .map_err(|err| format!("{role} STEP expansion failed: {err}"))?;
        if step_runs.len() != 3 {
            return Err(format!(
                "{role} STEP expansion produced {} batches instead of three",
                step_runs.len()
            ));
        }

        let mut columns = vec!["Index".to_string()];
        columns.extend(plan.print.probes.iter().cloned());
        let mut rows = Vec::new();
        for (step_index, run) in step_runs.into_iter().enumerate() {
            let results = engine
                .run_dc_sweep2_spec_with_report_and_abort(
                    &run.netlist,
                    &plan.dc.source,
                    &plan.dc.primary_spec(),
                    plan.dc.sweep2.as_ref(),
                    &abort,
                )
                .map_err(|err| {
                    format!("{role} step {} simulation failed: {err}", step_index + 1)
                })?;
            if results.len() != 6 {
                return Err(format!(
                    "{role} step {} produced {} DC points instead of six",
                    step_index + 1,
                    results.len()
                ));
            }
            for (row_index, point) in results.iter().enumerate() {
                let sweep_point = XyceDcSweepPoint {
                    primary: point.sweep_value,
                    secondary: None,
                };
                let mut row = vec![row_index as Value];
                for probe in &plan.print.probes {
                    row.push(Self::evaluate_dc_probe(
                        probe,
                        &run.netlist,
                        &plan.dc,
                        sweep_point,
                        &point.result,
                        &point.device_op_report,
                    )?);
                }
                rows.push(row);
            }
        }
        Ok(XycePrnTable { columns, rows })
    }

    fn compare_resistor_dtemp_tables(
        &self,
        reference: &XycePrnTable,
        owner: &XycePrnTable,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if reference.columns != owner.columns
            || reference.columns.len() != 3
            || reference.columns[0] != "Index"
        {
            return Err(format!(
                "upstream-compatible stepped PRN columns differ or are noncanonical: reference={:?}, owner={:?}",
                reference.columns, owner.columns
            ));
        }
        if reference.rows.len() != 18 || owner.rows.len() != reference.rows.len() {
            return Err(format!(
                "upstream-compatible stepped PRN row census must be 18, got reference={} owner={}",
                reference.rows.len(),
                owner.rows.len()
            ));
        }

        // The removed wrapper's first and effective oracle is `diff` over the
        // two default PRNs. It supplies no good-result artifact for the
        // attempted xyce_verify fallback, so this adapter intentionally keeps
        // segment order, per-step Index resets, columns, and serialized numeric
        // payload exact instead of admitting a tolerant substitute.
        let mut mismatches = Vec::new();
        for (row_index, (expected_row, actual_row)) in
            reference.rows.iter().zip(&owner.rows).enumerate()
        {
            if expected_row.len() != reference.columns.len()
                || actual_row.len() != owner.columns.len()
            {
                return Err(format!(
                    "stepped PRN row {row_index} has a noncanonical width"
                ));
            }
            let expected_index = (row_index % 6) as Value;
            if expected_row[0].to_bits() != expected_index.to_bits()
                || actual_row[0].to_bits() != expected_index.to_bits()
            {
                return Err(format!(
                    "stepped PRN row {row_index} does not preserve the canonical per-segment Index reset"
                ));
            }
            for (column_index, (&expected, &actual)) in
                expected_row.iter().zip(actual_row).enumerate()
            {
                let expected_text = Self::xyce_default_prn_text(expected)?;
                let actual_text = Self::xyce_default_prn_text(actual)?;
                if expected_text != actual_text {
                    let scale = expected.abs().max(actual.abs()).max(Value::MIN_POSITIVE);
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: reference.columns[column_index].clone(),
                        expected,
                        actual,
                        relative_error: (expected - actual).abs() / scale,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
        }
        Ok(mismatches)
    }

    fn run_bug647_resistor_relational_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceBug647ResistorContract,
        start: Instant,
    ) -> XyceTestResult {
        let result_contract = contract.role.result_contract();
        let tables = self.simulate_bug647_resistor_pair(
            &contract.owner_plan,
            &contract.reference_plan,
            start,
        );
        let (owner, reference) = match tables {
            Ok(tables) => tables,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!("BUG 647 resistor paired execution failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let mismatches = match self.compare_bug647_resistor_tables(&reference, &owner) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!("BUG 647 resistor file_compare adapter failed: {err}"),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            self.passed_result(deck, start, result_contract)
        } else {
            self.failure_result(
                deck,
                start,
                result_contract,
                format!("{} BUG 647 resistor mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn simulate_bug647_resistor_pair(
        &self,
        owner_plan: &XyceStaticDcPlan,
        reference_plan: &XyceStaticDcPlan,
        start: Instant,
    ) -> Result<(XycePrnTable, XycePrnTable), String> {
        let parse = |plan: &XyceStaticDcPlan, role: &str| {
            Self::parse_netlist_with_expression_dialect_policy_and_execution_dir(
                &plan.source,
                &plan.deck_path,
                plan.expression_dialect,
                plan.parameter_redefinition_policy,
                plan.execution_dir.as_deref(),
            )
            .map_err(|err| format!("{role} parse failed: {err}"))
        };
        let owner_netlist = parse(owner_plan, "instance-parameter owner")?;
        let reference_netlist = parse(reference_plan, "model-parameter reference")?;
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let engine = self.create_dc_engine();
        let expand = |netlist: &Netlist, plan: &XyceStaticDcPlan, role: &str| {
            Self::nested_step_runs_for_commands_with_limits_and_abort(
                &engine,
                netlist,
                &plan.steps,
                xyce_step_plan_limits(),
                &abort,
            )
            .map_err(|err| format!("{role} STEP expansion failed: {err}"))
        };
        let owner_runs = expand(&owner_netlist, owner_plan, "instance-parameter owner")?;
        let reference_runs = expand(
            &reference_netlist,
            reference_plan,
            "model-parameter reference",
        )?;
        if owner_runs.len() != 270 || reference_runs.len() != 270 {
            return Err(format!(
                "paired STEP census must be 270 runs per deck, got owner={} reference={}",
                owner_runs.len(),
                reference_runs.len()
            ));
        }

        let owner_grids = owner_plan
            .steps
            .iter()
            .map(|step| step.sweep.values())
            .collect::<Vec<_>>();
        let reference_grids = reference_plan
            .steps
            .iter()
            .map(|step| step.sweep.values())
            .collect::<Vec<_>>();
        if owner_grids.iter().map(Vec::len).collect::<Vec<_>>() != [5, 6, 3, 3]
            || owner_grids.len() != reference_grids.len()
            || owner_grids
                .iter()
                .zip(&reference_grids)
                .any(|(owner, reference)| {
                    owner.len() != reference.len()
                        || owner
                            .iter()
                            .zip(reference)
                            .any(|(owner, reference)| owner.to_bits() != reference.to_bits())
                })
        {
            return Err(
                "paired STEP grids are not the exact 5x6x3x3 W/TEMP/TC1/TC2 Cartesian product"
                    .into(),
            );
        }

        for (run_index, (owner, reference)) in owner_runs.iter().zip(&reference_runs).enumerate() {
            let expected = [
                owner_grids[0][run_index % 5],
                owner_grids[1][(run_index / 5) % 6],
                owner_grids[2][(run_index / 30) % 3],
                owner_grids[3][(run_index / 90) % 3],
            ];
            if owner.step_values.len() != 4
                || reference.step_values.len() != 4
                || owner
                    .step_values
                    .iter()
                    .zip(expected)
                    .any(|(actual, expected)| actual.to_bits() != expected.to_bits())
                || reference
                    .step_values
                    .iter()
                    .zip(expected)
                    .any(|(actual, expected)| actual.to_bits() != expected.to_bits())
            {
                return Err(format!(
                    "paired STEP coordinate {run_index} does not preserve first-declared-fastest W/TEMP/TC1/TC2 order"
                ));
            }

            for (parameter, coordinate_index) in
                [("W", 0usize), ("TEMP", 1), ("TC1", 2), ("TC2", 3)]
            {
                let resolve = |run: &XyceStepRun, role: &str| {
                    engine
                        .resolved_resistor_parameter(&run.netlist, "R1", parameter)
                        .map_err(|err| {
                            format!(
                                "{role} coordinate {run_index} effective {parameter} resolution failed: {err}"
                            )
                        })?
                        .ok_or_else(|| {
                            format!(
                                "{role} coordinate {run_index} has no effective R1:{parameter}"
                            )
                        })
                };
                let owner_value = resolve(owner, "owner")?;
                let reference_value = resolve(reference, "reference")?;
                if owner_value.to_bits() != reference_value.to_bits()
                    || owner_value.to_bits() != expected[coordinate_index].to_bits()
                {
                    return Err(format!(
                        "coordinate {run_index} effective R1:{parameter} differs: owner={owner_value} reference={reference_value} expected={}",
                        expected[coordinate_index]
                    ));
                }
            }
            let owner_resistance = engine
                .resolved_resistor_parameter(&owner.netlist, "R1", "R")
                .map_err(|err| {
                    format!("owner coordinate {run_index} resistance resolution failed: {err}")
                })?
                .ok_or_else(|| format!("owner coordinate {run_index} has no resistance"))?;
            let reference_resistance = engine
                .resolved_resistor_parameter(&reference.netlist, "R1", "R")
                .map_err(|err| {
                    format!("reference coordinate {run_index} resistance resolution failed: {err}")
                })?
                .ok_or_else(|| format!("reference coordinate {run_index} has no resistance"))?;
            if owner_resistance.to_bits() != reference_resistance.to_bits() {
                return Err(format!(
                    "coordinate {run_index} effective resistance differs: owner={owner_resistance} reference={reference_resistance}"
                ));
            }
        }

        let owner_table = self.simulate_bug647_resistor_runs(
            owner_plan,
            owner_runs,
            &engine,
            &abort,
            "instance-parameter owner",
        )?;
        let reference_table = self.simulate_bug647_resistor_runs(
            reference_plan,
            reference_runs,
            &engine,
            &abort,
            "model-parameter reference",
        )?;
        Ok((owner_table, reference_table))
    }

    fn simulate_bug647_resistor_runs(
        &self,
        plan: &XyceStaticDcPlan,
        runs: Vec<XyceStepRun>,
        engine: &Engine,
        abort: &DeadlineAbort,
        role: &str,
    ) -> Result<XycePrnTable, String> {
        let mut columns = vec!["Index".to_string()];
        columns.extend(plan.print.probes.iter().cloned());
        let mut rows = Vec::with_capacity(1_620);
        for (step_index, run) in runs.into_iter().enumerate() {
            let netlist = run.netlist;
            let results = engine
                .run_dc_sweep2_spec_with_report_and_abort(
                    &netlist,
                    &plan.dc.source,
                    &plan.dc.primary_spec(),
                    plan.dc.sweep2.as_ref(),
                    abort,
                )
                .map_err(|err| {
                    format!("{role} step {} simulation failed: {err}", step_index + 1)
                })?;
            if results.len() != 6 {
                return Err(format!(
                    "{role} step {} produced {} DC points instead of six",
                    step_index + 1,
                    results.len()
                ));
            }
            for (row_index, point) in results.iter().enumerate() {
                let sweep_point = XyceDcSweepPoint {
                    primary: point.sweep_value,
                    secondary: None,
                };
                let mut row = vec![row_index as Value];
                for probe in &plan.print.probes {
                    row.push(Self::evaluate_dc_probe(
                        probe,
                        &netlist,
                        &plan.dc,
                        sweep_point,
                        &point.result,
                        &point.device_op_report,
                    )?);
                }
                rows.push(row);
            }
        }
        if rows.len() != 1_620 {
            return Err(format!(
                "{role} output has {} rows instead of 1620",
                rows.len()
            ));
        }
        Ok(XycePrnTable { columns, rows })
    }

    fn compare_bug647_resistor_tables(
        &self,
        reference: &XycePrnTable,
        owner: &XycePrnTable,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        const ABS_TOL: Value = 1.0e-6;
        const REL_TOL: Value = 0.01;
        const ZERO_TOL: Value = 1.0e-12;
        let reference_tokens = Self::bug647_default_prn_token_lines(reference)?;
        let owner_tokens = Self::bug647_default_prn_token_lines(owner)?;
        if reference_tokens.len() != 1_622
            || owner_tokens.len() != 1_622
            || reference_tokens[0] != owner_tokens[0]
            || reference_tokens[1_621] != owner_tokens[1_621]
        {
            return Err("paired default PRNs do not have identical 1622-line header/data/footer token streams".into());
        }
        if reference.columns != owner.columns
            || reference.columns.len() != 7
            || reference.columns[0] != "Index"
            || reference.rows.len() != 1_620
            || owner.rows.len() != 1_620
        {
            return Err(format!(
                "paired default PRNs require identical seven-column headers and 1620 rows, got reference={:?}/{} owner={:?}/{}",
                reference.columns,
                reference.rows.len(),
                owner.columns,
                owner.rows.len()
            ));
        }
        let mut mismatches = Vec::new();
        for (row_index, (expected_row, actual_row)) in
            reference.rows.iter().zip(&owner.rows).enumerate()
        {
            if expected_row.len() != 7 || actual_row.len() != 7 {
                return Err(format!("paired PRN row {row_index} is not seven columns"));
            }
            let expected_index = (row_index % 6) as Value;
            if expected_row[0].to_bits() != expected_index.to_bits()
                || actual_row[0].to_bits() != expected_index.to_bits()
            {
                return Err(format!(
                    "paired PRN row {row_index} does not reset Index for each STEP coordinate"
                ));
            }
            for (column_index, (&expected, &actual)) in
                expected_row.iter().zip(actual_row).enumerate()
            {
                let expected = Self::xyce_default_prn_roundtrip(expected)?;
                let actual = Self::xyce_default_prn_roundtrip(actual)?;
                let exact = actual == expected;
                let both_zero = actual.abs() <= ZERO_TOL && expected.abs() <= ZERO_TOL;
                let absolute_error = (actual - expected).abs();
                let relative_error = absolute_error / expected.abs();
                let within_both = absolute_error < ABS_TOL && relative_error < REL_TOL;
                // Reproduce Release 7.10 file_compare.pl literally. Its FFT
                // phase clause omits an outer abs around `abs(value)-180`.
                let phase_clause =
                    (expected.abs() - 180.0) < ABS_TOL && (actual.abs() - 180.0) < ABS_TOL;
                if exact || both_zero || within_both || phase_clause {
                    continue;
                }
                mismatches.push(XyceValueMismatch {
                    row: row_index,
                    probe: reference.columns[column_index].clone(),
                    expected,
                    actual,
                    relative_error,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    return Ok(mismatches);
                }
            }
        }
        Ok(mismatches)
    }

    fn bug647_default_prn_token_lines(table: &XycePrnTable) -> Result<Vec<Vec<String>>, String> {
        if table.columns.len() != 7 || table.rows.len() != 1_620 {
            return Err(
                "BUG 647 default stepped PRN requires seven columns and 1620 data rows".into(),
            );
        }
        let mut lines = Vec::with_capacity(1_622);
        lines.push(table.columns.clone());
        for (row_index, row) in table.rows.iter().enumerate() {
            if row.len() != 7 {
                return Err(format!("BUG 647 PRN row {row_index} is not seven fields"));
            }
            lines.push(
                row.iter()
                    .map(|value| Self::xyce_default_prn_text(*value))
                    .collect::<Result<Vec<_>, _>>()?,
            );
        }
        lines.push(
            ["End", "of", "Xyce(TM)", "Parameter", "Sweep"]
                .into_iter()
                .map(str::to_string)
                .collect(),
        );
        Ok(lines)
    }

