    fn compare_bug754_global_parameter_tables(
        &self,
        reference: &XycePrnTable,
        owner: &XycePrnTable,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let reference_fingerprint = Self::bug754_default_prn_serialization_fingerprint(reference)?;
        let owner_fingerprint = Self::bug754_default_prn_serialization_fingerprint(owner)?;
        if reference_fingerprint == owner_fingerprint {
            return Ok(Vec::new());
        }
        let mismatches = self.compare_serialized_default_prn_tables(reference, owner)?;
        if mismatches.is_empty() {
            Err(
                "serialized default PRNs differ outside their numeric data tokens despite equal tables"
                    .into(),
            )
        } else {
            Ok(mismatches)
        }
    }

    fn bug754_default_prn_serialization_fingerprint(
        table: &XycePrnTable,
    ) -> Result<Vec<Vec<String>>, String> {
        const COLUMNS: [&str; 4] = ["Index", "v(drain)", "v(gate)", "I(vdrain)"];
        if table.columns != COLUMNS || table.rows.len() != 1_001 {
            return Err(format!(
                "BUG 754 default PRN requires exact columns {COLUMNS:?} and 1001 rows, got {:?}/{}",
                table.columns,
                table.rows.len()
            ));
        }
        // Release 7.10's default writer is deterministic: one fixed header
        // layout, one fixed whitespace layout per four-field row, precision-8
        // scientific formatting for every numeric token, and one fixed
        // simulation footer. Once exact columns, row count, Index sequence,
        // and every formatted token are equal, bytewise PRN equality follows;
        // there is no table-dependent separator or metadata left to vary.
        let mut lines = Vec::with_capacity(1_003);
        lines.push(table.columns.clone());
        for (row_index, row) in table.rows.iter().enumerate() {
            if row.len() != COLUMNS.len() || row[0].to_bits() != (row_index as Value).to_bits() {
                return Err(format!(
                    "BUG 754 default PRN row {row_index} has a noncanonical Index or field count"
                ));
            }
            lines.push(
                row.iter()
                    .map(|value| Self::xyce_default_prn_text(*value))
                    .collect::<Result<Vec<_>, _>>()?,
            );
        }
        lines.push(
            ["End", "of", "Xyce(TM)", "Simulation"]
                .into_iter()
                .map(str::to_string)
                .collect(),
        );
        Ok(lines)
    }

    fn compare_analytic_integer_dc_table(
        &self,
        actual: &XycePrnTable,
        kind: XyceAnalyticIntegerDcKind,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let expected_width = match kind {
            XyceAnalyticIntegerDcKind::Fmod => 3,
            XyceAnalyticIntegerDcKind::IntFloorCeilBehavioralSources => 5,
        };
        if actual.columns.len() != expected_width
            || actual
                .columns
                .first()
                .is_none_or(|column| column != "Index")
            || actual.rows.is_empty()
        {
            return Err(format!(
                "analytic integer DC output requires a nonempty indexed table with {expected_width} columns, got {:?} and {} row(s)",
                actual.columns,
                actual.rows.len()
            ));
        }

        let mut mismatches = Vec::new();
        for (row_index, row) in actual.rows.iter().enumerate() {
            if row.len() != expected_width
                || row[0].to_bits() != (row_index as Value).to_bits()
                || row.iter().any(|value| !value.is_finite())
            {
                return Err(format!(
                    "analytic integer DC row {row_index} is malformed, nonfinite, or has a noncanonical index"
                ));
            }
            // The Release 7.10 Perl wrappers consume whitespace-split tokens
            // from Xyce's already-written default PRN. Round-trip every input
            // and DUT output through that exact serialization boundary before
            // applying their numeric-equality checks.
            let printed_input = Self::xyce_default_prn_roundtrip(row[1])?;
            let expected = match kind {
                XyceAnalyticIntegerDcKind::Fmod => vec![99.5 % printed_input],
                XyceAnalyticIntegerDcKind::IntFloorCeilBehavioralSources => vec![
                    printed_input.trunc(),
                    printed_input.floor(),
                    printed_input.ceil(),
                ],
            };
            for (offset, expected_value) in expected.into_iter().enumerate() {
                let column = offset + 2;
                let actual_value = Self::xyce_default_prn_roundtrip(row[column])?;
                if expected_value == actual_value {
                    continue;
                }
                let scale = expected_value
                    .abs()
                    .max(actual_value.abs())
                    .max(Value::MIN_POSITIVE);
                mismatches.push(XyceValueMismatch {
                    row: row_index,
                    probe: actual.columns[column].clone(),
                    expected: expected_value,
                    actual: actual_value,
                    relative_error: (expected_value - actual_value).abs() / scale,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    return Ok(mismatches);
                }
            }
        }
        Ok(mismatches)
    }

    fn run_analytic_rc_wrapper_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceAnalyticRcContract,
        start: Instant,
    ) -> XyceTestResult {
        const RESULT_CONTRACT: &str = "analytic_first_order_rc_tran_wrapper";
        let (netlist, result) = match self.run_transient_family_plan(&contract.plan, start, None) {
            Ok(result) => result,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!(
                        "analytic first-order RC execution exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!("analytic first-order RC execution failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let actual =
            match Self::transient_family_result_to_prn_table(&contract.plan, &netlist, &result) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        RESULT_CONTRACT,
                        format!("analytic first-order RC output conversion failed: {err}"),
                        Vec::new(),
                    );
                }
            };
        if let Err(err) =
            Self::validate_analytic_rc_initial_sample(&actual, &contract.specification)
        {
            return self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!("analytic first-order RC initial-condition validation failed: {err}"),
                Vec::new(),
            );
        }
        if let Err(err) =
            Self::validate_analytic_rc_complete_time_domain(&actual, contract.plan.tran.stop)
        {
            return self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!("analytic first-order RC output-domain validation failed: {err}"),
                Vec::new(),
            );
        }
        let reference = match Self::analytic_rc_reference_table(&actual, &contract.specification) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!("analytic first-order RC reference generation failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let mismatches = match self.compare_xyce_verify_transient_tables(&reference, &actual) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!("analytic first-order RC xyce_verify comparison failed: {err}"),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            self.passed_result(deck, start, RESULT_CONTRACT)
        } else {
            self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!(
                    "{} analytic first-order RC xyce_verify mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            )
        }
    }

    fn analytic_sinusoidal_rc_reference_table(
        actual: &XycePrnTable,
        specification: &XyceAnalyticSinusoidalRcSpecification,
    ) -> Result<XycePrnTable, String> {
        const LABEL: &str = "analytic sinusoidal first-order RC";
        let (expression_node, expression_offset) =
            Self::analytic_sinusoidal_rc_print_expression(&specification.print_expression)?;
        if !specification.resistance.is_finite()
            || specification.resistance <= 0.0
            || !specification.capacitance.is_finite()
            || specification.capacitance <= 0.0
            || !specification.source_frequency.is_finite()
            || specification.source_frequency <= 0.0
            || !specification.print_offset.is_finite()
            || specification.resistance.to_bits()
                != XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_RESISTANCE.to_bits()
            || specification.capacitance.to_bits()
                != XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_CAPACITANCE.to_bits()
            || specification.source_frequency.to_bits()
                != XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_FREQUENCY.to_bits()
            || specification.print_offset.to_bits()
                != XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_PRINT_OFFSET.to_bits()
            || expression_node != specification.output_node
            || expression_offset.to_bits() != specification.print_offset.to_bits()
        {
            return Err(format!(
                "{LABEL} specification is nonfinite or differs from the fixed Release 7.10 generator"
            ));
        }
        if actual.columns.len() != 3
            || actual.columns[0] != "Index"
            || actual.columns[1] != "TIME"
            || Self::normalize_probe(&actual.columns[2])
                != Self::normalize_probe(&specification.print_expression)
        {
            return Err(format!(
                "{LABEL} generator requires Index, TIME, and the qualified expression, got {:?}",
                actual.columns
            ));
        }
        if actual.rows.is_empty() {
            return Err(format!("{LABEL} simulator output contains no rows"));
        }

        let a = -1.0 / (specification.resistance * specification.capacitance);
        let s = 2.0 * XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_PI * specification.source_frequency;
        let denominator = a * a + s * s;
        let initial_coefficient = -a * s / denominator;
        if !a.is_finite()
            || !s.is_finite()
            || !denominator.is_finite()
            || denominator <= 0.0
            || !initial_coefficient.is_finite()
        {
            return Err(format!("{LABEL} generator coefficients are invalid"));
        }

        let mut rows = Vec::with_capacity(actual.rows.len());
        for (row_index, row) in actual.rows.iter().enumerate() {
            if row.len() != actual.columns.len()
                || row[0].to_bits() != (row_index as Value).to_bits()
                || row.iter().any(|value| !value.is_finite())
            {
                return Err(format!(
                    "{LABEL} simulator row {row_index} is malformed, nonfinite, or has a noncanonical index"
                ));
            }
            // The Perl sidecar consumes the TIME token from the simulator's
            // already-written default PRN before evaluating its fixed formula.
            let printed_time = Self::xyce_default_prn_roundtrip(row[1])?;
            if printed_time < 0.0 {
                return Err(format!(
                    "{LABEL} simulator row {row_index} has negative printed time {printed_time}"
                ));
            }
            let analytic_value = specification.print_offset
                + initial_coefficient * (a * printed_time).exp()
                + a * (a * (s * printed_time).sin() + s * (s * printed_time).cos()) / denominator;
            if !analytic_value.is_finite() {
                return Err(format!(
                    "{LABEL} produced nonfinite value at printed time {printed_time}"
                ));
            }
            rows.push(vec![row[0], printed_time, analytic_value]);
        }
        Ok(XycePrnTable {
            columns: actual.columns.clone(),
            rows,
        })
    }

    fn validate_analytic_sinusoidal_rc_output_domain(
        actual: &XycePrnTable,
        specification: &XyceAnalyticSinusoidalRcSpecification,
        stop_time: Value,
        tolerance: XyceVerifyTransientTolerance,
    ) -> Result<(), String> {
        const LABEL: &str = "analytic sinusoidal first-order RC";
        let tolerance = tolerance.validate()?;
        if !stop_time.is_finite() || stop_time <= 0.0 {
            return Err(format!("{LABEL} has invalid planned stop time {stop_time}"));
        }
        if actual.columns.len() != 3
            || Self::normalize_probe(&actual.columns[2])
                != Self::normalize_probe(&specification.print_expression)
            || actual.rows.len() < 2
        {
            return Err(format!(
                "{LABEL} output domain requires Index/TIME/expression and at least two rows"
            ));
        }
        let first = actual.rows.first().expect("row count was checked");
        let last = actual.rows.last().expect("row count was checked");
        if first.len() != actual.columns.len() || last.len() != actual.columns.len() {
            return Err(format!(
                "{LABEL} output boundary rows do not match the output columns"
            ));
        }
        let printed_first_time = Self::xyce_default_prn_roundtrip(first[1])?;
        let printed_last_time = Self::xyce_default_prn_roundtrip(last[1])?;
        let printed_stop = Self::xyce_default_prn_roundtrip(stop_time)?;
        let printed_first_value = Self::xyce_default_prn_roundtrip(first[2])?;
        let printed_initial = Self::xyce_default_prn_roundtrip(specification.print_offset)?;
        let initial_error = Self::xyce_verify_normalized_error_with_tolerance(
            printed_initial,
            printed_first_value,
            tolerance,
        )
        .abs();
        if first[0].to_bits() != 0.0f64.to_bits()
            || printed_first_time != 0.0
            || printed_last_time.to_bits() != printed_stop.to_bits()
            || !initial_error.is_finite()
            || initial_error > 1.0
        {
            return Err(format!(
                "{LABEL} output must start at Index=0/TIME=0/value within the qualified xyce_verify bound around {printed_initial} and end at .TRAN stop {printed_stop}; got Index={}, TIME/value={printed_first_time}/{printed_first_value}, normalized initial error={initial_error}, final TIME={printed_last_time}",
                first[0]
            ));
        }
        Ok(())
    }

    fn run_analytic_sinusoidal_rc_wrapper_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceAnalyticSinusoidalRcContract,
        start: Instant,
    ) -> XyceTestResult {
        const RESULT_CONTRACT: &str = "analytic_sinusoidal_first_order_rc_tran_wrapper";
        let (netlist, result) = match self.run_transient_family_plan(&contract.plan, start, None) {
            Ok(result) => result,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!(
                        "analytic sinusoidal first-order RC execution exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!("analytic sinusoidal first-order RC execution failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let actual =
            match Self::transient_family_result_to_prn_table(&contract.plan, &netlist, &result) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        RESULT_CONTRACT,
                        format!(
                            "analytic sinusoidal first-order RC output conversion failed: {err}"
                        ),
                        Vec::new(),
                    );
                }
            };
        if let Err(err) = Self::validate_analytic_sinusoidal_rc_output_domain(
            &actual,
            &contract.specification,
            contract.plan.tran.stop,
            contract.tolerance,
        ) {
            return self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!(
                    "analytic sinusoidal first-order RC output-domain validation failed: {err}"
                ),
                Vec::new(),
            );
        }
        let reference =
            match Self::analytic_sinusoidal_rc_reference_table(&actual, &contract.specification) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        RESULT_CONTRACT,
                        format!(
                            "analytic sinusoidal first-order RC reference generation failed: {err}"
                        ),
                        Vec::new(),
                    );
                }
            };
        let mismatches = match self.compare_xyce_verify_transient_tables_with_tolerance(
            &reference,
            &actual,
            contract.tolerance,
        ) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!(
                        "analytic sinusoidal first-order RC xyce_verify comparison failed: {err}"
                    ),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            self.passed_result(deck, start, RESULT_CONTRACT)
        } else {
            self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!(
                    "{} analytic sinusoidal first-order RC xyce_verify mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            )
        }
    }

    fn run_stepped_ic_reference_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceSteppedIcReferenceContract,
        start: Instant,
    ) -> XyceTestResult {
        const WRAPPER_CONTRACT: &str = "stepped_ic_reference_wrapper";
        const BASELINE_CONTRACT: &str = "stepped_ic_reference_baseline";

        let result_contract = if Self::same_path(&contract.target_path, &contract.owner_path) {
            WRAPPER_CONTRACT
        } else {
            BASELINE_CONTRACT
        };
        let expansion_abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let qualification = (|| {
            let owner_plan = self.static_tran_family_plan_for_path(
                &contract.owner_path,
                XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily,
            )?;
            if owner_plan.output_override || owner_plan.timeint_conststep {
                return Err(
                    "stepped-IC generated-reference wrapper requires ordinary default transient output"
                        .to_string(),
                );
            }
            let [step] = owner_plan.steps.as_slice() else {
                return Err(format!(
                    "stepped-IC generated-reference wrapper requires exactly one .STEP command, found {}",
                    owner_plan.steps.len()
                ));
            };
            if step.target != StepTarget::Device
                || step
                    .param_name
                    .as_deref()
                    .is_none_or(|name| !name.eq_ignore_ascii_case("c"))
                || !matches!(
                    step.sweep,
                    StepSweep::Decade {
                        points_per_decade: 1..,
                        start,
                        stop,
                    } if start.is_finite() && stop.is_finite() && start > 0.0 && stop >= start
                )
            {
                return Err(
                    "stepped-IC generated-reference wrapper requires a finite positive DEC device-parameter sweep of capacitor parameter C"
                        .to_string(),
                );
            }
            let owner_options = Self::stepped_ic_option_signature(&owner_plan.source)?;
            let owner_netlist = Self::parse_xyce_netlist(&owner_plan.source, &owner_plan.deck_path)
                .map_err(|err| format!("owner netlist parse failed: {err}"))?;
            let step_runs = Self::nested_step_runs_for_commands_with_limits_and_abort(
                &self.create_xyce_engine(),
                &owner_netlist,
                &owner_plan.steps,
                xyce_step_plan_limits(),
                &expansion_abort,
            )
            .map_err(|err| match err {
                SimulationError::Aborted => format!(
                    "owner .STEP expansion exceeded timeout ({}ms)",
                    self.config.max_time_per_test_ms
                ),
                error => format!("owner .STEP expansion failed: {error}"),
            })?;
            if step_runs.len() != contract.member_paths.len() {
                return Err(format!(
                    "owner .STEP expands to {} run(s), but the family contains {} independent baseline deck(s)",
                    step_runs.len(),
                    contract.member_paths.len()
                ));
            }

            let mut members = Vec::with_capacity(contract.member_paths.len());
            for (index, (member_path, step_run)) in contract
                .member_paths
                .iter()
                .zip(step_runs.iter())
                .enumerate()
            {
                let member_plan = self.static_tran_family_plan_for_path(
                    member_path,
                    XyceStaticTranPlanPurpose::RelationalFamily,
                )?;
                if !member_plan.steps.is_empty()
                    || member_plan.output_override
                    || member_plan.timeint_conststep
                {
                    return Err(format!(
                        "independent baseline {} must use one ordinary non-stepped transient output",
                        self.display_path(member_path)
                    ));
                }
                if member_plan.print.probes != owner_plan.print.probes {
                    return Err(format!(
                        "independent baseline {} changes the ordered .PRINT TRAN probes",
                        self.display_path(member_path)
                    ));
                }
                if !Self::tran_analyses_match_exactly(&owner_plan.tran, &member_plan.tran) {
                    return Err(format!(
                        "independent baseline {} changes the .TRAN analysis tuple",
                        self.display_path(member_path)
                    ));
                }
                let member_options = Self::stepped_ic_option_signature(&member_plan.source)?;
                if member_options != owner_options {
                    return Err(format!(
                        "independent baseline {} changes the .OPTIONS contract",
                        self.display_path(member_path)
                    ));
                }
                let owner_scale = Self::tran_print_time_scale_factor(&owner_plan.source)?;
                let member_scale = Self::tran_print_time_scale_factor(&member_plan.source)?;
                if owner_scale.to_bits() != member_scale.to_bits() {
                    return Err(format!(
                        "independent baseline {} changes transient output time units",
                        self.display_path(member_path)
                    ));
                }
                let member_netlist =
                    Self::parse_xyce_netlist(&member_plan.source, &member_plan.deck_path).map_err(
                        |err| {
                            format!(
                                "independent baseline {} parse failed: {err}",
                                self.display_path(member_path)
                            )
                        },
                    )?;
                let stepped_snapshot = Self::stepped_ic_snapshot(&step_run.netlist)?;
                let member_snapshot = Self::stepped_ic_snapshot(&member_netlist)?;
                if !step
                    .name
                    .eq_ignore_ascii_case(&stepped_snapshot.capacitor_name)
                {
                    return Err(format!(
                        "owner step targets '{}', but the materialized circuit's qualified capacitor is '{}'",
                        step.name, stepped_snapshot.capacitor_name
                    ));
                }
                if !Self::stepped_ic_snapshots_match(&stepped_snapshot, &member_snapshot) {
                    return Err(format!(
                        "owner step {} is not structurally and numerically identical to independent baseline {}",
                        index,
                        self.display_path(member_path)
                    ));
                }
                let step_value = step_run.step_values.first().copied().ok_or_else(|| {
                    format!(
                        "owner step {index} did not retain its swept {}:C value",
                        step.name
                    )
                })?;
                let member_capacitance = Value::from_bits(member_snapshot.capacitor_value_bits);
                if step_run.step_values.len() != 1
                    || (step_value - member_capacitance).abs() > 1.0e-12
                {
                    return Err(format!(
                        "owner step {index} {}:C value {step_value} does not match independent baseline {} within the Release 7.10 sweep-result tolerance",
                        step.name,
                        self.display_path(member_path)
                    ));
                }
                if !step
                    .name
                    .eq_ignore_ascii_case(&member_snapshot.capacitor_name)
                {
                    return Err(format!(
                        "owner step targets '{}', but independent baseline {} names its qualified capacitor '{}'",
                        step.name,
                        self.display_path(member_path),
                        member_snapshot.capacitor_name
                    ));
                }
                members.push((member_plan, member_netlist));
            }
            Ok((owner_plan, step_runs, members))
        })();

        let (owner_plan, step_runs, members) = match qualification {
            Ok(qualified) => qualified,
            Err(reason) if reason.starts_with("owner .STEP expansion exceeded timeout") => {
                return self.failure_result(deck, start, result_contract, reason, Vec::new());
            }
            Err(reason) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!(
                        "stepped-IC generated-reference family '{}' qualification failed: {reason}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };

        let mut mismatches = Vec::new();
        let mut row_offset = 0usize;
        for (index, ((member_plan, member_netlist), step_run)) in
            members.iter().zip(step_runs.iter()).enumerate()
        {
            let member_result = match self.run_transient_family_netlist(
                member_plan,
                member_netlist,
                start,
                None,
            ) {
                Ok(result) => result,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!(
                            "independent baseline step {index} exceeded timeout ({}ms)",
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!(
                            "RSpice runtime does not yet support stepped-IC baseline step {index}: {err}"
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!("independent baseline step {index} simulation failed: {err}"),
                        Vec::new(),
                    );
                }
            };
            let stepped_result = match self.run_transient_family_netlist(
                &owner_plan,
                &step_run.netlist,
                start,
                None,
            ) {
                Ok(result) => result,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!(
                            "owner step {index} exceeded timeout ({}ms)",
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!(
                            "RSpice runtime does not yet support stepped-IC owner step {index}: {err}"
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!("owner step {index} simulation failed: {err}"),
                        Vec::new(),
                    );
                }
            };
            let baseline_table = match Self::transient_family_result_to_prn_table(
                member_plan,
                member_netlist,
                &member_result,
            ) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!("independent baseline step {index} output failed: {err}"),
                        Vec::new(),
                    );
                }
            };
            let stepped_table = match Self::transient_family_result_to_prn_table(
                &owner_plan,
                &step_run.netlist,
                &stepped_result,
            ) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!("owner step {index} output failed: {err}"),
                        Vec::new(),
                    );
                }
            };
            let mut step_mismatches =
                match self.compare_xyce_verify_transient_tables(&baseline_table, &stepped_table) {
                    Ok(found) => found,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            result_contract,
                            format!(
                                "Release 7.10 xyce_verify comparison failed for step {index}: {err}"
                            ),
                            Vec::new(),
                        );
                    }
                };
            for mismatch in &mut step_mismatches {
                mismatch.row += row_offset;
                mismatch.probe = format!("step {index}: {}", mismatch.probe);
            }
            row_offset += stepped_table.rows.len();
            mismatches.extend(step_mismatches);
            if mismatches.len() >= self.config.max_mismatches {
                mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }

        if mismatches.is_empty() {
            self.passed_result(deck, start, result_contract)
        } else {
            self.failure_result(
                deck,
                start,
                result_contract,
                format!(
                    "{} stepped-IC Release 7.10 xyce_verify mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            )
        }
    }

    fn stepped_ic_option_signature(source: &str) -> Result<Vec<String>, String> {
        let statements = Self::logical_netlist_lines(source)
            .into_iter()
            .map(|line| Self::strip_netlist_comment(&line).trim().to_string())
            .filter(|line| {
                line.split_whitespace()
                    .next()
                    .is_some_and(|command| command.eq_ignore_ascii_case(".options"))
            })
            .map(|line| {
                line.chars()
                    .filter(|ch| !ch.is_whitespace())
                    .collect::<String>()
                    .to_ascii_lowercase()
            })
            .collect::<Vec<_>>();
        if statements.len() != 1 {
            return Err(format!(
                "stepped-IC family requires exactly one .OPTIONS statement, found {}",
                statements.len()
            ));
        }
        Ok(statements)
    }

    fn stepped_ic_snapshot(netlist: &Netlist) -> Result<XyceSteppedIcSnapshot, String> {
        if !netlist.models.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
        {
            return Err(
                "stepped-IC family must be a diagnostic-free flat RC circuit without models, data, node sets, measurements, globals, or external model data"
                    .to_string(),
            );
        }
        if netlist.elements.len() != 3 {
            return Err(format!(
                "stepped-IC family requires exactly three circuit elements, found {}",
                netlist.elements.len()
            ));
        }

        let mut capacitor = None;
        let mut resistor_nodes = None;
        let mut source_nodes = None;
        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            match &element.kind {
                ElementKind::Capacitor {
                    value,
                    value_expr,
                    initial_voltage,
                    model,
                    instance_params,
                    deferred_params,
                } if element.nodes.len() == 2
                    && value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && initial_voltage.is_none()
                    && model.is_none()
                    && instance_params.len() <= 1
                    && instance_params.iter().all(|(name, parameter_value)| {
                        name.eq_ignore_ascii_case("c")
                            && parameter_value.to_bits() == value.to_bits()
                    })
                    && deferred_params.is_empty() =>
                {
                    if capacitor
                        .replace((element.name.clone(), element.nodes.clone(), *value))
                        .is_some()
                    {
                        return Err(
                            "stepped-IC family contains more than one qualified capacitor"
                                .to_string(),
                        );
                    }
                }
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } if element.nodes.len() == 2
                    && value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty() =>
                {
                    if resistor_nodes.replace(element.nodes.clone()).is_some() {
                        return Err(
                            "stepped-IC family contains more than one qualified resistor"
                                .to_string(),
                        );
                    }
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value))
                    if element.nodes.len() == 2
                        && value.is_finite()
                        && value.to_bits() == 0.0f64.to_bits() =>
                {
                    if source_nodes.replace(element.nodes.clone()).is_some() {
                        return Err(
                            "stepped-IC family contains more than one qualified zero-volt source"
                                .to_string(),
                        );
                    }
                }
                _ => {
                    return Err(format!(
                        "stepped-IC family contains unqualified element '{}'",
                        element.name
                    ));
                }
            }
            let name = element.name.trim().to_ascii_lowercase();
            if name.is_empty()
                || elements
                    .insert(
                        name,
                        Self::scoped_model_element_fingerprint(element, &netlist.params)?,
                    )
                    .is_some()
            {
                return Err(
                    "stepped-IC family contains an empty or duplicate element name".to_string(),
                );
            }
        }

        let (capacitor_name, capacitor_nodes, capacitance) =
            capacitor.ok_or_else(|| "stepped-IC family has no qualified capacitor".to_string())?;
        let resistor_nodes = resistor_nodes
            .ok_or_else(|| "stepped-IC family has no qualified resistor".to_string())?;
        let source_nodes = source_nodes
            .ok_or_else(|| "stepped-IC family has no qualified zero-volt source".to_string())?;
        let capacitor_signal = capacitor_nodes
            .iter()
            .find(|node| !Self::node_name_is_ground(node))
            .ok_or_else(|| "stepped-IC capacitor has no non-ground signal node".to_string())?;
        if capacitor_nodes
            .iter()
            .filter(|node| Self::node_name_is_ground(node))
            .count()
            != 1
        {
            return Err("stepped-IC capacitor must connect one signal node to ground".to_string());
        }
        let source_signal = source_nodes
            .iter()
            .find(|node| !Self::node_name_is_ground(node))
            .ok_or_else(|| "stepped-IC zero-volt source has no non-ground node".to_string())?;
        if source_nodes
            .iter()
            .filter(|node| Self::node_name_is_ground(node))
            .count()
            != 1
            || !resistor_nodes
                .iter()
                .any(|node| node.eq_ignore_ascii_case(capacitor_signal))
            || !resistor_nodes
                .iter()
                .any(|node| node.eq_ignore_ascii_case(source_signal))
        {
            return Err(
                "stepped-IC topology must be grounded C -> R -> grounded zero-volt source"
                    .to_string(),
            );
        }

        let [initial_condition] = netlist.initial_conditions.as_slice() else {
            return Err(format!(
                "stepped-IC family requires exactly one .IC voltage, found {}",
                netlist.initial_conditions.len()
            ));
        };
        if initial_condition.voltage_expr.is_some()
            || !initial_condition.voltage.is_finite()
            || !initial_condition
                .node
                .eq_ignore_ascii_case(capacitor_signal)
        {
            return Err(
                "stepped-IC .IC must be one finite direct voltage on the capacitor signal node"
                    .to_string(),
            );
        }
        let initial_conditions = vec![(
            initial_condition.node.trim().to_ascii_lowercase(),
            initial_condition.voltage.to_bits(),
        )];

        Ok(XyceSteppedIcSnapshot {
            elements,
            initial_conditions,
            capacitor_name,
            capacitor_value_bits: capacitance.to_bits(),
        })
    }

    fn stepped_ic_snapshots_match(
        stepped: &XyceSteppedIcSnapshot,
        independent: &XyceSteppedIcSnapshot,
    ) -> bool {
        if !stepped
            .capacitor_name
            .eq_ignore_ascii_case(&independent.capacitor_name)
            || stepped.initial_conditions != independent.initial_conditions
        {
            return false;
        }
        let capacitor_key = stepped.capacitor_name.trim().to_ascii_lowercase();
        let mut stepped_elements = stepped.elements.clone();
        let mut independent_elements = independent.elements.clone();
        let Some(mut stepped_capacitor) = stepped_elements.remove(&capacitor_key) else {
            return false;
        };
        let Some(mut independent_capacitor) = independent_elements.remove(&capacitor_key) else {
            return false;
        };
        let Some(stepped_bits) = stepped_capacitor.numeric_bits.first_mut() else {
            return false;
        };
        let Some(independent_bits) = independent_capacitor.numeric_bits.first_mut() else {
            return false;
        };
        *stepped_bits = 0.0f64.to_bits();
        *independent_bits = 0.0f64.to_bits();
        let stepped_value = Value::from_bits(stepped.capacitor_value_bits);
        let independent_value = Value::from_bits(independent.capacitor_value_bits);
        stepped_elements == independent_elements
            && stepped_capacitor == independent_capacitor
            && stepped_value.is_finite()
            && independent_value.is_finite()
            && (stepped_value - independent_value).abs() <= 1.0e-12
    }

    fn run_subckt_parameter_resolution_family_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceSubcktParameterResolutionFamilyContract,
        start: Instant,
    ) -> XyceTestResult {
        const MEMBER_CONTRACT: &str = "subckt_parameter_resolution_family_member";
        const ERROR_CONTRACT: &str = "subckt_parameter_resolution_expected_error";
        if !contract
            .valid_paths
            .iter()
            .any(|path| Self::same_path(path, &contract.baseline_path))
            || !contract.anchor_path.is_file()
            || !contract.error_path.is_file()
        {
            return self.failure_result(
                deck,
                start,
                XyceBaselineFamilyKind::SubcktParameterResolution.wrapper_contract(),
                format!(
                    "subcircuit-parameter resolution family '{}' lost a qualified anchor, error member, or baseline",
                    contract.family
                ),
                Vec::new(),
            );
        }
        let target_path = match contract.role {
            XyceSubcktParameterResolutionRole::Baseline
            | XyceSubcktParameterResolutionRole::Member => Some(contract.target_path.clone()),
            XyceSubcktParameterResolutionRole::Anchor
            | XyceSubcktParameterResolutionRole::ExpectedError => None,
        };
        let relational = XyceBaselineFamilyContract {
            kind: XyceBaselineFamilyKind::SubcktParameterResolution,
            comparison: XyceBaselineFamilyComparison::ExactPrn,
            family: contract.family,
            baseline_path: contract.baseline_path,
            member_paths: contract.valid_paths,
            target_path,
        };
        let mut result = self.run_baseline_family_contract(deck, relational, start);
        if result.passed && !result.expected_unsupported {
            result.contract = match contract.role {
                XyceSubcktParameterResolutionRole::Anchor => {
                    XyceBaselineFamilyKind::SubcktParameterResolution.wrapper_contract()
                }
                XyceSubcktParameterResolutionRole::Baseline => {
                    XyceBaselineFamilyKind::SubcktParameterResolution.baseline_contract()
                }
                XyceSubcktParameterResolutionRole::Member => MEMBER_CONTRACT,
                XyceSubcktParameterResolutionRole::ExpectedError => ERROR_CONTRACT,
            }
            .to_string();
        }
        result
    }

