    fn elements_device_is_native_b3soi_mosfet(
        elements: &[crate::netlist::Element],
        models: &[crate::netlist::ModelDef],
        scoped_models: &[crate::netlist::ModelDef],
        instance_name: &str,
    ) -> bool {
        elements.iter().any(|element| {
            if !Self::device_instance_names_match(&element.name, instance_name) {
                return false;
            }
            let ElementKind::Mosfet {
                model,
                instance_params,
                ..
            } = &element.kind
            else {
                return false;
            };
            Self::find_model(scoped_models, model)
                .or_else(|| Self::find_model(models, model))
                .is_some_and(|model| Self::model_is_native_b3soi_mosfet(model, instance_params))
        })
    }

    fn model_is_native_b3soi_mosfet(
        model: &crate::netlist::ModelDef,
        instance_params: &[(String, Value)],
    ) -> bool {
        if !matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NMOS" | "PMOS"
        ) {
            return false;
        }
        let Some(level) = Self::numeric_param_value(&model.params, "LEVEL") else {
            return false;
        };
        if (level - 10.0).abs() <= 1.0e-9 {
            return Self::numeric_param_value(instance_params, "SOIMOD")
                .or_else(|| Self::numeric_param_value(&model.params, "SOIMOD"))
                .is_none_or(|soi_mod| {
                    soi_mod.is_finite()
                        && (soi_mod - soi_mod.round()).abs() <= 1.0e-12
                        && matches!(soi_mod.round() as i32, 0..=3)
                });
        }
        [55.0, 56.0, 57.0]
            .iter()
            .any(|native_level| (level - native_level).abs() <= 1.0e-9)
    }

    fn numeric_param_value(params: &[(String, Value)], name: &str) -> Option<Value> {
        params
            .iter()
            .rev()
            .find(|(param_name, _)| param_name.eq_ignore_ascii_case(name))
            .map(|(_, value)| *value)
    }

    fn netlist_element_exports_device_op(element: &crate::netlist::Element) -> bool {
        matches!(
            element.kind,
            ElementKind::Diode { .. }
                | ElementKind::Bjt { .. }
                | ElementKind::Mosfet { .. }
                | ElementKind::Jfet { .. }
                | ElementKind::Mesfet { .. }
        )
    }

    fn device_instance_names_match(lhs: &str, rhs: &str) -> bool {
        Self::normalize_device_instance_name(lhs) == Self::normalize_device_instance_name(rhs)
    }

    fn normalize_device_instance_name(name: &str) -> String {
        Self::normalize_probe(name).replace(':', ".")
    }

    fn node_lookup_candidates(netlist: &Netlist, node_name: &str) -> Vec<String> {
        Engine::node_lookup_candidates(netlist, node_name)
    }

    fn evaluate_scalar_parameter_probe(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        parameter_name: &str,
    ) -> Result<f64, String> {
        if parameter_name.eq_ignore_ascii_case("TEMP")
            || parameter_name.eq_ignore_ascii_case("TEMPER")
        {
            return Ok(Self::active_temperature_c(
                netlist,
                Some(dc),
                Some(sweep_point),
            ));
        }
        if parameter_name.eq_ignore_ascii_case("VT") {
            return Ok(Self::thermal_voltage_celsius(Self::active_temperature_c(
                netlist,
                Some(dc),
                Some(sweep_point),
            )));
        }

        netlist
            .params
            .get(parameter_name)
            .map(Ok)
            .unwrap_or_else(|| {
                let expression = Self::scalar_parameter_expression(&netlist.params, parameter_name)
                    .ok_or_else(|| {
                        format!("scalar parameter probe '{}' is not defined", parameter_name)
                    })?;
                let context = Self::print_eval_context(netlist, Some(dc), Some(sweep_point));
                let prepared =
                    crate::netlist::expr::prepare_behavioral_expression(expression, &context)
                        .map_err(|err| {
                            format!(
                                "scalar parameter probe '{}' could not be prepared: {}",
                                parameter_name, err
                            )
                        })?;
                crate::netlist::expr::eval_expression(&prepared, &context).map_err(|err| {
                    format!(
                        "scalar parameter probe '{}' could not be evaluated: {}",
                        parameter_name, err
                    )
                })
            })
    }

    fn print_eval_context(
        netlist: &Netlist,
        dc: Option<&XyceDcSweep>,
        sweep_point: Option<XyceDcSweepPoint>,
    ) -> crate::netlist::ParamContext {
        let mut context = netlist.params.clone();
        let temp_c = Self::active_temperature_c(netlist, dc, sweep_point);
        context.set("TEMP", temp_c);
        context.set("TEMPER", temp_c);
        context.set("TNOM", netlist.options.tnom.unwrap_or(27.0));
        context.set("VT", Self::thermal_voltage_celsius(temp_c));
        context.set(
            "GMIN",
            netlist.options.gmin.unwrap_or(crate::constants::GMIN),
        );
        Self::add_runtime_scalar_parameter_bindings(&mut context);
        Self::add_resistor_parameter_bindings(netlist, &mut context);
        context
    }

    fn add_runtime_scalar_parameter_bindings(context: &mut crate::netlist::ParamContext) {
        crate::netlist::expr::materialize_available_parameter_expressions(context);
    }

    fn print_tran_eval_context(netlist: &Netlist, time: Value) -> crate::netlist::ParamContext {
        let mut context = Self::print_eval_context(netlist, None, None);
        context.set("TIME", time);
        Self::add_runtime_scalar_parameter_bindings(&mut context);
        for measurement in &netlist.measurements {
            if measurement.analysis.eq_ignore_ascii_case("TRAN") {
                if matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Equation { .. }
                ) {
                    context.set(
                        &measurement.name,
                        netlist
                            .options
                            .measure_default_value
                            .or(measurement.default_value)
                            .unwrap_or(-1.0),
                    );
                }
            }
        }
        context
    }

    fn add_resistor_parameter_bindings(
        netlist: &Netlist,
        context: &mut crate::netlist::ParamContext,
    ) {
        for element in &netlist.elements {
            let ElementKind::Resistor {
                value,
                value_expr,
                model,
                instance_params,
                ..
            } = &element.kind
            else {
                continue;
            };
            if netlist.params.get(&element.name).is_some() {
                continue;
            }

            let Some(resistance) = Self::resistor_parameter_r_value_from_parts(
                *value,
                value_expr.as_deref(),
                model.as_deref(),
                instance_params,
                context,
            ) else {
                continue;
            };
            context.set(&element.name, resistance);
        }
    }

    fn active_temperature_c(
        netlist: &Netlist,
        dc: Option<&XyceDcSweep>,
        sweep_point: Option<XyceDcSweepPoint>,
    ) -> Value {
        if let (Some(dc), Some(sweep_point)) = (dc, sweep_point) {
            if Self::is_temperature_name(&dc.source) {
                return sweep_point.primary;
            }
            if let Some(sweep2) = &dc.sweep2
                && Self::is_temperature_name(&sweep2.source)
                && let Some(secondary) = sweep_point.secondary
            {
                return secondary;
            }
        }

        Self::netlist_temperature_c(netlist)
    }

    fn netlist_temperature_c(netlist: &Netlist) -> Value {
        netlist
            .options
            .temp
            .or_else(|| netlist.params.get("TEMP"))
            .or_else(|| netlist.params.get("TEMPER"))
            .unwrap_or(27.0)
    }

    fn thermal_voltage_celsius(temp_c: Value) -> Value {
        crate::constants::thermal_voltage(crate::analysis::temperature::celsius_to_kelvin(temp_c))
    }

    fn is_temperature_name(name: &str) -> bool {
        name.eq_ignore_ascii_case("TEMP") || name.eq_ignore_ascii_case("TEMPER")
    }

    fn evaluate_resistor_current(
        netlist: &Netlist,
        result: &crate::SimulationResult,
        resistor_name: &str,
        resistance: Value,
    ) -> Result<f64, String> {
        if Self::resistor_uses_branch_form(netlist, resistance) {
            return Err(format!(
                "missing solved branch current for zero/near-zero resistor '{}'",
                resistor_name
            ));
        }
        if resistance.is_infinite() && resistance.is_sign_positive() {
            return Ok(0.0);
        }
        Ok(Self::resistor_voltage_drop(netlist, result, resistor_name)? / resistance)
    }

    fn evaluate_resistor_power(
        netlist: &Netlist,
        result: &crate::SimulationResult,
        resistor_name: &str,
        resistance: Value,
    ) -> Result<f64, String> {
        let voltage_drop = Self::resistor_voltage_drop(netlist, result, resistor_name)?;
        let current =
            if let Some(current) = Self::result_branch_current_named(result, resistor_name) {
                current
            } else {
                Self::evaluate_resistor_current(netlist, result, resistor_name, resistance)?
            };
        Ok(voltage_drop * current)
    }

    fn resistor_voltage_drop(
        netlist: &Netlist,
        result: &crate::SimulationResult,
        resistor_name: &str,
    ) -> Result<Value, String> {
        let element = Self::find_resistor_element(netlist, resistor_name)
            .ok_or_else(|| format!("resistor '{}' not found", resistor_name))?;
        let node_pos = element
            .nodes
            .first()
            .ok_or_else(|| format!("resistor '{}' has no positive node", resistor_name))?;
        let node_neg = element
            .nodes
            .get(1)
            .ok_or_else(|| format!("resistor '{}' has no negative node", resistor_name))?;
        let v_pos = Self::result_voltage_named(result, netlist, node_pos)
            .ok_or_else(|| format!("node '{}' not found in DC result", node_pos))?;
        let v_neg = Self::result_voltage_named(result, netlist, node_neg)
            .ok_or_else(|| format!("node '{}' not found in DC result", node_neg))?;
        Ok(v_pos - v_neg)
    }

    fn result_voltage_named(
        result: &crate::SimulationResult,
        netlist: &Netlist,
        node_name: &str,
    ) -> Option<Value> {
        Self::node_lookup_candidates(netlist, node_name)
            .into_iter()
            .find_map(|candidate| result.try_voltage_named(&candidate))
    }

    fn result_branch_current_named(
        result: &crate::SimulationResult,
        branch_name: &str,
    ) -> Option<Value> {
        result.branch_current_named(branch_name).or_else(|| {
            let normalized = Self::normalize_device_instance_name(branch_name);
            (normalized != branch_name).then(|| result.branch_current_named(&normalized))?
        })
    }

    fn ac_node_voltage_named(
        result: &AcResult,
        netlist: &Netlist,
        node_name: &str,
    ) -> Option<Complex64> {
        if netlist.ground_policy().is_ground(node_name) {
            return Some(Complex64::new(0.0, 0.0));
        }
        Self::node_lookup_candidates(netlist, node_name)
            .into_iter()
            .find_map(|candidate| {
                result
                    .node_names
                    .iter()
                    .position(|name| name.eq_ignore_ascii_case(&candidate))
                    .and_then(|index| result.voltages.get(index).copied())
            })
    }

    fn ac_branch_current_named(result: &AcResult, branch_name: &str) -> Option<Complex64> {
        result
            .branch_names
            .iter()
            .position(|name| name.eq_ignore_ascii_case(branch_name))
            .and_then(|index| result.currents.get(index).copied())
            .or_else(|| {
                let normalized = Self::normalize_device_instance_name(branch_name);
                (normalized != branch_name).then(|| {
                    result
                        .branch_names
                        .iter()
                        .position(|name| name.eq_ignore_ascii_case(&normalized))
                        .and_then(|index| result.currents.get(index).copied())
                })?
            })
    }

    fn netlist_has_recorded_branch_current(netlist: &Netlist, source: &str) -> bool {
        if Self::elements_have_recorded_branch_current(&netlist.elements, source) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            Self::elements_have_recorded_branch_current(&flattened.elements, source)
        })
    }

    fn elements_have_recorded_branch_current(
        elements: &[crate::netlist::Element],
        source: &str,
    ) -> bool {
        elements.iter().any(|element| {
            Self::device_instance_names_match(&element.name, source)
                && Self::element_has_recorded_branch_current(&element.kind)
        })
    }

    fn element_has_recorded_branch_current(kind: &ElementKind) -> bool {
        matches!(
            kind,
            ElementKind::VoltageSource(_)
                | ElementKind::Resistor { .. }
                | ElementKind::Capacitor { .. }
                | ElementKind::Inductor { .. }
                | ElementKind::JilesAthertonInductor { .. }
                | ElementKind::XyceMemristor { .. }
                | ElementKind::Vcvs { .. }
                | ElementKind::Ccvs { .. }
                | ElementKind::VSwitch { .. }
                | ElementKind::ISwitch { .. }
                | ElementKind::GenericSwitch { .. }
                | ElementKind::BehavioralVoltage { .. }
                | ElementKind::BehavioralCurrent { .. }
        )
    }

    fn netlist_has_independent_current_source(netlist: &Netlist, source: &str) -> bool {
        if Self::elements_have_independent_current_source(&netlist.elements, source) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            Self::elements_have_independent_current_source(&flattened.elements, source)
        })
    }

    fn elements_have_independent_current_source(
        elements: &[crate::netlist::Element],
        source: &str,
    ) -> bool {
        elements.iter().any(|element| {
            Self::device_instance_names_match(&element.name, source)
                && matches!(&element.kind, ElementKind::CurrentSource(_))
        })
    }

    fn evaluate_independent_current_source_probe(
        netlist: &Netlist,
        result: &TransientResult,
        source: &str,
        time: Value,
    ) -> Option<Value> {
        if Self::tran_uses_uic(netlist)
            && Self::time_is_transient_initial_sample(result, time)
            && Self::netlist_has_independent_current_source(netlist, source)
        {
            return Some(0.0);
        }
        if let Some(value) = Self::evaluate_current_source_probe_from_elements(
            &netlist.elements,
            result,
            source,
            time,
        ) {
            return Some(value);
        }

        let flattened = crate::netlist::flatten_netlist_with_models(netlist).ok()?;
        Self::evaluate_current_source_probe_from_elements(&flattened.elements, result, source, time)
    }

    fn tran_uses_uic(netlist: &Netlist) -> bool {
        netlist.analyses.iter().any(|analysis| {
            matches!(
                analysis,
                crate::netlist::AnalysisCommand::Tran { uic: true, .. }
            )
        })
    }

    fn time_is_transient_initial_sample(result: &TransientResult, time: Value) -> bool {
        let Some(first) = result.time.first().copied() else {
            return false;
        };
        (time - first).abs() <= 1.0e-30
    }

    fn evaluate_current_source_probe_from_elements(
        elements: &[crate::netlist::Element],
        result: &TransientResult,
        source: &str,
        time: Value,
    ) -> Option<Value> {
        let spec = elements.iter().find_map(|element| {
            if Self::device_instance_names_match(&element.name, source)
                && let ElementKind::CurrentSource(spec) = &element.kind
            {
                return Some(spec);
            }
            None
        })?;
        let (tstep, tstop) = Self::transient_result_source_context(result);
        Some(
            crate::circuit::VoltageSources::evaluate_source_spec_at_time_with_dialect(
                spec,
                time,
                tstep,
                tstop,
                SpiceDialect::Xyce,
            ),
        )
    }

    fn transient_result_source_context(result: &TransientResult) -> (Value, Value) {
        let tstop = result.time.last().copied().unwrap_or(1e99).max(1e-18);
        let mut previous: Option<Value> = None;
        let mut min_step: Option<Value> = None;
        for &sample in &result.time {
            if let Some(previous_sample) = previous {
                let step = sample - previous_sample;
                if step.is_finite() && step > 0.0 {
                    min_step = Some(min_step.map_or(step, |current| current.min(step)));
                }
            }
            previous = Some(sample);
        }
        (min_step.unwrap_or(1e-12), tstop)
    }

    fn source_is_voltage_source(netlist: &Netlist, source: &str) -> bool {
        netlist.elements.iter().any(|element| {
            element.name.eq_ignore_ascii_case(source)
                && matches!(&element.kind, ElementKind::VoltageSource(_))
        })
    }

    fn source_is_current_source(netlist: &Netlist, source: &str) -> bool {
        netlist.elements.iter().any(|element| {
            element.name.eq_ignore_ascii_case(source)
                && matches!(&element.kind, ElementKind::CurrentSource(_))
        })
    }

    fn source_is_independent_source(netlist: &Netlist, source: &str) -> bool {
        netlist.elements.iter().any(|element| {
            element.name.eq_ignore_ascii_case(source)
                && matches!(
                    &element.kind,
                    ElementKind::VoltageSource(_) | ElementKind::CurrentSource(_)
                )
        })
    }

    fn independent_source_dc_value(netlist: &Netlist, source: &str) -> Option<Value> {
        netlist
            .elements
            .iter()
            .find(|element| element.name.eq_ignore_ascii_case(source))
            .and_then(|element| match &element.kind {
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    Some(extract_dc_value(spec))
                }
                _ => None,
            })
    }

    fn independent_source_ac_terms(netlist: &Netlist, source: &str) -> Option<(Value, Value)> {
        netlist
            .elements
            .iter()
            .find(|element| element.name.eq_ignore_ascii_case(source))
            .and_then(|element| match &element.kind {
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    Some(extract_ac_value(spec))
                }
                _ => None,
            })
    }

    fn evaluate_current_source_current(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        source: &str,
    ) -> Option<Value> {
        let element = netlist
            .elements
            .iter()
            .find(|element| element.name.eq_ignore_ascii_case(source))?;
        let ElementKind::CurrentSource(spec) = &element.kind else {
            return None;
        };

        if source.eq_ignore_ascii_case(&dc.source) {
            return Some(sweep_point.primary);
        }
        if let Some(sweep2) = &dc.sweep2
            && source.eq_ignore_ascii_case(&sweep2.source)
        {
            return sweep_point.secondary;
        }

        Some(extract_dc_value(spec))
    }

    fn scalar_parameter_probe_is_supported(netlist: &Netlist, parameter_name: &str) -> bool {
        parameter_name.eq_ignore_ascii_case("TEMP")
            || parameter_name.eq_ignore_ascii_case("TEMPER")
            || parameter_name.eq_ignore_ascii_case("VT")
            || netlist.params.get(parameter_name).is_some()
            || Self::scalar_parameter_expression(&netlist.params, parameter_name).is_some_and(
                |expression| {
                    let context = Self::print_eval_context(netlist, None, None);
                    crate::netlist::expr::prepare_behavioral_expression(expression, &context)
                        .and_then(|prepared| {
                            crate::netlist::expr::eval_expression(&prepared, &context)
                                .map_err(|err| err.to_string())
                        })
                        .is_ok()
                },
            )
    }

    fn scalar_parameter_expression<'a>(
        params: &'a crate::netlist::ParamContext,
        parameter_name: &str,
    ) -> Option<&'a str> {
        if params.has_parameter_binding(parameter_name) {
            params.get_parameter_expression(parameter_name)
        } else {
            params.get_global_expression(parameter_name)
        }
    }

    fn scalar_parameter_sweep_source_is_supported(netlist: &Netlist, parameter_name: &str) -> bool {
        netlist
            .params
            .all_params()
            .iter()
            .any(|(name, _)| name.eq_ignore_ascii_case(parameter_name))
    }

    fn effective_resistor_value(netlist: &Netlist, name: &str) -> Result<Option<Value>, String> {
        Engine::new(SimulationConfig {
            spice_dialect: SpiceDialect::Xyce,
            ..SimulationConfig::default()
        })
        .resolved_resistor_parameter(netlist, name, "R")
        .map_err(|err| format!("resistor '{name}' parameter resolution failed: {err}"))
    }

    fn effective_capacitor_value(netlist: &Netlist, name: &str) -> Option<Value> {
        Engine::new(SimulationConfig {
            spice_dialect: SpiceDialect::Xyce,
            ..SimulationConfig::default()
        })
        .resolved_capacitor_value(netlist, name)
        .ok()
        .flatten()
    }

    fn effective_inductor_value(netlist: &Netlist, name: &str) -> Option<Value> {
        Engine::new(SimulationConfig {
            spice_dialect: SpiceDialect::Xyce,
            ..SimulationConfig::default()
        })
        .resolved_inductor_value(netlist, name)
        .ok()
        .flatten()
    }

    fn inductor_instance_params_affect_effective_value(
        instance_params: &[(String, Value)],
    ) -> bool {
        const EFFECTIVE_VALUE_PARAMS: &[&str] = &[
            "L",
            "IND",
            "VALUE",
            "INDUCTANCE",
            "M",
            "MULT",
            "SCALE",
            "TEMP",
            "DTEMP",
            "TC1",
            "TC2",
        ];
        instance_params.iter().any(|(name, _)| {
            EFFECTIVE_VALUE_PARAMS
                .iter()
                .any(|candidate| name.eq_ignore_ascii_case(candidate))
        })
    }

    fn capacitor_instance_params_affect_effective_value(
        instance_params: &[(String, Value)],
    ) -> bool {
        const EFFECTIVE_VALUE_PARAMS: &[&str] = &["L", "W", "M", "TEMP", "DTEMP", "TC1", "TC2"];
        instance_params.iter().any(|(name, _)| {
            EFFECTIVE_VALUE_PARAMS
                .iter()
                .any(|candidate| name.eq_ignore_ascii_case(candidate))
        })
    }

    fn resistor_parameter_r_value(netlist: &Netlist, name: &str) -> Result<Option<Value>, String> {
        let Some(element) = Self::find_resistor_element(netlist, name) else {
            return Ok(None);
        };
        let ElementKind::Resistor {
            value,
            value_expr,
            model,
            instance_params,
            ..
        } = &element.kind
        else {
            return Ok(None);
        };

        if Self::resistor_uses_xyce_default_marker(instance_params) {
            if let Some(resistance) = Self::effective_resistor_value(netlist, name)? {
                return Ok(Some(resistance));
            }
        }
        if let Some(resistance) = Self::instance_param(instance_params, &["R", "VALUE"]) {
            return Ok(Some(resistance));
        }
        Ok(Self::resistor_parameter_r_value_from_parts(
            *value,
            value_expr.as_deref(),
            model.as_deref(),
            instance_params,
            &Self::print_eval_context(netlist, None, None),
        ))
    }

    fn evaluate_resistor_parameter_r_value(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        result: &crate::SimulationResult,
        op_report: &crate::circuit::DeviceOpReport,
        name: &str,
    ) -> Result<Value, String> {
        let element = Self::find_resistor_element(netlist, name).ok_or_else(|| {
            format!("resistor parameter probe '{name}:R' targets an unknown resistor")
        })?;
        let ElementKind::Resistor {
            value,
            value_expr,
            model,
            instance_params,
            ..
        } = &element.kind
        else {
            return Err(format!(
                "resistor parameter probe '{name}:R' targets a non-resistor element"
            ));
        };

        if Self::resistor_uses_xyce_default_marker(instance_params) {
            if let Some(resistance) = Self::effective_resistor_value(netlist, name)? {
                return Ok(resistance);
            }
        }
        if let Some(resistance) = Self::instance_param(instance_params, &["R", "VALUE"]) {
            return Ok(resistance);
        }
        if value.is_finite() {
            return Ok(*value);
        }
        if let Some(expression) = value_expr.as_deref() {
            let context = Self::print_eval_context(netlist, Some(dc), Some(sweep_point));
            let mut call_value = |call: &str| {
                let normalized = Self::normalize_probe(call);
                Self::evaluate_atomic_dc_probe(
                    &normalized,
                    netlist,
                    dc,
                    sweep_point,
                    result,
                    op_report,
                )
            };
            return Self::evaluate_print_expression_with_probe_calls(
                expression,
                context,
                &mut call_value,
            )
            .map_err(|err| {
                format!("failed to evaluate resistor parameter probe '{name}:R': {err}")
            });
        }
        if model.is_some() {
            if let Some(resistance) = Self::resistor_parameter_r_value(netlist, name)? {
                return Ok(resistance);
            }
        }

        Err(format!(
            "resistor parameter probe '{name}:R' could not resolve a resistance value"
        ))
    }

    fn resistor_uses_xyce_default_marker(instance_params: &[(String, Value)]) -> bool {
        Self::instance_param(
            instance_params,
            &[crate::netlist::XYCE_DEFAULT_RESISTOR_VALUE_MARKER],
        )
        .is_some()
    }

    fn resistor_parameter_r_value_from_parts(
        value: Value,
        value_expr: Option<&str>,
        model: Option<&str>,
        instance_params: &[(String, Value)],
        context: &crate::netlist::ParamContext,
    ) -> Option<Value> {
        if let Some(resistance) = Self::instance_param(instance_params, &["R", "VALUE"]) {
            return Some(resistance);
        }
        if value.is_finite() {
            return Some(value);
        }
        if let Some(expression) = value_expr {
            return crate::netlist::expr::eval_expression(expression, context).ok();
        }
        if model.is_some() {
            return Some(1000.0);
        }
        None
    }

    fn resistor_temperature_value(netlist: &Netlist, name: &str) -> Result<Option<Value>, String> {
        Engine::new(SimulationConfig {
            spice_dialect: SpiceDialect::Xyce,
            ..SimulationConfig::default()
        })
        .resolved_resistor_parameter(netlist, name, "TEMP")
        .map_err(|err| format!("resistor '{name}' parameter resolution failed: {err}"))
    }

    fn resistor_instance_parameter_probe_is_supported(
        netlist: &Netlist,
        name: &str,
        parameter: &str,
    ) -> bool {
        let Some(element) = Self::find_resistor_element(netlist, name) else {
            return false;
        };
        let ElementKind::Resistor {
            instance_params, ..
        } = &element.kind
        else {
            return false;
        };
        ["W", "WIDTH", "TC", "TC1", "TC2", "M"]
            .iter()
            .any(|candidate| parameter.eq_ignore_ascii_case(candidate))
            || Self::instance_param(instance_params, &[parameter]).is_some()
    }

    fn evaluate_resistor_instance_parameter_probe(
        netlist: &Netlist,
        name: &str,
        parameter: &str,
    ) -> Result<Value, String> {
        Self::resistor_instance_parameter_value(netlist, name, parameter)?.ok_or_else(|| {
            format!(
                "resistor parameter probe '{}:{}' targets an unknown or unset resistor instance parameter",
                name, parameter
            )
        })
    }

    fn resistor_instance_parameter_value(
        netlist: &Netlist,
        name: &str,
        parameter: &str,
    ) -> Result<Option<Value>, String> {
        let Some(element) = Self::find_resistor_element(netlist, name) else {
            return Ok(None);
        };
        let ElementKind::Resistor {
            instance_params, ..
        } = &element.kind
        else {
            return Ok(None);
        };

        if ["W", "WIDTH", "TC", "TC1", "TC2"]
            .iter()
            .any(|candidate| parameter.eq_ignore_ascii_case(candidate))
        {
            return Engine::new(SimulationConfig {
                spice_dialect: SpiceDialect::Xyce,
                ..SimulationConfig::default()
            })
            .resolved_resistor_parameter(netlist, name, parameter)
            .map_err(|err| format!("resistor '{name}' parameter resolution failed: {err}"));
        }
        if parameter.eq_ignore_ascii_case("M") {
            return Ok(Some(
                Self::instance_param(instance_params, &[parameter]).unwrap_or(1.0),
            ));
        }
        Ok(Self::instance_param(instance_params, &[parameter]))
    }

    fn find_recorded_two_terminal_branch_element(
        netlist: &Netlist,
        name: &str,
    ) -> Option<crate::netlist::Element> {
        if let Some(element) = netlist.elements.iter().find(|element| {
            Self::device_instance_names_match(&element.name, name)
                && element.nodes.len() >= 2
                && Self::element_has_recorded_branch_current(&element.kind)
        }) {
            return Some(element.clone());
        }

        crate::netlist::flatten_netlist_with_models(netlist)
            .ok()?
            .elements
            .into_iter()
            .find(|element| {
                Self::device_instance_names_match(&element.name, name)
                    && element.nodes.len() >= 2
                    && Self::element_has_recorded_branch_current(&element.kind)
            })
    }

    fn find_resistor_element(netlist: &Netlist, name: &str) -> Option<crate::netlist::Element> {
        if let Some(element) = netlist.elements.iter().find(|element| {
            Self::device_instance_names_match(&element.name, name)
                && matches!(&element.kind, ElementKind::Resistor { .. })
        }) {
            return Some(element.clone());
        }

        crate::netlist::flatten_netlist_with_models(netlist)
            .ok()?
            .elements
            .into_iter()
            .find(|element| {
                Self::device_instance_names_match(&element.name, name)
                    && matches!(&element.kind, ElementKind::Resistor { .. })
            })
    }

    fn find_native_xyce_memristor_element(
        netlist: &Netlist,
        name: &str,
    ) -> Option<crate::netlist::Element> {
        if let Some(element) = netlist.elements.iter().find(|element| {
            Self::device_instance_names_match(&element.name, name)
                && matches!(&element.kind, ElementKind::XyceMemristor { .. })
                && Self::netlist_element_is_native_xyce_memristor(netlist, element)
        }) {
            return Some(element.clone());
        }

        let flattened = crate::netlist::flatten_netlist_with_models(netlist).ok()?;
        let mut flat_netlist = netlist.clone();
        flat_netlist.elements = flattened.elements;
        flat_netlist.models.extend(flattened.scoped_models);
        flat_netlist.subcircuits.clear();
        flat_netlist
            .elements
            .iter()
            .find(|element| {
                Self::device_instance_names_match(&element.name, name)
                    && matches!(&element.kind, ElementKind::XyceMemristor { .. })
                    && Self::netlist_element_is_native_xyce_memristor(&flat_netlist, element)
            })
            .cloned()
    }

    /// Admit only the exact native Xyce memristor families that circuit
    /// construction can validate and instantiate. `YMEMRISTOR` is shared by
    /// several model levels, so syntax alone must never claim unsupported
    /// families.
    fn netlist_element_is_native_xyce_memristor(
        netlist: &Netlist,
        element: &crate::netlist::Element,
    ) -> bool {
        let ElementKind::XyceMemristor {
            model,
            instance_params,
            deferred_params,
        } = &element.kind
        else {
            return false;
        };
        if !deferred_params.is_empty() {
            return false;
        }
        let Some(model_def) = Self::find_model(&netlist.models, model) else {
            return false;
        };
        crate::engine::build_native_xyce_memristor(
            netlist,
            model_def,
            &element.name,
            model,
            instance_params,
            SimulationConfig::default().temperature,
        )
        .is_ok()
    }

    fn xyce_memristor_resistance_store_name(netlist: &Netlist, name: &str) -> Option<String> {
        Self::find_native_xyce_memristor_element(netlist, name)
            .map(|element| format!("{}:R", element.name))
    }

    fn find_capacitor_element(netlist: &Netlist, name: &str) -> Option<crate::netlist::Element> {
        if let Some(element) = netlist.elements.iter().find(|element| {
            Self::device_instance_names_match(&element.name, name)
                && matches!(&element.kind, ElementKind::Capacitor { .. })
        }) {
            return Some(element.clone());
        }

        crate::netlist::flatten_netlist_with_models(netlist)
            .ok()?
            .elements
            .into_iter()
            .find(|element| {
                Self::device_instance_names_match(&element.name, name)
                    && matches!(&element.kind, ElementKind::Capacitor { .. })
            })
    }

    fn find_inductor_element(netlist: &Netlist, name: &str) -> Option<crate::netlist::Element> {
        if let Some(element) = netlist.elements.iter().find(|element| {
            Self::device_instance_names_match(&element.name, name)
                && matches!(&element.kind, ElementKind::Inductor { .. })
        }) {
            return Some(element.clone());
        }

        crate::netlist::flatten_netlist_with_models(netlist)
            .ok()?
            .elements
            .into_iter()
            .find(|element| {
                Self::device_instance_names_match(&element.name, name)
                    && matches!(&element.kind, ElementKind::Inductor { .. })
            })
    }

    fn find_bare_device_parameter_element(
        netlist: &Netlist,
        probe: &str,
    ) -> Option<crate::netlist::Element> {
        let probe_name = Self::parse_bare_device_parameter_probe(probe)?;
        if let Some(element) = netlist.elements.iter().find(|element| {
            Self::device_instance_names_match(&element.name, &probe_name)
                && Self::element_has_bare_device_parameter(&element.kind)
        }) {
            return Some(element.clone());
        }

        crate::netlist::flatten_netlist_with_models(netlist)
            .ok()?
            .elements
            .into_iter()
            .find(|element| {
                Self::device_instance_names_match(&element.name, &probe_name)
                    && Self::element_has_bare_device_parameter(&element.kind)
            })
    }

    fn element_has_bare_device_parameter(kind: &ElementKind) -> bool {
        matches!(
            kind,
            ElementKind::VoltageSource(_)
                | ElementKind::CurrentSource(_)
                | ElementKind::Resistor { .. }
                | ElementKind::Capacitor { .. }
                | ElementKind::Inductor { .. }
        )
    }

    fn instance_param(params: &[(String, Value)], names: &[&str]) -> Option<Value> {
        names.iter().find_map(|candidate| {
            params
                .iter()
                .find(|(name, _)| name.eq_ignore_ascii_case(candidate))
                .map(|(_, value)| *value)
        })
    }

    fn step_commands(netlist: &Netlist) -> Result<Vec<StepCommand>, String> {
        let step_commands = netlist
            .analyses
            .iter()
            .filter_map(|analysis| match analysis {
                AnalysisCommand::Step(step) => Some(step),
                _ => None,
            })
            .cloned()
            .collect::<Vec<_>>();

        for step in &step_commands {
            match &step.sweep {
                StepSweep::Data { table_name } => {
                    let table = netlist
                        .data_tables
                        .iter()
                        .find(|table| table.name.eq_ignore_ascii_case(table_name))
                        .ok_or_else(|| format!(".STEP DATA table '{table_name}' not found"))?;
                    if table.params.is_empty() {
                        return Err(format!(".STEP DATA table '{}' has no columns", table.name));
                    }
                    if table.rows.is_empty() {
                        return Err(format!(".STEP DATA table '{}' has no rows", table.name));
                    }
                    for (row_index, row) in table.rows.iter().enumerate() {
                        if row.len() != table.params.len() {
                            return Err(format!(
                                ".STEP DATA table '{}' row {} has {} value(s), expected {}",
                                table.name,
                                row_index,
                                row.len(),
                                table.params.len()
                            ));
                        }
                    }
                }
                _ if step.sweep.values().is_empty() => {
                    return Err("deck has invalid .STEP sweep bounds".to_string());
                }
                _ => {}
            }
        }

        Ok(step_commands)
    }

    fn single_tran_analysis(netlist: &Netlist) -> Result<XyceTranAnalysis, String> {
        let analyses = netlist
            .analyses
            .iter()
            .filter_map(|analysis| match analysis {
                AnalysisCommand::Tran {
                    step,
                    stop,
                    start,
                    max_step,
                    uic,
                } => Some(XyceTranAnalysis {
                    step: *step,
                    stop: *stop,
                    start: *start,
                    max_step: *max_step,
                    uic: *uic,
                }),
                _ => None,
            })
            .collect::<Vec<_>>();

        match analyses.len() {
            0 => Err("deck has no .TRAN analysis for static .PRINT TRAN output".to_string()),
            1 => Ok(analyses[0]),
            _ => Err(
                "deck has multiple .TRAN analyses; multi-analysis transient comparison is not implemented yet"
                    .to_string(),
            ),
        }
    }

    fn single_ac_analysis(netlist: &Netlist) -> Result<XyceAcAnalysis, String> {
        let mut analyses = Vec::new();
        for analysis in &netlist.analyses {
            match analysis {
                AnalysisCommand::Ac {
                    variation,
                    points,
                    start_freq,
                    stop_freq,
                } => analyses.push(XyceAcAnalysis {
                    frequencies: ac_sweep_frequencies(*variation, *points, *start_freq, *stop_freq),
                    data_points: None,
                }),
                AnalysisCommand::AcData { table_name } => {
                    let data_points = Self::ac_data_table_points(netlist, table_name)?;
                    analyses.push(XyceAcAnalysis {
                        frequencies: data_points
                            .iter()
                            .map(|point| point.frequency)
                            .collect::<Vec<_>>(),
                        data_points: Some(data_points),
                    });
                }
                _ => {}
            }
        }

        match analyses.len() {
            0 => Err("deck has no .AC analysis for static .PRINT AC output".to_string()),
            1 => Ok(analyses[0].clone()),
            _ => Err(
                "deck has multiple .AC analyses; multi-analysis AC comparison is not implemented yet"
                    .to_string(),
            ),
        }
    }

    fn ac_data_table_points(
        netlist: &Netlist,
        table_name: &str,
    ) -> Result<Vec<XyceAcDataPoint>, String> {
        let table = netlist
            .data_tables
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(table_name))
            .ok_or_else(|| format!(".AC DATA references unknown .DATA table '{table_name}'"))?;
        if table.params.is_empty() {
            return Err(format!(".AC DATA table '{}' has no columns", table.name));
        }
        if table.rows.is_empty() {
            return Err(format!(".AC DATA table '{}' has no rows", table.name));
        }
        let mut unique_params = BTreeSet::new();
        for param in &table.params {
            if !unique_params.insert(param.to_ascii_uppercase()) {
                return Err(format!(
                    ".AC DATA table '{}' has duplicate column '{}'",
                    table.name, param
                ));
            }
        }
        let freq_column = table
            .params
            .iter()
            .position(|param| param.eq_ignore_ascii_case("FREQ"))
            .ok_or_else(|| format!(".AC DATA table '{}' has no FREQ column", table.name))?;
        let points = table
            .rows
            .iter()
            .enumerate()
            .map(|(row_index, row)| {
                if row.len() != table.params.len() {
                    return Err(format!(
                        ".AC DATA table '{}' row {} has {} value(s), expected {}",
                        table.name,
                        row_index + 1,
                        row.len(),
                        table.params.len()
                    ));
                }
                if let Some((column_index, value)) =
                    row.iter().enumerate().find(|(_, value)| !value.is_finite())
                {
                    return Err(format!(
                        ".AC DATA table '{}' row {} column '{}' must be finite, got {}",
                        table.name,
                        row_index + 1,
                        table.params[column_index],
                        value
                    ));
                }
                let frequency = row.get(freq_column).copied().ok_or_else(|| {
                    format!(
                        ".AC DATA table '{}' row {} does not contain FREQ column {}",
                        table.name,
                        row_index + 1,
                        freq_column + 1
                    )
                })?;
                let overrides = table
                    .params
                    .iter()
                    .cloned()
                    .zip(row.iter().copied())
                    .collect::<Vec<_>>();
                Ok(XyceAcDataPoint {
                    frequency,
                    overrides,
                })
            })
            .collect::<Result<Vec<_>, _>>()?;
        Ok(points)
    }

    fn single_dc_sweep(netlist: &Netlist) -> Result<XyceDcSweep, String> {
        let mut dimensions = Vec::new();
        for analysis in &netlist.analyses {
            let AnalysisCommand::Dc {
                source,
                start,
                stop,
                step,
                mode,
                sweep2,
            } = analysis
            else {
                continue;
            };

            dimensions.push(XyceDcSweepDimension {
                source: source.clone(),
                start: *start,
                stop: *stop,
                step: *step,
                mode: mode.clone(),
            });
            if let Some(sweep2) = sweep2 {
                dimensions.push(XyceDcSweepDimension {
                    source: sweep2.source.clone(),
                    start: sweep2.start,
                    stop: sweep2.stop,
                    step: sweep2.step,
                    mode: sweep2.mode.clone(),
                });
            }
        }

        if dimensions.is_empty() {
            if netlist
                .analyses
                .iter()
                .any(|analysis| matches!(analysis, AnalysisCommand::Op))
            {
                return Self::synthetic_op_dc_sweep(netlist);
            }
            return Err("deck has no .DC or .OP analysis for static .PRINT DC output".to_string());
        }
        if dimensions.len() > 2 {
            return Err(format!(
                "deck has {} .DC sweep dimensions; native Xyce static adapter currently supports one or two",
                dimensions.len()
            ));
        }

        for (index, dimension) in dimensions.iter().enumerate() {
            if dimension.spec().points().is_empty() {
                if index == 0 {
                    return Err("deck has invalid .DC sweep bounds".to_string());
                }
                return Err("deck has invalid secondary .DC sweep bounds".to_string());
            }
        }

        let primary = dimensions.remove(0);
        let sweep2 = dimensions
            .pop()
            .map(XyceDcSweepDimension::into_second_sweep);
        Ok(XyceDcSweep {
            source: primary.source,
            start: primary.start,
            stop: primary.stop,
            step: primary.step,
            mode: primary.mode,
            sweep2,
        })
    }

    fn synthetic_op_dc_sweep(netlist: &Netlist) -> Result<XyceDcSweep, String> {
        for element in &netlist.elements {
            let dc_value = match &element.kind {
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    extract_dc_value(spec)
                }
                _ => continue,
            };
            if !dc_value.is_finite() {
                return Err(format!(
                    ".OP source '{}' has non-finite DC value {}",
                    element.name, dc_value
                ));
            }
            return Ok(XyceDcSweep {
                source: element.name.clone(),
                start: dc_value,
                stop: dc_value,
                step: 1.0,
                mode: crate::netlist::DcSweepMode::Linear,
                sweep2: None,
            });
        }

        Err(".OP static .PRINT DC output requires at least one independent source for the native one-point adapter".to_string())
    }

    fn single_dc_print_request(source: &str) -> Result<XycePrintRequest, String> {
        let request = Self::single_dc_print_output_request(source)?;
        Ok(XycePrintRequest {
            probes: request.probes,
        })
    }

    fn single_dc_print_output_request(source: &str) -> Result<XycePrintOutputRequest, String> {
        let requests = Self::print_output_requests(source, "DC")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .collect::<Vec<_>>();

        match requests.len() {
            0 => Err("deck has no .PRINT DC statement with static columns".to_string()),
            1 => Ok(requests.into_iter().next().expect("one request")),
            _ => Err("deck has multiple .PRINT DC statements; multi-table comparison is not implemented yet".to_string()),
        }
    }

    fn single_dc_or_file_output_request(source: &str) -> Result<XycePrintOutputRequest, String> {
        match Self::single_dc_print_output_request(source) {
            Ok(request) => Ok(request),
            Err(primary_error) => {
                let mut side_outputs = Self::prn_compatible_side_output_requests(source)?
                    .into_iter()
                    .collect::<Vec<_>>();
                if side_outputs.is_empty() {
                    return Err(primary_error);
                }
                side_outputs.sort_by(|left, right| left.file.cmp(&right.file));
                Ok(side_outputs.remove(0))
            }
        }
    }

    fn single_tran_print_output_request(source: &str) -> Result<XycePrintOutputRequest, String> {
        let requests = Self::print_output_requests(source, "TRAN")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .collect::<Vec<_>>();

        match requests.len() {
            0 => Err("deck has no .PRINT TRAN statement with static columns".to_string()),
            1 => Ok(requests.into_iter().next().expect("one request")),
            _ => Err("deck has multiple .PRINT TRAN statements; multi-table comparison is not implemented yet".to_string()),
        }
    }

    #[cfg(test)]
    fn single_ac_print_request(source: &str) -> Result<XycePrintRequest, String> {
        let request = Self::single_ac_print_output_request(source)?;
        Ok(XycePrintRequest {
            probes: request.probes,
        })
    }

    #[cfg(test)]
    fn single_ac_print_output_request(source: &str) -> Result<XycePrintOutputRequest, String> {
        match Self::primary_print_output_request(source, "AC")? {
            Some(request) => Ok(request),
            None => Err("deck has no .PRINT AC statement with static columns".to_string()),
        }
    }

    #[cfg(test)]
    fn primary_print_output_request(
        source: &str,
        analysis: &str,
    ) -> Result<Option<XycePrintOutputRequest>, String> {
        Self::canonical_print_output_request(source, analysis, false)
    }

    fn canonical_print_output_request(
        source: &str,
        analysis: &str,
        allow_single_file_output: bool,
    ) -> Result<Option<XycePrintOutputRequest>, String> {
        let requests = Self::aggregate_print_output_requests(
            Self::print_output_requests(source, analysis)?,
            analysis,
        )?;
        let primary_requests = requests
            .iter()
            .filter(|request| request.file.is_none())
            .cloned()
            .collect::<Vec<_>>();

        match primary_requests.len() {
            0 => Ok(None),
            1 => Ok(Some(
                primary_requests.into_iter().next().expect("one request"),
            )),
            _ => Err(format!(
                "deck has multiple primary .PRINT {analysis} output destinations after aggregation"
            )),
        }
        .and_then(|primary| {
            if primary.is_some() || !allow_single_file_output {
                return Ok(primary);
            }
            let file_requests = requests
                .into_iter()
                .filter(|request| request.file.is_some())
                .collect::<Vec<_>>();
            match file_requests.len() {
                0 => Ok(None),
                1 => Ok(file_requests.into_iter().next()),
                _ => Err(format!(
                    "deck has multiple .PRINT {analysis} FILE= outputs and no primary output"
                )),
            }
        })
    }

    fn output_override_print_output_request(
        source: &str,
        analysis: &str,
    ) -> Result<Option<XycePrintOutputRequest>, String> {
        let mut probes = Vec::new();
        for request in Self::print_output_requests(source, analysis)? {
            probes.extend(request.probes);
        }
        if probes.is_empty() {
            return Ok(None);
        }
        Ok(Some(XycePrintOutputRequest {
            format: None,
            file: None,
            probes,
        }))
    }

    fn aggregate_print_output_requests(
        requests: Vec<XycePrintOutputRequest>,
        analysis: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        let mut aggregated: Vec<XycePrintOutputRequest> = Vec::new();
        for request in requests {
            if let Some(existing) = aggregated
                .iter_mut()
                .find(|existing| existing.file == request.file)
            {
                Self::validate_print_output_format_compatible(
                    existing.format.as_deref(),
                    request.format.as_deref(),
                    analysis,
                    request.file.as_deref(),
                )?;
                existing.probes.extend(request.probes);
                if existing.format.is_none() {
                    existing.format = request.format;
                }
            } else {
                aggregated.push(request);
            }
        }
        Ok(aggregated)
    }

    fn validate_print_output_format_compatible(
        existing: Option<&str>,
        incoming: Option<&str>,
        analysis: &str,
        file: Option<&str>,
    ) -> Result<(), String> {
        let existing_key = Self::print_format_key(existing);
        let incoming_key = Self::print_format_key(incoming);
        if existing_key == incoming_key {
            return Ok(());
        }
        let destination = file
            .map(|file| format!("FILE={file}"))
            .unwrap_or_else(|| "primary output".to_string());
        Err(format!(
            "multiple .PRINT {analysis} statements for {destination} use different FORMAT values ({existing_key} and {incoming_key})"
        ))
    }

    fn print_format_key(format: Option<&str>) -> String {
        format.unwrap_or("STD").trim().to_ascii_lowercase()
    }

    fn dc_print_output_requests(source: &str) -> Result<Vec<XycePrintOutputRequest>, String> {
        Self::print_output_requests(source, "DC")
    }

    fn deck_has_print_analysis(&self, deck: &XyceDeck, analysis: &str) -> bool {
        fs::read_to_string(&deck.path).is_ok_and(|source| {
            Self::print_output_requests(&source, analysis).is_ok_and(|requests| {
                requests
                    .into_iter()
                    .any(|request| request.file.is_none() && !request.probes.is_empty())
            })
        })
    }

    fn print_output_requests(
        source: &str,
        expected_analysis: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        let mut requests = Vec::new();
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if !command.eq_ignore_ascii_case(".print") {
                continue;
            }
            let tokens = Self::split_print_fields(&trimmed)?;
            let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
            let Some(analysis) = token_refs.get(1).copied() else {
                return Err(".PRINT statement has no analysis type".to_string());
            };
            if !analysis.eq_ignore_ascii_case(expected_analysis) {
                continue;
            }

            let mut format = None;
            let mut file = None;
            let mut probes = Vec::new();
            let mut index = 2usize;
            while index < tokens.len() {
                if let Some((raw_key, raw_value, consumed)) =
                    Self::print_option_assignment(&token_refs, index)
                {
                    let key = raw_key.trim().to_ascii_lowercase();
                    let value = raw_value.trim().trim_matches(['"', '\'']).to_string();
                    match key.as_str() {
                        "format" => format = Some(value),
                        "file" => file = Some(value),
                        _ => {}
                    }
                    index += consumed;
                    continue;
                }

                let normalized = token_refs[index].to_ascii_lowercase();
                if Self::is_print_option_token(&normalized) {
                    index += 1;
                    continue;
                }
                probes.push(Self::canonicalize_single_quoted_print_probe(
                    &tokens[index],
                )?);
                index += 1;
            }

            if probes.is_empty() {
                continue;
            }
            requests.push(XycePrintOutputRequest {
                format,
                file,
                probes,
            });
        }

        Ok(requests)
    }

    fn split_print_fields(line: &str) -> Result<Vec<String>, String> {
        Self::split_grouped_whitespace_fields(line, ".PRINT statement")
    }

    fn canonicalize_single_quoted_print_probe(probe: &str) -> Result<String, String> {
        let trimmed = probe.trim();
        let starts_quote = trimmed.starts_with('\'');
        let ends_quote = trimmed.ends_with('\'');
        if !starts_quote && !ends_quote {
            return Ok(probe.to_string());
        }
        if !starts_quote || !ends_quote || trimmed.len() < 2 {
            return Err(format!(
                "malformed single-quoted .PRINT expression '{probe}'"
            ));
        }
        let inner = trimmed[1..trimmed.len() - 1].trim();
        if inner.is_empty() || inner.contains('\'') || inner.contains('{') || inner.contains('}') {
            return Err(format!(
                "single-quoted .PRINT expression must be nonempty and must not mix expression delimiters: '{probe}'"
            ));
        }
        Ok(format!("{{{inner}}}"))
    }

    fn split_prn_header_fields(line: &str) -> Result<Vec<String>, String> {
        Self::split_grouped_whitespace_fields(line, "Xyce .prn header")
    }

    fn split_grouped_whitespace_fields(
        line: &str,
        source_label: &str,
    ) -> Result<Vec<String>, String> {
        let mut fields = Vec::new();
        let mut current = String::new();
        let mut single_quote = false;
        let mut double_quote = false;
        let mut escaped = false;
        let mut brace_depth = 0usize;
        let mut paren_depth = 0usize;

        for ch in line.chars() {
            if escaped {
                current.push(ch);
                escaped = false;
                continue;
            }

            match ch {
                '\\' if single_quote || double_quote => {
                    current.push(ch);
                    escaped = true;
                }
                '\'' if !double_quote => {
                    single_quote = !single_quote;
                    current.push(ch);
                }
                '"' if !single_quote => {
                    double_quote = !double_quote;
                    current.push(ch);
                }
                '{' if !single_quote && !double_quote => {
                    brace_depth += 1;
                    current.push(ch);
                }
                '}' if !single_quote && !double_quote => {
                    brace_depth = brace_depth.checked_sub(1).ok_or_else(|| {
                        format!("unmatched closing brace in {source_label}: {line}")
                    })?;
                    current.push(ch);
                }
                '(' if !single_quote && !double_quote => {
                    paren_depth += 1;
                    current.push(ch);
                }
                ')' if !single_quote && !double_quote => {
                    paren_depth = paren_depth.checked_sub(1).ok_or_else(|| {
                        format!("unmatched closing parenthesis in {source_label}: {line}")
                    })?;
                    current.push(ch);
                }
                ch if ch.is_whitespace()
                    && !single_quote
                    && !double_quote
                    && brace_depth == 0
                    && paren_depth == 0 =>
                {
                    if !current.is_empty() {
                        fields.push(std::mem::take(&mut current));
                    }
                }
                _ => current.push(ch),
            }
        }

        if single_quote || double_quote {
            return Err(format!("unterminated quote in {source_label}: {line}"));
        }
        if brace_depth != 0 {
            return Err(format!(
                "unterminated brace expression in {source_label}: {line}"
            ));
        }
        if paren_depth != 0 {
            return Err(format!(
                "unterminated parenthesized probe in {source_label}: {line}"
            ));
        }
        if !current.is_empty() {
            fields.push(current);
        }

        Ok(fields)
    }

    fn gnuplot_splot_print_pair(
        source: &str,
    ) -> Result<(XycePrintOutputRequest, XycePrintOutputRequest), String> {
        let requests = Self::dc_print_output_requests(source)?;
        let mut primary = None;
        let mut side = None;
        for request in requests {
            let format = request.format.as_deref().unwrap_or("STD");
            if request.file.is_none() && format.eq_ignore_ascii_case("GNUPLOT") {
                if primary.replace(request).is_some() {
                    return Err(
                        "GNUPLOT/SPLOT contract requires exactly one primary GNUPLOT .PRINT DC"
                            .to_string(),
                    );
                }
                continue;
            }
            if request.file.is_some() && format.eq_ignore_ascii_case("SPLOT") {
                if side.replace(request).is_some() {
                    return Err(
                        "GNUPLOT/SPLOT contract requires exactly one named SPLOT .PRINT DC"
                            .to_string(),
                    );
                }
                continue;
            }
            return Err(format!(
                "GNUPLOT/SPLOT contract does not cover .PRINT DC FORMAT={format} FILE={}",
                request.file.as_deref().unwrap_or("<default>")
            ));
        }

        match (primary, side) {
            (Some(primary), Some(side)) => Ok((primary, side)),
            _ => Err(
                "GNUPLOT/SPLOT contract requires one primary GNUPLOT and one named SPLOT .PRINT DC"
                    .to_string(),
            ),
        }
    }

    fn is_print_option_token(token: &str) -> bool {
        token.starts_with("format=")
            || token.starts_with("width=")
            || token.starts_with("precision=")
            || token.starts_with("delimiter=")
            || token.starts_with("noindex")
            || token.starts_with("index=")
    }

    fn parse_measurement_reference_file(
        path: &Path,
    ) -> Result<Vec<XyceMeasurementReference>, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        let mut references = Vec::new();
        let mut names = BTreeSet::new();
        for (line_index, raw_line) in content.lines().enumerate() {
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('*') {
                continue;
            }
            let (raw_name, raw_value) = line.split_once('=').ok_or_else(|| {
                format!(
                    "{}:{}: expected '<measurement> = <value|FAILED>'",
                    path.display(),
                    line_index + 1
                )
            })?;
            let name = raw_name.trim();
            if name.is_empty() {
                return Err(format!(
                    "{}:{}: measurement name is empty",
                    path.display(),
                    line_index + 1
                ));
            }
            let normalized_name = name.to_ascii_uppercase();
            if !names.insert(normalized_name) {
                return Err(format!(
                    "{}:{}: duplicate measurement '{}'",
                    path.display(),
                    line_index + 1,
                    name
                ));
            }
            let raw_value = raw_value.trim();
            if raw_value.split_whitespace().count() != 1 {
                return Err(format!(
                    "{}:{}: measurement result must be one token",
                    path.display(),
                    line_index + 1
                ));
            }
            let value = if raw_value == "FAILED" {
                XyceMeasurementReferenceValue::Failed
            } else {
                let value = crate::netlist::lexer::parse_spice_value(raw_value).map_err(|err| {
                    format!(
                        "{}:{}: invalid measurement value '{}': {err}",
                        path.display(),
                        line_index + 1,
                        raw_value
                    )
                })?;
                if !value.is_finite() {
                    return Err(format!(
                        "{}:{}: measurement value must be finite",
                        path.display(),
                        line_index + 1
                    ));
                }
                XyceMeasurementReferenceValue::Numeric {
                    value,
                    quantization: Self::measurement_literal_quantization(raw_value),
                }
            };
            references.push(XyceMeasurementReference {
                name: name.to_string(),
                value,
            });
        }
        if references.is_empty() {
            return Err(format!("{} has no measurement results", path.display()));
        }
        Ok(references)
    }

    fn parse_continuous_measurement_reference_file(
        path: &Path,
    ) -> Result<XyceContinuousMeasurementReference, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        let mut name: Option<String> = None;
        let mut records = Vec::new();
        for (line_index, raw_line) in content.lines().enumerate() {
            let line_number = line_index + 1;
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('*') {
                continue;
            }
            let (raw_name, raw_fields) = line.split_once('=').ok_or_else(|| {
                format!(
                    "{}:{line_number}: expected '<measurement> = <value|FAILED>'",
                    path.display()
                )
            })?;
            let row_name = raw_name.trim();
            if row_name.is_empty() {
                return Err(format!(
                    "{}:{line_number}: measurement name is empty",
                    path.display()
                ));
            }
            if let Some(expected_name) = name.as_deref() {
                if !row_name.eq_ignore_ascii_case(expected_name) {
                    return Err(format!(
                        "{}:{line_number}: measurement '{}' does not match first row '{}'",
                        path.display(),
                        row_name,
                        expected_name
                    ));
                }
            } else {
                name = Some(row_name.to_string());
            }

            let fields = raw_fields.split_whitespace().collect::<Vec<_>>();
            if fields.is_empty() {
                return Err(format!(
                    "{}:{line_number}: measurement result is empty",
                    path.display()
                ));
            }
            let value = Self::parse_measurement_reference_token(path, line_number, fields[0])?;
            let mut trigger_axis = None;
            let mut target_axis = None;
            let mut field_index = 1usize;
            while field_index < fields.len() {
                if field_index + 2 >= fields.len() || fields[field_index + 1] != "=" {
                    return Err(format!(
                        "{}:{line_number}: expected '<targ|trig> = <value>' after measurement value",
                        path.display()
                    ));
                }
                let label = fields[field_index];
                let parsed = Self::parse_measurement_reference_token(
                    path,
                    line_number,
                    fields[field_index + 2],
                )?;
                if matches!(parsed, XyceMeasurementReferenceValue::Failed) {
                    return Err(format!(
                        "{}:{line_number}: {label} metadata cannot be FAILED",
                        path.display()
                    ));
                }
                let slot = if label.eq_ignore_ascii_case("trig") {
                    &mut trigger_axis
                } else if label.eq_ignore_ascii_case("targ") {
                    &mut target_axis
                } else {
                    return Err(format!(
                        "{}:{line_number}: unknown continuous measurement metadata '{label}'",
                        path.display()
                    ));
                };
                if slot.replace(parsed).is_some() {
                    return Err(format!(
                        "{}:{line_number}: duplicate {label} metadata",
                        path.display()
                    ));
                }
                field_index += 3;
            }
            if matches!(value, XyceMeasurementReferenceValue::Failed)
                && (trigger_axis.is_some() || target_axis.is_some())
            {
                return Err(format!(
                    "{}:{line_number}: FAILED result cannot carry trigger or target metadata",
                    path.display()
                ));
            }
            if trigger_axis.is_some() != target_axis.is_some() {
                return Err(format!(
                    "{}:{line_number}: trigger/target metadata must be present as a pair",
                    path.display()
                ));
            }
            records.push(XyceContinuousMeasurementReferenceRecord {
                value,
                trigger_axis,
                target_axis,
            });
        }
        let name = name.ok_or_else(|| format!("{} has no measurement results", path.display()))?;
        Ok(XyceContinuousMeasurementReference { name, records })
    }

    fn parse_measurement_reference_token(
        path: &Path,
        line_number: usize,
        raw_value: &str,
    ) -> Result<XyceMeasurementReferenceValue, String> {
        if raw_value == "FAILED" {
            return Ok(XyceMeasurementReferenceValue::Failed);
        }
        let value = crate::netlist::lexer::parse_spice_value(raw_value).map_err(|err| {
            format!(
                "{}:{line_number}: invalid measurement value '{}': {err}",
                path.display(),
                raw_value
            )
        })?;
        if !value.is_finite() {
            return Err(format!(
                "{}:{line_number}: measurement value must be finite",
                path.display()
            ));
        }
        Ok(XyceMeasurementReferenceValue::Numeric {
            value,
            quantization: Self::measurement_literal_quantization(raw_value),
        })
    }

    fn parse_mixed_measurement_reference_file(
        path: &Path,
    ) -> Result<Vec<XyceMixedMeasurementReferenceRow>, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        let mut rows = Vec::new();
        for (line_index, raw_line) in content.lines().enumerate() {
            let line_number = line_index + 1;
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('*') {
                continue;
            }
            let (raw_name, raw_fields) = line.split_once('=').ok_or_else(|| {
                format!(
                    "{}:{line_number}: expected '<measurement> = <value|FAILED>'",
                    path.display()
                )
            })?;
            let name = raw_name.trim();
            if name.is_empty() {
                return Err(format!(
                    "{}:{line_number}: measurement name is empty",
                    path.display()
                ));
            }
            let fields = raw_fields.split_whitespace().collect::<Vec<_>>();
            if fields.is_empty() {
                return Err(format!(
                    "{}:{line_number}: measurement result is empty",
                    path.display()
                ));
            }
            let value = Self::parse_measurement_reference_token(path, line_number, fields[0])?;
            let mut trigger_axis = None;
            let mut target_axis = None;
            let mut field_index = 1usize;
            while field_index < fields.len() {
                if field_index + 2 >= fields.len() || fields[field_index + 1] != "=" {
                    return Err(format!(
                        "{}:{line_number}: expected '<targ|trig> = <value|not found>' after measurement value",
                        path.display()
                    ));
                }
                let label = fields[field_index];
                let (parsed, consumed) = if fields[field_index + 2].eq_ignore_ascii_case("not") {
                    if fields
                        .get(field_index + 3)
                        .is_none_or(|field| !field.eq_ignore_ascii_case("found"))
                    {
                        return Err(format!(
                            "{}:{line_number}: expected 'not found' after {label} =",
                            path.display()
                        ));
                    }
                    (XyceMeasurementReferenceValue::Failed, 4)
                } else {
                    (
                        Self::parse_measurement_reference_token(
                            path,
                            line_number,
                            fields[field_index + 2],
                        )?,
                        3,
                    )
                };
                let slot = if label.eq_ignore_ascii_case("trig") {
                    &mut trigger_axis
                } else if label.eq_ignore_ascii_case("targ") {
                    &mut target_axis
                } else {
                    return Err(format!(
                        "{}:{line_number}: unknown mixed measurement metadata '{label}'",
                        path.display()
                    ));
                };
                if slot.replace(parsed).is_some() {
                    return Err(format!(
                        "{}:{line_number}: duplicate {label} metadata",
                        path.display()
                    ));
                }
                field_index += consumed;
            }
            if trigger_axis.is_some() != target_axis.is_some() {
                return Err(format!(
                    "{}:{line_number}: trigger/target metadata must be present as a pair",
                    path.display()
                ));
            }
            rows.push(XyceMixedMeasurementReferenceRow {
                name: name.to_string(),
                value,
                trigger_axis,
                target_axis,
            });
        }
        if rows.is_empty() {
            return Err(format!("{} has no measurement results", path.display()));
        }
        Ok(rows)
    }

    fn compare_measurement_references(
        &self,
        paths: &[PathBuf],
        actual: &[crate::analysis::MeasureResult],
        tolerance: XyceFileCompareTolerance,
        measure_fail_output: Option<bool>,
        measure_default_value: Option<Value>,
        analysis: &str,
        declarations: &[crate::analysis::MeasureStatement],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if paths.len() != 1 {
            return Err(format!(
                "unstepped measurement comparison requires exactly one artifact, found {}",
                paths.len()
            ));
        }
        let expected = Self::parse_measurement_reference_file(&paths[0])?;
        if expected.len() != actual.len() {
            return Err(format!(
                "measurement artifact contains {} results but the netlist evaluated {} statements",
                expected.len(),
                actual.len()
            ));
        }
        let mut mismatches = Vec::new();
        for (row, (reference, result)) in expected.iter().zip(actual).enumerate() {
            if reference.name != result.name {
                return Err(format!(
                    "measurement {} is '{}' in the artifact but '{}' in declaration order",
                    row, reference.name, result.name
                ));
            }
            match reference.value {
                XyceMeasurementReferenceValue::Failed if result.value.is_none() => {}
                XyceMeasurementReferenceValue::Failed => {
                    return Err(format!(
                        "measurement '{}' was expected to be FAILED but evaluated to {}",
                        reference.name,
                        result.value.expect("matched nonempty measurement result")
                    ));
                }
                XyceMeasurementReferenceValue::Numeric {
                    value: expected_value,
                    quantization,
                } => {
                    let actual_value = match result.value {
                        Some(value) => value,
                        None if measure_fail_output == Some(false) => {
                            let local_default = declarations
                                .iter()
                                .find(|statement| {
                                    statement.name.eq_ignore_ascii_case(&reference.name)
                                        && statement.analysis.eq_ignore_ascii_case(analysis)
                                })
                                .and_then(|statement| statement.default_value);
                            measure_default_value.or(local_default).unwrap_or(0.0)
                        }
                        None => {
                            return Err(format!(
                                "measurement '{}' was expected to evaluate to {} but FAILED: {}",
                                reference.name,
                                expected_value,
                                result.error.as_deref().unwrap_or("no failure reason")
                            ));
                        }
                    };
                    let absolute_error = (expected_value - actual_value).abs();
                    let relative_error = if expected_value == 0.0 {
                        f64::INFINITY
                    } else {
                        absolute_error / expected_value.abs()
                    };
                    let matches = Self::measurement_value_matches(
                        expected_value,
                        actual_value,
                        quantization,
                        tolerance,
                    );
                    if !matches {
                        mismatches.push(XyceValueMismatch {
                            row,
                            probe: reference.name.clone(),
                            expected: expected_value,
                            actual: actual_value,
                            relative_error,
                        });
                    }
                }
            }
        }
        Ok(mismatches)
    }

    fn compare_continuous_measurement_references(
        &self,
        paths: &[PathBuf],
        actual: &[crate::analysis::ContinuousMeasureResult],
        tolerance: XyceFileCompareTolerance,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        for result in actual {
            result.validate_invariants().map_err(|error| {
                format!(
                    "continuous measurement '{}' violates its result invariant: {error}",
                    result.name
                )
            })?;
        }
        if paths.len() != actual.len() {
            return Err(format!(
                "continuous measurement oracle contains {} artifact(s) but the netlist evaluated {} statement(s)",
                paths.len(),
                actual.len()
            ));
        }
        let mut mismatches = Vec::new();
        let mut global_row = 0usize;
        for (path, result) in paths.iter().zip(actual) {
            let reference = Self::parse_continuous_measurement_reference_file(path)?;
            if !reference.name.eq_ignore_ascii_case(&result.name) {
                return Err(format!(
                    "continuous artifact '{}' contains '{}' but declaration order requires '{}'",
                    path.display(),
                    reference.name,
                    result.name
                ));
            }
            if reference.records.len() == 1
                && matches!(
                    reference.records[0].value,
                    XyceMeasurementReferenceValue::Failed
                )
            {
                if result.failure.is_none() {
                    return Err(format!(
                        "continuous measurement '{}' was expected to be FAILED but produced {} record(s)",
                        result.name,
                        result.records.len()
                    ));
                }
                global_row += 1;
                continue;
            }
            if let Some(failure) = result.failure.as_deref() {
                return Err(format!(
                    "continuous measurement '{}' was expected to produce {} record(s) but FAILED: {failure}",
                    result.name,
                    reference.records.len()
                ));
            }
            if reference.records.len() != result.records.len() {
                return Err(format!(
                    "continuous measurement '{}' artifact contains {} record(s) but evaluation produced {}",
                    result.name,
                    reference.records.len(),
                    result.records.len()
                ));
            }
            for (reference_record, actual_record) in reference.records.iter().zip(&result.records) {
                Self::compare_continuous_measurement_value(
                    &mut mismatches,
                    global_row,
                    &result.name,
                    reference_record.value,
                    Some(actual_record.value),
                    tolerance,
                )?;
                Self::compare_continuous_measurement_value(
                    &mut mismatches,
                    global_row,
                    &format!("{}:trig", result.name),
                    reference_record
                        .trigger_axis
                        .unwrap_or(XyceMeasurementReferenceValue::Failed),
                    actual_record.trigger_axis,
                    tolerance,
                )?;
                Self::compare_continuous_measurement_value(
                    &mut mismatches,
                    global_row,
                    &format!("{}:targ", result.name),
                    reference_record
                        .target_axis
                        .unwrap_or(XyceMeasurementReferenceValue::Failed),
                    actual_record.target_axis,
                    tolerance,
                )?;
                global_row += 1;
            }
        }
        Ok(mismatches)
    }

    #[allow(clippy::too_many_arguments)]
    fn compare_analysis_measurement_outputs(
        &self,
        scalar_paths: &[PathBuf],
        continuous_paths: &[PathBuf],
        scalar: &[crate::analysis::MeasureResult],
        continuous: &[crate::analysis::ContinuousMeasureResult],
        tolerance: XyceFileCompareTolerance,
        measure_fail_output: Option<bool>,
        measure_default_value: Option<Value>,
        use_continuous_files: bool,
        declarations: &[crate::analysis::MeasureStatement],
        base_analysis: &str,
        continuous_analysis: &str,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if !use_continuous_files {
            return self.compare_mixed_measurement_references(
                scalar_paths,
                scalar,
                continuous,
                tolerance,
                declarations,
                base_analysis,
                continuous_analysis,
            );
        }

        let mut mismatches = if scalar_paths.is_empty() {
            Vec::new()
        } else {
            self.compare_measurement_references(
                scalar_paths,
                scalar,
                tolerance,
                measure_fail_output,
                measure_default_value,
                base_analysis,
                declarations,
            )?
        };
        let continuous_declarations = declarations
            .iter()
            .filter(|declaration| {
                declaration
                    .analysis
                    .eq_ignore_ascii_case(continuous_analysis)
            })
            .collect::<Vec<_>>();
        if continuous_declarations.len() != continuous.len() {
            return Err(format!(
                "{continuous_analysis} evaluator returned {} result(s) for {} declaration(s)",
                continuous.len(),
                continuous_declarations.len()
            ));
        }
        let mut visible_continuous = Vec::new();
        for (declaration, result) in continuous_declarations.into_iter().zip(continuous) {
            if !declaration.name.eq_ignore_ascii_case(&result.name) {
                return Err(format!(
                    "{continuous_analysis} evaluator returned '{}' for declaration '{}'",
                    result.name, declaration.name
                ));
            }
            if declaration.print_policy == crate::analysis::MeasurePrintPolicy::All {
                visible_continuous.push(result.clone());
            }
        }
        mismatches.extend(self.compare_continuous_measurement_references(
            continuous_paths,
            &visible_continuous,
            tolerance,
        )?);
        Ok(mismatches)
    }

    fn compare_mixed_measurement_references(
        &self,
        paths: &[PathBuf],
        scalar: &[crate::analysis::MeasureResult],
        continuous: &[crate::analysis::ContinuousMeasureResult],
        tolerance: XyceFileCompareTolerance,
        declarations: &[crate::analysis::MeasureStatement],
        base_analysis: &str,
        continuous_analysis: &str,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        for result in continuous {
            result.validate_invariants().map_err(|error| {
                format!(
                    "continuous measurement '{}' violates its result invariant: {error}",
                    result.name
                )
            })?;
        }
        if paths.len() != 1 {
            return Err(format!(
                "one mixed measurement run requires exactly one aggregate artifact, found {}",
                paths.len()
            ));
        }
        let expected = Self::parse_mixed_measurement_reference_file(&paths[0])?;
        let actual = Self::mixed_measurement_rows(
            scalar,
            continuous,
            declarations,
            base_analysis,
            continuous_analysis,
        )?;
        if expected.len() != actual.len() {
            return Err(format!(
                "mixed measurement artifact contains {} row(s) but evaluation emitted {} row(s)",
                expected.len(),
                actual.len()
            ));
        }

        let mut mismatches = Vec::new();
        for (row, (reference, result)) in expected.iter().zip(&actual).enumerate() {
            if !reference.name.eq_ignore_ascii_case(&result.name) {
                return Err(format!(
                    "mixed measurement row {row} is '{}' in the artifact but '{}' in declaration-ordered evaluation",
                    reference.name, result.name
                ));
            }
            Self::compare_mixed_measurement_value(
                &mut mismatches,
                row,
                &reference.name,
                reference.value,
                result.value,
                tolerance,
            )?;
            Self::compare_mixed_measurement_metadata(
                &mut mismatches,
                row,
                &format!("{}:trig", reference.name),
                reference.trigger_axis,
                result.trigger_axis,
                tolerance,
            )?;
            Self::compare_mixed_measurement_metadata(
                &mut mismatches,
                row,
                &format!("{}:targ", reference.name),
                reference.target_axis,
                result.target_axis,
                tolerance,
            )?;
        }
        Ok(mismatches)
    }

    fn mixed_measurement_rows(
        scalar: &[crate::analysis::MeasureResult],
        continuous: &[crate::analysis::ContinuousMeasureResult],
        declarations: &[crate::analysis::MeasureStatement],
        base_analysis: &str,
        continuous_analysis: &str,
    ) -> Result<Vec<XyceMixedMeasurementReferenceRow>, String> {
        for result in continuous {
            result.validate_invariants().map_err(|error| {
                format!(
                    "continuous measurement '{}' violates its result invariant: {error}",
                    result.name
                )
            })?;
        }
        let mut actual = Vec::new();
        let mut scalar_index = 0usize;
        let mut continuous_index = 0usize;
        for declaration in declarations.iter().filter(|declaration| {
            declaration.analysis.eq_ignore_ascii_case(base_analysis)
                || declaration
                    .analysis
                    .eq_ignore_ascii_case(continuous_analysis)
        }) {
            if declaration.analysis.eq_ignore_ascii_case(base_analysis) {
                let result = scalar.get(scalar_index).ok_or_else(|| {
                    format!(
                        "scalar {base_analysis} evaluator omitted declaration {} ('{}')",
                        scalar_index, declaration.name
                    )
                })?;
                scalar_index += 1;
                if !result.name.eq_ignore_ascii_case(&declaration.name) {
                    return Err(format!(
                        "scalar {base_analysis} evaluator returned '{}' for declaration '{}'",
                        result.name, declaration.name
                    ));
                }
                if declaration.print_policy == crate::analysis::MeasurePrintPolicy::All {
                    actual.push(XyceMixedMeasurementReferenceRow {
                        name: result.name.clone(),
                        value: result.value.map_or(
                            XyceMeasurementReferenceValue::Failed,
                            |value| XyceMeasurementReferenceValue::Numeric {
                                value,
                                quantization: None,
                            },
                        ),
                        trigger_axis: None,
                        target_axis: None,
                    });
                }
            } else {
                let result = continuous.get(continuous_index).ok_or_else(|| {
                    format!(
                        "continuous {continuous_analysis} evaluator omitted declaration {} ('{}')",
                        continuous_index, declaration.name
                    )
                })?;
                continuous_index += 1;
                if !result.name.eq_ignore_ascii_case(&declaration.name) {
                    return Err(format!(
                        "continuous {continuous_analysis} evaluator returned '{}' for declaration '{}'",
                        result.name, declaration.name
                    ));
                }
                if declaration.print_policy != crate::analysis::MeasurePrintPolicy::All {
                    continue;
                }
                if result.failure.is_some() {
                    actual.push(XyceMixedMeasurementReferenceRow {
                        name: result.name.clone(),
                        value: XyceMeasurementReferenceValue::Failed,
                        trigger_axis: result.failure_metadata.and_then(|metadata| {
                            metadata.trigger_axis.map(|value| {
                                XyceMeasurementReferenceValue::Numeric {
                                    value,
                                    quantization: None,
                                }
                            })
                        }),
                        target_axis: result.failure_metadata.and_then(|metadata| {
                            metadata.target_axis.map(|value| {
                                XyceMeasurementReferenceValue::Numeric {
                                    value,
                                    quantization: None,
                                }
                            })
                        }),
                    });
                } else {
                    actual.extend(result.records.iter().map(|record| {
                        XyceMixedMeasurementReferenceRow {
                            name: result.name.clone(),
                            value: XyceMeasurementReferenceValue::Numeric {
                                value: record.value,
                                quantization: None,
                            },
                            trigger_axis: record.trigger_axis.map(|value| {
                                XyceMeasurementReferenceValue::Numeric {
                                    value,
                                    quantization: None,
                                }
                            }),
                            target_axis: record.target_axis.map(|value| {
                                XyceMeasurementReferenceValue::Numeric {
                                    value,
                                    quantization: None,
                                }
                            }),
                        }
                    }));
                }
            }
        }
        if scalar_index != scalar.len() || continuous_index != continuous.len() {
            return Err(format!(
                "measurement evaluators returned unclaimed results (scalar {scalar_index}/{}, continuous {continuous_index}/{})",
                scalar.len(),
                continuous.len()
            ));
        }
        Ok(actual)
    }

    fn compare_mixed_measurement_value(
        mismatches: &mut Vec<XyceValueMismatch>,
        row: usize,
        probe: &str,
        expected: XyceMeasurementReferenceValue,
        actual: XyceMeasurementReferenceValue,
        tolerance: XyceFileCompareTolerance,
    ) -> Result<(), String> {
        match (expected, actual) {
            (XyceMeasurementReferenceValue::Failed, XyceMeasurementReferenceValue::Failed) => {
                Ok(())
            }
            (
                XyceMeasurementReferenceValue::Failed,
                XyceMeasurementReferenceValue::Numeric { value, .. },
            ) => Err(format!(
                "mixed measurement '{probe}' row {row} was expected to be FAILED but evaluated to {value}"
            )),
            (
                XyceMeasurementReferenceValue::Numeric { value, .. },
                XyceMeasurementReferenceValue::Failed,
            ) => Err(format!(
                "mixed measurement '{probe}' row {row} was expected to evaluate to {value} but FAILED"
            )),
            (
                XyceMeasurementReferenceValue::Numeric {
                    value: expected,
                    quantization,
                },
                XyceMeasurementReferenceValue::Numeric { value: actual, .. },
            ) => {
                if !Self::measurement_value_matches(expected, actual, quantization, tolerance) {
                    let absolute_error = (expected - actual).abs();
                    mismatches.push(XyceValueMismatch {
                        row,
                        probe: probe.to_string(),
                        expected,
                        actual,
                        relative_error: if expected == 0.0 {
                            f64::INFINITY
                        } else {
                            absolute_error / expected.abs()
                        },
                    });
                }
                Ok(())
            }
        }
    }

    fn compare_mixed_measurement_metadata(
        mismatches: &mut Vec<XyceValueMismatch>,
        row: usize,
        probe: &str,
        expected: Option<XyceMeasurementReferenceValue>,
        actual: Option<XyceMeasurementReferenceValue>,
        tolerance: XyceFileCompareTolerance,
    ) -> Result<(), String> {
        match (expected, actual) {
            (None, None) | (Some(XyceMeasurementReferenceValue::Failed), None) => Ok(()),
            (None, Some(XyceMeasurementReferenceValue::Numeric { value, .. })) => Err(format!(
                "mixed measurement artifact has no {probe} metadata at row {row}, but evaluation produced {value}"
            )),
            (
                Some(XyceMeasurementReferenceValue::Failed),
                Some(XyceMeasurementReferenceValue::Numeric { value, .. }),
            ) => Err(format!(
                "mixed measurement artifact marks {probe} not found at row {row}, but evaluation produced {value}"
            )),
            (
                Some(XyceMeasurementReferenceValue::Numeric { value, .. }),
                None | Some(XyceMeasurementReferenceValue::Failed),
            ) => Err(format!(
                "mixed measurement artifact expects {probe}={value} at row {row}, but evaluation omitted it"
            )),
            (Some(expected), Some(actual)) => Self::compare_mixed_measurement_value(
                mismatches, row, probe, expected, actual, tolerance,
            ),
            (None, Some(XyceMeasurementReferenceValue::Failed)) => Ok(()),
        }
    }

    fn compare_continuous_measurement_value(
        mismatches: &mut Vec<XyceValueMismatch>,
        row: usize,
        probe: &str,
        expected: XyceMeasurementReferenceValue,
        actual: Option<Value>,
        tolerance: XyceFileCompareTolerance,
    ) -> Result<(), String> {
        match (expected, actual) {
            (XyceMeasurementReferenceValue::Failed, None) => Ok(()),
            (XyceMeasurementReferenceValue::Failed, Some(actual)) => Err(format!(
                "continuous artifact has no {probe} metadata at row {row}, but evaluation produced {actual}"
            )),
            (
                XyceMeasurementReferenceValue::Numeric {
                    value,
                    quantization,
                },
                Some(actual),
            ) => {
                if !Self::measurement_value_matches(value, actual, quantization, tolerance) {
                    let absolute_error = (value - actual).abs();
                    mismatches.push(XyceValueMismatch {
                        row,
                        probe: probe.to_string(),
                        expected: value,
                        actual,
                        relative_error: if value == 0.0 {
                            f64::INFINITY
                        } else {
                            absolute_error / value.abs()
                        },
                    });
                }
                Ok(())
            }
            (XyceMeasurementReferenceValue::Numeric { value, .. }, None) => Err(format!(
                "continuous artifact expects {probe}={value} at row {row}, but evaluation omitted it"
            )),
        }
    }

    fn measurement_value_matches(
        expected: Value,
        actual: Value,
        quantization: Option<Value>,
        tolerance: XyceFileCompareTolerance,
    ) -> bool {
        if !expected.is_finite() || !actual.is_finite() {
            return false;
        }
        let absolute_error = (expected - actual).abs();
        let both_zero = expected.abs() <= tolerance.zero && actual.abs() <= tolerance.zero;
        let relative_error = if expected == 0.0 {
            f64::INFINITY
        } else {
            absolute_error / expected.abs()
        };
        let within_printed_quantization =
            quantization.is_some_and(|unit| absolute_error <= unit * 0.5);
        expected == actual
            || both_zero
            || within_printed_quantization
            || (absolute_error < tolerance.absolute && relative_error < tolerance.relative)
    }

    fn measurement_literal_quantization(raw: &str) -> Option<Value> {
        let raw = raw.trim();
        let exponent_index = raw.find(['e', 'E']);
        let (mantissa, exponent) = if let Some(index) = exponent_index {
            let exponent = raw.get(index + 1..)?.parse::<i32>().ok()?;
            (raw.get(..index)?, exponent)
        } else {
            (raw, 0)
        };
        let unsigned = mantissa.strip_prefix(['+', '-']).unwrap_or(mantissa);
        let (integer, fraction) = unsigned.split_once('.')?;
        if integer.is_empty()
            || !integer.bytes().all(|byte| byte.is_ascii_digit())
            || !fraction.bytes().all(|byte| byte.is_ascii_digit())
        {
            return None;
        }
        let fractional_digits = i32::try_from(fraction.len()).ok()?;
        let decimal_exponent = exponent.checked_sub(fractional_digits)?;
        let quantization = 10.0_f64.powi(decimal_exponent);
        (quantization.is_finite() && quantization > 0.0).then_some(quantization)
    }

    fn parse_prn_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_prn_table(&content)
    }

    fn parse_ac_comparator_prn_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        if content.is_empty() {
            return Err(format!("{} is empty", path.display()));
        }
        let last_nonempty = content.lines().rev().find(|line| !line.trim().is_empty());
        if last_nonempty.map(str::trim) != Some("End of Xyce(TM) Simulation") {
            return Err(format!(
                "{} has no exact ACComparator footer 'End of Xyce(TM) Simulation'",
                path.display()
            ));
        }
        Self::parse_prn_table(&content)
    }

    fn parse_dc_reference_file(
        contract: XyceStaticDcContract,
        path: &Path,
    ) -> Result<XycePrnTable, String> {
        match contract {
            XyceStaticDcContract::WrapperRaw => Self::parse_raw_file(path),
            XyceStaticDcContract::PlainCsv | XyceStaticDcContract::WrapperCsv => {
                Self::parse_csv_file(path)
            }
            XyceStaticDcContract::PlainCsd | XyceStaticDcContract::WrapperCsd => {
                Self::parse_csd_file(path)
            }
            _ => Self::parse_prn_file(path),
        }
    }

    fn parse_ac_reference_file(
        contract: XyceStaticAcContract,
        path: &Path,
    ) -> Result<XycePrnTable, String> {
        match contract {
            XyceStaticAcContract::PlainCsd | XyceStaticAcContract::WrapperCsd => {
                Self::parse_ac_csd_file(path)
            }
            _ => Self::parse_prn_file(path),
        }
    }

    fn parse_tran_reference_file(
        contract: XyceStaticTranContract,
        path: &Path,
    ) -> Result<XycePrnTable, String> {
        match contract {
            XyceStaticTranContract::PlainCsv | XyceStaticTranContract::WrapperCsv => {
                Self::parse_csv_file(path)
            }
            XyceStaticTranContract::PlainCsd | XyceStaticTranContract::WrapperCsd => {
                Self::parse_tran_csd_file(path)
            }
            _ => Self::parse_tran_prn_or_legacy_probe_file(path),
        }
    }

    fn parse_xyce_verify_tran_reference_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_xyce_verify_tran_reference_table(&content)
    }

    fn parse_xyce_verify_tran_reference_table(content: &str) -> Result<XycePrnTable, String> {
        let first_classified_line = content
            .lines()
            .find(|line| !line.is_empty())
            .ok_or_else(|| "empty Release 7.10 xyce_verify transient input".to_string())?;
        let first_header = first_classified_line.trim();
        if Self::prn_header_delimiter(first_header) != Some(XycePrnDelimiter::Whitespace) {
            return Err(
                "Release 7.10 xyce_verify transient input must begin with an indexed STD PRN header"
                    .to_string(),
            );
        }
        let first_columns = Self::parse_prn_columns(first_header, XycePrnDelimiter::Whitespace)?;
        if first_columns.first().map(String::as_str) != Some("Index") {
            return Err(
                "Release 7.10 xyce_verify transient input must begin with an indexed STD PRN header"
                    .to_string(),
            );
        }
        let table = Self::parse_prn_table(content)?;
        let header_index = content
            .lines()
            .position(|line| Self::is_prn_header_line(line.trim()))
            .expect("a parsed PRN table has a header");
        if !content
            .lines()
            .skip(header_index + 1)
            .any(|line| line.contains("End of Xyce"))
        {
            return Err(
                "Release 7.10 xyce_verify transient input has no normal 'End of Xyce' completion footer"
                    .to_string(),
            );
        }
        Ok(table)
    }

    fn parse_tran_prn_or_legacy_probe_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_tran_prn_or_legacy_probe_table(&content)
    }

    fn parse_tran_prn_or_legacy_probe_table(content: &str) -> Result<XycePrnTable, String> {
        let first_nonempty = content.lines().map(str::trim).find(|line| !line.is_empty());
        if first_nonempty.is_some_and(|line| line.eq_ignore_ascii_case("#H")) {
            return Self::parse_tran_csd_table(content);
        }
        Self::parse_prn_table(content)
    }

    fn parse_csv_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_prn_table(&content)
    }

    fn parse_raw_file(path: &Path) -> Result<XycePrnTable, String> {
        let bytes = fs::read(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_raw_table(&bytes)
    }

    fn parse_csd_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_csd_table(&content)
    }

    fn parse_ac_csd_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_ac_csd_table(&content)
    }

    fn parse_tran_csd_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_tran_csd_table(&content)
    }

    fn parse_tran_csd_table(content: &str) -> Result<XycePrnTable, String> {
        let lines = content
            .lines()
            .enumerate()
            .map(|(line_number, line)| (line_number + 1, line.trim()))
            .filter(|(_, line)| !line.is_empty())
            .collect::<Vec<_>>();
        if lines.is_empty() {
            return Err("empty Xyce transient CSDF table".to_string());
        }

        let mut columns: Option<Vec<String>> = None;
        let mut rows = Vec::new();
        let mut index = 0usize;
        while index < lines.len() {
            let (line_number, line) = lines[index];
            if !line.eq_ignore_ascii_case("#H") {
                return Err(format!(
                    "Xyce transient CSDF section must start with #H at line {line_number}, got '{line}'"
                ));
            }
            index += 1;

            let mut complex_values = false;
            let mut sweep_column = "TIME".to_string();
            while index < lines.len() {
                let (_, header_line) = lines[index];
                if header_line.eq_ignore_ascii_case("#N") {
                    break;
                }
                for (key, value) in Self::parse_csd_header_assignments(header_line) {
                    if key.eq_ignore_ascii_case("COMPLEXVALUES")
                        && value.eq_ignore_ascii_case("YES")
                    {
                        complex_values = true;
                    }
                    if key.eq_ignore_ascii_case("SWEEPVAR") {
                        sweep_column = value.to_ascii_uppercase();
                    }
                }
                index += 1;
            }
            if complex_values {
                return Err("Xyce transient CSDF COMPLEXVALUES=YES is not supported".to_string());
            }
            if index >= lines.len() {
                return Err("Xyce transient CSDF section has no #N column block".to_string());
            }

            index += 1;
            let Some((column_line_number, column_line)) = lines.get(index).copied() else {
                return Err("Xyce transient CSDF #N block has no column line".to_string());
            };
            let section_input_columns = Self::parse_csd_columns(column_line).map_err(|err| {
                format!("invalid Xyce transient CSDF column line {column_line_number}: {err}")
            })?;
            if section_input_columns.is_empty() {
                return Err(format!(
                    "Xyce transient CSDF column line {column_line_number} has no columns"
                ));
            }
            let mut section_columns = Vec::with_capacity(section_input_columns.len() + 1);
            section_columns.push(sweep_column);
            section_columns.extend(section_input_columns.iter().cloned());
            if let Some(columns) = &columns {
                if !Self::same_prn_columns(columns, &section_columns) {
                    return Err(format!(
                        "Xyce transient CSDF section changes columns from {:?} to {:?}",
                        columns, section_columns
                    ));
                }
            } else {
                columns = Some(section_columns);
            }
            index += 1;

            while index < lines.len() {
                let (line_number, line) = lines[index];
                if line.eq_ignore_ascii_case("#;") {
                    index += 1;
                    break;
                }
                if line.eq_ignore_ascii_case("#H") {
                    break;
                }
                if !line.starts_with("#C") {
                    return Err(format!(
                        "expected Xyce transient CSDF #C row header at line {line_number}, got '{line}'"
                    ));
                }
                let (time, expected_count) =
                    Self::parse_csd_sweep_row_header(line).map_err(|err| {
                        format!(
                            "invalid Xyce transient CSDF #C row header at line {line_number}: {err}"
                        )
                    })?;
                index += 1;

                let mut row = Vec::with_capacity(expected_count + 1);
                row.push(time);
                while row.len() <= expected_count {
                    let Some((data_line_number, data_line)) = lines.get(index).copied() else {
                        return Err(format!(
                            "Xyce transient CSDF row beginning at line {line_number} ended after {} value(s), expected {expected_count}",
                            row.len().saturating_sub(1)
                        ));
                    };
                    if data_line.starts_with('#') {
                        return Err(format!(
                            "Xyce transient CSDF row beginning at line {line_number} ended before {expected_count} value(s) at line {data_line_number}"
                        ));
                    }
                    for token in data_line.split_whitespace() {
                        if row.len() > expected_count {
                            return Err(format!(
                                "Xyce transient CSDF row beginning at line {line_number} has more than {expected_count} value(s)"
                            ));
                        }
                        let expected_position = row.len();
                        let value = Self::parse_csd_complex_value_token(token, expected_position)
                            .map_err(|err| {
                                format!(
                                    "invalid Xyce transient CSDF data token '{token}' at line {data_line_number}: {err}"
                                )
                            })?;
                        if value.im.abs() > f64::EPSILON {
                            return Err(format!(
                                "Xyce transient CSDF token '{token}' at line {data_line_number} has nonzero imaginary component {}",
                                value.im
                            ));
                        }
                        row.push(value.re);
                    }
                    index += 1;
                }
                if let Some(columns) = &columns {
                    if row.len() != columns.len() {
                        return Err(format!(
                            "Xyce transient CSDF row beginning at line {line_number} has {} column value(s), expected {}",
                            row.len(),
                            columns.len()
                        ));
                    }
                }
                rows.push(row);
            }
        }

        let columns =
            columns.ok_or_else(|| "Xyce transient CSDF table has no columns".to_string())?;
        if rows.is_empty() {
            return Err("Xyce transient CSDF table has no data rows".to_string());
        }
        Ok(XycePrnTable { columns, rows })
    }

    fn parse_ac_csd_table(content: &str) -> Result<XycePrnTable, String> {
        let lines = content
            .lines()
            .enumerate()
            .map(|(line_number, line)| (line_number + 1, line.trim()))
            .filter(|(_, line)| !line.is_empty())
            .collect::<Vec<_>>();
        if lines.is_empty() {
            return Err("empty Xyce AC CSDF table".to_string());
        }

        let mut columns: Option<Vec<String>> = None;
        let mut expansion: Option<Vec<XyceAcCsdColumnExpansion>> = None;
        let mut rows = Vec::new();
        let mut index = 0usize;
        while index < lines.len() {
            let (line_number, line) = lines[index];
            if !line.eq_ignore_ascii_case("#H") {
                return Err(format!(
                    "Xyce AC CSDF section must start with #H at line {line_number}, got '{line}'"
                ));
            }
            index += 1;

            let mut complex_values = false;
            let mut sweep_column = "FREQ".to_string();
            while index < lines.len() {
                let (_, header_line) = lines[index];
                if header_line.eq_ignore_ascii_case("#N") {
                    break;
                }
                for (key, value) in Self::parse_csd_header_assignments(header_line) {
                    if key.eq_ignore_ascii_case("COMPLEXVALUES")
                        && value.eq_ignore_ascii_case("YES")
                    {
                        complex_values = true;
                    }
                    if key.eq_ignore_ascii_case("SWEEPVAR") {
                        sweep_column = value.to_ascii_uppercase();
                    }
                }
                index += 1;
            }
            if index >= lines.len() {
                return Err("Xyce AC CSDF section has no #N column block".to_string());
            }

            index += 1;
            let Some((column_line_number, column_line)) = lines.get(index).copied() else {
                return Err("Xyce AC CSDF #N block has no column line".to_string());
            };
            let section_input_columns = Self::parse_csd_columns(column_line).map_err(|err| {
                format!("invalid Xyce AC CSDF column line {column_line_number}: {err}")
            })?;
            if section_input_columns.is_empty() {
                return Err(format!(
                    "Xyce AC CSDF column line {column_line_number} has no columns"
                ));
            }
            let section_expansion =
                Self::ac_csd_column_expansion(&section_input_columns, complex_values);
            let section_columns = Self::expanded_ac_csd_columns(
                &sweep_column,
                &section_input_columns,
                &section_expansion,
            );
            if let Some(columns) = &columns {
                if !Self::same_prn_columns(columns, &section_columns) {
                    return Err(format!(
                        "Xyce AC CSDF section changes columns from {:?} to {:?}",
                        columns, section_columns
                    ));
                }
            } else {
                columns = Some(section_columns);
                expansion = Some(section_expansion);
            }
            let expansion = expansion
                .as_ref()
                .expect("AC CSDF expansion initialized with columns");
            index += 1;

            while index < lines.len() {
                let (line_number, line) = lines[index];
                if line.eq_ignore_ascii_case("#;") {
                    index += 1;
                    break;
                }
                if line.eq_ignore_ascii_case("#H") {
                    break;
                }
                if !line.starts_with("#C") {
                    return Err(format!(
                        "expected Xyce AC CSDF #C row header at line {line_number}, got '{line}'"
                    ));
                }
                let (frequency, expected_count) =
                    Self::parse_csd_sweep_row_header(line).map_err(|err| {
                        format!("invalid Xyce AC CSDF #C row header at line {line_number}: {err}")
                    })?;
                index += 1;

                let mut tokens = Vec::with_capacity(expected_count);
                while tokens.len() < expected_count {
                    let Some((data_line_number, data_line)) = lines.get(index).copied() else {
                        return Err(format!(
                            "Xyce AC CSDF row beginning at line {line_number} ended after {} value(s), expected {expected_count}",
                            tokens.len()
                        ));
                    };
                    if data_line.starts_with('#') {
                        return Err(format!(
                            "Xyce AC CSDF row beginning at line {line_number} ended before {expected_count} value(s) at line {data_line_number}"
                        ));
                    }
                    for token in data_line.split_whitespace() {
                        if tokens.len() >= expected_count {
                            return Err(format!(
                                "Xyce AC CSDF row beginning at line {line_number} has more than {expected_count} value(s)"
                            ));
                        }
                        let expected_position = tokens.len() + 1;
                        tokens.push(
                            Self::parse_csd_complex_value_token(token, expected_position).map_err(
                                |err| {
                                    format!(
                                        "invalid Xyce AC CSDF data token '{token}' at line {data_line_number}: {err}"
                                    )
                                },
                            )?,
                        );
                    }
                    index += 1;
                }
                if tokens.len() != section_input_columns.len() {
                    return Err(format!(
                        "Xyce AC CSDF row beginning at line {line_number} has {} value(s), expected {} column(s)",
                        tokens.len(),
                        section_input_columns.len()
                    ));
                }

                let mut row = Vec::new();
                row.push(frequency);
                for (value, expansion) in tokens.into_iter().zip(expansion.iter()) {
                    match expansion {
                        XyceAcCsdColumnExpansion::Scalar => {
                            if value.im.abs() > f64::EPSILON {
                                return Err(format!(
                                    "Xyce AC CSDF scalar row beginning at line {line_number} has nonzero imaginary component {}",
                                    value.im
                                ));
                            }
                            row.push(value.re);
                        }
                        XyceAcCsdColumnExpansion::Complex => {
                            row.push(value.re);
                            row.push(value.im);
                        }
                    }
                }
                rows.push(row);
            }
        }

        let columns = columns.ok_or_else(|| "Xyce AC CSDF table has no columns".to_string())?;
        if rows.is_empty() {
            return Err("Xyce AC CSDF table has no data rows".to_string());
        }
        Ok(XycePrnTable { columns, rows })
    }

    fn ac_csd_column_expansion(
        columns: &[String],
        complex_values: bool,
    ) -> Vec<XyceAcCsdColumnExpansion> {
        columns
            .iter()
            .map(|column| {
                if complex_values && Self::ac_csd_column_is_complex_probe(column) {
                    XyceAcCsdColumnExpansion::Complex
                } else {
                    XyceAcCsdColumnExpansion::Scalar
                }
            })
            .collect()
    }

    fn expanded_ac_csd_columns(
        sweep_column: &str,
        input_columns: &[String],
        expansion: &[XyceAcCsdColumnExpansion],
    ) -> Vec<String> {
        let mut columns = Vec::with_capacity(
            1 + input_columns.len()
                + expansion
                    .iter()
                    .filter(|kind| matches!(kind, XyceAcCsdColumnExpansion::Complex))
                    .count(),
        );
        columns.push(sweep_column.to_string());
        for (column, expansion) in input_columns.iter().zip(expansion.iter()) {
            match expansion {
                XyceAcCsdColumnExpansion::Scalar => columns.push(column.clone()),
                XyceAcCsdColumnExpansion::Complex => {
                    columns.push(format!("Re({column})"));
                    columns.push(format!("Im({column})"));
                }
            }
        }
        columns
    }

    fn ac_csd_column_is_complex_probe(column: &str) -> bool {
        let normalized = Self::normalize_probe(column);
        if let Some(voltage_probe) = Self::parse_ac_voltage_probe(&normalized) {
            return voltage_probe.accessor == XyceVoltageAccessor::Value;
        }
        if let Some(current_probe) = Self::parse_ac_current_probe(&normalized) {
            return current_probe.accessor == XyceCurrentAccessor::Value;
        }
        false
    }

    fn parse_csd_table(content: &str) -> Result<XycePrnTable, String> {
        let lines = content
            .lines()
            .enumerate()
            .map(|(line_number, line)| (line_number + 1, line.trim()))
            .filter(|(_, line)| !line.is_empty())
            .collect::<Vec<_>>();
        if lines.is_empty() {
            return Err("empty Xyce CSDF table".to_string());
        }

        let mut columns: Option<Vec<String>> = None;
        let mut rows = Vec::new();
        let mut index = 0usize;
        while index < lines.len() {
            let (line_number, line) = lines[index];
            if !line.eq_ignore_ascii_case("#H") {
                return Err(format!(
                    "Xyce CSDF section must start with #H at line {line_number}, got '{line}'"
                ));
            }
            index += 1;

            let mut complex_values = false;
            while index < lines.len() {
                let (_, header_line) = lines[index];
                if header_line.eq_ignore_ascii_case("#N") {
                    break;
                }
                for (key, value) in Self::parse_csd_header_assignments(header_line) {
                    if key.eq_ignore_ascii_case("COMPLEXVALUES")
                        && value.eq_ignore_ascii_case("YES")
                    {
                        complex_values = true;
                    }
                }
                index += 1;
            }
            if complex_values {
                return Err("Xyce CSDF COMPLEXVALUES=YES is not supported".to_string());
            }
            if index >= lines.len() {
                return Err("Xyce CSDF section has no #N column block".to_string());
            }

            index += 1;
            let Some((column_line_number, column_line)) = lines.get(index).copied() else {
                return Err("Xyce CSDF #N block has no column line".to_string());
            };
            let section_columns = Self::parse_csd_columns(column_line).map_err(|err| {
                format!("invalid Xyce CSDF column line {column_line_number}: {err}")
            })?;
            if section_columns.is_empty() {
                return Err(format!(
                    "Xyce CSDF column line {column_line_number} has no columns"
                ));
            }
            if let Some(columns) = &columns {
                if !Self::same_prn_columns(columns, &section_columns) {
                    return Err(format!(
                        "Xyce CSDF section changes columns from {:?} to {:?}",
                        columns, section_columns
                    ));
                }
            } else {
                columns = Some(section_columns);
            }
            index += 1;

            while index < lines.len() {
                let (line_number, line) = lines[index];
                if line.eq_ignore_ascii_case("#;") {
                    index += 1;
                    break;
                }
                if line.eq_ignore_ascii_case("#H") {
                    break;
                }
                if !line.starts_with("#C") {
                    return Err(format!(
                        "expected Xyce CSDF #C row header at line {line_number}, got '{line}'"
                    ));
                }
                let (_, expected_count) =
                    Self::parse_csd_sweep_row_header(line).map_err(|err| {
                        format!("invalid Xyce CSDF #C row header at line {line_number}: {err}")
                    })?;
                index += 1;

                let mut row = Vec::with_capacity(expected_count);
                while row.len() < expected_count {
                    let Some((data_line_number, data_line)) = lines.get(index).copied() else {
                        return Err(format!(
                            "Xyce CSDF row beginning at line {line_number} ended after {} value(s), expected {expected_count}",
                            row.len()
                        ));
                    };
                    if data_line.starts_with('#') {
                        return Err(format!(
                            "Xyce CSDF row beginning at line {line_number} ended before {expected_count} value(s) at line {data_line_number}"
                        ));
                    }
                    for token in data_line.split_whitespace() {
                        if row.len() >= expected_count {
                            return Err(format!(
                                "Xyce CSDF row beginning at line {line_number} has more than {expected_count} value(s)"
                            ));
                        }
                        let expected_position = row.len() + 1;
                        let value = Self::parse_csd_complex_value_token(token, expected_position)
                            .map_err(|err| {
                                format!(
                                    "invalid Xyce CSDF data token '{token}' at line {data_line_number}: {err}"
                                )
                            })?;
                        if value.im.abs() > f64::EPSILON {
                            return Err(format!(
                                "Xyce CSDF real table token '{token}' at line {data_line_number} has nonzero imaginary component {}",
                                value.im
                            ));
                        }
                        row.push(value.re);
                    }
                    index += 1;
                }
                if let Some(columns) = &columns {
                    if row.len() != columns.len() {
                        return Err(format!(
                            "Xyce CSDF row beginning at line {line_number} has {} value(s), expected {} column(s)",
                            row.len(),
                            columns.len()
                        ));
                    }
                }
                rows.push(row);
            }
        }

        let columns = columns.ok_or_else(|| "Xyce CSDF table has no columns".to_string())?;
        if rows.is_empty() {
            return Err("Xyce CSDF table has no data rows".to_string());
        }
        Ok(XycePrnTable { columns, rows })
    }

    fn parse_csd_header_assignments(line: &str) -> Vec<(&str, &str)> {
        line.split_whitespace()
            .filter_map(|field| {
                let (key, value) = field.split_once('=')?;
                Some((key.trim(), value.trim_matches(['"', '\''])))
            })
            .collect()
    }

    fn parse_csd_columns(line: &str) -> Result<Vec<String>, String> {
        if !line.contains('\'') {
            return Ok(line.split_whitespace().map(str::to_string).collect());
        }

        let mut columns = Vec::new();
        let mut rest = line;
        loop {
            let Some(start) = rest.find('\'') else {
                if rest.trim().is_empty() {
                    return Ok(columns);
                }
                return Err(format!(
                    "unexpected unquoted text after CSDF column list: '{}'",
                    rest.trim()
                ));
            };
            if !rest[..start].trim().is_empty() {
                return Err(format!(
                    "unexpected text before quoted CSDF column: '{}'",
                    rest[..start].trim()
                ));
            }
            let after_start = &rest[start + 1..];
            let Some(end) = after_start.find('\'') else {
                return Err("unterminated quoted CSDF column".to_string());
            };
            columns.push(after_start[..end].to_string());
            rest = &after_start[end + 1..];
        }
    }

    fn parse_csd_sweep_row_header(line: &str) -> Result<(f64, usize), String> {
        let fields = line.split_whitespace().collect::<Vec<_>>();
        if fields.len() != 3 || !fields[0].eq_ignore_ascii_case("#C") {
            return Err("expected '#C <sweep-value> <value-count>'".to_string());
        }
        let sweep_value = Self::parse_xyce_numeric_token(fields[1])
            .map_err(|err| format!("invalid sweep value '{}': {err}", fields[1]))?;
        let value_count = fields[2]
            .parse::<usize>()
            .map_err(|err| format!("invalid value count '{}': {err}", fields[2]))?;
        Ok((sweep_value, value_count))
    }

    fn parse_csd_complex_value_token(
        token: &str,
        expected_position: usize,
    ) -> Result<Complex64, String> {
        let (value, position) = token
            .split_once(':')
            .ok_or_else(|| "expected '<value>:<position>'".to_string())?;
        let position = position
            .parse::<usize>()
            .map_err(|err| format!("invalid position '{}': {err}", position))?;
        if position != expected_position {
            return Err(format!(
                "position {position} does not match expected position {expected_position}"
            ));
        }
        let (real, imaginary) = value.split_once('/').unwrap_or((value, "0"));
        let real = Self::parse_xyce_numeric_token(real)
            .map_err(|err| format!("invalid real value '{}': {err}", real))?;
        let imaginary = Self::parse_xyce_numeric_token(imaginary)
            .map_err(|err| format!("invalid imaginary value '{}': {err}", imaginary))?;
        Ok(Complex64::new(real, imaginary))
    }

    fn parse_raw_table(bytes: &[u8]) -> Result<XycePrnTable, String> {
        let mut offset = 0usize;
        let mut columns: Option<Vec<String>> = None;
        let mut rows = Vec::new();
        let mut plot_index = 0usize;

        while offset < bytes.len() {
            Self::skip_raw_blank_lines(bytes, &mut offset);
            if offset >= bytes.len() {
                break;
            }

            let (plot_columns, plot_rows) = Self::parse_raw_plot(bytes, &mut offset, plot_index)?;
            if let Some(columns) = &columns {
                if !Self::same_prn_columns(columns, &plot_columns) {
                    return Err(format!(
                        "Xyce RAW plot {} changes variables from {:?} to {:?}",
                        plot_index + 1,
                        columns,
                        plot_columns
                    ));
                }
            } else {
                columns = Some(plot_columns);
            }
            rows.extend(plot_rows);
            plot_index += 1;
        }

        let columns = columns.ok_or_else(|| "empty Xyce RAW table".to_string())?;
        if rows.is_empty() {
            return Err("Xyce RAW table has no data rows".to_string());
        }

        Ok(XycePrnTable { columns, rows })
    }

    fn parse_raw_plot(
        bytes: &[u8],
        offset: &mut usize,
        plot_index: usize,
    ) -> Result<(Vec<String>, Vec<Vec<f64>>), String> {
        let mut flags = None;
        let mut variable_count = None;
        let mut point_count = None;

        loop {
            let line = Self::read_raw_line(bytes, offset).ok_or_else(|| {
                format!(
                    "Xyce RAW plot {} ended before Variables header",
                    plot_index + 1
                )
            })?;
            let trimmed = line.trim();
            if trimmed.is_empty()
                || trimmed.starts_with("Title:")
                || trimmed.starts_with("Date:")
                || trimmed.starts_with("Version:")
            {
                continue;
            }
            if trimmed.starts_with("Plotname:") {
                continue;
            }
            if let Some(value) = trimmed.strip_prefix("Flags:") {
                flags = Some(value.trim().to_string());
                continue;
            }
            if let Some(value) = trimmed.strip_prefix("No. Variables:") {
                variable_count = Some(value.trim().parse::<usize>().map_err(|err| {
                    format!(
                        "invalid RAW variable count '{}' in plot {}: {err}",
                        value.trim(),
                        plot_index + 1
                    )
                })?);
                continue;
            }
            if let Some(value) = trimmed.strip_prefix("No. Points:") {
                point_count = Some(value.trim().parse::<usize>().map_err(|err| {
                    format!(
                        "invalid RAW point count '{}' in plot {}: {err}",
                        value.trim(),
                        plot_index + 1
                    )
                })?);
                continue;
            }
            if trimmed.eq_ignore_ascii_case("Variables:") {
                break;
            }
            return Err(format!(
                "unexpected RAW header line in plot {}: '{}'",
                plot_index + 1,
                trimmed
            ));
        }

        let flags =
            flags.ok_or_else(|| format!("RAW plot {} has no Flags line", plot_index + 1))?;
        if !flags
            .split_whitespace()
            .any(|flag| flag.eq_ignore_ascii_case("real"))
        {
            return Err(format!(
                "RAW plot {} uses unsupported Flags: {flags}; only real-valued RAW is supported",
                plot_index + 1
            ));
        }
        if flags
            .split_whitespace()
            .any(|flag| flag.eq_ignore_ascii_case("complex"))
        {
            return Err(format!(
                "RAW plot {} is complex-valued; DC RAW comparison currently supports real data",
                plot_index + 1
            ));
        }
        let variable_count = variable_count
            .ok_or_else(|| format!("RAW plot {} has no variable count", plot_index + 1))?;
        let point_count =
            point_count.ok_or_else(|| format!("RAW plot {} has no point count", plot_index + 1))?;
        if variable_count == 0 {
            return Err(format!("RAW plot {} has no variables", plot_index + 1));
        }

        let mut columns = Vec::with_capacity(variable_count);
        for variable_index in 0..variable_count {
            let line = Self::read_raw_line(bytes, offset).ok_or_else(|| {
                format!(
                    "RAW plot {} ended while reading variable {}",
                    plot_index + 1,
                    variable_index
                )
            })?;
            let fields = line.split_whitespace().collect::<Vec<_>>();
            if fields.len() < 3 {
                return Err(format!(
                    "invalid RAW variable line in plot {}: '{}'",
                    plot_index + 1,
                    line.trim()
                ));
            }
            let parsed_index = fields[0].parse::<usize>().map_err(|err| {
                format!(
                    "invalid RAW variable index '{}' in plot {}: {err}",
                    fields[0],
                    plot_index + 1
                )
            })?;
            if parsed_index != variable_index {
                return Err(format!(
                    "RAW variable index {} appears where {} was expected in plot {}",
                    parsed_index,
                    variable_index,
                    plot_index + 1
                ));
            }
            columns.push(fields[1].to_string());
        }

        let data_marker = loop {
            let line = Self::read_raw_line(bytes, offset).ok_or_else(|| {
                format!(
                    "RAW plot {} ended before Values/Binary marker",
                    plot_index + 1
                )
            })?;
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            break trimmed.to_ascii_lowercase();
        };

        let rows = match data_marker.as_str() {
            "values:" => {
                Self::parse_ascii_raw_rows(bytes, offset, plot_index, point_count, variable_count)?
            }
            "binary:" => {
                Self::parse_binary_raw_rows(bytes, offset, plot_index, point_count, variable_count)?
            }
            other => {
                return Err(format!(
                    "RAW plot {} expected Values: or Binary:, got '{}'",
                    plot_index + 1,
                    other
                ));
            }
        };

        Ok((columns, rows))
    }

    fn parse_ascii_raw_rows(
        bytes: &[u8],
        offset: &mut usize,
        plot_index: usize,
        point_count: usize,
        variable_count: usize,
    ) -> Result<Vec<Vec<f64>>, String> {
        let mut rows = Vec::with_capacity(point_count);
        for point_index in 0..point_count {
            let first_line = Self::read_next_nonempty_raw_line(bytes, offset).ok_or_else(|| {
                format!(
                    "RAW plot {} ended while reading point {}",
                    plot_index + 1,
                    point_index
                )
            })?;
            let first_fields = first_line.split_whitespace().collect::<Vec<_>>();
            if first_fields.is_empty() {
                return Err(format!(
                    "RAW plot {} has empty point line for point {}",
                    plot_index + 1,
                    point_index
                ));
            }
            let parsed_index = first_fields[0].parse::<usize>().map_err(|err| {
                format!(
                    "invalid RAW point index '{}' in plot {}: {err}",
                    first_fields[0],
                    plot_index + 1
                )
            })?;
            if parsed_index != point_index {
                return Err(format!(
                    "RAW point index {} appears where {} was expected in plot {}",
                    parsed_index,
                    point_index,
                    plot_index + 1
                ));
            }

            let mut row = first_fields
                .iter()
                .skip(1)
                .map(|token| {
                    Self::parse_xyce_numeric_token(token).map_err(|err| {
                        format!(
                            "invalid RAW numeric token '{}' at plot {}, point {}: {err}",
                            token,
                            plot_index + 1,
                            point_index
                        )
                    })
                })
                .collect::<Result<Vec<_>, _>>()?;
            while row.len() < variable_count {
                let line = Self::read_next_nonempty_raw_line(bytes, offset).ok_or_else(|| {
                    format!(
                        "RAW plot {} ended while reading values for point {}",
                        plot_index + 1,
                        point_index
                    )
                })?;
                for token in line.split_whitespace() {
                    row.push(Self::parse_xyce_numeric_token(token).map_err(|err| {
                        format!(
                            "invalid RAW numeric token '{}' at plot {}, point {}: {err}",
                            token,
                            plot_index + 1,
                            point_index
                        )
                    })?);
                }
            }
            if row.len() != variable_count {
                return Err(format!(
                    "RAW plot {} point {} has {} values, expected {}",
                    plot_index + 1,
                    point_index,
                    row.len(),
                    variable_count
                ));
            }
            rows.push(row);
        }
        Ok(rows)
    }

    fn parse_binary_raw_rows(
        bytes: &[u8],
        offset: &mut usize,
        plot_index: usize,
        point_count: usize,
        variable_count: usize,
    ) -> Result<Vec<Vec<f64>>, String> {
        let value_count = point_count
            .checked_mul(variable_count)
            .ok_or_else(|| format!("RAW plot {} point/variable count overflows", plot_index + 1))?;
        let byte_count = value_count
            .checked_mul(std::mem::size_of::<f64>())
            .ok_or_else(|| format!("RAW plot {} binary byte count overflows", plot_index + 1))?;
        if bytes.len().saturating_sub(*offset) < byte_count {
            return Err(format!(
                "RAW plot {} binary payload has {} byte(s), expected {}",
                plot_index + 1,
                bytes.len().saturating_sub(*offset),
                byte_count
            ));
        }

        let mut rows = Vec::with_capacity(point_count);
        for point_index in 0..point_count {
            let mut row = Vec::with_capacity(variable_count);
            for variable_index in 0..variable_count {
                let start = *offset
                    + (point_index * variable_count + variable_index) * std::mem::size_of::<f64>();
                let bytes: [u8; 8] = bytes[start..start + 8]
                    .try_into()
                    .expect("slice length checked");
                row.push(f64::from_le_bytes(bytes));
            }
            rows.push(row);
        }
        *offset += byte_count;
        Ok(rows)
    }

    fn read_next_nonempty_raw_line(bytes: &[u8], offset: &mut usize) -> Option<String> {
        loop {
            let line = Self::read_raw_line(bytes, offset)?;
            if !line.trim().is_empty() {
                return Some(line);
            }
        }
    }

    fn skip_raw_blank_lines(bytes: &[u8], offset: &mut usize) {
        while *offset < bytes.len() {
            let mut cursor = *offset;
            let Some(line) = Self::read_raw_line(bytes, &mut cursor) else {
                return;
            };
            if !line.trim().is_empty() {
                return;
            }
            *offset = cursor;
        }
    }

    fn read_raw_line(bytes: &[u8], offset: &mut usize) -> Option<String> {
        if *offset >= bytes.len() {
            return None;
        }
        let start = *offset;
        let mut end = start;
        while end < bytes.len() && bytes[end] != b'\n' {
            end += 1;
        }
        *offset = end.saturating_add(usize::from(end < bytes.len()));
        let mut line = &bytes[start..end];
        if line.ends_with(b"\r") {
            line = &line[..line.len().saturating_sub(1)];
        }
        Some(String::from_utf8_lossy(line).into_owned())
    }

    fn is_parameter_sweep_summary_reference(path: &Path) -> bool {
        let Ok(content) = fs::read_to_string(path) else {
            return false;
        };
        let mut lines = content
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty());
        let Some(header) = lines.next() else {
            return false;
        };
        header.to_ascii_uppercase().starts_with("STEP")
            && content
                .to_ascii_lowercase()
                .contains("end of xyce(tm) parameter sweep")
    }

    fn parse_prn_table(content: &str) -> Result<XycePrnTable, String> {
        let nonempty_lines = content
            .lines()
            .enumerate()
            .map(|(line_number, line)| (line_number + 1, line.trim()))
            .filter(|(_, line)| !line.is_empty())
            .collect::<Vec<_>>();
        if nonempty_lines.is_empty() {
            return Err("empty Xyce .prn table".to_string());
        }

        let Some((header_index, (_header_line_number, header))) = nonempty_lines
            .iter()
            .enumerate()
            .find(|(_, (_, line))| Self::is_prn_header_line(line))
        else {
            return Err("Xyce .prn table has no header".to_string());
        };
        let delimiter = Self::prn_header_delimiter(header)
            .ok_or_else(|| format!("invalid Xyce .prn header '{}'", header))?;
        let columns = Self::parse_prn_columns(header, delimiter)?;
        if columns.is_empty() {
            return Err("Xyce .prn header has no columns".to_string());
        }

        let mut rows = Vec::new();
        for (line_number, line) in nonempty_lines.iter().skip(header_index + 1).copied() {
            if line.to_ascii_lowercase().starts_with("end of xyce") {
                break;
            }
            if !rows.is_empty() && Self::is_prn_footer_line(line) {
                break;
            }
            if Self::is_prn_separator_line(line) {
                continue;
            }
            if Self::is_prn_header_line(line) {
                let repeated_delimiter = Self::prn_header_delimiter(line)
                    .ok_or_else(|| format!("invalid repeated Xyce .prn header '{}'", line))?;
                let repeated_columns = Self::parse_prn_columns(line, repeated_delimiter)?;
                if Self::same_prn_columns(&columns, &repeated_columns) {
                    continue;
                }
                return Err(format!(
                    "Xyce .prn table changes columns at line {}; multi-table .prn output is not supported",
                    line_number
                ));
            }
            let values = Self::split_prn_fields(line, delimiter)
                .map(|token| {
                    Self::parse_xyce_numeric_token(token).map_err(|err| {
                        format!(
                            "invalid numeric token '{}' on data line {}: {err}",
                            token, line_number
                        )
                    })
                })
                .collect::<Result<Vec<_>, _>>()?;
            if values.len() != columns.len() {
                return Err(format!(
                    "data line {} has {} values, expected {}",
                    line_number,
                    values.len(),
                    columns.len()
                ));
            }
            rows.push(values);
        }

        if rows.is_empty() {
            return Err("Xyce .prn table has no data rows".to_string());
        }

        Ok(XycePrnTable { columns, rows })
    }

    fn parse_prn_columns(line: &str, delimiter: XycePrnDelimiter) -> Result<Vec<String>, String> {
        match delimiter {
            XycePrnDelimiter::Whitespace => Self::split_prn_header_fields(line),
            XycePrnDelimiter::Comma => {
                Ok(line.split(',').map(str::trim).map(str::to_string).collect())
            }
        }
    }

    fn is_prn_header_line(line: &str) -> bool {
        Self::prn_header_delimiter(line).is_some()
    }

    fn prn_header_delimiter(line: &str) -> Option<XycePrnDelimiter> {
        if line
            .split(',')
            .next()
            .is_some_and(|token| Self::is_prn_metadata_header_token(token.trim()))
        {
            return Some(XycePrnDelimiter::Comma);
        }
        let whitespace_fields = Self::split_prn_header_fields(line).ok()?;
        if whitespace_fields
            .first()
            .is_some_and(|token| Self::is_prn_metadata_header_token(token))
        {
            return Some(XycePrnDelimiter::Whitespace);
        }
        let comma_fields = line.split(',').map(str::trim).collect::<Vec<_>>();
        if comma_fields.len() > 1
            && comma_fields
                .first()
                .is_some_and(|token| Self::looks_like_reference_probe_header(token))
        {
            return Some(XycePrnDelimiter::Comma);
        }
        if whitespace_fields.len() > 1
            && whitespace_fields
                .first()
                .is_some_and(|token| Self::looks_like_reference_probe_header(token))
        {
            return Some(XycePrnDelimiter::Whitespace);
        }
        None
    }

    fn is_prn_metadata_header_token(token: &str) -> bool {
        token.eq_ignore_ascii_case("index") || token.eq_ignore_ascii_case("stepnum")
    }

    fn reference_columns_are_compact_probe_table(reference: &XycePrnTable) -> bool {
        reference
            .columns
            .first()
            .is_some_and(|column| Self::looks_like_reference_probe_header(column))
    }

    fn looks_like_reference_probe_header(token: &str) -> bool {
        let normalized = Self::normalize_probe(token);
        normalized == "temp"
            || normalized == "time"
            || normalized == "freq"
            || normalized == "frequency"
            || normalized == "sweep"
            || normalized.starts_with("v(")
            || normalized.starts_with("i(")
            || normalized.starts_with("n(")
            || Self::compact_reference_probe_alias(&normalized).is_some()
    }

    fn split_prn_fields(
        line: &str,
        delimiter: XycePrnDelimiter,
    ) -> Box<dyn Iterator<Item = &str> + '_> {
        match delimiter {
            XycePrnDelimiter::Whitespace => Box::new(line.split_whitespace()),
            XycePrnDelimiter::Comma => Box::new(line.split(',').map(str::trim)),
        }
    }

    fn same_prn_columns(left: &[String], right: &[String]) -> bool {
        left.len() == right.len()
            && left
                .iter()
                .zip(right.iter())
                .all(|(left, right)| left.eq_ignore_ascii_case(right))
    }

    fn is_prn_separator_line(line: &str) -> bool {
        line.chars()
            .all(|ch| ch == '-' || ch == '=' || ch.is_whitespace())
    }

    fn is_prn_footer_line(line: &str) -> bool {
        let normalized = line.to_ascii_lowercase();
        normalized.starts_with("cpu time")
            || normalized.starts_with("total cpu time")
            || normalized.starts_with("current dynamic memory usage")
            || normalized.starts_with("dynamic memory limit")
    }

    fn static_prn_reference_path(&self, deck_path: &Path) -> Option<PathBuf> {
        self.static_output_reference_path(deck_path, "prn")
    }

    fn measurement_reference_paths(
        &self,
        deck_path: &Path,
        analysis_prefix: &str,
    ) -> Result<Vec<PathBuf>, String> {
        let first = self
            .static_output_reference_path(deck_path, &format!("{analysis_prefix}0"))
            .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
        let Some(parent) = first.parent() else {
            return Err("measurement artifact path has no parent directory".to_string());
        };
        if !parent.is_dir() {
            return Ok(Vec::new());
        }
        let deck_name = deck_path
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or_else(|| "deck filename is not valid UTF-8".to_string())?;
        let file_prefix = format!("{deck_name}.{analysis_prefix}");
        let mut indexed = BTreeMap::new();
        for entry in fs::read_dir(parent)
            .map_err(|err| format!("failed to scan {}: {err}", parent.display()))?
        {
            let entry =
                entry.map_err(|err| format!("failed to scan {}: {err}", parent.display()))?;
            let name = entry.file_name();
            let Some(name) = name.to_str() else {
                continue;
            };
            let Some(raw_index) = name.strip_prefix(&file_prefix) else {
                continue;
            };
            if raw_index.is_empty() || !raw_index.chars().all(|ch| ch.is_ascii_digit()) {
                continue;
            }
            let index = raw_index.parse::<usize>().map_err(|err| {
                format!("measurement artifact index '{raw_index}' is invalid: {err}")
            })?;
            if indexed.insert(index, entry.path()).is_some() {
                return Err(format!(
                    "duplicate measurement artifact index {index} for {}",
                    deck_path.display()
                ));
            }
        }
        for (expected, actual) in indexed.keys().copied().enumerate() {
            if expected != actual {
                return Err(format!(
                    "measurement artifacts for {} are not contiguous: expected index {expected}, found {actual}",
                    deck_path.display()
                ));
            }
        }
        Ok(indexed.into_values().collect())
    }

    fn continuous_measurement_reference_paths(
        &self,
        deck_path: &Path,
        netlist: &Netlist,
        analysis: &str,
        artifact_prefix: &str,
    ) -> Result<Vec<PathBuf>, String> {
        let declarations = netlist
            .measurements
            .iter()
            .filter(|measurement| {
                measurement.analysis.eq_ignore_ascii_case(analysis)
                    && measurement.print_policy == crate::analysis::MeasurePrintPolicy::All
            })
            .collect::<Vec<_>>();
        if declarations.is_empty() {
            return Ok(Vec::new());
        }

        let output_directory = self
            .static_output_reference_path(deck_path, &format!("{artifact_prefix}0"))
            .and_then(|path| path.parent().map(Path::to_path_buf))
            .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
        let deck_name = deck_path
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or_else(|| "deck filename is not valid UTF-8".to_string())?;
        let prefix = format!("{deck_name}_");
        let suffix = format!(".{artifact_prefix}0");
        let mut available = BTreeMap::<String, PathBuf>::new();
        if output_directory.is_dir() {
            for entry in fs::read_dir(&output_directory)
                .map_err(|err| format!("failed to scan {}: {err}", output_directory.display()))?
            {
                let entry = entry.map_err(|err| {
                    format!("failed to scan {}: {err}", output_directory.display())
                })?;
                let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                    continue;
                };
                let Some(raw_measurement) = file_name
                    .strip_prefix(&prefix)
                    .and_then(|name| name.strip_suffix(&suffix))
                else {
                    continue;
                };
                if raw_measurement.is_empty() {
                    return Err(format!(
                        "continuous measurement artifact '{}' has an empty measurement name",
                        entry.path().display()
                    ));
                }
                let normalized = raw_measurement.to_ascii_uppercase();
                if available.insert(normalized.clone(), entry.path()).is_some() {
                    return Err(format!(
                        "duplicate continuous measurement artifact for '{normalized}'"
                    ));
                }
            }
        }

        let mut paths = Vec::with_capacity(declarations.len());
        for declaration in declarations {
            let normalized = declaration.name.to_ascii_uppercase();
            let path = available.remove(&normalized).ok_or_else(|| {
                format!(
                    "{analysis} measurement '{}' has no checked-in sidecar artifact",
                    declaration.name,
                )
            })?;
            paths.push(path);
        }
        if !available.is_empty() {
            return Err(format!(
                "unclaimed continuous measurement sidecar artifact(s): {}",
                available
                    .values()
                    .map(|path| path.display().to_string())
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
        Ok(paths)
    }

    fn tran_gsfile_reference_path(deck_path: &Path) -> Option<PathBuf> {
        let candidate = deck_path.with_extension("cir.GSfile");
        candidate.is_file().then_some(candidate)
    }

    fn static_output_reference_path(&self, deck_path: &Path, extension: &str) -> Option<PathBuf> {
        let netlists_root = self.root.join("Netlists");
        let canonical = deck_path
            .canonicalize()
            .unwrap_or_else(|_| deck_path.to_path_buf());
        let relative = canonical
            .strip_prefix(&netlists_root)
            .or_else(|_| deck_path.strip_prefix(&netlists_root))
            .ok()?;
        let parent = relative.parent().unwrap_or_else(|| Path::new(""));
        let file_name = relative.file_name()?.to_string_lossy();
        Some(
            self.root
                .join("OutputData")
                .join(parent)
                .join(format!("{file_name}.{extension}")),
        )
    }

    fn collect_circuit_files(dir: &Path, out: &mut Vec<PathBuf>) {
        let Ok(entries) = fs::read_dir(dir) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                Self::collect_circuit_files(&path, out);
            } else if path
                .extension()
                .and_then(|ext| ext.to_str())
                .is_some_and(|ext| ext.eq_ignore_ascii_case("cir"))
            {
                out.push(path);
            }
        }
    }

    fn section_for_relative_path(relative_path: &str) -> XyceDeckSection {
        if relative_path.starts_with("Netlists/") {
            XyceDeckSection::Netlists
        } else {
            XyceDeckSection::Other
        }
    }

    fn load_upstream_wrapper_decks(root: &Path) -> BTreeSet<String> {
        let manifest_path = root.join(HARNESS_MANIFEST_FILE);
        let Ok(content) = fs::read_to_string(manifest_path) else {
            return BTreeSet::new();
        };

        let mut decks = BTreeSet::new();
        for raw_line in content.lines() {
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let Some((path, contract)) = line.split_once('\t') else {
                continue;
            };
            if contract.trim() == REQUIRES_UPSTREAM_WRAPPER_CONTRACT {
                decks.insert(Self::normalize_manifest_key(path));
            }
        }
        decks
    }

    fn subckt_parameter_resolution_family_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<XyceSubcktParameterResolutionFamilyContract> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/certification_tests/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let mut anchor_path = None;
        let mut records = Vec::<(
            PathBuf,
            XyceSubcktParameterResolutionRepresentation,
            XyceStaticDcPlan,
            Option<XyceSubcktParameterResolutionSnapshot>,
            String,
        )>::new();
        let mut all_paths = Vec::new();
        for entry in fs::read_dir(parent).ok()? {
            let entry = entry.ok()?;
            let path = entry.path();
            if !path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
            {
                continue;
            }
            if !entry.file_type().ok()?.is_file()
                || self
                    .static_prn_reference_path(&path)
                    .is_some_and(|reference| reference.is_file())
            {
                return None;
            }
            all_paths.push(path.clone());
            let member_relative = self.relative_key(&path);
            let wrapper = self.requires_upstream_wrapper(&member_relative);
            if fs::metadata(&path).ok()?.len() == 0 {
                if !wrapper || anchor_path.replace(path).is_some() {
                    return None;
                }
                continue;
            }
            let source = fs::read_to_string(&path).ok()?;
            Self::validate_subckt_parameter_resolution_source_directives(&source).ok()?;
            let plan = self
                .static_dc_plan_for_path(&path, ExpressionDialect::Xyce)
                .ok()?;
            Self::validate_subckt_parameter_resolution_dc_plan(&plan).ok()?;
            let netlist = Self::parse_xyce_netlist(&plan.source, &path).ok()?;
            let (representation, parameter_name, snapshot) =
                Self::subckt_parameter_resolution_qualification(
                    &netlist,
                    &plan.print,
                    &plan.dc.source,
                )
                .ok()?;
            if wrapper
                != (representation == XyceSubcktParameterResolutionRepresentation::UndefinedBinding)
            {
                return None;
            }
            records.push((path, representation, plan, snapshot, parameter_name));
        }
        let anchor_path = anchor_path?;
        if all_paths.len() != records.len() + 1 || records.len() != 6 {
            return None;
        }

        let mut representation_counts = BTreeMap::new();
        let parameter_names = records
            .iter()
            .map(|(_, _, _, _, name)| name.to_ascii_lowercase())
            .collect::<BTreeSet<_>>();
        for (_, representation, _, _, _) in &records {
            *representation_counts.entry(*representation).or_default() += 1usize;
        }
        let required = [
            XyceSubcktParameterResolutionRepresentation::FormalDefaultAndInstanceOverride,
            XyceSubcktParameterResolutionRepresentation::ImplicitInstanceBinding,
            XyceSubcktParameterResolutionRepresentation::GlobalBinding,
            XyceSubcktParameterResolutionRepresentation::InstanceOverridesGlobal,
            XyceSubcktParameterResolutionRepresentation::UnusedInstanceBinding,
            XyceSubcktParameterResolutionRepresentation::UndefinedBinding,
        ];
        if parameter_names.len() != 1
            || required.iter().any(|representation| {
                representation_counts
                    .get(representation)
                    .copied()
                    .unwrap_or(0)
                    != 1
            })
        {
            return None;
        }

        let baseline_record = records.iter().find(|(_, representation, _, _, _)| {
            *representation
                == XyceSubcktParameterResolutionRepresentation::FormalDefaultAndInstanceOverride
        })?;
        let baseline_snapshot = baseline_record.3.as_ref()?;
        for (_, representation, plan, snapshot, _) in &records {
            if plan.print.probes != baseline_record.2.print.probes
                || !Self::dc_sweeps_match_exactly(&baseline_record.2.dc, &plan.dc)
            {
                return None;
            }
            if *representation == XyceSubcktParameterResolutionRepresentation::UndefinedBinding {
                if snapshot.is_some() {
                    return None;
                }
            } else if snapshot
                .as_ref()
                .map(|snapshot| &snapshot.flattened_elements)
                != Some(&baseline_snapshot.flattened_elements)
            {
                return None;
            }
        }

        let baseline_path = baseline_record.0.clone();
        let error_path = records
            .iter()
            .find(|(_, representation, _, _, _)| {
                *representation == XyceSubcktParameterResolutionRepresentation::UndefinedBinding
            })?
            .0
            .clone();
        if !all_paths
            .iter()
            .any(|path| Self::same_path(path, &deck.path))
        {
            return None;
        }
        let role = if Self::same_path(&deck.path, &anchor_path) {
            XyceSubcktParameterResolutionRole::Anchor
        } else if Self::same_path(&deck.path, &error_path) {
            XyceSubcktParameterResolutionRole::ExpectedError
        } else if Self::same_path(&deck.path, &baseline_path) {
            XyceSubcktParameterResolutionRole::Baseline
        } else {
            XyceSubcktParameterResolutionRole::Member
        };
        let valid_paths = records
            .into_iter()
            .filter_map(|(path, representation, _, _, _)| {
                (representation != XyceSubcktParameterResolutionRepresentation::UndefinedBinding)
                    .then_some(path)
            })
            .collect::<Vec<_>>();
        Some(XyceSubcktParameterResolutionFamilyContract {
            family: parent.file_name()?.to_str()?.to_string(),
            anchor_path,
            error_path,
            baseline_path,
            valid_paths,
            role,
            target_path: deck.path.clone(),
        })
    }

    fn baseline_family_contract(&self, deck: &XyceDeck) -> Option<XyceBaselineFamilyContract> {
        self.ac_analysis_expression_family_contract(deck)
            .or_else(|| self.bjt_external_node_family_contract(deck))
            .or_else(|| self.delimited_expression_family_contract(deck))
            .or_else(|| self.dc_analysis_expression_family_contract(deck))
            .or_else(|| self.sin_expression_family_contract(deck))
            .or_else(|| self.param_expression_family_contract(deck))
            .or_else(|| self.passive_temperature_override_family_contract(deck))
            .or_else(|| self.transient_analysis_expression_family_contract(deck))
            .or_else(|| self.subckt_parameter_precedence_family_contract(deck))
            .or_else(|| self.scoped_model_family_contract(deck))
            .or_else(|| self.subckt_family_contract(deck))
            .or_else(|| self.supernode_family_contract(deck))
    }

    fn validate_nested_include_identity_dc_plan(plan: &XyceStaticDcPlan) -> Result<(), String> {
        if plan.execution_dir.is_some()
            || plan.print_format.is_some()
            || plan.dc_data.is_some()
            || !plan.steps.is_empty()
            || !plan.diagnostics.is_empty()
            || plan.dc.sweep2.is_some()
            || !matches!(plan.dc.mode, crate::netlist::DcSweepMode::Linear)
        {
            return Err("nested-include identity requires one diagnostic-free, one-dimensional linear .DC analysis with ordinary default PRN output".to_string());
        }
        let points = plan.dc.primary_spec().points();
        if points.len() != 3
            || points.iter().any(|point| !point.is_finite())
            || !plan.dc.start.is_finite()
            || !plan.dc.stop.is_finite()
            || !plan.dc.step.is_finite()
            || plan.dc.step == 0.0
            || plan.print.probes.len() != 2
        {
            return Err("nested-include identity requires one finite three-point linear sweep and exactly two ordered DC probes".to_string());
        }
        for line in Self::logical_netlist_lines(&plan.source) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            if stripped.is_empty() {
                continue;
            }
            let head = stripped.split_whitespace().next().unwrap_or("");
            if !(head.eq_ignore_ascii_case(".subckt")
                || head.eq_ignore_ascii_case(".ends")
                || head.eq_ignore_ascii_case(".include")
                || head.eq_ignore_ascii_case(".inc")
                || head.eq_ignore_ascii_case(".incl")
                || head.eq_ignore_ascii_case(".dc")
                || head.eq_ignore_ascii_case(".print")
                || head.eq_ignore_ascii_case(".end")
                || matches!(
                    head.chars().next().map(|ch| ch.to_ascii_uppercase()),
                    Some('R' | 'V' | 'X')
                ))
            {
                return Err(format!(
                    "nested-include identity does not admit source statement '{stripped}'"
                ));
            }
        }
        Ok(())
    }

    fn nested_include_identity_family_snapshot(
        netlist: &Netlist,
        plan: &XyceStaticDcPlan,
    ) -> Result<XyceNestedIncludeIdentityFamilySnapshot, String> {
        if !netlist.models.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
            || netlist.subcircuits.len() != 4
            || netlist.elements.len() != 3
        {
            return Err("nested-include identity requires a diagnostic-free two-parent/two-local-subcircuit R/V circuit without auxiliary state".to_string());
        }

        let mut definition_names = BTreeSet::new();
        for subcircuit in &netlist.subcircuits {
            if !definition_names.insert(subcircuit.name.to_ascii_lowercase()) {
                return Err(format!(
                    "duplicate fully-qualified subcircuit definition '{}'",
                    subcircuit.name
                ));
            }
        }
        let parents = netlist
            .subcircuits
            .iter()
            .filter(|subcircuit| !subcircuit.nested_subcircuits.is_empty())
            .collect::<Vec<_>>();
        let leaves = netlist
            .subcircuits
            .iter()
            .filter(|subcircuit| subcircuit.nested_subcircuits.is_empty())
            .collect::<Vec<_>>();
        if parents.len() != 2 || leaves.len() != 2 {
            return Err("nested-include identity requires exactly two parent and two qualified local definitions".to_string());
        }

        let mut hierarchy = Vec::new();
        let mut local_names = BTreeSet::new();
        for parent in &parents {
            Self::validate_nested_include_subcircuit_auxiliary_state(parent)?;
            let [nested] = parent.nested_subcircuits.as_slice() else {
                return Err(format!(
                    "parent subcircuit '{}' must own exactly one local definition",
                    parent.name
                ));
            };
            Self::validate_nested_include_subcircuit_auxiliary_state(nested)?;
            let expected_prefix = format!("{}.", parent.name);
            let local_name = nested.name.strip_prefix(&expected_prefix).ok_or_else(|| {
                format!(
                    "local definition '{}' is not qualified beneath parent '{}'",
                    nested.name, parent.name
                )
            })?;
            if local_name.is_empty() || local_name.contains('.') {
                return Err(format!(
                    "local definition '{}' has a non-local qualified suffix",
                    nested.name
                ));
            }
            local_names.insert(local_name.to_ascii_lowercase());
            if !leaves
                .iter()
                .any(|candidate| candidate.name.eq_ignore_ascii_case(&nested.name))
            {
                return Err(format!(
                    "parent '{}' local definition '{}' is absent from the executable definition table",
                    parent.name, nested.name
                ));
            }
            if parent.ports.len() != 2 || nested.ports.len() != 2 || nested.elements.len() != 1 {
                return Err("nested-include parent and local definitions must be two-terminal series-resistor blocks".to_string());
            }
            let nested_resistor = &nested.elements[0];
            Self::strict_nested_include_resistor_fingerprint(nested_resistor)?;
            if nested_resistor.nodes.len() != 2
                || !nested_resistor.nodes[0].eq_ignore_ascii_case(&nested.ports[0])
                || !nested_resistor.nodes[1].eq_ignore_ascii_case(&nested.ports[1])
            {
                return Err(format!(
                    "local definition '{}' must connect one direct resistor across its ordered ports",
                    nested.name
                ));
            }

            let mut child = None;
            let mut resistor = None;
            for element in &parent.elements {
                match &element.kind {
                    ElementKind::Subcircuit {
                        subckt_name,
                        params,
                    } if params.is_empty()
                        && subckt_name.eq_ignore_ascii_case(&nested.name)
                        && element.nodes.len() == 2 =>
                    {
                        if child.replace(element).is_some() {
                            return Err(format!(
                                "parent '{}' has multiple local subcircuit instances",
                                parent.name
                            ));
                        }
                    }
                    ElementKind::Resistor { .. } => {
                        Self::strict_nested_include_resistor_fingerprint(element)?;
                        if resistor.replace(element).is_some() {
                            return Err(format!(
                                "parent '{}' has multiple direct resistors",
                                parent.name
                            ));
                        }
                    }
                    _ => {
                        return Err(format!(
                            "parent '{}' contains unqualified element '{}'",
                            parent.name, element.name
                        ));
                    }
                }
            }
            let child = child.ok_or_else(|| {
                format!(
                    "parent '{}' does not bind its local definition",
                    parent.name
                )
            })?;
            let resistor = resistor
                .ok_or_else(|| format!("parent '{}' has no direct series resistor", parent.name))?;
            let internal = child
                .nodes
                .iter()
                .find(|node| {
                    !parent
                        .ports
                        .iter()
                        .any(|port| port.eq_ignore_ascii_case(node))
                })
                .ok_or_else(|| format!("parent '{}' has no private series node", parent.name))?;
            if child
                .nodes
                .iter()
                .filter(|node| node.eq_ignore_ascii_case(internal))
                .count()
                != 1
                || resistor
                    .nodes
                    .iter()
                    .filter(|node| node.eq_ignore_ascii_case(internal))
                    .count()
                    != 1
                || !parent.ports.iter().all(|port| {
                    child
                        .nodes
                        .iter()
                        .any(|node| node.eq_ignore_ascii_case(port))
                        || resistor
                            .nodes
                            .iter()
                            .any(|node| node.eq_ignore_ascii_case(port))
                })
            {
                return Err(format!(
                    "parent '{}' does not form a simple local-block/resistor series path",
                    parent.name
                ));
            }

            hierarchy.push(Self::nested_include_subcircuit_fingerprint(parent)?);
            hierarchy.push(Self::nested_include_subcircuit_fingerprint(nested)?);
        }
        if local_names.len() != 1 {
            return Err(
                "qualified local definitions do not share one lexical local name".to_string(),
            );
        }
        hierarchy.sort();

        let mut voltage_source = None;
        let mut top_instances = Vec::new();
        for element in &netlist.elements {
            match &element.kind {
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value))
                    if value.is_finite() && element.nodes.len() == 2 =>
                {
                    if voltage_source.replace(element).is_some() {
                        return Err(
                            "nested-include identity contains multiple voltage sources".to_string()
                        );
                    }
                }
                ElementKind::Subcircuit {
                    subckt_name,
                    params,
                } if params.is_empty()
                    && element.nodes.len() == 2
                    && parents
                        .iter()
                        .any(|parent| parent.name.eq_ignore_ascii_case(subckt_name)) =>
                {
                    top_instances.push(element);
                }
                _ => {
                    return Err(format!(
                        "nested-include top level contains unqualified element '{}'",
                        element.name
                    ));
                }
            }
        }
        let source = voltage_source.ok_or_else(|| {
            "nested-include identity requires one finite DC voltage source".to_string()
        })?;
        let instantiated_parents = top_instances
            .iter()
            .filter_map(|instance| match &instance.kind {
                ElementKind::Subcircuit { subckt_name, .. } => {
                    Some(subckt_name.to_ascii_lowercase())
                }
                _ => None,
            })
            .collect::<BTreeSet<_>>();
        if top_instances.len() != 2
            || instantiated_parents.len() != 2
            || parents
                .iter()
                .any(|parent| !instantiated_parents.contains(&parent.name.to_ascii_lowercase()))
            || !source.name.eq_ignore_ascii_case(&plan.dc.source)
        {
            return Err("nested-include identity requires two parent instances swept by its sole voltage source".to_string());
        }
        let source_ground = source
            .nodes
            .iter()
            .position(|node| Self::node_name_is_ground(node))
            .ok_or_else(|| "nested-include source must have one grounded terminal".to_string())?;
        if source
            .nodes
            .iter()
            .filter(|node| Self::node_name_is_ground(node))
            .count()
            != 1
        {
            return Err(
                "nested-include source must have exactly one grounded terminal".to_string(),
            );
        }
        let driven = source.nodes[1 - source_ground].to_ascii_lowercase();
        let mut degree = BTreeMap::<String, usize>::new();
        for instance in &top_instances {
            for node in &instance.nodes {
                *degree.entry(node.to_ascii_lowercase()).or_default() += 1;
            }
        }
        let ground = degree
            .keys()
            .find(|node| Self::node_name_is_ground(node))
            .cloned()
            .ok_or_else(|| "parent instance chain is not grounded".to_string())?;
        let middle = degree
            .iter()
            .find_map(|(node, count)| (*count == 2).then_some(node.clone()))
            .ok_or_else(|| "parent instances do not form a two-block series chain".to_string())?;
        if degree.len() != 3
            || degree.get(&driven) != Some(&1)
            || degree.get(&ground) != Some(&1)
            || degree.get(&middle) != Some(&2)
        {
            return Err(
                "parent instances do not connect the driven node through one shared node to ground"
                    .to_string(),
            );
        }
        let probes = plan
            .print
            .probes
            .iter()
            .map(|probe| Self::normalize_probe(probe))
            .collect::<Vec<_>>();
        if probes
            != [
                format!("v({middle})"),
                format!("i({})", source.name.to_ascii_lowercase()),
            ]
        {
            return Err("nested-include identity requires ordered shared-node voltage and swept-source current probes".to_string());
        }

        let flattened = crate::netlist::flatten_netlist_with_models(netlist)
            .map_err(|err| format!("nested-include hierarchy did not flatten: {err}"))?;
        if !flattened.scoped_models.is_empty()
            || !flattened.scoped_initial_conditions.is_empty()
            || !flattened.scoped_node_sets.is_empty()
            || flattened.elements.len() != 5
        {
            return Err(
                "nested-include flattening produced unexpected scoped or element state".to_string(),
            );
        }
        let mut flattened_elements = BTreeMap::new();
        for element in &flattened.elements {
            let fingerprint = match &element.kind {
                ElementKind::Resistor { .. } => {
                    Self::strict_nested_include_resistor_fingerprint(element)?
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value))
                    if value.is_finite() && element.nodes.len() == 2 =>
                {
                    XyceRelationalElementFingerprint {
                        kind: "V:DC".to_string(),
                        nodes: element
                            .nodes
                            .iter()
                            .map(|node| node.to_ascii_lowercase())
                            .collect(),
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                _ => {
                    return Err(format!(
                        "flattened nested-include circuit contains unqualified element '{}'",
                        element.name
                    ));
                }
            };
            if flattened_elements
                .insert(element.name.to_ascii_lowercase(), fingerprint)
                .is_some()
            {
                return Err(format!(
                    "flattened nested-include circuit has duplicate element '{}'",
                    element.name
                ));
            }
        }
        Ok(XyceNestedIncludeIdentityFamilySnapshot {
            title: netlist.title.trim().to_string(),
            hierarchy,
            flattened_elements,
        })
    }

    fn validate_nested_include_subcircuit_auxiliary_state(
        subcircuit: &SubcircuitDef,
    ) -> Result<(), String> {
        if !subcircuit.initial_conditions.is_empty()
            || !subcircuit.node_sets.is_empty()
            || !subcircuit.params.is_empty()
            || !subcircuit.expr_params.is_empty()
            || !subcircuit.string_params.is_empty()
            || !subcircuit.body_params.is_empty()
            || !subcircuit.body_expr_params.is_empty()
            || !subcircuit.body_string_params.is_empty()
            || !subcircuit.body_functions.is_empty()
            || !subcircuit.local_options.is_empty()
            || subcircuit.library_ref.is_some()
        {
            return Err(format!(
                "subcircuit '{}' contains auxiliary scoped state",
                subcircuit.name
            ));
        }
        Ok(())
    }

    fn strict_nested_include_resistor_fingerprint(
        element: &crate::netlist::Element,
    ) -> Result<XyceRelationalElementFingerprint, String> {
        let ElementKind::Resistor {
            value,
            value_expr,
            model,
            instance_params,
            deferred_params,
        } = &element.kind
        else {
            return Err(format!("element '{}' is not a resistor", element.name));
        };
        if element.nodes.len() != 2
            || !value.is_finite()
            || *value <= 0.0
            || value_expr.is_some()
            || model.is_some()
            || !instance_params.is_empty()
            || !deferred_params.is_empty()
        {
            return Err(format!(
                "resistor '{}' is not one direct finite positive two-terminal resistor",
                element.name
            ));
        }
        Ok(XyceRelationalElementFingerprint {
            kind: "R".to_string(),
            nodes: element
                .nodes
                .iter()
                .map(|node| node.to_ascii_lowercase())
                .collect(),
            numeric_bits: vec![value.to_bits()],
            text: Vec::new(),
        })
    }

    fn nested_include_subcircuit_fingerprint(
        subcircuit: &SubcircuitDef,
    ) -> Result<XyceNestedIncludeSubcircuitFingerprint, String> {
        let mut elements = BTreeMap::new();
        for element in &subcircuit.elements {
            let fingerprint = match &element.kind {
                ElementKind::Resistor { .. } => {
                    Self::strict_nested_include_resistor_fingerprint(element)?
                }
                ElementKind::Subcircuit {
                    subckt_name,
                    params,
                } if params.is_empty() && element.nodes.len() == 2 => {
                    XyceRelationalElementFingerprint {
                        kind: "X".to_string(),
                        nodes: element
                            .nodes
                            .iter()
                            .map(|node| node.to_ascii_lowercase())
                            .collect(),
                        numeric_bits: Vec::new(),
                        text: vec![subckt_name.to_ascii_lowercase()],
                    }
                }
                _ => {
                    return Err(format!(
                        "subcircuit '{}' contains unqualified element '{}'",
                        subcircuit.name, element.name
                    ));
                }
            };
            if elements
                .insert(element.name.to_ascii_lowercase(), fingerprint)
                .is_some()
            {
                return Err(format!(
                    "subcircuit '{}' contains duplicate element '{}'",
                    subcircuit.name, element.name
                ));
            }
        }
        let mut nested_names = subcircuit
            .nested_subcircuits
            .iter()
            .map(|nested| nested.name.to_ascii_lowercase())
            .collect::<Vec<_>>();
        nested_names.sort();
        Ok(XyceNestedIncludeSubcircuitFingerprint {
            name: subcircuit.name.to_ascii_lowercase(),
            ports: subcircuit
                .ports
                .iter()
                .map(|port| port.to_ascii_lowercase())
                .collect(),
            elements,
            nested_names,
        })
    }

    fn nested_include_identity_family_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<XyceNestedIncludeIdentityFamilyContract> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/certification_tests/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let entries = fs::read_dir(parent)
            .ok()?
            .collect::<Result<Vec<_>, _>>()
            .ok()?;
        if entries.iter().any(|entry| {
            entry
                .file_type()
                .map_or(true, |file_type| !file_type.is_file())
        }) {
            return None;
        }
        let circuit_paths = entries
            .iter()
            .map(|entry| entry.path())
            .filter(|path| {
                path.extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
            })
            .collect::<Vec<_>>();
        if circuit_paths.len() != 3
            || !circuit_paths
                .iter()
                .any(|path| Self::same_path(path, &deck.path))
        {
            return None;
        }

        let mut anchor = None;
        let mut workers = Vec::new();
        for path in &circuit_paths {
            let source = fs::read_to_string(path).ok()?;
            let wrapper = self.requires_upstream_wrapper(&self.relative_key(path));
            if source.is_empty() {
                if !wrapper || anchor.replace(path.clone()).is_some() {
                    return None;
                }
                continue;
            }
            if wrapper {
                return None;
            }
            let provenance = Self::nested_include_identity_provenance(&source, path).ok()?;
            let plan = self
                .static_dc_plan_for_path(path, ExpressionDialect::Xyce)
                .ok()?;
            Self::validate_nested_include_identity_dc_plan(&plan).ok()?;
            let netlist = Self::parse_xyce_netlist(&plan.source, path).ok()?;
            let snapshot = Self::nested_include_identity_family_snapshot(&netlist, &plan).ok()?;
            workers.push((path.clone(), provenance, plan, snapshot));
        }
        let anchor = anchor?;
        if workers.len() != 2 {
            return None;
        }
        let repeated = workers.iter().find(|(_, provenance, _, _)| {
            provenance.representation
                == XyceNestedIncludeIdentityRepresentation::RepeatedCanonicalTarget
        })?;
        let split = workers.iter().find(|(_, provenance, _, _)| {
            provenance.representation
                == XyceNestedIncludeIdentityRepresentation::SplitIdenticalTargets
        })?;
        if Self::same_path(&repeated.0, &split.0)
            || repeated.1.canonical_source != split.1.canonical_source
            || repeated.1.expanded_source != split.1.expanded_source
            || repeated.2.print.probes != split.2.print.probes
            || !Self::dc_sweeps_match_exactly(&repeated.2.dc, &split.2.dc)
            || repeated.3 != split.3
        {
            return None;
        }
        let all_support_paths = repeated
            .1
            .support_paths
            .union(&split.1.support_paths)
            .cloned()
            .collect::<BTreeSet<_>>();
        if all_support_paths.len() != 2
            || repeated.1.support_paths.len() != 1
            || split.1.support_paths.len() != 2
        {
            return None;
        }
        let expected_paths = circuit_paths
            .iter()
            .cloned()
            .chain(all_support_paths.iter().cloned())
            .map(|path| path.canonicalize().unwrap_or(path))
            .collect::<BTreeSet<_>>();
        let actual_paths = entries
            .iter()
            .map(|entry| {
                let path = entry.path();
                path.canonicalize().unwrap_or(path)
            })
            .collect::<BTreeSet<_>>();
        if actual_paths != expected_paths {
            return None;
        }

        let artifact_dir = self
            .static_output_reference_path(&repeated.0, "artifact")?
            .parent()?
            .to_path_buf();
        if artifact_dir.try_exists().ok()? {
            if !fs::metadata(&artifact_dir).ok()?.is_dir()
                || fs::read_dir(&artifact_dir).ok()?.next().is_some()
            {
                return None;
            }
        }

        let role = if Self::same_path(&deck.path, &anchor) {
            XyceNestedIncludeIdentityFamilyRole::Anchor
        } else if Self::same_path(&deck.path, &repeated.0) {
            XyceNestedIncludeIdentityFamilyRole::RepeatedTargetBaseline
        } else if Self::same_path(&deck.path, &split.0) {
            XyceNestedIncludeIdentityFamilyRole::SplitIdenticalTargetsMember
        } else {
            return None;
        };
        let target_path = match role {
            XyceNestedIncludeIdentityFamilyRole::Anchor => None,
            XyceNestedIncludeIdentityFamilyRole::RepeatedTargetBaseline => Some(repeated.0.clone()),
            XyceNestedIncludeIdentityFamilyRole::SplitIdenticalTargetsMember => {
                Some(split.0.clone())
            }
        };
        Some(XyceNestedIncludeIdentityFamilyContract {
            relational: XyceBaselineFamilyContract {
                kind: XyceBaselineFamilyKind::NestedIncludeIdentity,
                comparison: XyceBaselineFamilyComparison::ExactPrn,
                family: parent.file_name()?.to_str()?.to_string(),
                baseline_path: repeated.0.clone(),
                member_paths: vec![repeated.0.clone(), split.0.clone()],
                target_path,
            },
            role,
        })
    }

    fn nested_include_identity_provenance(
        source: &str,
        deck_path: &Path,
    ) -> Result<XyceNestedIncludeProvenance, String> {
        let parent_dir = deck_path
            .parent()
            .ok_or_else(|| "nested-include deck has no parent directory".to_string())?;
        let canonical_parent = parent_dir
            .canonicalize()
            .unwrap_or_else(|_| parent_dir.to_path_buf());
        let (canonical_source, occurrences) =
            Self::nested_include_identity_raw_provenance(source, parent_dir, &canonical_parent)?;
        let support_paths = occurrences
            .iter()
            .map(|(_, path)| path.clone())
            .collect::<BTreeSet<_>>();
        let representation = match support_paths.len() {
            1 => XyceNestedIncludeIdentityRepresentation::RepeatedCanonicalTarget,
            2 => XyceNestedIncludeIdentityRepresentation::SplitIdenticalTargets,
            _ => return Err("include target identity is ambiguous".to_string()),
        };
        let mut support_source = None::<String>;
        for path in &support_paths {
            let content = fs::read_to_string(path).map_err(|err| {
                format!("failed to read support source {}: {err}", path.display())
            })?;
            Self::validate_nested_include_support_source(&content)?;
            if support_source
                .as_ref()
                .is_some_and(|expected| expected != &content)
            {
                return Err("split include targets are not byte-identical".to_string());
            }
            support_source = Some(content);
        }
        let expanded_source = Netlist::preprocess_includes(source, deck_path)
            .map_err(|err| format!("include expansion failed: {err}"))?;
        Ok(XyceNestedIncludeProvenance {
            representation,
            canonical_source,
            expanded_source,
            support_paths,
        })
    }

    fn nested_include_identity_raw_provenance(
        source: &str,
        parent_dir: &Path,
        canonical_parent: &Path,
    ) -> Result<(String, Vec<(String, PathBuf)>), String> {
        const INCLUDE_SENTINEL: &str = "<RSPICE_NESTED_INCLUDE_TARGET>";

        let mut open_parent = None::<String>;
        let mut parent_names = BTreeSet::new();
        let mut subckt_count = 0usize;
        let mut ends_count = 0usize;
        let mut dc_count = 0usize;
        let mut print_count = 0usize;
        let mut end_count = 0usize;
        let mut occurrences = Vec::<(String, PathBuf)>::new();
        let mut operand_spans = Vec::<(usize, usize)>::new();
        let mut source_offset = 0usize;

        for physical_line in source.split_inclusive('\n') {
            let line_start = source_offset;
            source_offset += physical_line.len();
            let line = physical_line.strip_suffix('\n').unwrap_or(physical_line);
            let line = line.strip_suffix('\r').unwrap_or(line);
            let uncommented = line.split_once(';').map_or(line, |(head, _)| head);
            let stripped = uncommented.trim();
            if stripped.is_empty() || stripped.starts_with('*') || stripped.starts_with("//") {
                continue;
            }
            let tokens = stripped.split_whitespace().collect::<Vec<_>>();
            let head = tokens.first().copied().unwrap_or("");
            if head.eq_ignore_ascii_case(".subckt") {
                subckt_count += 1;
                if open_parent.is_some() {
                    return Err("worker source contains a lexically nested .SUBCKT before include expansion".to_string());
                }
                let name = tokens
                    .get(1)
                    .ok_or_else(|| ".SUBCKT has no name".to_string())?
                    .to_ascii_lowercase();
                if !parent_names.insert(name.clone()) {
                    return Err(format!(
                        "duplicate top-level subcircuit definition '{name}'"
                    ));
                }
                open_parent = Some(name);
                continue;
            }
            if head.eq_ignore_ascii_case(".ends") {
                ends_count += 1;
                let owner = open_parent
                    .take()
                    .ok_or_else(|| ".ENDS appears outside a parent subcircuit".to_string())?;
                if tokens.len() > 2
                    || tokens
                        .get(1)
                        .is_some_and(|name| !name.eq_ignore_ascii_case(&owner))
                {
                    return Err(format!(
                        ".ENDS does not close its lexical parent subcircuit '{owner}'"
                    ));
                }
                continue;
            }
            if head.eq_ignore_ascii_case(".lib") || head.eq_ignore_ascii_case(".endl") {
                return Err("nested-include identity does not admit .LIB sections".to_string());
            }
            if matches!(
                head.to_ascii_lowercase().as_str(),
                ".include" | ".inc" | ".incl"
            ) {
                let owner = open_parent.clone().ok_or_else(|| {
                    "nested-include identity requires every include inside a parent subcircuit"
                        .to_string()
                })?;
                let (requested, operand_start, operand_end) =
                    Self::nested_include_identity_operand_span(line)?;
                let relative = crate::netlist::source_path_literal_to_host_path(&requested);
                if requested.contains(['/', '\\'])
                    || requested == "."
                    || requested == ".."
                    || relative.is_absolute()
                    || relative.components().count() != 1
                {
                    return Err(
                        "nested-include identity requires one bare local include filename"
                            .to_string(),
                    );
                }
                let target = parent_dir.join(relative);
                let canonical = target.canonicalize().map_err(|err| {
                    format!("could not resolve include '{}': {err}", target.display())
                })?;
                if canonical.parent() != Some(canonical_parent) || !canonical.is_file() {
                    return Err(format!(
                        "include target '{}' escapes the family directory or is not a file",
                        canonical.display()
                    ));
                }
                let exact_directory_name = fs::read_dir(parent_dir)
                    .map_err(|err| {
                        format!(
                            "could not inspect include directory '{}': {err}",
                            parent_dir.display()
                        )
                    })?
                    .filter_map(Result::ok)
                    .any(|entry| {
                        entry.file_name().to_str() == Some(requested.as_str())
                            && entry.path().canonicalize().ok().as_ref() == Some(&canonical)
                    });
                if !exact_directory_name {
                    return Err(
                        "nested-include operand does not exactly spell its directory entry"
                            .to_string(),
                    );
                }
                occurrences.push((owner, canonical));
                operand_spans.push((line_start + operand_start, line_start + operand_end));
                continue;
            }
            if head.eq_ignore_ascii_case(".dc") {
                if open_parent.is_some() {
                    return Err("nested-include .DC analysis must be top-level".to_string());
                }
                dc_count += 1;
                continue;
            }
            if head.eq_ignore_ascii_case(".print") {
                if open_parent.is_some() {
                    return Err("nested-include .PRINT directive must be top-level".to_string());
                }
                print_count += 1;
                if tokens.len() != 4
                    || !tokens
                        .get(1)
                        .is_some_and(|analysis| analysis.eq_ignore_ascii_case("dc"))
                    || tokens.iter().skip(2).any(|token| {
                        let option = token.to_ascii_lowercase();
                        option == "file"
                            || option.starts_with("file=")
                            || option == "format"
                            || option.starts_with("format=")
                            || option == "noindex"
                            || option.starts_with("noindex=")
                    })
                {
                    return Err("nested-include identity requires default-PRN .PRINT DC without FILE, FORMAT, NOINDEX, or side-output options".to_string());
                }
                continue;
            }
            if head.eq_ignore_ascii_case(".end") {
                if open_parent.is_some() || tokens.len() != 1 || line.contains(';') {
                    return Err(
                        "nested-include identity requires one exact top-level .END card"
                            .to_string(),
                    );
                }
                end_count += 1;
                if source_offset != source.len() {
                    return Err(
                        "nested-include identity does not admit content after .END".to_string()
                    );
                }
            }
        }

        let include_owners = occurrences
            .iter()
            .map(|(owner, _)| owner.clone())
            .collect::<BTreeSet<_>>();
        if open_parent.is_some()
            || subckt_count != 2
            || ends_count != 2
            || occurrences.len() != 2
            || include_owners != parent_names
            || dc_count != 1
            || print_count != 1
            || end_count != 1
        {
            return Err("nested-include identity requires exactly two matched parent .SUBCKT/.ENDS pairs with one include each, one .DC, one default .PRINT DC, and one terminal .END".to_string());
        }

        let mut canonical_source = source.to_string();
        for (start, end) in operand_spans.into_iter().rev() {
            canonical_source.replace_range(start..end, INCLUDE_SENTINEL);
        }
        Ok((canonical_source, occurrences))
    }

    fn nested_include_identity_operand_span(line: &str) -> Result<(String, usize, usize), String> {
        let statement_end = line.find(';').unwrap_or(line.len());
        let statement = &line[..statement_end];
        let bytes = statement.as_bytes();
        let mut cursor = 0usize;
        while bytes.get(cursor).is_some_and(u8::is_ascii_whitespace) {
            cursor += 1;
        }
        while bytes
            .get(cursor)
            .is_some_and(|byte| !byte.is_ascii_whitespace())
        {
            cursor += 1;
        }
        if !bytes.get(cursor).is_some_and(u8::is_ascii_whitespace) {
            return Err("include directive has no separated operand".to_string());
        }
        while bytes.get(cursor).is_some_and(u8::is_ascii_whitespace) {
            cursor += 1;
        }
        let operand_start = cursor;
        if bytes
            .get(cursor)
            .is_some_and(|byte| matches!(*byte, b'\'' | b'\"'))
        {
            return Err("nested-include identity requires an unquoted include operand".to_string());
        }
        while bytes
            .get(cursor)
            .is_some_and(|byte| !byte.is_ascii_whitespace())
        {
            cursor += 1;
        }
        let operand_end = cursor;
        if operand_start == operand_end || !statement[cursor..].trim().is_empty() {
            return Err("include directive must contain exactly one bare operand".to_string());
        }
        let requested = crate::netlist::parse_include_directive(statement)
            .ok_or_else(|| format!("malformed include directive '{}'", statement.trim()))?;
        if requested != statement[operand_start..operand_end] {
            return Err("include operand span does not match the parsed path".to_string());
        }
        Ok((requested, operand_start, operand_end))
    }

    fn validate_nested_include_support_source(source: &str) -> Result<(), String> {
        let mut subckt_count = 0usize;
        let mut ends_count = 0usize;
        let mut resistor_count = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            if stripped.is_empty() {
                continue;
            }
            let head = stripped.split_whitespace().next().unwrap_or("");
            if head.eq_ignore_ascii_case(".subckt") {
                subckt_count += 1;
            } else if head.eq_ignore_ascii_case(".ends") {
                ends_count += 1;
            } else if head
                .chars()
                .next()
                .is_some_and(|character| character.eq_ignore_ascii_case(&'R'))
            {
                resistor_count += 1;
            } else {
                return Err(format!(
                    "nested-include support source contains unqualified statement '{stripped}'"
                ));
            }
        }
        if subckt_count != 1 || ends_count != 1 || resistor_count != 1 {
            return Err("nested-include support source must contain exactly one resistor-only subcircuit definition".to_string());
        }
        // Standalone include fragments intentionally begin with .SUBCKT and have no
        // circuit-title record. Supply a validation-only title so the ordinary
        // top-level parser does not consume the first directive as SPICE's title.
        let validation_source = format!("nested include support validation\n{source}");
        let parsed = Netlist::parse(&validation_source)
            .map_err(|err| format!("support source parse failed: {err}"))?;
        if parsed.subcircuits.len() != 1
            || parsed.subcircuits[0].ports.len() != 2
            || parsed.subcircuits[0].elements.len() != 1
        {
            return Err("support source is not one two-terminal local subcircuit".to_string());
        }
        Self::validate_nested_include_subcircuit_auxiliary_state(&parsed.subcircuits[0])?;
        Self::strict_nested_include_resistor_fingerprint(&parsed.subcircuits[0].elements[0])?;
        Ok(())
    }

    fn age_cap_family_contract(&self, deck: &XyceDeck) -> Option<XyceAgeCapFamilyContract> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let mut anchor = None;
        let mut workers = Vec::new();
        for entry in fs::read_dir(parent).ok()? {
            let entry = entry.ok()?;
            let path = entry.path();
            if !path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
            {
                continue;
            }
            if !entry.file_type().ok()?.is_file() {
                return None;
            }
            let source = fs::read_to_string(&path).ok()?;
            let wrapper = self.requires_upstream_wrapper(&self.relative_key(&path));
            if source.trim().is_empty() {
                if !wrapper || anchor.replace(path).is_some() {
                    return None;
                }
                continue;
            }
            if wrapper {
                return None;
            }
            let plan = self
                .static_tran_family_plan_for_path(
                    &path,
                    XyceStaticTranPlanPurpose::AgeCapRelationalFamily,
                )
                .ok()?;
            Self::validate_age_cap_transient_plan(&plan).ok()?;
            let netlist = Self::parse_xyce_netlist(&plan.source, &path).ok()?;
            let snapshot = Self::age_cap_family_snapshot(&netlist, &plan.print).ok()?;
            workers.push((path, plan, snapshot));
        }
        let anchor = anchor?;
        if workers.len() != 2
            || ![&anchor]
                .into_iter()
                .chain(workers.iter().map(|(path, _, _)| path))
                .any(|path| Self::same_path(path, &deck.path))
        {
            return None;
        }
        let aged = workers.iter().find(|(_, _, snapshot)| {
            snapshot.representation == XyceAgeCapRepresentation::NativeAge
        })?;
        let equivalent = workers.iter().find(|(_, _, snapshot)| {
            snapshot.representation == XyceAgeCapRepresentation::ParameterExpression
        })?;
        if Self::same_path(&aged.0, &equivalent.0)
            || aged.1.print.probes != equivalent.1.print.probes
            || !Self::tran_analyses_match_exactly(&aged.1.tran, &equivalent.1.tran)
            || aged.1.timeint_conststep != equivalent.1.timeint_conststep
            || Self::compare_age_cap_family_snapshots(&aged.2, &equivalent.2).is_err()
        {
            return None;
        }
        let family_paths = [&anchor, &aged.0, &equivalent.0];
        let output_parent = self
            .static_prn_reference_path(&aged.0)?
            .parent()?
            .to_path_buf();
        let prefixes = family_paths
            .iter()
            .filter_map(|path| {
                path.file_name()
                    .and_then(|name| name.to_str())
                    .map(|name| format!("{name}."))
            })
            .collect::<Vec<_>>();
        if prefixes.len() != family_paths.len() {
            return None;
        }
        let mut artifacts = Vec::new();
        for entry in fs::read_dir(&output_parent).ok()? {
            let entry = entry.ok()?;
            let name = entry.file_name();
            let name = name.to_str()?;
            if !prefixes.iter().any(|prefix| name.starts_with(prefix)) {
                continue;
            }
            if !entry.file_type().ok()?.is_file() {
                return None;
            }
            artifacts.push(entry.path());
        }
        let aged_prn = self.static_prn_reference_path(&aged.0)?;
        if artifacts.len() != 1
            || !Self::same_path(&artifacts[0], &aged_prn)
            || fs::metadata(&aged_prn).ok()?.len() == 0
        {
            return None;
        }
        let role = if Self::same_path(&deck.path, &anchor) {
            XyceAgeCapFamilyRole::Anchor
        } else if Self::same_path(&deck.path, &aged.0) {
            XyceAgeCapFamilyRole::AgedBaseline
        } else if Self::same_path(&deck.path, &equivalent.0) {
            XyceAgeCapFamilyRole::EquivalentMember
        } else {
            return None;
        };
        let target_path = match role {
            XyceAgeCapFamilyRole::Anchor => None,
            XyceAgeCapFamilyRole::AgedBaseline => Some(aged.0.clone()),
            XyceAgeCapFamilyRole::EquivalentMember => Some(equivalent.0.clone()),
        };
        Some(XyceAgeCapFamilyContract {
            relational: XyceBaselineFamilyContract {
                kind: XyceBaselineFamilyKind::AgeCap,
                comparison: XyceBaselineFamilyComparison::ExactPrn,
                family: parent.file_name()?.to_str()?.to_string(),
                baseline_path: aged.0.clone(),
                member_paths: vec![aged.0.clone(), equivalent.0.clone()],
                target_path,
            },
            role,
        })
    }

    fn diode_model_alias_family_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<XyceDiodeModelAliasFamilyContract> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/certification_tests/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let mut records = Vec::new();
        for entry in fs::read_dir(parent).ok()? {
            let entry = entry.ok()?;
            let path = entry.path();
            if !path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
            {
                continue;
            }
            if !entry.file_type().ok()?.is_file() {
                return None;
            }
            let source = fs::read_to_string(&path).ok()?;
            let wrapper = self.requires_upstream_wrapper(&self.relative_key(&path));
            let worker = if source.trim().is_empty() {
                None
            } else {
                let plan = self
                    .static_tran_family_plan_for_path(
                        &path,
                        XyceStaticTranPlanPurpose::RelationalFamily,
                    )
                    .ok()?;
                Self::validate_diode_model_alias_transient_plan(&plan).ok()?;
                let netlist = Self::parse_xyce_netlist(&plan.source, &path).ok()?;
                let snapshot =
                    Self::diode_model_alias_family_snapshot(&netlist, &plan.print).ok()?;
                Some((plan, snapshot))
            };
            records.push((path, wrapper, worker));
        }
        if records.len() != 3
            || !records
                .iter()
                .any(|(path, _, _)| Self::same_path(path, &deck.path))
        {
            return None;
        }
        let anchors = records
            .iter()
            .filter(|(_, wrapper, worker)| *wrapper && worker.is_none())
            .collect::<Vec<_>>();
        let workers = records
            .iter()
            .filter(|(_, wrapper, worker)| !*wrapper && worker.is_some())
            .collect::<Vec<_>>();
        if anchors.len() != 1
            || workers.len() != 2
            || records.iter().any(|(_, wrapper, worker)| {
                (*wrapper && worker.is_some()) || (!*wrapper && worker.is_none())
            })
        {
            return None;
        }
        let canonical = workers.iter().find(|(_, _, worker)| {
            worker.as_ref().is_some_and(|(_, snapshot)| {
                snapshot.representation == XyceDiodeModelAliasRepresentation::Canonical
            })
        })?;
        let alias = workers.iter().find(|(_, _, worker)| {
            worker.as_ref().is_some_and(|(_, snapshot)| {
                snapshot.representation == XyceDiodeModelAliasRepresentation::Alias
            })
        })?;
        if Self::same_path(&canonical.0, &alias.0) {
            return None;
        }
        let (canonical_plan, canonical_snapshot) = canonical.2.as_ref()?;
        let (alias_plan, alias_snapshot) = alias.2.as_ref()?;
        if canonical_plan.print.probes != alias_plan.print.probes
            || !Self::tran_analyses_match_exactly(&canonical_plan.tran, &alias_plan.tran)
            || canonical_plan.timeint_conststep != alias_plan.timeint_conststep
            || canonical_plan.wrapper_tolerance.is_some()
            || alias_plan.wrapper_tolerance.is_some()
            || canonical_plan.comparison_mode != alias_plan.comparison_mode
            || Self::compare_diode_model_alias_family_snapshots(canonical_snapshot, alias_snapshot)
                .is_err()
        {
            return None;
        }

        let artifact_dir = self
            .static_output_reference_path(&canonical.0, "artifact")?
            .parent()?
            .to_path_buf();
        if artifact_dir.try_exists().ok()? {
            if !fs::metadata(&artifact_dir).ok()?.is_dir() {
                return None;
            }
            if let Some(artifact) = fs::read_dir(&artifact_dir).ok()?.next() {
                let artifact = artifact.ok()?;
                artifact.file_type().ok()?;
                return None;
            }
        }

        let anchor_path = anchors[0].0.clone();
        let role = if Self::same_path(&deck.path, &anchor_path) {
            XyceDiodeModelAliasFamilyRole::Anchor
        } else if Self::same_path(&deck.path, &canonical.0) {
            XyceDiodeModelAliasFamilyRole::CanonicalBaseline
        } else if Self::same_path(&deck.path, &alias.0) {
            XyceDiodeModelAliasFamilyRole::AliasMember
        } else {
            return None;
        };
        let target_path = match role {
            XyceDiodeModelAliasFamilyRole::Anchor => None,
            XyceDiodeModelAliasFamilyRole::CanonicalBaseline => Some(canonical.0.clone()),
            XyceDiodeModelAliasFamilyRole::AliasMember => Some(alias.0.clone()),
        };
        Some(XyceDiodeModelAliasFamilyContract {
            relational: XyceBaselineFamilyContract {
                kind: XyceBaselineFamilyKind::DiodeModelAlias,
                comparison: XyceBaselineFamilyComparison::ExactPrn,
                family: parent.file_name()?.to_str()?.to_string(),
                baseline_path: canonical.0.clone(),
                member_paths: vec![canonical.0.clone(), alias.0.clone()],
                target_path,
            },
            role,
        })
    }

    fn switch_state_case_family_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<XyceSwitchStateCaseFamilyContract> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/certification_tests/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let mut records = Vec::new();
        for entry in fs::read_dir(parent).ok()? {
            let entry = entry.ok()?;
            let path = entry.path();
            if !path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
            {
                continue;
            }
            if !entry.file_type().ok()?.is_file() {
                return None;
            }
            let artifact_prefix = format!("{}.", path.file_name()?.to_str()?).to_ascii_lowercase();
            let artifact_dir = self
                .static_output_reference_path(&path, "artifact")?
                .parent()?
                .to_path_buf();
            if artifact_dir.try_exists().ok()? {
                if !fs::metadata(&artifact_dir).ok()?.is_dir() {
                    return None;
                }
                for artifact in fs::read_dir(&artifact_dir).ok()? {
                    let artifact = artifact.ok()?;
                    let name = artifact.file_name();
                    let name = name.to_str()?.to_ascii_lowercase();
                    artifact.file_type().ok()?;
                    if name.starts_with(&artifact_prefix) {
                        return None;
                    }
                }
            }
            let source = fs::read_to_string(&path).ok()?;
            let wrapper = self.requires_upstream_wrapper(&self.relative_key(&path));
            if source.trim().is_empty() {
                records.push((path, wrapper, None));
                continue;
            }
            let plan = self
                .static_tran_family_plan_for_path(
                    &path,
                    XyceStaticTranPlanPurpose::RelationalFamily,
                )
                .ok()?;
            Self::validate_switch_state_case_transient_plan(&plan).ok()?;
            let netlist = Self::parse_xyce_netlist(&plan.source, &path).ok()?;
            let snapshot = Self::switch_state_case_family_snapshot(&netlist, &plan.print).ok()?;
            records.push((path, wrapper, Some((plan, snapshot))));
        }
        if records.len() != 3
            || !records
                .iter()
                .any(|(path, _, _)| Self::same_path(path, &deck.path))
        {
            return None;
        }
        let anchors = records
            .iter()
            .filter(|(_, wrapper, worker)| *wrapper && worker.is_none())
            .collect::<Vec<_>>();
        let workers = records
            .iter()
            .filter(|(_, wrapper, worker)| !*wrapper && worker.is_some())
            .collect::<Vec<_>>();
        if anchors.len() != 1
            || workers.len() != 2
            || records.iter().any(|(_, wrapper, worker)| {
                (*wrapper && worker.is_some()) || (!*wrapper && worker.is_none())
            })
        {
            return None;
        }
        let uppercase = workers.iter().find(|(_, _, worker)| {
            worker.as_ref().is_some_and(|(_, snapshot)| {
                snapshot.representation == XyceSwitchStateCaseRepresentation::Uppercase
            })
        })?;
        let lowercase = workers.iter().find(|(_, _, worker)| {
            worker.as_ref().is_some_and(|(_, snapshot)| {
                snapshot.representation == XyceSwitchStateCaseRepresentation::Lowercase
            })
        })?;
        if Self::same_path(&uppercase.0, &lowercase.0) {
            return None;
        }
        let (_, uppercase_snapshot) = uppercase.2.as_ref()?;
        let (_, lowercase_snapshot) = lowercase.2.as_ref()?;
        Self::compare_switch_state_case_family_snapshots(uppercase_snapshot, lowercase_snapshot)
            .ok()?;
        let anchor_path = anchors[0].0.clone();
        let role = if Self::same_path(&deck.path, &anchor_path) {
            XyceSwitchStateCaseFamilyRole::Anchor
        } else if Self::same_path(&deck.path, &uppercase.0) {
            XyceSwitchStateCaseFamilyRole::UppercaseBaseline
        } else if Self::same_path(&deck.path, &lowercase.0) {
            XyceSwitchStateCaseFamilyRole::LowercaseMember
        } else {
            return None;
        };
        let target_path = match role {
            XyceSwitchStateCaseFamilyRole::Anchor => None,
            XyceSwitchStateCaseFamilyRole::UppercaseBaseline => Some(uppercase.0.clone()),
            XyceSwitchStateCaseFamilyRole::LowercaseMember => Some(lowercase.0.clone()),
        };
        Some(XyceSwitchStateCaseFamilyContract {
            relational: XyceBaselineFamilyContract {
                kind: XyceBaselineFamilyKind::SwitchStateCase,
                comparison: XyceBaselineFamilyComparison::ExactPrn,
                family: parent.file_name()?.to_str()?.to_string(),
                baseline_path: uppercase.0.clone(),
                member_paths: vec![uppercase.0.clone(), lowercase.0.clone()],
                target_path,
            },
            role,
        })
    }

    fn delimited_expression_family_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<XyceBaselineFamilyContract> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/certification_tests/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let mut records = Vec::new();
        for entry in fs::read_dir(parent).ok()? {
            let entry = entry.ok()?;
            let path = entry.path();
            if !path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
            {
                continue;
            }
            if !entry.file_type().ok()?.is_file()
                || fs::metadata(&path)
                    .ok()
                    .is_none_or(|metadata| metadata.len() == 0)
                || self
                    .static_prn_reference_path(&path)
                    .is_some_and(|reference| reference.is_file())
            {
                return None;
            }
            let wrapper = self.requires_upstream_wrapper(&self.relative_key(&path));
            let source = fs::read_to_string(&path).ok()?;
            let (representation, _) =
                Self::delimited_expression_source_qualification(&source).ok()?;
            if wrapper != (representation == XyceDelimitedExpressionRepresentation::SingleQuoted) {
                return None;
            }
            let plan = self
                .static_dc_plan_for_path(&path, ExpressionDialect::Xyce)
                .ok()?;
            Self::validate_delimited_expression_plan(&plan).ok()?;
            let netlist = Self::parse_xyce_netlist(&plan.source, &path).ok()?;
            let snapshot = Self::delimited_expression_family_snapshot(&plan, &netlist).ok()?;
            records.push((path, wrapper, plan, snapshot));
        }
        if records.len() != 2
            || !records
                .iter()
                .any(|(path, _, _, _)| Self::same_path(path, &deck.path))
            || records.iter().filter(|(_, wrapper, _, _)| *wrapper).count() != 1
        {
            return None;
        }
        let baseline = records.iter().find(|(_, wrapper, _, _)| !wrapper)?;
        let target = records.iter().find(|(_, wrapper, _, _)| *wrapper)?;
        if baseline.2.print_format.is_some()
            || target.2.print_format.is_some()
            || baseline.2.print.probes != target.2.print.probes
            || !Self::dc_sweeps_match_exactly(&baseline.2.dc, &target.2.dc)
            || Self::compare_delimited_expression_snapshots(&baseline.3, &target.3).is_err()
        {
            return None;
        }
        Some(XyceBaselineFamilyContract {
            kind: XyceBaselineFamilyKind::DelimitedExpression,
            comparison: XyceBaselineFamilyComparison::ExactPrnCaseInsensitive,
            family: parent.file_name()?.to_str()?.to_string(),
            baseline_path: baseline.0.clone(),
            member_paths: vec![baseline.0.clone(), target.0.clone()],
            target_path: Some(deck.path.clone()),
        })
    }

    fn ac_analysis_expression_family_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<XyceBaselineFamilyContract> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/certification_tests/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let mut records = Vec::new();
        for entry in fs::read_dir(parent).ok()? {
            let entry = entry.ok()?;
            let path = entry.path();
            if !path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
            {
                continue;
            }
            if !entry.file_type().ok()?.is_file()
                || fs::metadata(&path)
                    .ok()
                    .is_none_or(|metadata| metadata.len() == 0)
                || self
                    .static_output_reference_path(&path, "FD.prn")
                    .is_some_and(|reference| reference.is_file())
            {
                return None;
            }
            let source = fs::read_to_string(&path).ok()?;
            let (representation, _) = Self::ac_analysis_source_qualification(&source).ok()?;
            let wrapper = self.requires_upstream_wrapper(&self.relative_key(&path));
            if wrapper != (representation == XyceAcAnalysisRepresentation::ParameterExpression) {
                return None;
            }
            let plan = self.relational_ac_plan_for_path(&path).ok()?;
            Self::validate_ac_analysis_expression_plan(&plan).ok()?;
            let netlist = Self::parse_xyce_netlist(&plan.source, &path).ok()?;
            let snapshot = Self::ac_analysis_expression_snapshot(&netlist).ok()?;
            records.push((path, wrapper, plan, netlist, snapshot));
        }
        if records.len() != 2
            || !records
                .iter()
                .any(|(path, _, _, _, _)| Self::same_path(path, &deck.path))
        {
            return None;
        }
        let baseline_index = records.iter().position(|(_, wrapper, _, _, _)| !wrapper)?;
        let target_index = records.iter().position(|(_, wrapper, _, _, _)| *wrapper)?;
        if baseline_index == target_index
            || records
                .iter()
                .filter(|(_, wrapper, _, _, _)| !wrapper)
                .count()
                != 1
            || records
                .iter()
                .filter(|(_, wrapper, _, _, _)| *wrapper)
                .count()
                != 1
        {
            return None;
        }
        let (baseline_path, _, baseline_plan, baseline_netlist, baseline_snapshot) =
            &records[baseline_index];
        let (target_path, _, target_plan, target_netlist, target_snapshot) = &records[target_index];
        if baseline_plan.print.probes != target_plan.print.probes
            || baseline_plan.ac.frequencies.len() != target_plan.ac.frequencies.len()
            || !baseline_plan
                .ac
                .frequencies
                .iter()
                .zip(&target_plan.ac.frequencies)
                .all(|(baseline, target)| {
                    baseline.is_finite()
                        && target.is_finite()
                        && baseline.to_bits() == target.to_bits()
                })
            || !Self::ac_analyses_match_exactly(baseline_netlist, target_netlist)
            || Self::compare_ac_analysis_expression_snapshots(baseline_snapshot, target_snapshot)
                .is_err()
        {
            return None;
        }
        let tolerance = XyceAcComparatorTolerance::new(6.0e-5, 1.0e-4, 1.0e-6, 1.0e-6).ok()?;
        let family = format!(
            "{}:{}",
            parent.file_name()?.to_str()?,
            baseline_path.file_stem()?.to_str()?
        );
        Some(XyceBaselineFamilyContract {
            kind: XyceBaselineFamilyKind::AcAnalysisExpression,
            comparison: XyceBaselineFamilyComparison::AcComparator(tolerance),
            family,
            baseline_path: baseline_path.clone(),
            member_paths: vec![baseline_path.clone(), target_path.clone()],
            target_path: Some(deck.path.clone()),
        })
    }

    fn numbered_redefinition_dc_family_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceNumberedRedefinitionDcFamilyContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        if !relative.starts_with("netlists/") {
            return None;
        }
        let relative_parent = relative.rsplit_once('/')?.0;
        let deck_stem = deck.path.file_stem()?.to_str()?.to_ascii_lowercase();
        let manifest_anchors = self
            .upstream_wrapper_decks
            .iter()
            .filter_map(|path| {
                let (parent, file_name) = path.rsplit_once('/')?;
                if parent != relative_parent {
                    return None;
                }
                let stem = file_name.strip_suffix(".cir")?;
                Some((file_name, stem.to_ascii_lowercase()))
            })
            .collect::<Vec<_>>();
        let manifest_named_candidate = manifest_anchors.len() == 2
            && manifest_anchors.iter().any(|(_, anchor)| {
                deck_stem == *anchor
                    || deck_stem.strip_prefix(anchor).is_some_and(|suffix| {
                        suffix.len() == 1 && suffix.as_bytes()[0].is_ascii_digit()
                    })
            });
        if !manifest_named_candidate {
            return None;
        }
        let parent = deck.path.parent()?;
        let candidate_stems = fs::read_dir(parent)
            .ok()?
            .filter_map(Result::ok)
            .filter(|entry| entry.file_type().ok().is_some_and(|kind| kind.is_file()))
            .filter_map(|entry| {
                let path = entry.path();
                path.extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
                    .then(|| {
                        path.file_stem()
                            .and_then(|stem| stem.to_str())
                            .map(str::to_ascii_lowercase)
                    })
                    .flatten()
            })
            .collect::<Vec<_>>();
        let numbered_counts = manifest_anchors
            .iter()
            .map(|(_, anchor)| {
                candidate_stems
                    .iter()
                    .filter(|stem| {
                        stem.strip_prefix(anchor).is_some_and(|suffix| {
                            suffix.len() == 1 && suffix.as_bytes()[0].is_ascii_digit()
                        })
                    })
                    .count()
            })
            .collect::<Vec<_>>();
        if numbered_counts.len() != 2
            || numbered_counts.iter().any(|count| !(2..=3).contains(count))
        {
            return None;
        }

        Some((|| {
            let entries = fs::read_dir(parent)
                .map_err(|err| format!("failed to read candidate family directory: {err}"))?
                .collect::<Result<Vec<_>, _>>()
                .map_err(|err| format!("failed to enumerate candidate family directory: {err}"))?;
            let mut cir_paths = Vec::new();
            let mut source_artifacts = Vec::new();
            let mut folded_names = BTreeSet::new();
            for entry in entries {
                if !entry.file_type().map_err(|err| err.to_string())?.is_file() {
                    return Err("family directory may contain only regular files".to_string());
                }
                let path = entry.path();
                let name = path
                    .file_name()
                    .and_then(|name| name.to_str())
                    .ok_or_else(|| "family directory contains a non-UTF-8 name".to_string())?;
                if !folded_names.insert(name.to_ascii_lowercase()) {
                    return Err("case-colliding family filenames are not admissible".to_string());
                }
                if path
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
                {
                    cir_paths.push(path);
                } else if name.to_ascii_lowercase().ends_with(".cir.res.gs") {
                    source_artifacts.push(path);
                } else {
                    return Err(format!("unexpected source-side family artifact '{}'", name));
                }
            }
            if cir_paths.len() != 11 || source_artifacts.len() != 1 {
                return Err(format!(
                    "family census requires eleven .cir files and one .cir.res.gs artifact, found {} and {}",
                    cir_paths.len(),
                    source_artifacts.len()
                ));
            }

            let mut anchors = Vec::new();
            for (file_name, _) in &manifest_anchors {
                let path = cir_paths
                    .iter()
                    .find(|path| {
                        path.file_name()
                            .and_then(|name| name.to_str())
                            .is_some_and(|name| name.eq_ignore_ascii_case(file_name))
                    })
                    .cloned()
                    .ok_or_else(|| format!("manifest anchor '{file_name}' is missing"))?;
                let source = fs::read_to_string(&path)
                    .map_err(|err| format!("failed to read manifest anchor: {err}"))?;
                if !source.trim().is_empty() {
                    return Err(format!(
                        "manifest anchor '{}' must contain only whitespace",
                        path.display()
                    ));
                }
                anchors.push(path);
            }
            anchors.sort_by_key(|path| {
                path.file_name()
                    .map(|name| name.to_string_lossy().to_ascii_lowercase())
            });

            let mut claimed = BTreeSet::new();
            let mut groups = Vec::new();
            for owner_path in anchors {
                let owner_stem = owner_path
                    .file_stem()
                    .and_then(|stem| stem.to_str())
                    .ok_or_else(|| "family anchor has a non-UTF-8 stem".to_string())?;
                let folded_owner = owner_stem.to_ascii_lowercase();
                let mut numbered = BTreeMap::new();
                for path in &cir_paths {
                    if Self::same_path(path, &owner_path) {
                        continue;
                    }
                    let stem = path
                        .file_stem()
                        .and_then(|stem| stem.to_str())
                        .ok_or_else(|| "family member has a non-UTF-8 stem".to_string())?
                        .to_ascii_lowercase();
                    let Some(suffix) = stem.strip_prefix(&folded_owner) else {
                        continue;
                    };
                    if suffix.len() != 1 || !suffix.as_bytes()[0].is_ascii_digit() {
                        continue;
                    }
                    let index = usize::from(suffix.as_bytes()[0] - b'0');
                    if numbered.insert(index, path.clone()).is_some() {
                        return Err(format!(
                            "family '{owner_stem}' has duplicate member index {index}"
                        ));
                    }
                }
                if numbered.keys().copied().ne(0..3) {
                    return Err(format!(
                        "family '{owner_stem}' requires contiguous members 0, 1, and 2"
                    ));
                }
                let members = numbered.into_values().collect::<Vec<_>>();
                if !claimed.insert(owner_path.clone())
                    || members.iter().any(|path| !claimed.insert(path.clone()))
                {
                    return Err("a circuit is claimed by more than one numbered family".to_string());
                }
                groups.push((owner_path, members));
            }

            let standalone = cir_paths
                .iter()
                .filter(|path| !claimed.contains(*path))
                .cloned()
                .collect::<Vec<_>>();
            if standalone.len() != 3 || claimed.len() != 8 {
                return Err(
                    "directory must contain two four-record numbered families and three standalone oracle decks"
                        .to_string(),
                );
            }
            if standalone.iter().any(|path| {
                self.requires_upstream_wrapper(&self.relative_key(path))
                    || fs::read_to_string(path)
                        .ok()
                        .is_none_or(|source| source.trim().is_empty())
            }) {
                return Err(
                    "standalone oracle decks must be nonempty non-wrapper circuits".to_string(),
                );
            }
            let artifact_name = source_artifacts[0]
                .file_name()
                .and_then(|name| name.to_str())
                .ok_or_else(|| "source artifact has a non-UTF-8 name".to_string())?;
            if standalone
                .iter()
                .filter(|path| {
                    path.file_name()
                        .and_then(|name| name.to_str())
                        .is_some_and(|name| {
                            artifact_name.eq_ignore_ascii_case(&format!("{name}.res.gs"))
                        })
                })
                .count()
                != 1
            {
                return Err(
                    "the sole source-side .res.gs artifact must belong to exactly one standalone deck"
                        .to_string(),
                );
            }

            let first_reference = self
                .static_output_reference_path(&standalone[0], "prn")
                .ok_or_else(|| "cannot map standalone deck into OutputData".to_string())?;
            let output_parent = first_reference
                .parent()
                .ok_or_else(|| "OutputData mapping has no parent".to_string())?;
            let output_entries = fs::read_dir(output_parent)
                .map_err(|err| format!("failed to read family OutputData directory: {err}"))?
                .collect::<Result<Vec<_>, _>>()
                .map_err(|err| format!("failed to enumerate family OutputData: {err}"))?;
            let mut actual_outputs = BTreeSet::new();
            for entry in output_entries {
                if !entry.file_type().map_err(|err| err.to_string())?.is_file() {
                    return Err("family OutputData may contain only regular files".to_string());
                }
                let name = entry.file_name().to_string_lossy().to_ascii_lowercase();
                if !name.ends_with(".cir.prn") || !actual_outputs.insert(name) {
                    return Err(
                        "family OutputData must contain unique default-PRN artifacts only"
                            .to_string(),
                    );
                }
            }
            let expected_outputs = standalone
                .iter()
                .map(|path| {
                    format!(
                        "{}.prn",
                        path.file_name()
                            .unwrap()
                            .to_string_lossy()
                            .to_ascii_lowercase()
                    )
                })
                .collect::<BTreeSet<_>>();
            if actual_outputs != expected_outputs {
                return Err(
                    "family OutputData census must contain exactly one .prn per standalone deck"
                        .to_string(),
                );
            }
            for path in &standalone {
                let plan = self.static_dc_plan_for_path(path, ExpressionDialect::Xyce)?;
                if plan.print.probes.is_empty() || !plan.diagnostics.is_empty() {
                    return Err(format!(
                        "standalone deck '{}' is not a diagnostic-free static DC plan",
                        path.display()
                    ));
                }
            }

            let mut selected_contract = None;
            let mut selected_policies = Vec::new();
            for (owner_path, member_paths) in groups {
                for path in &member_paths {
                    if self.requires_upstream_wrapper(&self.relative_key(path))
                        || fs::read_to_string(path)
                            .map_err(|err| format!("failed to read numbered member: {err}"))?
                            .trim()
                            .is_empty()
                    {
                        return Err(
                            "numbered members must be nonempty non-wrapper decks".to_string()
                        );
                    }
                    for extension in ["prn", "res"] {
                        if self
                            .static_output_reference_path(path, extension)
                            .is_some_and(|oracle| oracle.exists())
                        {
                            return Err(format!(
                                "numbered member '{}' must not own a .{extension} oracle",
                                path.display()
                            ));
                        }
                    }
                }

                let baseline_source = fs::read_to_string(&member_paths[0])
                    .map_err(|err| format!("failed to read numbered baseline: {err}"))?;
                if !Self::top_level_literal_parameter_definitions(&baseline_source)?.is_empty() {
                    return Err(
                        "numbered baseline must not define top-level literal parameters"
                            .to_string(),
                    );
                }
                let first_definitions = Self::top_level_literal_parameter_definitions(
                    &fs::read_to_string(&member_paths[1]).map_err(|err| err.to_string())?,
                )?;
                let second_definitions = Self::top_level_literal_parameter_definitions(
                    &fs::read_to_string(&member_paths[2]).map_err(|err| err.to_string())?,
                )?;
                if first_definitions != second_definitions
                    || first_definitions
                        .values()
                        .filter(|values| {
                            values.len() == 2 && values[0].to_bits() != values[1].to_bits()
                        })
                        .count()
                        != 1
                    || first_definitions
                        .values()
                        .any(|values| values.is_empty() || values.len() > 2)
                {
                    return Err(
                        "parameterized members must share one literal-definition map with exactly one distinct two-value duplicate"
                            .to_string(),
                    );
                }

                let mut matching_policies = Vec::new();
                for policy in [
                    ParameterRedefinitionPolicy::UseFirst,
                    ParameterRedefinitionPolicy::UseLast,
                ] {
                    let mut plans = Vec::new();
                    let mut snapshots = Vec::new();
                    let mut representations = Vec::new();
                    for path in &member_paths {
                        let plan = self.static_dc_plan_for_path_with_redefinition_policy(
                            path,
                            ExpressionDialect::Xyce,
                            policy,
                        )?;
                        Self::validate_numbered_redefinition_dc_plan(&plan)?;
                        let netlist =
                            Self::parse_netlist_with_expression_dialect_policy_and_execution_dir(
                                &plan.source,
                                path,
                                ExpressionDialect::Xyce,
                                policy,
                                None,
                            )
                            .map_err(|err| format!("failed to parse numbered member: {err}"))?;
                        representations.push(Self::numbered_redefinition_representation(&netlist)?);
                        snapshots.push(Self::numbered_redefinition_snapshot(
                            &netlist,
                            &plan.dc.source,
                        )?);
                        plans.push(plan);
                    }
                    if representations
                        != [
                            XyceNumberedRedefinitionRepresentation::LiteralBaseline,
                            XyceNumberedRedefinitionRepresentation::DependentFormalExpression,
                            XyceNumberedRedefinitionRepresentation::DependentInstanceExpression,
                        ]
                    {
                        return Err(
                            "numbered members must use baseline, dependent-formal, and dependent-instance representations in order"
                                .to_string(),
                        );
                    }
                    let baseline_plan = &plans[0];
                    if plans.iter().skip(1).any(|plan| {
                        plan.print.probes != baseline_plan.print.probes
                            || !Self::dc_sweeps_match_exactly(&plan.dc, &baseline_plan.dc)
                    }) {
                        return Err(
                            "numbered members must share identical PRINT and DC contracts"
                                .to_string(),
                        );
                    }
                    if snapshots
                        .iter()
                        .skip(1)
                        .all(|snapshot| snapshot == &snapshots[0])
                    {
                        matching_policies.push(policy);
                    }
                }
                let [policy] = matching_policies.as_slice() else {
                    return Err(
                        "numbered family must select exactly one first/last redefinition policy"
                            .to_string(),
                    );
                };
                selected_policies.push(*policy);

                if Self::same_path(&deck.path, &owner_path)
                    || member_paths
                        .iter()
                        .any(|path| Self::same_path(path, &deck.path))
                {
                    let role = member_paths
                        .iter()
                        .position(|path| Self::same_path(path, &deck.path))
                        .map_or(XyceNumberedRedefinitionDcFamilyRole::Owner, |index| {
                            if index == 0 {
                                XyceNumberedRedefinitionDcFamilyRole::Baseline
                            } else {
                                XyceNumberedRedefinitionDcFamilyRole::Member(index)
                            }
                        });
                    selected_contract = Some(XyceNumberedRedefinitionDcFamilyContract {
                        family: owner_path
                            .file_stem()
                            .unwrap()
                            .to_string_lossy()
                            .to_string(),
                        owner_path,
                        baseline_path: member_paths[0].clone(),
                        member_paths,
                        parameter_redefinition_policy: *policy,
                        role,
                    });
                }
            }
            if selected_policies.len() != 2 || selected_policies[0] == selected_policies[1] {
                return Err(
                    "the two numbered families must select opposite redefinition policies"
                        .to_string(),
                );
            }
            selected_contract.ok_or_else(|| {
                "requested deck is not claimed by either numbered family".to_string()
            })
        })())
    }

    fn top_level_literal_parameter_definitions(
        source: &str,
    ) -> Result<BTreeMap<String, Vec<Value>>, String> {
        let mut definitions = BTreeMap::<String, Vec<Value>>::new();
        let mut subckt_depth = 0usize;
        for line in Self::logical_netlist_lines(source) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            if stripped.is_empty() {
                continue;
            }
            let fields = Self::split_grouped_whitespace_fields(
                stripped,
                "numbered redefinition parameter statement",
            )?;
            let Some(command) = fields.first() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".subckt") {
                subckt_depth = subckt_depth
                    .checked_add(1)
                    .ok_or_else(|| "subcircuit nesting depth overflow".to_string())?;
                continue;
            }
            if command.eq_ignore_ascii_case(".ends") {
                subckt_depth = subckt_depth
                    .checked_sub(1)
                    .ok_or_else(|| ".ENDS without .SUBCKT in family source".to_string())?;
                continue;
            }
            if subckt_depth != 0 {
                continue;
            }
            if command.eq_ignore_ascii_case(".global_param")
                || command.eq_ignore_ascii_case(".csparam")
            {
                return Err(
                    "numbered redefinition family admits top-level .PARAM literals only"
                        .to_string(),
                );
            }
            if !command.eq_ignore_ascii_case(".param") {
                continue;
            }
            if fields.len() != 2 {
                return Err(
                    "each top-level .PARAM line must contain exactly one assignment".to_string(),
                );
            }
            let (name, raw_value) = fields[1]
                .split_once('=')
                .ok_or_else(|| "top-level .PARAM must use NAME=VALUE syntax".to_string())?;
            if raw_value.contains('=') || !Self::is_single_spice_identifier(name) {
                return Err("top-level .PARAM assignment is not canonical".to_string());
            }
            let value = Self::single_spice_numeric_literal_value(raw_value)?;
            if !value.is_finite() {
                return Err("top-level .PARAM literal must be finite".to_string());
            }
            definitions
                .entry(name.to_ascii_uppercase())
                .or_default()
                .push(value);
        }
        if subckt_depth != 0 {
            return Err("unterminated .SUBCKT in family source".to_string());
        }
        Ok(definitions)
    }

    fn validate_numbered_redefinition_dc_plan(plan: &XyceStaticDcPlan) -> Result<(), String> {
        if plan.expression_dialect != ExpressionDialect::Xyce
            || plan.execution_dir.is_some()
            || !plan.steps.is_empty()
            || plan.dc_data.is_some()
            || plan.print_format.is_some()
            || plan.dc.sweep2.is_some()
            || !matches!(plan.dc.mode, crate::netlist::DcSweepMode::Linear)
            || !plan.diagnostics.is_empty()
            || plan.print.probes.is_empty()
        {
            return Err(
                "numbered redefinition family requires one diagnostic-free, unstepped, one-dimensional linear default-PRN DC plan"
                    .to_string(),
            );
        }
        let points = plan.dc.primary_spec().points();
        if points.len() != 1 || points.iter().any(|point| !point.is_finite()) {
            return Err(
                "numbered redefinition family requires exactly one finite DC sweep point"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn numbered_redefinition_representation(
        netlist: &Netlist,
    ) -> Result<XyceNumberedRedefinitionRepresentation, String> {
        if !netlist.models.is_empty()
            || !netlist.diagnostics.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || netlist.subcircuits.len() != 1
            || netlist.elements.len() != 3
        {
            return Err(
                "numbered redefinition member requires one three-element, one-subcircuit divider without auxiliary state"
                    .to_string(),
            );
        }
        let subcircuit = &netlist.subcircuits[0];
        let [body_element] = subcircuit.elements.as_slice() else {
            return Err("numbered redefinition subcircuit must contain one element".to_string());
        };
        let ElementKind::Resistor { value_expr, .. } = &body_element.kind else {
            return Err("numbered redefinition subcircuit element must be a resistor".to_string());
        };
        let instances = netlist
            .elements
            .iter()
            .filter_map(|element| match &element.kind {
                ElementKind::Subcircuit {
                    subckt_name,
                    params,
                } => Some((subckt_name, params)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let [(subckt_name, instance_params)] = instances.as_slice() else {
            return Err(
                "numbered redefinition member must contain one subcircuit instance".to_string(),
            );
        };
        if !subckt_name.eq_ignore_ascii_case(&subcircuit.name)
            || netlist
                .elements
                .iter()
                .filter(|element| matches!(element.kind, ElementKind::VoltageSource(_)))
                .count()
                != 1
            || netlist
                .elements
                .iter()
                .filter(|element| matches!(element.kind, ElementKind::Resistor { .. }))
                .count()
                != 1
        {
            return Err(
                "numbered redefinition member must contain one source, one series resistor, and one matching subcircuit instance"
                    .to_string(),
            );
        }

        let Some(load_parameter) = value_expr.as_deref() else {
            if subcircuit.params.is_empty()
                && subcircuit.expr_params.is_empty()
                && subcircuit.string_params.is_empty()
                && instance_params.is_empty()
            {
                return Ok(XyceNumberedRedefinitionRepresentation::LiteralBaseline);
            }
            return Err(
                "literal baseline must not carry formal or instance parameters".to_string(),
            );
        };
        if !Self::is_single_spice_identifier(load_parameter) {
            return Err("parameterized subcircuit load must reference one identifier".to_string());
        }
        let formal_expression = subcircuit
            .expr_params
            .iter()
            .any(|(name, _)| name.eq_ignore_ascii_case(load_parameter));
        let instance_expression = instance_params
            .iter()
            .any(|(name, _)| name.eq_ignore_ascii_case(load_parameter));
        match (formal_expression, instance_expression) {
            (true, false) => Ok(
                XyceNumberedRedefinitionRepresentation::DependentFormalExpression,
            ),
            (false, true) => Ok(
                XyceNumberedRedefinitionRepresentation::DependentInstanceExpression,
            ),
            _ => Err(
                "load parameter must be supplied by exactly one dependent formal or instance expression"
                    .to_string(),
            ),
        }
    }

    fn numbered_redefinition_snapshot(
        netlist: &Netlist,
        sweep_source: &str,
    ) -> Result<Vec<XyceRelationalElementFingerprint>, String> {
        let flattened = crate::netlist::flatten_netlist_with_models(netlist)
            .map_err(|err| format!("could not flatten numbered member: {err}"))?;
        if flattened.elements.len() != 3 {
            return Err(format!(
                "numbered member must flatten to three elements, found {}",
                flattened.elements.len()
            ));
        }
        let voltage_sources = flattened
            .elements
            .iter()
            .filter(|element| matches!(element.kind, ElementKind::VoltageSource(_)))
            .collect::<Vec<_>>();
        if voltage_sources.len() != 1
            || !voltage_sources[0].name.eq_ignore_ascii_case(sweep_source)
            || flattened
                .elements
                .iter()
                .filter(|element| matches!(element.kind, ElementKind::Resistor { .. }))
                .count()
                != 2
        {
            return Err(
                "numbered member must flatten to the swept source and two resistors".to_string(),
            );
        }
        let mut fingerprints = flattened
            .elements
            .iter()
            .map(|element| Self::scoped_model_element_fingerprint(element, &netlist.params))
            .collect::<Result<Vec<_>, _>>()?;
        fingerprints.sort();
        Ok(fingerprints)
    }

    fn shared_stepped_dc_family_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceSharedSteppedDcFamilyContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        if !relative.starts_with("netlists/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let relative_parent = relative.rsplit_once('/')?.0;
        let deck_stem = deck
            .path
            .file_stem()
            .and_then(|stem| stem.to_str())?
            .to_ascii_lowercase();
        let manifest_anchor_files = self
            .upstream_wrapper_decks
            .iter()
            .filter_map(|path| {
                let (candidate_parent, file_name) = path.rsplit_once('/')?;
                (candidate_parent == relative_parent)
                    .then(|| file_name.strip_suffix(".cir").map(|stem| (file_name, stem)))
                    .flatten()
            })
            .collect::<Vec<_>>();
        let manifest_named_candidate = manifest_anchor_files.len() == 2
            && manifest_anchor_files.iter().any(|(_, anchor)| {
                deck_stem == *anchor
                    || deck_stem.strip_prefix(anchor).is_some_and(|suffix| {
                        suffix.len() == 1 && suffix.as_bytes()[0].is_ascii_digit()
                    })
            });
        let manifest_family_candidate = manifest_named_candidate
            && (|| {
                let expected = manifest_anchor_files
                    .iter()
                    .flat_map(|(file_name, _)| {
                        [
                            format!("{file_name}.prn").to_ascii_lowercase(),
                            format!("{file_name}.res").to_ascii_lowercase(),
                        ]
                    })
                    .collect::<BTreeSet<_>>();
                let output_subdirectory = Path::new(&deck.relative_path)
                    .parent()?
                    .strip_prefix("Netlists")
                    .ok()?;
                let output_parent = self.root.join("OutputData").join(output_subdirectory);
                let mut actual = BTreeSet::new();
                for entry in fs::read_dir(output_parent).ok()? {
                    let entry = entry.ok()?;
                    if !entry.file_type().ok()?.is_file() {
                        return None;
                    }
                    let name = entry.file_name().to_str()?.to_ascii_lowercase();
                    if !actual.insert(name) {
                        return None;
                    }
                }
                (actual == expected).then_some(())
            })()
            .is_some();
        let entries = match fs::read_dir(parent) {
            Ok(entries) => entries,
            Err(err) if manifest_family_candidate => {
                return Some(Err(format!(
                    "failed to read candidate shared stepped-DC family directory: {err}"
                )));
            }
            Err(_) => return None,
        };
        let mut cir_paths = Vec::new();
        let mut empty_cir_paths = BTreeSet::new();
        let mut folded_names = BTreeSet::new();
        let mut unexpected_entries = 0_usize;
        for entry in entries {
            let entry = match entry {
                Ok(entry) => entry,
                Err(_) => {
                    unexpected_entries += 1;
                    continue;
                }
            };
            let path = entry.path();
            let is_circuit = path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"));
            let Ok(file_type) = entry.file_type() else {
                unexpected_entries += 1;
                continue;
            };
            if !file_type.is_file() || !is_circuit {
                unexpected_entries += 1;
                continue;
            }
            let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                unexpected_entries += 1;
                continue;
            };
            let metadata = match entry.metadata() {
                Ok(metadata) => metadata,
                Err(_) => {
                    unexpected_entries += 1;
                    continue;
                }
            };
            if !folded_names.insert(name.to_ascii_lowercase()) {
                return Some(Err(
                    "case-colliding .cir names are not admissible".to_string()
                ));
            }
            if metadata.len() == 0 {
                empty_cir_paths.insert(path.clone());
            }
            cir_paths.push(path);
        }
        if !cir_paths
            .iter()
            .any(|path| Self::same_path(path, &deck.path))
        {
            if manifest_family_candidate {
                return Some(Err(
                    "candidate shared stepped-DC family does not contain its requested physical record"
                        .to_string(),
                ));
            }
            return None;
        }
        let manifest_anchors = cir_paths
            .iter()
            .filter(|path| {
                empty_cir_paths.contains(*path)
                    && self.requires_upstream_wrapper(&self.relative_key(path))
            })
            .cloned()
            .collect::<Vec<_>>();
        if manifest_anchors.len() != 2 {
            if manifest_family_candidate {
                return Some(Err(
                    "candidate shared stepped-DC family must retain both zero-byte manifest anchors"
                        .to_string(),
                ));
            }
            return None;
        }
        let physical_family_candidate = cir_paths.len() == 8
            && (|| {
                let mut claimed = BTreeSet::new();
                let mut sizes = Vec::new();
                for owner_path in &manifest_anchors {
                    let owner_stem = owner_path.file_stem()?.to_str()?.to_ascii_lowercase();
                    let mut indices = BTreeSet::new();
                    claimed.insert(owner_path.clone());
                    for path in &cir_paths {
                        if Self::same_path(path, owner_path) {
                            continue;
                        }
                        let stem = path.file_stem()?.to_str()?.to_ascii_lowercase();
                        let Some(suffix) = stem.strip_prefix(&owner_stem) else {
                            continue;
                        };
                        if suffix.len() != 1 || !suffix.as_bytes()[0].is_ascii_digit() {
                            continue;
                        }
                        let index = usize::from(suffix.as_bytes()[0] - b'0');
                        if !indices.insert(index) || !claimed.insert(path.clone()) {
                            return None;
                        }
                    }
                    if !matches!(indices.len(), 2 | 4)
                        || indices.iter().copied().ne(0..indices.len())
                    {
                        return None;
                    }
                    sizes.push(indices.len());
                }
                sizes.sort_unstable();
                (sizes == [2, 4] && claimed.len() == cir_paths.len()).then_some(())
            })()
            .is_some();
        if !manifest_family_candidate && !physical_family_candidate {
            return None;
        }

        Some((|| {
            if unexpected_entries > 0 {
                return Err(format!(
                    "shared stepped-DC family directory contains {unexpected_entries} unexpected, unreadable, non-.cir, or non-regular entries"
                ));
            }
            if cir_paths.len() != 8 {
                return Err(format!(
                    "directory census requires exactly eight .cir files, found {}",
                    cir_paths.len()
                ));
            }
            if cir_paths.iter().any(|path| {
                let empty = empty_cir_paths.contains(path);
                let wrapper = self.requires_upstream_wrapper(&self.relative_key(path));
                empty != wrapper
            }) {
                return Err(
                    "only the two zero-byte family anchors may carry wrapper-manifest contracts"
                        .to_string(),
                );
            }

            let mut anchors = manifest_anchors;
            anchors.sort_by_key(|path| {
                path.file_name()
                    .map(|name| name.to_string_lossy().to_ascii_lowercase())
            });
            let mut groups = Vec::new();
            let mut claimed = BTreeSet::new();
            for owner_path in anchors {
                let owner_stem = owner_path
                    .file_stem()
                    .and_then(|stem| stem.to_str())
                    .ok_or_else(|| "family anchor has a non-UTF-8 stem".to_string())?;
                let owner_folded = owner_stem.to_ascii_lowercase();
                let mut numbered = BTreeMap::new();
                for path in &cir_paths {
                    if Self::same_path(path, &owner_path) {
                        continue;
                    }
                    let stem = path
                        .file_stem()
                        .and_then(|stem| stem.to_str())
                        .ok_or_else(|| "family member has a non-UTF-8 stem".to_string())?;
                    let stem_folded = stem.to_ascii_lowercase();
                    let Some(suffix) = stem_folded.strip_prefix(&owner_folded) else {
                        continue;
                    };
                    if suffix.len() != 1 || !suffix.as_bytes()[0].is_ascii_digit() {
                        continue;
                    }
                    let index = usize::from(suffix.as_bytes()[0] - b'0');
                    if numbered.insert(index, path.clone()).is_some() {
                        return Err(format!(
                            "family '{}' has duplicate numeric member index {index}",
                            owner_stem
                        ));
                    }
                }
                if !matches!(numbered.len(), 2 | 4)
                    || numbered.keys().copied().ne(0..numbered.len())
                {
                    return Err(format!(
                        "family '{}' requires contiguous one-digit members 0..N with cardinality two or four",
                        owner_stem
                    ));
                }
                let members = numbered.into_values().collect::<Vec<_>>();
                if !claimed.insert(owner_path.clone())
                    || members.iter().any(|path| !claimed.insert(path.clone()))
                {
                    return Err("a .cir file is claimed by more than one family".to_string());
                }
                groups.push((owner_path, members));
            }
            if claimed.len() != cir_paths.len() {
                return Err("every .cir file must be claimed by exactly one anchor".to_string());
            }
            let mut sizes = groups
                .iter()
                .map(|(_, members)| members.len())
                .collect::<Vec<_>>();
            sizes.sort_unstable();
            if sizes != [2, 4] {
                return Err(
                    "directory must contain exactly one two-member and one four-member family"
                        .to_string(),
                );
            }

            let expected_artifacts = groups
                .iter()
                .flat_map(|(owner, _)| {
                    let name = owner.file_name().unwrap().to_string_lossy();
                    [
                        format!("{name}.prn").to_ascii_lowercase(),
                        format!("{name}.res").to_ascii_lowercase(),
                    ]
                })
                .collect::<BTreeSet<_>>();
            let first_output = self
                .static_output_reference_path(&groups[0].0, "prn")
                .ok_or_else(|| "cannot map anchor into OutputData".to_string())?;
            let output_parent = first_output
                .parent()
                .ok_or_else(|| "anchor OutputData path has no parent".to_string())?;
            let output_entries = fs::read_dir(output_parent)
                .map_err(|err| format!("failed to read shared OutputData directory: {err}"))?
                .collect::<Result<Vec<_>, _>>()
                .map_err(|err| format!("failed to enumerate shared OutputData directory: {err}"))?;
            let mut actual_artifacts = BTreeSet::new();
            for entry in output_entries {
                if !entry.file_type().map_err(|err| err.to_string())?.is_file() {
                    return Err(
                        "shared OutputData directory may contain only four anchor files"
                            .to_string(),
                    );
                }
                let name = entry.file_name().to_string_lossy().to_ascii_lowercase();
                if !actual_artifacts.insert(name) {
                    return Err(
                        "case-colliding shared OutputData artifacts are not admissible".to_string(),
                    );
                }
            }
            if actual_artifacts != expected_artifacts {
                return Err(
                    "shared OutputData census must contain exactly each anchor's .prn and .res"
                        .to_string(),
                );
            }

            let mut selected = None;
            for (owner_path, member_paths) in groups {
                let belongs = Self::same_path(&deck.path, &owner_path)
                    || member_paths
                        .iter()
                        .any(|path| Self::same_path(path, &deck.path));
                let mut plans = Vec::with_capacity(member_paths.len());
                let mut netlists = Vec::with_capacity(member_paths.len());
                let mut topologies = Vec::with_capacity(member_paths.len());
                for member_path in &member_paths {
                    if fs::metadata(member_path)
                        .map_err(|err| format!("failed to inspect family member: {err}"))?
                        .len()
                        == 0
                        || self.requires_upstream_wrapper(&self.relative_key(member_path))
                    {
                        return Err("numbered family members must be nonempty non-wrapper decks"
                            .to_string());
                    }
                    for extension in ["prn", "res"] {
                        if self
                            .static_output_reference_path(member_path, extension)
                            .is_some_and(|path| path.exists())
                        {
                            return Err(format!(
                                "numbered member '{}' must not own a .{extension} oracle",
                                member_path.display()
                            ));
                        }
                    }
                    let plan =
                        self.static_dc_plan_for_path(member_path, ExpressionDialect::Xyce)?;
                    if plan.execution_dir.is_some()
                        || plan.print_format.is_some()
                        || plan.dc_data.is_some()
                        || plan.steps.is_empty()
                        || plan.print.probes.is_empty()
                        || !plan.diagnostics.is_empty()
                    {
                        return Err(format!(
                            "member '{}' is not a diagnostic-free default-PRN stepped-DC plan",
                            member_path.display()
                        ));
                    }
                    let netlist = Self::parse_xyce_netlist(&plan.source, member_path)
                        .map_err(|err| format!("failed to parse family member: {err}"))?;
                    topologies.push(Self::shared_stepped_dc_topology(&netlist)?);
                    netlists.push(netlist);
                    plans.push(plan);
                }
                let (representations, expected) = if member_paths.len() == 2 {
                    let direct =
                        Self::shared_stepped_dc_representation(&netlists[0], &plans[0], None)?;
                    let hierarchical =
                        Self::shared_stepped_dc_representation(&netlists[1], &plans[1], None)?;
                    (
                        vec![direct.0, hierarchical.0],
                        vec![
                            XyceSharedSteppedDcRepresentation::DirectIdentity,
                            XyceSharedSteppedDcRepresentation::HierarchicalIdentity,
                        ],
                    )
                } else {
                    let direct =
                        Self::shared_stepped_dc_representation(&netlists[0], &plans[0], None)?;
                    let transform = direct.1.as_deref().ok_or_else(|| {
                        "four-member family baseline does not define a non-identity transform"
                            .to_string()
                    })?;
                    let mut found = vec![direct.0];
                    for (netlist, plan) in netlists.iter().zip(&plans).skip(1) {
                        found.push(
                            Self::shared_stepped_dc_representation(netlist, plan, Some(transform))?
                                .0,
                        );
                    }
                    (
                        found,
                        vec![
                            XyceSharedSteppedDcRepresentation::DirectTransform,
                            XyceSharedSteppedDcRepresentation::TransformInSubcircuitBody,
                            XyceSharedSteppedDcRepresentation::FunctionCallInSubcircuitBody,
                            XyceSharedSteppedDcRepresentation::FunctionCallAtInstance,
                        ],
                    )
                };
                if representations != expected {
                    return Err(format!(
                        "family '{}' does not contain the required ordered semantic representations",
                        owner_path.display()
                    ));
                }
                if topologies.into_iter().collect::<BTreeSet<_>>().len() != 1 {
                    return Err(format!(
                        "family '{}' members do not share identical ordered source/load topology",
                        owner_path.display()
                    ));
                }
                let baseline_plan = &plans[0];
                if plans.iter().skip(1).any(|plan| {
                    plan.print.probes != baseline_plan.print.probes
                        || !Self::dc_sweeps_match_exactly(&plan.dc, &baseline_plan.dc)
                        || !Self::step_commands_match_exactly(&plan.steps, &baseline_plan.steps)
                }) {
                    return Err(format!(
                        "family '{}' members do not share identical PRINT, DC, and STEP policies",
                        owner_path.display()
                    ));
                }
                let global_bits = netlists
                    .iter()
                    .zip(&plans)
                    .map(|(netlist, plan)| {
                        let step_name = &plan.steps[0].name;
                        netlist
                            .params
                            .numeric_parameters()
                            .into_iter()
                            .find(|(name, _)| name.eq_ignore_ascii_case(step_name))
                            .map(|(_, value)| value.to_bits())
                    })
                    .collect::<Option<BTreeSet<_>>>()
                    .ok_or_else(|| {
                        "every member must retain its stepped global's initial value".to_string()
                    })?;
                if global_bits.len() != 1 {
                    return Err(
                        "all members must share one identical stepped-global initial value"
                            .to_string(),
                    );
                }
                let formal_default_bits = netlists
                    .iter()
                    .filter_map(|netlist| netlist.subcircuits.first())
                    .map(|subcircuit| subcircuit.params[0].1.to_bits())
                    .collect::<BTreeSet<_>>();
                if formal_default_bits.len() != 1 {
                    return Err(
                        "all hierarchical members must share one identical formal default"
                            .to_string(),
                    );
                }
                let source_bits = netlists
                    .iter()
                    .filter_map(|netlist| {
                        netlist
                            .elements
                            .iter()
                            .find_map(|element| match element.kind {
                                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(
                                    value,
                                )) => Some(value.to_bits()),
                                _ => None,
                            })
                    })
                    .collect::<BTreeSet<_>>();
                if source_bits.len() != 1 {
                    return Err(
                        "all members must share one identical finite DC source value".to_string(),
                    );
                }
                let prn_reference_path = self
                    .static_output_reference_path(&owner_path, "prn")
                    .filter(|path| path.is_file())
                    .ok_or_else(|| "family anchor is missing its shared .prn oracle".to_string())?;
                let res_reference_path = self
                    .static_output_reference_path(&owner_path, "res")
                    .filter(|path| path.is_file())
                    .ok_or_else(|| "family anchor is missing its shared .res oracle".to_string())?;
                if belongs {
                    let member_index = member_paths
                        .iter()
                        .position(|path| Self::same_path(path, &deck.path));
                    let role = match member_index {
                        None => XyceSharedSteppedDcFamilyRole::Owner,
                        Some(0) => XyceSharedSteppedDcFamilyRole::Baseline(representations[0]),
                        Some(index) => {
                            XyceSharedSteppedDcFamilyRole::Member(representations[index])
                        }
                    };
                    selected = Some(XyceSharedSteppedDcFamilyContract {
                        family: owner_path
                            .file_stem()
                            .unwrap()
                            .to_string_lossy()
                            .to_string(),
                        baseline_path: member_paths[0].clone(),
                        owner_path,
                        member_paths,
                        prn_reference_path,
                        res_reference_path,
                        role,
                    });
                }
            }
            selected
                .ok_or_else(|| "deck is not claimed by the qualified directory census".to_string())
        })())
    }

    fn step_commands_match_exactly(left: &[StepCommand], right: &[StepCommand]) -> bool {
        fn sweep_matches(left: &StepSweep, right: &StepSweep) -> bool {
            match (left, right) {
                (
                    StepSweep::Linear {
                        start: a,
                        stop: b,
                        step: c,
                    },
                    StepSweep::Linear {
                        start: d,
                        stop: e,
                        step: f,
                    },
                ) => [a, b, c]
                    .into_iter()
                    .zip([d, e, f])
                    .all(|(x, y)| x.to_bits() == y.to_bits()),
                (
                    StepSweep::Decade {
                        points_per_decade: a,
                        start: b,
                        stop: c,
                    },
                    StepSweep::Decade {
                        points_per_decade: d,
                        start: e,
                        stop: f,
                    },
                )
                | (
                    StepSweep::Octave {
                        points_per_octave: a,
                        start: b,
                        stop: c,
                    },
                    StepSweep::Octave {
                        points_per_octave: d,
                        start: e,
                        stop: f,
                    },
                ) => a == d && b.to_bits() == e.to_bits() && c.to_bits() == f.to_bits(),
                (StepSweep::List(a), StepSweep::List(b)) => {
                    a.len() == b.len() && a.iter().zip(b).all(|(x, y)| x.to_bits() == y.to_bits())
                }
                (StepSweep::Data { table_name: a }, StepSweep::Data { table_name: b }) => {
                    a.eq_ignore_ascii_case(b)
                }
                _ => false,
            }
        }
        left.len() == right.len()
            && left.iter().zip(right).all(|(a, b)| {
                a.target == b.target
                    && a.name.eq_ignore_ascii_case(&b.name)
                    && a.param_name.as_deref().map(str::to_ascii_lowercase)
                        == b.param_name.as_deref().map(str::to_ascii_lowercase)
                    && sweep_matches(&a.sweep, &b.sweep)
            })
    }

    fn shared_stepped_dc_topology(netlist: &Netlist) -> Result<Vec<String>, String> {
        let source = netlist
            .elements
            .iter()
            .find(|element| {
                matches!(
                    &element.kind,
                    ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(_))
                )
            })
            .ok_or_else(|| "semantic member has no independent DC source".to_string())?;
        let source_value = match &source.kind {
            ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value)) => *value,
            _ => unreachable!("source was selected by its element kind"),
        };
        let source_nodes = source
            .nodes
            .iter()
            .map(|node| node.trim().to_ascii_lowercase())
            .collect::<Vec<_>>();
        if !source_value.is_finite()
            || source_nodes.len() != 2
            || source_nodes.iter().any(String::is_empty)
            || source_nodes[0] == "0"
            || source_nodes[1] != "0"
            || source_nodes[0] == source_nodes[1]
        {
            return Err(
                "semantic member requires one finite, non-degenerate two-terminal DC source oriented from a non-ground node to ground".to_string(),
            );
        }

        let load = netlist
            .elements
            .iter()
            .find(|element| {
                matches!(
                    &element.kind,
                    ElementKind::Resistor { .. } | ElementKind::Subcircuit { .. }
                )
            })
            .ok_or_else(|| "semantic member has no resistor load or subcircuit load".to_string())?;
        let load_nodes = load
            .nodes
            .iter()
            .map(|node| node.trim().to_ascii_lowercase())
            .collect::<Vec<_>>();
        if load_nodes != source_nodes {
            return Err(
                "semantic member load terminals must match the ordered DC-source terminals"
                    .to_string(),
            );
        }

        if let ElementKind::Subcircuit { subckt_name, .. } = &load.kind {
            let [subcircuit] = netlist.subcircuits.as_slice() else {
                return Err("semantic hierarchical member requires one subcircuit".to_string());
            };
            let [body_element] = subcircuit.elements.as_slice() else {
                return Err(
                    "semantic hierarchical member requires one subcircuit body element".to_string(),
                );
            };
            let ports = subcircuit
                .ports
                .iter()
                .map(|node| node.trim().to_ascii_lowercase())
                .collect::<Vec<_>>();
            let body_nodes = body_element
                .nodes
                .iter()
                .map(|node| node.trim().to_ascii_lowercase())
                .collect::<Vec<_>>();
            if !subcircuit.name.eq_ignore_ascii_case(subckt_name)
                || ports.len() != 2
                || ports.iter().any(|port| port.is_empty() || port == "0")
                || ports[0] == ports[1]
                || !matches!(&body_element.kind, ElementKind::Resistor { .. })
                || ports != body_nodes
            {
                return Err(
                    "semantic subcircuit resistor terminals must match its ordered two-port interface"
                        .to_string(),
                );
            }
        }

        Ok(source_nodes)
    }

    fn shared_stepped_dc_representation(
        netlist: &Netlist,
        plan: &XyceStaticDcPlan,
        expected_transform: Option<&str>,
    ) -> Result<(XyceSharedSteppedDcRepresentation, Option<String>), String> {
        let [step] = plan.steps.as_slice() else {
            return Err("semantic family member requires exactly one .STEP command".to_string());
        };
        if step.target != StepTarget::Param || step.name.trim().is_empty() {
            return Err("semantic family .STEP must target one named global parameter".to_string());
        }
        let globals = netlist.params.numeric_parameters();
        if globals.len() != 1
            || !globals[0].0.eq_ignore_ascii_case(&step.name)
            || !globals[0].1.is_finite()
            || !Self::source_has_sole_global_parameter_definition(&plan.source, &step.name)
            || !netlist.models.is_empty()
            || netlist.elements.len() != 2
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
        {
            return Err(format!(
                "semantic member must contain one true finite .GLOBAL_PARAM stepped definition and no auxiliary state outside its two-element DC harness (numeric={}, models={}, elements={}, data={}, ic={}, nodeset={}, measure={}, veriloga={}, spef={})",
                globals.len(),
                netlist.models.len(),
                netlist.elements.len(),
                netlist.data_tables.len(),
                netlist.initial_conditions.len(),
                netlist.node_sets.len(),
                netlist.measurements.len(),
                netlist.veriloga_includes.len(),
                netlist.spef_includes.len()
            ));
        }
        let top_resistor = netlist
            .elements
            .iter()
            .find_map(|element| match &element.kind {
                ElementKind::Resistor {
                    value_expr,
                    model: None,
                    instance_params,
                    deferred_params,
                    ..
                } if instance_params.is_empty() && deferred_params.is_empty() => {
                    Some((element, value_expr.as_deref()))
                }
                _ => None,
            });
        let top_instance = netlist
            .elements
            .iter()
            .find_map(|element| match &element.kind {
                ElementKind::Subcircuit {
                    subckt_name,
                    params,
                } => Some((subckt_name, params)),
                _ => None,
            });
        if netlist
            .elements
            .iter()
            .filter(|element| {
                matches!(
                    element.kind,
                    ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(_))
                )
            })
            .count()
            != 1
        {
            return Err(
                "semantic member requires exactly one independent DC voltage source".to_string(),
            );
        }
        let functions = netlist.params.all_functions();
        if let Some((resistor, expression)) = top_resistor {
            if top_instance.is_some() || !netlist.subcircuits.is_empty() || !functions.is_empty() {
                return Err(
                    "direct semantic baseline may not contain hierarchy or functions".to_string(),
                );
            }
            if Self::source_has_bare_resistor_parameter_value(
                &plan.source,
                &resistor.name,
                &step.name,
            ) {
                return Ok((XyceSharedSteppedDcRepresentation::DirectIdentity, None));
            }
            let expression = expression.ok_or_else(|| {
                "direct transform baseline must retain a parameter expression".to_string()
            })?;
            let transform = Self::alpha_normalize_expression(expression, &[(&step.name, "$x")]);
            if transform == "$x" || transform.is_empty() {
                return Err("direct transform baseline must be non-identity".to_string());
            }
            return Ok((
                XyceSharedSteppedDcRepresentation::DirectTransform,
                Some(transform),
            ));
        }
        let (subckt_name, instance_params) = top_instance.ok_or_else(|| {
            "semantic member requires one resistor or subcircuit instance".to_string()
        })?;
        let [subckt] = netlist.subcircuits.as_slice() else {
            return Err("hierarchical semantic member requires exactly one subcircuit".to_string());
        };
        if !subckt.name.eq_ignore_ascii_case(subckt_name)
            || subckt.ports.len() != 2
            || subckt.elements.len() != 1
            || subckt.params.len() != 1
            || !subckt.params[0].1.is_finite()
            || !subckt.expr_params.is_empty()
            || !subckt.string_params.is_empty()
            || !subckt.body_params.is_empty()
            || !subckt.body_expr_params.is_empty()
            || !subckt.body_string_params.is_empty()
            || !subckt.body_functions.is_empty()
            || !subckt.local_options.is_empty()
            || !subckt.initial_conditions.is_empty()
            || !subckt.node_sets.is_empty()
            || !subckt.nested_subcircuits.is_empty()
        {
            return Err(
                "hierarchical semantic member has an unqualified subcircuit signature".to_string(),
            );
        }
        let formal_name = &subckt.params[0].0;
        let [(binding_name, ParametricValue::Expression(binding))] = instance_params.as_slice()
        else {
            return Err(
                "subcircuit instance requires one deferred formal-parameter binding".to_string(),
            );
        };
        if !binding_name.eq_ignore_ascii_case(formal_name) {
            return Err(
                "subcircuit instance binding must name its sole formal parameter".to_string(),
            );
        }
        let resistor_expression = match &subckt.elements[0].kind {
            ElementKind::Resistor {
                value_expr: Some(expression),
                model: None,
                instance_params,
                deferred_params,
                ..
            } if instance_params.is_empty() && deferred_params.is_empty() => expression.as_str(),
            _ => return Err("subcircuit must contain one expression-valued resistor".to_string()),
        };
        let binding_to_global = Self::alpha_normalize_expression(binding, &[(&step.name, "$g")]);
        let resistor_to_formal =
            Self::alpha_normalize_expression(resistor_expression, &[(formal_name, "$f")]);
        if functions.is_empty() {
            if expected_transform.is_none()
                && binding_to_global == "$g"
                && resistor_to_formal == "$f"
            {
                return Ok((
                    XyceSharedSteppedDcRepresentation::HierarchicalIdentity,
                    None,
                ));
            }
            if let Some(transform) = expected_transform {
                let body =
                    Self::alpha_normalize_expression(resistor_expression, &[(formal_name, "$x")]);
                if binding_to_global == "$g" && body == transform {
                    return Ok((
                        XyceSharedSteppedDcRepresentation::TransformInSubcircuitBody,
                        None,
                    ));
                }
            }
            return Err("unrecognized hierarchy-only transform representation".to_string());
        }
        let [function] = functions.as_slice() else {
            return Err(
                "function representation requires exactly one user-defined function".to_string(),
            );
        };
        let [argument] = function.args.as_slice() else {
            return Err("family transform function requires exactly one argument".to_string());
        };
        let transform = expected_transform.ok_or_else(|| {
            "identity family may not introduce a user-defined transform".to_string()
        })?;
        if Self::alpha_normalize_expression(&function.body, &[(argument, "$x")]) != transform {
            return Err(
                "function body is not alpha-equivalent to the direct transform".to_string(),
            );
        }
        let resistor_call = Self::alpha_normalize_expression(
            resistor_expression,
            &[(formal_name, "$f"), (&function.name, "$fn")],
        );
        let binding_call = Self::alpha_normalize_expression(
            binding,
            &[(&step.name, "$g"), (&function.name, "$fn")],
        );
        match (binding_call.as_str(), resistor_call.as_str()) {
            ("$g", "$fn($f)") => Ok((
                XyceSharedSteppedDcRepresentation::FunctionCallInSubcircuitBody,
                None,
            )),
            ("$fn($g)", "$f") => Ok((
                XyceSharedSteppedDcRepresentation::FunctionCallAtInstance,
                None,
            )),
            _ => Err("unrecognized function placement in hierarchical transform".to_string()),
        }
    }

    fn source_has_bare_resistor_parameter_value(
        source: &str,
        resistor_name: &str,
        parameter_name: &str,
    ) -> bool {
        let mut matching_lines = source.lines().filter_map(|line| {
            let line = line.trim();
            if line.is_empty() || line.starts_with('*') {
                return None;
            }
            let fields = line.split_ascii_whitespace().collect::<Vec<_>>();
            fields
                .first()
                .is_some_and(|name| name.eq_ignore_ascii_case(resistor_name))
                .then_some(fields)
        });
        let Some(fields) = matching_lines.next() else {
            return false;
        };
        matching_lines.next().is_none() && {
            fields.len() == 4
                && fields[3]
                    .trim_matches(['{', '}'])
                    .eq_ignore_ascii_case(parameter_name)
        }
    }

    fn source_has_sole_global_parameter_definition(source: &str, parameter_name: &str) -> bool {
        let mut definitions = source.lines().filter_map(|line| {
            let line = line.trim();
            if line.is_empty() || line.starts_with('*') {
                return None;
            }
            let compact = line
                .chars()
                .filter(|character| !character.is_ascii_whitespace())
                .collect::<String>();
            compact
                .get(..13)
                .is_some_and(|prefix| prefix.eq_ignore_ascii_case(".global_param"))
                .then_some(compact)
        });
        let Some(definition) = definitions.next() else {
            return false;
        };
        if definitions.next().is_some() {
            return false;
        }
        let Some(assignment) = definition.get(13..) else {
            return false;
        };
        let Some((name, expression)) = assignment.split_once('=') else {
            return false;
        };
        !expression.is_empty()
            && !expression.contains(',')
            && name.eq_ignore_ascii_case(parameter_name)
    }

    fn alpha_normalize_expression(text: &str, substitutions: &[(&str, &str)]) -> String {
        let mut result = String::new();
        let mut token = String::new();
        let flush = |token: &mut String, result: &mut String| {
            if token.is_empty() {
                return;
            }
            if let Some((_, replacement)) = substitutions
                .iter()
                .find(|(name, _)| name.eq_ignore_ascii_case(token))
            {
                result.push_str(replacement);
            } else {
                result.push_str(&token.to_ascii_lowercase());
            }
            token.clear();
        };
        for character in text.chars() {
            if character.is_ascii_alphanumeric() || character == '_' {
                token.push(character);
            } else {
                flush(&mut token, &mut result);
                if !character.is_ascii_whitespace() && character != '{' && character != '}' {
                    result.push(character.to_ascii_lowercase());
                }
            }
        }
        flush(&mut token, &mut result);
        result
    }

    fn stepped_ic_reference_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<XyceSteppedIcReferenceContract> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/") {
            return None;
        }
        let parent = deck.path.parent()?;
        let stem = deck.path.file_stem()?.to_str()?;
        let stem_lower = stem.to_ascii_lowercase();
        let family = if let Some(family) = stem_lower.strip_suffix("_step") {
            (!family.is_empty()).then_some(family.to_string())?
        } else {
            let digit_start = stem_lower
                .char_indices()
                .rev()
                .find(|(_, ch)| !ch.is_ascii_digit())
                .map_or(0, |(index, ch)| index + ch.len_utf8());
            if digit_start == 0 || digit_start == stem_lower.len() {
                return None;
            }
            stem_lower[..digit_start].to_string()
        };
        let owner_stem = format!("{family}_step");
        let mut owner_path = None;
        let mut numbered = BTreeMap::new();
        for entry in fs::read_dir(parent).ok()? {
            let entry = entry.ok()?;
            let path = entry.path();
            if !entry.file_type().ok()?.is_file()
                || !path
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
            {
                continue;
            }
            let candidate_stem = path.file_stem()?.to_str()?.to_ascii_lowercase();
            if candidate_stem == owner_stem {
                if owner_path.replace(path).is_some() {
                    return None;
                }
                continue;
            }
            let Some(index_text) = candidate_stem.strip_prefix(&family) else {
                continue;
            };
            if index_text.is_empty() || !index_text.bytes().all(|byte| byte.is_ascii_digit()) {
                continue;
            }
            let index = index_text.parse::<usize>().ok()?;
            if numbered.insert(index, path).is_some() {
                return None;
            }
        }
        let owner_path = owner_path?;
        if !self.requires_upstream_wrapper(&self.relative_key(&owner_path)) {
            return None;
        }
        if numbered.len() < 2 || numbered.keys().copied().ne(0..numbered.len()) {
            return None;
        }
        let member_paths = numbered.into_values().collect::<Vec<_>>();
        if member_paths.iter().any(|path| {
            self.requires_upstream_wrapper(&self.relative_key(path))
                || fs::metadata(path)
                    .ok()
                    .is_none_or(|metadata| !metadata.is_file() || metadata.len() == 0)
        }) || fs::metadata(&owner_path)
            .ok()
            .is_none_or(|metadata| !metadata.is_file() || metadata.len() == 0)
        {
            return None;
        }
        if !Self::same_path(&deck.path, &owner_path)
            && !member_paths
                .iter()
                .any(|path| Self::same_path(path, &deck.path))
        {
            return None;
        }

        Some(XyceSteppedIcReferenceContract {
            family,
            owner_path,
            member_paths,
            target_path: deck.path.clone(),
        })
    }

    fn analytic_generated_wrapper_source(&self, deck: &XyceDeck) -> Option<String> {
        let relative_path = Self::normalize_manifest_key(&deck.relative_path);
        if !relative_path.starts_with("netlists/")
            || !self.requires_upstream_wrapper(&deck.relative_path)
            || fs::metadata(&deck.path)
                .ok()
                .is_none_or(|metadata| !metadata.is_file() || metadata.len() == 0)
            || self.has_static_tran_reference_oracle(&deck.path)
        {
            return None;
        }
        fs::read_to_string(&deck.path).ok()
    }

    fn analytic_rc_wrapper_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceAnalyticRcContract, String>> {
        let source = self.analytic_generated_wrapper_source(deck)?;
        if !Self::is_analytic_rc_wrapper_candidate(&source) {
            return None;
        }
        Some((|| {
            let source_contract = Self::analytic_rc_source_contract(&source)?;
            let plan = self.static_tran_plan_for_path_with_purpose(
                &deck.path,
                XyceStaticTranPlanPurpose::AnalyticOracle,
            )?;
            Self::validate_analytic_rc_plan(&plan, &source_contract)?;
            let netlist = Self::parse_xyce_netlist(&plan.source, &plan.deck_path)
                .map_err(|err| format!("netlist parser rejected analytic RC deck: {err}"))?;
            let specification = Self::analytic_rc_specification(&netlist, &plan, &source_contract)?;
            Ok(XyceAnalyticRcContract {
                plan,
                specification,
            })
        })())
    }

    fn analytic_sinusoidal_rc_wrapper_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceAnalyticSinusoidalRcContract, String>> {
        let source = self.analytic_generated_wrapper_source(deck)?;
        if !Self::is_analytic_sinusoidal_rc_wrapper_candidate(&source) {
            return None;
        }
        Some((|| {
            let source_contract = Self::analytic_sinusoidal_rc_source_contract(&source)?;
            let plan = self.static_tran_plan_for_path_with_purpose(
                &deck.path,
                XyceStaticTranPlanPurpose::AnalyticOracle,
            )?;
            Self::validate_analytic_sinusoidal_rc_plan(&plan, &source_contract)?;
            let netlist =
                Self::parse_xyce_netlist(&plan.source, &plan.deck_path).map_err(|err| {
                    format!("netlist parser rejected analytic sinusoidal RC deck: {err}")
                })?;
            let specification =
                Self::analytic_sinusoidal_rc_specification(&netlist, &plan, &source_contract)?;
            let tolerance = XyceVerifyTransientTolerance {
                relative: Value::from_bits(source_contract.verify_reltol_bits),
                absolute: Value::from_bits(source_contract.verify_abstol_bits),
                zero: XYCE_VERIFY_DEFAULT_ZERO_TOLERANCE,
                absolute_difference: XYCE_VERIFY_DEFAULT_ABSOLUTE_DIFFERENCE_TOLERANCE,
                offset: 0.0,
            }
            .validate()?;
            Ok(XyceAnalyticSinusoidalRcContract {
                plan,
                specification,
                tolerance,
            })
        })())
    }

    fn analytic_integer_dc_wrapper_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceAnalyticIntegerDcContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        let kind = match relative.as_str() {
            XYCE_ANALYTIC_FMOD_DC_RECORD => XyceAnalyticIntegerDcKind::Fmod,
            XYCE_ANALYTIC_INT_FLOOR_CEIL_DC_RECORD => {
                XyceAnalyticIntegerDcKind::IntFloorCeilBehavioralSources
            }
            _ => return None,
        };
        Some((|| {
            if !self.requires_upstream_wrapper(&deck.relative_path) {
                return Err("record is not owned by the wrapper provenance manifest".to_string());
            }
            let metadata = fs::metadata(&deck.path)
                .map_err(|err| format!("could not inspect wrapper deck: {err}"))?;
            if !metadata.is_file() || metadata.len() == 0 {
                return Err("wrapper deck must be a nonempty regular file".to_string());
            }
            self.reject_wrapper_output_artifacts(&deck.path)?;
            let plan = self.static_dc_plan_for_path(&deck.path, ExpressionDialect::Xyce)?;
            let netlist =
                Self::parse_xyce_netlist(&plan.source, &plan.deck_path).map_err(|err| {
                    format!("netlist parser rejected analytic integer DC deck: {err}")
                })?;
            Self::validate_analytic_integer_dc_plan(&plan, &netlist, kind)?;
            Ok(XyceAnalyticIntegerDcContract { plan, kind })
        })())
    }

    fn resistor_dtemp_relational_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceResistorDtempContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        let role = match relative.as_str() {
            XYCE_RESISTOR_DTEMP_OWNER_RECORD => XyceResistorDtempRole::Owner,
            XYCE_RESISTOR_DTEMP_REFERENCE_RECORD => XyceResistorDtempRole::Reference,
            _ => return None,
        };
        Some((|| {
            let parent = deck
                .path
                .parent()
                .ok_or_else(|| "resistor DTEMP record has no sibling directory".to_string())?;
            let owner_path = parent.join("res_dtemp.cir");
            let reference_path = parent.join("res_ref.cir");
            if Self::normalize_manifest_key(&self.relative_key(&owner_path))
                != XYCE_RESISTOR_DTEMP_OWNER_RECORD
                || Self::normalize_manifest_key(&self.relative_key(&reference_path))
                    != XYCE_RESISTOR_DTEMP_REFERENCE_RECORD
            {
                return Err(
                    "owner/reference paths do not form the exact manifest-owned sibling pair"
                        .to_string(),
                );
            }
            if !self.requires_upstream_wrapper(XYCE_RESISTOR_DTEMP_OWNER_RECORD)
                || self.requires_upstream_wrapper(XYCE_RESISTOR_DTEMP_REFERENCE_RECORD)
            {
                return Err(
                    "exactly res_dtemp.cir must own the removed upstream wrapper".to_string(),
                );
            }
            for (member_role, path) in [("owner", &owner_path), ("reference", &reference_path)] {
                let metadata = fs::metadata(path)
                    .map_err(|err| format!("could not inspect {member_role} sibling: {err}"))?;
                if !metadata.is_file() || metadata.len() == 0 {
                    return Err(format!(
                        "resistor DTEMP {member_role} sibling must be a nonempty regular file"
                    ));
                }
                self.reject_wrapper_output_artifacts(path)
                    .map_err(|err| format!("resistor DTEMP {member_role} {err}"))?;
            }

            let owner_plan = self.static_dc_plan_for_path(&owner_path, ExpressionDialect::Xyce)?;
            let reference_plan =
                self.static_dc_plan_for_path(&reference_path, ExpressionDialect::Xyce)?;
            let owner_netlist = Self::parse_xyce_netlist(&owner_plan.source, &owner_path)
                .map_err(|err| format!("owner netlist parse failed: {err}"))?;
            let reference_netlist =
                Self::parse_xyce_netlist(&reference_plan.source, &reference_path)
                    .map_err(|err| format!("reference netlist parse failed: {err}"))?;
            let owner_snapshot = Self::resistor_dtemp_snapshot(
                &owner_plan,
                &owner_netlist,
                XyceResistorDtempRole::Owner,
            )?;
            let reference_snapshot = Self::resistor_dtemp_snapshot(
                &reference_plan,
                &reference_netlist,
                XyceResistorDtempRole::Reference,
            )?;
            if owner_snapshot != reference_snapshot {
                return Err(format!(
                    "owner/reference semantics differ after TEMP-versus-DTEMP normalization: owner={owner_snapshot:?}, reference={reference_snapshot:?}"
                ));
            }
            Ok(XyceResistorDtempContract {
                owner_plan,
                reference_plan,
                role,
            })
        })())
    }

    fn bug647_resistor_relational_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceBug647ResistorContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        let role = match relative.as_str() {
            XYCE_BUG647_RESISTOR_OWNER_RECORD => XyceBug647ResistorRole::Owner,
            XYCE_BUG647_RESISTOR_REFERENCE_RECORD => {
                XyceBug647ResistorRole::ModelParameterReference
            }
            _ => return None,
        };
        Some((|| {
            let parent = deck
                .path
                .parent()
                .ok_or_else(|| "BUG 647 resistor record has no sibling directory".to_string())?;
            let owner_path = parent.join("semic_resistor.cir");
            let reference_path = parent.join("semic_resistor_modpar.cir");
            if Self::normalize_manifest_key(&self.relative_key(&owner_path))
                != XYCE_BUG647_RESISTOR_OWNER_RECORD
                || Self::normalize_manifest_key(&self.relative_key(&reference_path))
                    != XYCE_BUG647_RESISTOR_REFERENCE_RECORD
            {
                return Err("owner/reference paths are not the exact BUG 647 sibling pair".into());
            }
            if !self.requires_upstream_wrapper(XYCE_BUG647_RESISTOR_OWNER_RECORD)
                || self.requires_upstream_wrapper(XYCE_BUG647_RESISTOR_REFERENCE_RECORD)
            {
                return Err(
                    "exactly semic_resistor.cir must own the removed upstream wrapper".into(),
                );
            }
            for (member_role, path) in [
                ("instance-parameter owner", &owner_path),
                ("model-parameter reference", &reference_path),
            ] {
                let metadata = fs::metadata(path)
                    .map_err(|err| format!("could not inspect {member_role}: {err}"))?;
                if !metadata.is_file() || metadata.len() == 0 {
                    return Err(format!("{member_role} must be a nonempty regular file"));
                }
                self.reject_wrapper_output_artifacts(path)
                    .map_err(|err| format!("{member_role} {err}"))?;
            }
            let owner_plan = self.static_dc_plan_for_path(&owner_path, ExpressionDialect::Xyce)?;
            let reference_plan =
                self.static_dc_plan_for_path(&reference_path, ExpressionDialect::Xyce)?;
            let owner_netlist = Self::parse_xyce_netlist(&owner_plan.source, &owner_path)
                .map_err(|err| format!("instance-parameter owner parse failed: {err}"))?;
            let reference_netlist =
                Self::parse_xyce_netlist(&reference_plan.source, &reference_path)
                    .map_err(|err| format!("model-parameter reference parse failed: {err}"))?;
            Self::validate_bug647_resistor_member(
                &owner_plan,
                &owner_netlist,
                XyceBug647ResistorRole::Owner,
            )?;
            Self::validate_bug647_resistor_member(
                &reference_plan,
                &reference_netlist,
                XyceBug647ResistorRole::ModelParameterReference,
            )?;
            Ok(XyceBug647ResistorContract {
                owner_plan,
                reference_plan,
                role,
            })
        })())
    }

    fn bug655_continuation_relational_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceBug655ContinuationContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        let role = match relative.as_str() {
            XYCE_BUG655_CONTINUATION_OWNER_RECORD => XyceBug655ContinuationRole::ColumnZeroOwner,
            XYCE_BUG655_CONTINUATION_REFERENCE_RECORD => {
                XyceBug655ContinuationRole::LeadingSpaceReference
            }
            _ => return None,
        };
        Some((|| {
            let parent = deck
                .path
                .parent()
                .ok_or_else(|| "BUG 655 record has no sibling directory".to_string())?;
            let owner_path = parent.join("contLine.cir");
            let reference_path = parent.join("contLine_with_spaces.cir");
            if Self::normalize_manifest_key(&self.relative_key(&owner_path))
                != XYCE_BUG655_CONTINUATION_OWNER_RECORD
                || Self::normalize_manifest_key(&self.relative_key(&reference_path))
                    != XYCE_BUG655_CONTINUATION_REFERENCE_RECORD
            {
                return Err("owner/reference paths are not the exact BUG 655 sibling pair".into());
            }
            if !self.requires_upstream_wrapper(XYCE_BUG655_CONTINUATION_OWNER_RECORD)
                || self.requires_upstream_wrapper(XYCE_BUG655_CONTINUATION_REFERENCE_RECORD)
            {
                return Err("exactly contLine.cir must own the removed upstream wrapper".into());
            }

            let mut directory_entries = fs::read_dir(parent)
                .map_err(|err| format!("could not inspect BUG 655 directory: {err}"))?
                .map(|entry| {
                    let entry =
                        entry.map_err(|err| format!("could not inspect BUG 655 entry: {err}"))?;
                    let file_type = entry
                        .file_type()
                        .map_err(|err| format!("could not inspect BUG 655 entry type: {err}"))?;
                    let name = entry.file_name().into_string().map_err(|_| {
                        "BUG 655 directory contains a non-Unicode entry".to_string()
                    })?;
                    Ok((name, file_type.is_file()))
                })
                .collect::<Result<Vec<_>, String>>()?;
            directory_entries.sort();
            if directory_entries
                != [
                    ("contLine.cir".to_string(), true),
                    ("contLine_with_spaces.cir".to_string(), true),
                ]
            {
                return Err(format!(
                    "BUG 655 directory must contain exactly its two regular .cir records, got {directory_entries:?}"
                ));
            }
            for (member_role, path) in [
                ("column-zero continuation owner", &owner_path),
                ("leading-space continuation reference", &reference_path),
            ] {
                let metadata = fs::metadata(path)
                    .map_err(|err| format!("could not inspect {member_role}: {err}"))?;
                if !metadata.is_file() || metadata.len() == 0 {
                    return Err(format!("{member_role} must be a nonempty regular file"));
                }
                self.reject_wrapper_output_artifacts(path)
                    .map_err(|err| format!("{member_role} {err}"))?;
            }

            let owner_source = fs::read_to_string(&owner_path)
                .map_err(|err| format!("failed to read BUG 655 owner: {err}"))?;
            let reference_source = fs::read_to_string(&reference_path)
                .map_err(|err| format!("failed to read BUG 655 reference: {err}"))?;
            Self::validate_bug655_continuation_source_pair(&owner_source, &reference_source)?;

            let owner_plan = self.static_dc_plan_for_path(&owner_path, ExpressionDialect::Xyce)?;
            let reference_plan =
                self.static_dc_plan_for_path(&reference_path, ExpressionDialect::Xyce)?;
            let owner_netlist = Self::parse_xyce_netlist(&owner_plan.source, &owner_path)
                .map_err(|err| format!("BUG 655 owner parse failed: {err}"))?;
            let reference_netlist =
                Self::parse_xyce_netlist(&reference_plan.source, &reference_path)
                    .map_err(|err| format!("BUG 655 reference parse failed: {err}"))?;
            Self::validate_bug655_continuation_member(
                &owner_plan,
                &owner_netlist,
                XyceBug655ContinuationRole::ColumnZeroOwner,
            )?;
            Self::validate_bug655_continuation_member(
                &reference_plan,
                &reference_netlist,
                XyceBug655ContinuationRole::LeadingSpaceReference,
            )?;
            Self::validate_bug655_continuation_semantic_identity(
                &owner_netlist,
                &reference_netlist,
            )?;

            Ok(XyceBug655ContinuationContract {
                owner_plan,
                reference_plan,
                role,
            })
        })())
    }

    fn bug662_long_header_relational_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceBug662HeaderContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        let role = match relative.as_str() {
            XYCE_BUG662_LONG_HEADER_OWNER_RECORD => XyceBug662HeaderRole::LongHeaderOwner,
            XYCE_BUG662_SHORT_HEADER_REFERENCE_RECORD => XyceBug662HeaderRole::ShortHeaderReference,
            _ => return None,
        };
        Some((|| {
            let parent = deck
                .path
                .parent()
                .ok_or_else(|| "BUG 662 record has no sibling directory".to_string())?;
            let owner_path = parent.join("headerLineLengthMoreThan256.cir");
            let reference_path = parent.join("headerLineLengthLessThan256.cir");
            if Self::normalize_manifest_key(&self.relative_key(&owner_path))
                != XYCE_BUG662_LONG_HEADER_OWNER_RECORD
                || Self::normalize_manifest_key(&self.relative_key(&reference_path))
                    != XYCE_BUG662_SHORT_HEADER_REFERENCE_RECORD
            {
                return Err("owner/reference paths are not the exact BUG 662 sibling pair".into());
            }
            if !self.requires_upstream_wrapper(XYCE_BUG662_LONG_HEADER_OWNER_RECORD)
                || self.requires_upstream_wrapper(XYCE_BUG662_SHORT_HEADER_REFERENCE_RECORD)
            {
                return Err(
                    "exactly headerLineLengthMoreThan256.cir must own the removed wrapper".into(),
                );
            }
            for (member_role, path) in [
                ("long-header owner", &owner_path),
                ("short-header reference", &reference_path),
            ] {
                let metadata = fs::metadata(path)
                    .map_err(|err| format!("could not inspect {member_role}: {err}"))?;
                if !metadata.is_file() || metadata.len() == 0 {
                    return Err(format!("{member_role} must be a nonempty regular file"));
                }
                self.reject_wrapper_output_artifacts(path)
                    .map_err(|err| format!("{member_role} {err}"))?;
            }

            let owner_source = fs::read_to_string(&owner_path)
                .map_err(|err| format!("failed to read long-header owner: {err}"))?;
            let reference_source = fs::read_to_string(&reference_path)
                .map_err(|err| format!("failed to read short-header reference: {err}"))?;
            Self::validate_bug662_header_source_pair(&owner_source, &reference_source)?;

            let owner_plan = self.static_tran_plan_for_path_with_purpose(
                &owner_path,
                XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily,
            )?;
            let reference_plan = self.static_tran_plan_for_path_with_purpose(
                &reference_path,
                XyceStaticTranPlanPurpose::RelationalFamily,
            )?;
            let owner_netlist = Self::parse_xyce_netlist(&owner_plan.source, &owner_path)
                .map_err(|err| format!("long-header owner parse failed: {err}"))?;
            let reference_netlist =
                Self::parse_xyce_netlist(&reference_plan.source, &reference_path)
                    .map_err(|err| format!("short-header reference parse failed: {err}"))?;
            Self::validate_bug662_header_member(
                &owner_plan,
                &owner_netlist,
                XyceBug662HeaderRole::LongHeaderOwner,
            )?;
            Self::validate_bug662_header_member(
                &reference_plan,
                &reference_netlist,
                XyceBug662HeaderRole::ShortHeaderReference,
            )?;
            Ok(XyceBug662HeaderContract {
                owner_plan,
                reference_plan,
                role,
            })
        })())
    }

    fn bug667_nodeset_relational_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceBug667NodesetContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        let role = match relative.as_str() {
            XYCE_BUG667_NODESET_OWNER_RECORD => XyceBug667NodesetRole::ScopedOwner,
            XYCE_BUG667_NODESET_REFERENCE_RECORD => {
                XyceBug667NodesetRole::ExplicitHierarchicalReference
            }
            _ => return None,
        };
        Some((|| {
            let parent = deck
                .path
                .parent()
                .ok_or_else(|| "BUG 667 NODESET record has no sibling directory".to_string())?;
            let owner_path = parent.join("nodeset_in_subckt.cir");
            let reference_path = parent.join("nodeset_not_in_subckt.cir");
            if Self::normalize_manifest_key(&self.relative_key(&owner_path))
                != XYCE_BUG667_NODESET_OWNER_RECORD
                || Self::normalize_manifest_key(&self.relative_key(&reference_path))
                    != XYCE_BUG667_NODESET_REFERENCE_RECORD
            {
                return Err("owner/reference paths are not the exact BUG 667 sibling pair".into());
            }
            if !self.requires_upstream_wrapper(XYCE_BUG667_NODESET_OWNER_RECORD)
                || self.requires_upstream_wrapper(XYCE_BUG667_NODESET_REFERENCE_RECORD)
            {
                return Err(
                    "exactly nodeset_in_subckt.cir must own the removed upstream wrapper".into(),
                );
            }
            for (member_role, path) in [
                ("subcircuit-scoped owner", &owner_path),
                ("explicit hierarchical reference", &reference_path),
            ] {
                let metadata = fs::metadata(path)
                    .map_err(|err| format!("could not inspect {member_role}: {err}"))?;
                if !metadata.is_file() || metadata.len() == 0 {
                    return Err(format!("{member_role} must be a nonempty regular file"));
                }
                self.reject_wrapper_output_artifacts(path)
                    .map_err(|err| format!("{member_role} {err}"))?;
            }

            let owner_plan = self.static_tran_plan_for_path_with_purpose(
                &owner_path,
                XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily,
            )?;
            let reference_plan = self.static_tran_plan_for_path_with_purpose(
                &reference_path,
                XyceStaticTranPlanPurpose::RelationalFamily,
            )?;
            let owner_netlist = Self::parse_xyce_netlist(&owner_plan.source, &owner_path)
                .map_err(|err| format!("subcircuit-scoped owner parse failed: {err}"))?;
            let reference_netlist =
                Self::parse_xyce_netlist(&reference_plan.source, &reference_path).map_err(
                    |err| format!("explicit hierarchical reference parse failed: {err}"),
                )?;
            Self::validate_bug667_nodeset_member(
                &owner_plan,
                &owner_netlist,
                XyceBug667NodesetRole::ScopedOwner,
            )?;
            Self::validate_bug667_nodeset_member(
                &reference_plan,
                &reference_netlist,
                XyceBug667NodesetRole::ExplicitHierarchicalReference,
            )?;

            let owner_nodesets = Self::bug667_effective_nodeset_map(&owner_netlist)?;
            let reference_nodesets = Self::bug667_effective_nodeset_map(&reference_netlist)?;
            let expected_nodesets = BTreeMap::from([
                ("n15967".to_string(), 0.5f64.to_bits()),
                ("x_x1.mid".to_string(), 0.5f64.to_bits()),
            ]);
            if owner_nodesets != expected_nodesets
                || reference_nodesets != expected_nodesets
                || owner_nodesets != reference_nodesets
            {
                return Err(format!(
                    "BUG 667 effective NODESET maps differ from the exact hierarchical equivalence contract: owner={owner_nodesets:?} reference={reference_nodesets:?}"
                ));
            }

            Ok(XyceBug667NodesetContract {
                owner_plan,
                reference_plan,
                role,
            })
        })())
    }

    fn bug754_global_parameter_relational_contract(
        &self,
        deck: &XyceDeck,
    ) -> Option<Result<XyceBug754GlobalParameterContract, String>> {
        let relative = Self::normalize_manifest_key(&deck.relative_path);
        let role = match relative.as_str() {
            XYCE_BUG754_GLOBAL_PARAMETER_OWNER_RECORD => {
                XyceBug754GlobalParameterRole::GlobalParameterOwner
            }
            XYCE_BUG754_LITERAL_REFERENCE_RECORD => XyceBug754GlobalParameterRole::LiteralReference,
            _ => return None,
        };
        Some((|| {
            let parent = deck
                .path
                .parent()
                .ok_or_else(|| "BUG 754 record has no sibling directory".to_string())?;
            let owner_path = parent.join("dcsweep_globalpar.cir");
            let reference_path = parent.join("dcsweep_nopar.cir");
            if Self::normalize_manifest_key(&self.relative_key(&owner_path))
                != XYCE_BUG754_GLOBAL_PARAMETER_OWNER_RECORD
                || Self::normalize_manifest_key(&self.relative_key(&reference_path))
                    != XYCE_BUG754_LITERAL_REFERENCE_RECORD
            {
                return Err("owner/reference paths are not the exact BUG 754 sibling pair".into());
            }
            if !self.requires_upstream_wrapper(XYCE_BUG754_GLOBAL_PARAMETER_OWNER_RECORD)
                || self.requires_upstream_wrapper(XYCE_BUG754_LITERAL_REFERENCE_RECORD)
            {
                return Err(
                    "exactly dcsweep_globalpar.cir must own the removed upstream wrapper".into(),
                );
            }

            let mut family_members = BTreeSet::new();
            for entry in fs::read_dir(parent)
                .map_err(|err| format!("could not inspect BUG 754 directory: {err}"))?
            {
                let entry =
                    entry.map_err(|err| format!("could not inspect BUG 754 entry: {err}"))?;
                let path = entry.path();
                let file_name = entry.file_name();
                let name = file_name
                    .to_str()
                    .ok_or_else(|| "BUG 754 directory contains a non-Unicode entry".to_string())?;
                let normalized_name = name.to_ascii_lowercase();
                if normalized_name.starts_with("dcsweep_")
                    && path
                        .extension()
                        .and_then(|extension| extension.to_str())
                        .is_some_and(|extension| extension.eq_ignore_ascii_case("cir"))
                {
                    let metadata = fs::symlink_metadata(&path)
                        .map_err(|err| format!("could not inspect BUG 754 family member: {err}"))?;
                    if !metadata.file_type().is_file()
                        || metadata.file_type().is_symlink()
                        || metadata.len() == 0
                    {
                        return Err(format!(
                            "BUG 754 family member '{}' must be a nonempty regular non-symlink file",
                            path.display()
                        ));
                    }
                    Self::insert_bug754_family_member_name(&mut family_members, name)?;
                }
            }
            if family_members
                != BTreeSet::from([
                    "dcsweep_globalpar.cir".to_string(),
                    "dcsweep_nopar.cir".to_string(),
                ])
            {
                return Err(format!(
                    "BUG 754 dcsweep family must contain exactly its two records, got {family_members:?}"
                ));
            }
            for (member_role, path) in [
                ("global-parameter owner", &owner_path),
                ("literal reference", &reference_path),
            ] {
                self.reject_wrapper_output_artifacts(path)
                    .map_err(|err| format!("{member_role} {err}"))?;
            }

            let owner_source = fs::read_to_string(&owner_path)
                .map_err(|err| format!("failed to read BUG 754 owner: {err}"))?;
            let reference_source = fs::read_to_string(&reference_path)
                .map_err(|err| format!("failed to read BUG 754 reference: {err}"))?;
            Self::validate_bug754_source_pair(&owner_source, &reference_source)?;

            let owner_plan = self.static_dc_plan_for_path(&owner_path, ExpressionDialect::Xyce)?;
            let reference_plan =
                self.static_dc_plan_for_path(&reference_path, ExpressionDialect::Xyce)?;
            let owner_netlist = Self::parse_xyce_netlist(&owner_plan.source, &owner_path)
                .map_err(|err| format!("BUG 754 owner parse failed: {err}"))?;
            let reference_netlist =
                Self::parse_xyce_netlist(&reference_plan.source, &reference_path)
                    .map_err(|err| format!("BUG 754 reference parse failed: {err}"))?;
            Self::validate_bug754_member(
                &owner_plan,
                &owner_netlist,
                XyceBug754GlobalParameterRole::GlobalParameterOwner,
            )?;
            Self::validate_bug754_member(
                &reference_plan,
                &reference_netlist,
                XyceBug754GlobalParameterRole::LiteralReference,
            )?;
            let owner_snapshot =
                Self::bug754_global_parameter_snapshot(&owner_plan, &owner_netlist)?;
            let reference_snapshot =
                Self::bug754_global_parameter_snapshot(&reference_plan, &reference_netlist)?;
            if owner_snapshot != reference_snapshot {
                return Err(format!(
                    "BUG 754 effective circuits differ after global-parameter normalization: owner={owner_snapshot:?} reference={reference_snapshot:?}"
                ));
            }

            Ok(XyceBug754GlobalParameterContract {
                owner_plan,
                reference_plan,
                role,
            })
        })())
    }

    fn insert_bug754_family_member_name(
        family_members: &mut BTreeSet<String>,
        name: &str,
    ) -> Result<(), String> {
        let normalized = name.to_ascii_lowercase();
        if !family_members.insert(normalized.clone()) {
            return Err(format!(
                "BUG 754 dcsweep family contains case-colliding physical record '{name}' normalized as '{normalized}'"
            ));
        }
        Ok(())
    }

    fn validate_bug754_source_pair(owner: &str, reference: &str) -> Result<(), String> {
        let statements = |source: &str| {
            Self::logical_netlist_lines(source)
                .into_iter()
                .filter_map(|line| {
                    let statement = Self::strip_netlist_comment(&line).trim();
                    (!statement.is_empty()).then(|| Self::normalize_probe(statement))
                })
                .collect::<Vec<_>>()
        };
        let owner_statements = statements(owner);
        let reference_statements = statements(reference);
        let expected_owner = [
            ".global_paramvgi=0.5",
            ".global_paramvdi=1.0",
            "m1draingatesource0mlev1",
            "vdraindrain0dc{vdi}",
            "vgategate0dc.5",
            "vsourcesource0dc{0}",
            ".dcvdrain010.001",
            ".printdcv(drain)v(gate)i(vdrain)",
            ".modelmlev1nmoslevel=1",
            ".end",
        ];
        let expected_reference = [
            "m1draingatesource0mlev1",
            "vdraindrain0dc1.0",
            "vgategate0dc.5",
            "vsourcesource0dc{0}",
            ".dcvdrain010.001",
            ".printdcv(drain)v(gate)i(vdrain)",
            ".modelmlev1nmoslevel=1",
            ".end",
        ];
        if owner_statements != expected_owner {
            return Err(format!(
                "BUG 754 owner executable statements changed: {owner_statements:?}"
            ));
        }
        if reference_statements != expected_reference {
            return Err(format!(
                "BUG 754 reference executable statements changed: {reference_statements:?}"
            ));
        }
        Ok(())
    }

    fn validate_bug754_member(
        plan: &XyceStaticDcPlan,
        netlist: &Netlist,
        role: XyceBug754GlobalParameterRole,
    ) -> Result<(), String> {
        let requires_wrapper = role == XyceBug754GlobalParameterRole::GlobalParameterOwner;
        let expected_contract = if requires_wrapper {
            XyceStaticDcContract::WrapperDefault
        } else {
            XyceStaticDcContract::PlainStatic
        };
        if Self::static_dc_contract_for_print_format(
            requires_wrapper,
            plan.print_format.as_deref(),
        )? != expected_contract
        {
            return Err(format!(
                "BUG 754 {role:?} does not map to the required {expected_contract:?} contract"
            ));
        }
        if plan.execution_dir.is_some()
            || plan.dc_data.is_some()
            || plan.print_format.is_some()
            || !plan.steps.is_empty()
            || !plan.diagnostics.is_empty()
            || plan.dc.sweep2.is_some()
            || !matches!(plan.dc.mode, crate::netlist::DcSweepMode::Linear)
            || !plan.dc.source.eq_ignore_ascii_case("Vdrain")
            || plan.dc.start.to_bits() != 0.0f64.to_bits()
            || plan.dc.stop.to_bits() != 1.0f64.to_bits()
            || plan.dc.step.to_bits() != 0.001f64.to_bits()
            || plan
                .print
                .probes
                .iter()
                .map(|probe| Self::normalize_probe(probe))
                .ne(["v(drain)", "v(gate)", "i(vdrain)"])
        {
            return Err(format!(
                "BUG 754 member requires one diagnostic-free Vdrain 0:0.001:1 linear DC sweep and ordered default V(drain), V(gate), I(Vdrain) output; actual plan={plan:?}"
            ));
        }
        if netlist.elements.len() != 4
            || netlist.models.len() != 1
            || !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Dc { .. }])
            || !netlist.subcircuits.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(
                "BUG 754 member admits exactly one Level-1 NMOS, three DC sources, one DC analysis, and no auxiliary state"
                    .into(),
            );
        }
        let mut numeric_params = netlist.params.numeric_parameters();
        numeric_params.sort_by(|left, right| {
            left.0
                .to_ascii_lowercase()
                .cmp(&right.0.to_ascii_lowercase())
        });
        match role {
            XyceBug754GlobalParameterRole::GlobalParameterOwner => {
                let expected = [("vdi", 1.0f64.to_bits()), ("vgi", 0.5f64.to_bits())];
                let actual = numeric_params
                    .iter()
                    .map(|(name, value)| (name.to_ascii_lowercase(), value.to_bits()))
                    .collect::<Vec<_>>();
                if actual
                    != expected
                        .into_iter()
                        .map(|(name, bits)| (name.to_string(), bits))
                        .collect::<Vec<_>>()
                {
                    return Err(format!(
                        "BUG 754 owner must retain exactly VDI=1.0 and VGI=0.5 global parameters, got {actual:?}"
                    ));
                }
            }
            XyceBug754GlobalParameterRole::LiteralReference if numeric_params.is_empty() => {}
            XyceBug754GlobalParameterRole::LiteralReference => {
                return Err("BUG 754 literal reference must not declare numeric parameters".into());
            }
        }
        Self::bug754_global_parameter_snapshot(plan, netlist).map(|_| ())
    }

    fn bug754_global_parameter_snapshot(
        plan: &XyceStaticDcPlan,
        netlist: &Netlist,
    ) -> Result<XyceBug754GlobalParameterSnapshot, String> {
        let [model] = netlist.models.as_slice() else {
            return Err("BUG 754 requires exactly one MOS model".into());
        };
        if !model.name.eq_ignore_ascii_case("mlev1")
            || !model.model_type.eq_ignore_ascii_case("nmos")
            || model.params.len() != 1
            || !model.params[0].0.eq_ignore_ascii_case("level")
            || model.params[0].1.to_bits() != 1.0f64.to_bits()
            || !model.expr_params.is_empty()
            || !model.string_params.is_empty()
            || !model.string_vector_params.is_empty()
            || !model.real_vector_params.is_empty()
            || !model.real_vector_expr_params.is_empty()
            || !model.integer_vector_params.is_empty()
        {
            return Err(format!("BUG 754 Level-1 NMOS model changed: {model:?}"));
        }

        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            let name = element.name.to_ascii_lowercase();
            let nodes = element
                .nodes
                .iter()
                .map(|node| node.to_ascii_lowercase())
                .collect::<Vec<_>>();
            let fingerprint = match &element.kind {
                ElementKind::Mosfet {
                    model,
                    mos_type: crate::netlist::MosType::Nmos,
                    compact_syntax: false,
                    instance_params,
                    deferred_params,
                } if model.eq_ignore_ascii_case("mlev1")
                    && instance_params.is_empty()
                    && deferred_params.is_empty()
                    && nodes == ["drain", "gate", "source", "0"] =>
                {
                    XyceRelationalElementFingerprint {
                        kind: "M:NMOS:L1".to_string(),
                        nodes,
                        numeric_bits: Vec::new(),
                        text: vec!["mlev1".to_string()],
                    }
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value))
                    if value.is_finite() =>
                {
                    XyceRelationalElementFingerprint {
                        kind: "V:DC".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                _ => {
                    return Err(format!(
                        "BUG 754 element '{}' is outside the exact Level-1 NMOS/DC-source envelope",
                        element.name
                    ));
                }
            };
            if elements.insert(name.clone(), fingerprint).is_some() {
                return Err(format!("BUG 754 contains duplicate element '{name}'"));
            }
        }
        let expected_elements = BTreeMap::from([
            (
                "m1".to_string(),
                XyceRelationalElementFingerprint {
                    kind: "M:NMOS:L1".to_string(),
                    nodes: vec![
                        "drain".to_string(),
                        "gate".to_string(),
                        "source".to_string(),
                        "0".to_string(),
                    ],
                    numeric_bits: Vec::new(),
                    text: vec!["mlev1".to_string()],
                },
            ),
            (
                "vdrain".to_string(),
                XyceRelationalElementFingerprint {
                    kind: "V:DC".to_string(),
                    nodes: vec!["drain".to_string(), "0".to_string()],
                    numeric_bits: vec![1.0f64.to_bits()],
                    text: Vec::new(),
                },
            ),
            (
                "vgate".to_string(),
                XyceRelationalElementFingerprint {
                    kind: "V:DC".to_string(),
                    nodes: vec!["gate".to_string(), "0".to_string()],
                    numeric_bits: vec![0.5f64.to_bits()],
                    text: Vec::new(),
                },
            ),
            (
                "vsource".to_string(),
                XyceRelationalElementFingerprint {
                    kind: "V:DC".to_string(),
                    nodes: vec!["source".to_string(), "0".to_string()],
                    numeric_bits: vec![0.0f64.to_bits()],
                    text: Vec::new(),
                },
            ),
        ]);
        if elements != expected_elements {
            return Err(format!(
                "BUG 754 canonical Level-1 NMOS/source topology changed: {elements:?}"
            ));
        }
        Ok(XyceBug754GlobalParameterSnapshot {
            elements,
            model_name: model.name.to_ascii_lowercase(),
            model_type: model.model_type.to_ascii_lowercase(),
            model_params: vec![("level".to_string(), 1.0f64.to_bits())],
            dc_source: plan.dc.source.to_ascii_lowercase(),
            dc_start_bits: plan.dc.start.to_bits(),
            dc_stop_bits: plan.dc.stop.to_bits(),
            dc_step_bits: plan.dc.step.to_bits(),
            probes: plan
                .print
                .probes
                .iter()
                .map(|probe| Self::normalize_probe(probe))
                .collect(),
        })
    }

    fn validate_bug667_nodeset_member(
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        role: XyceBug667NodesetRole,
    ) -> Result<(), String> {
        Self::validate_bug667_nodeset_statement_envelope(&plan.source)?;
        let expected_contract = match role {
            XyceBug667NodesetRole::ScopedOwner => XyceStaticTranContract::WrapperStatic,
            XyceBug667NodesetRole::ExplicitHierarchicalReference => {
                XyceStaticTranContract::PlainStatic
            }
        };
        let expected_probes = [
            "V(N15206)",
            "V(N15971)",
            "V(N15554)",
            "V(N15997)",
            "V(N16554)",
            "V(N16997)",
        ];
        if plan.contract != expected_contract
            || plan.output_override
            || plan.timeint_conststep
            || !plan.steps.is_empty()
            || plan.wrapper_tolerance.is_some()
            || plan.comparison_mode != XyceStaticTranComparisonMode::Pointwise
            || plan.print.probes != expected_probes
            || plan.reference_path.is_file()
            || plan.tran.step.to_bits() != 0.0f64.to_bits()
            || plan.tran.stop.to_bits() != 10e-3f64.to_bits()
            || plan.tran.start.is_some()
            || plan.tran.max_step.is_some()
            || plan.tran.uic
        {
            return Err(format!(
                "BUG 667 member requires one ordinary default-PRN '.TRAN 0 10ms' with the exact six ordered probes and no STEP, output override, tolerance, reference artifact, START, MAXSTEP, or UIC state: contract={:?} probes={:?} tran={:?}",
                plan.contract, plan.print.probes, plan.tran
            ));
        }
        if netlist.title.trim() != "*Analysis directives:"
            || netlist.elements.len() != 14
            || netlist.subcircuits.len() != 1
            || !netlist.models.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
            || !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Tran { .. }])
            || !netlist.params.all_params().is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(
                "BUG 667 member admits only the canonical 14-element RC/PULSE harness, one two-element subcircuit, two NODESET hints, and one TRAN analysis"
                    .into(),
            );
        }

        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            let name = element.name.to_ascii_lowercase();
            if elements.insert(name.clone(), element).is_some() {
                return Err(format!(
                    "BUG 667 member contains duplicate element '{name}'"
                ));
            }
        }
        let expected_names = [
            "r_r1", "r_r2", "c_c1", "r_r3", "v_v1", "v_v2", "r_r4", "r_r5", "c_c2", "r_r6", "v_v3",
            "r_r7", "x_x1", "r_r8",
        ]
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
        if elements.keys().cloned().collect::<BTreeSet<_>>() != expected_names {
            return Err(format!(
                "BUG 667 top-level element inventory changed: {:?}",
                elements.keys().collect::<Vec<_>>()
            ));
        }

        for (name, nodes, resistance) in [
            ("r_r1", ["N15206", "N15971"], 1e3),
            ("r_r2", ["N15975", "N15971"], 10.0),
            ("r_r3", ["N16095", "0"], 10.0),
            ("r_r4", ["N15554", "N15997"], 1e3),
            ("r_r5", ["N15967", "N15997"], 10.0),
            ("r_r6", ["N16112", "0"], 10.0),
            ("r_r7", ["N16554", "N16997"], 1e3),
            ("r_r8", ["N17112", "0"], 10.0),
        ] {
            Self::validate_bug667_scalar_resistor(elements[name], nodes, resistance)?;
        }
        for (name, nodes) in [
            ("c_c1", ["N16095", "N15975"]),
            ("c_c2", ["N16112", "N15967"]),
        ] {
            Self::validate_bug667_scalar_capacitor(elements[name], nodes, 1e-6)?;
        }
        for (name, node) in [("v_v1", "N15206"), ("v_v2", "N15554"), ("v_v3", "N16554")] {
            let source = elements[name];
            if source.nodes != [node, "0"]
                || !matches!(
                    source.kind,
                    ElementKind::VoltageSource(crate::netlist::SourceSpec::Pulse {
                        v1,
                        v2,
                        delay,
                        rise,
                        fall,
                        width,
                        period,
                        phase,
                        width_defaults_to_zero: false,
                    }) if v1.to_bits() == 0.0f64.to_bits()
                        && v2.to_bits() == 1.0f64.to_bits()
                        && delay.to_bits() == 0.0f64.to_bits()
                        && rise.to_bits() == 1e-3f64.to_bits()
                        && fall.to_bits() == 1e-3f64.to_bits()
                        && width.to_bits() == 5e-3f64.to_bits()
                        && period.to_bits() == 1.0f64.to_bits()
                        && phase.to_bits() == 0.0f64.to_bits()
                )
            {
                return Err(format!("{name} topology or PULSE waveform changed"));
            }
        }

        let instance = elements["x_x1"];
        let ElementKind::Subcircuit {
            subckt_name,
            params,
        } = &instance.kind
        else {
            return Err("X_X1 is not the canonical subcircuit instance".into());
        };
        if instance.nodes != ["N16997", "N17112"]
            || !subckt_name.eq_ignore_ascii_case("NODESET_Subckt")
        {
            return Err("X_X1 topology or subcircuit binding changed".into());
        }
        match role {
            XyceBug667NodesetRole::ScopedOwner => match params.as_slice() {
                [(name, ParametricValue::Resolved(value))]
                    if name.eq_ignore_ascii_case("vmid") && value.to_bits() == 0.5f64.to_bits() => {
                }
                _ => return Err("owner X_X1 must retain the exact vmid=0.5 override".into()),
            },
            XyceBug667NodesetRole::ExplicitHierarchicalReference if params.is_empty() => {}
            XyceBug667NodesetRole::ExplicitHierarchicalReference => {
                return Err("reference X_X1 must not carry an instance parameter".into());
            }
        }

        let subcircuit = &netlist.subcircuits[0];
        if !subcircuit.name.eq_ignore_ascii_case("NODESET_Subckt")
            || subcircuit.ports.len() != 2
            || !subcircuit.ports[0].eq_ignore_ascii_case("in")
            || !subcircuit.ports[1].eq_ignore_ascii_case("out")
            || subcircuit.elements.len() != 2
            || !subcircuit.initial_conditions.is_empty()
            || !subcircuit.body_params.is_empty()
            || !subcircuit.expr_params.is_empty()
            || !subcircuit.string_params.is_empty()
            || !subcircuit.body_expr_params.is_empty()
            || !subcircuit.body_string_params.is_empty()
            || !subcircuit.body_functions.is_empty()
            || !subcircuit.local_options.is_empty()
            || subcircuit.library_ref.is_some()
            || !subcircuit.nested_subcircuits.is_empty()
        {
            return Err("NODESET_Subckt definition shape or auxiliary state changed".into());
        }
        let sub_resistor = subcircuit
            .elements
            .iter()
            .find(|element| element.name.eq_ignore_ascii_case("R1"))
            .ok_or_else(|| "NODESET_Subckt is missing R1".to_string())?;
        Self::validate_bug667_scalar_resistor(sub_resistor, ["in", "mid"], 10.0)?;
        let sub_capacitor = subcircuit
            .elements
            .iter()
            .find(|element| element.name.eq_ignore_ascii_case("C1"))
            .ok_or_else(|| "NODESET_Subckt is missing C1".to_string())?;
        Self::validate_bug667_scalar_capacitor(sub_capacitor, ["mid", "out"], 1e-6)?;

        match role {
            XyceBug667NodesetRole::ScopedOwner => {
                if subcircuit.params.len() != 1
                    || !subcircuit.params[0].0.eq_ignore_ascii_case("vmid")
                    || subcircuit.params[0].1.to_bits() != 5.0f64.to_bits()
                    || subcircuit.node_sets.len() != 1
                    || !netlist.node_sets.iter().any(|nodeset| {
                        nodeset.node.eq_ignore_ascii_case("N15967")
                            && nodeset.voltage.to_bits() == 0.5f64.to_bits()
                            && nodeset.voltage_expr.is_none()
                    })
                {
                    return Err(
                        "owner must retain vmid=5.0 formal, vmid=0.5 instance override, local V(mid)={vmid}, and common V(N15967)=0.5"
                            .into(),
                    );
                }
                let local = &subcircuit.node_sets[0];
                if !local.node.eq_ignore_ascii_case("mid")
                    || local.voltage.to_bits() != 5.0f64.to_bits()
                    || local
                        .voltage_expr
                        .as_deref()
                        .is_none_or(|expr| !expr.eq_ignore_ascii_case("vmid"))
                    || netlist.node_sets.len() != 1
                {
                    return Err(
                        "owner local NODESET must remain deferred as V(mid)={vmid} before instance-scope flattening"
                            .into(),
                    );
                }
            }
            XyceBug667NodesetRole::ExplicitHierarchicalReference => {
                if !subcircuit.params.is_empty()
                    || !subcircuit.node_sets.is_empty()
                    || netlist.node_sets.len() != 2
                {
                    return Err(
                        "reference subcircuit must have no parameters/local NODESET and exactly two top-level NODESET hints"
                            .into(),
                    );
                }
                let raw = netlist
                    .node_sets
                    .iter()
                    .map(|nodeset| {
                        (
                            nodeset.node.to_ascii_lowercase().replace(':', "."),
                            nodeset.voltage.to_bits(),
                            nodeset.voltage_expr.is_none(),
                        )
                    })
                    .collect::<BTreeSet<_>>();
                if raw
                    != BTreeSet::from([
                        ("n15967".to_string(), 0.5f64.to_bits(), true),
                        ("x_x1.mid".to_string(), 0.5f64.to_bits(), true),
                    ])
                {
                    return Err(format!(
                        "reference raw top-level NODESET representation changed: {raw:?}"
                    ));
                }
            }
        }
        Ok(())
    }

    fn validate_bug667_scalar_resistor(
        element: &crate::netlist::Element,
        nodes: [&str; 2],
        expected: Value,
    ) -> Result<(), String> {
        let ElementKind::Resistor {
            value,
            value_expr: None,
            model: None,
            instance_params,
            deferred_params,
        } = &element.kind
        else {
            return Err(format!(
                "BUG 667 element '{}' is not a scalar resistor",
                element.name
            ));
        };
        if element.nodes.len() != 2
            || !element.nodes[0].eq_ignore_ascii_case(nodes[0])
            || !element.nodes[1].eq_ignore_ascii_case(nodes[1])
            || value.to_bits() != expected.to_bits()
            || !instance_params.is_empty()
            || !deferred_params.is_empty()
        {
            return Err(format!(
                "BUG 667 resistor '{}' topology, value, or parameter state changed",
                element.name
            ));
        }
        Ok(())
    }

    fn validate_bug667_scalar_capacitor(
        element: &crate::netlist::Element,
        nodes: [&str; 2],
        expected: Value,
    ) -> Result<(), String> {
        let ElementKind::Capacitor {
            value,
            value_expr: None,
            initial_voltage: None,
            model: None,
            instance_params,
            deferred_params,
        } = &element.kind
        else {
            return Err(format!(
                "BUG 667 element '{}' is not a scalar capacitor",
                element.name
            ));
        };
        if element.nodes.len() != 2
            || !element.nodes[0].eq_ignore_ascii_case(nodes[0])
            || !element.nodes[1].eq_ignore_ascii_case(nodes[1])
            || value.to_bits() != expected.to_bits()
            || !instance_params.is_empty()
            || !deferred_params.is_empty()
        {
            return Err(format!(
                "BUG 667 capacitor '{}' topology, value, or parameter state changed",
                element.name
            ));
        }
        Ok(())
    }

    fn bug667_effective_nodeset_map(netlist: &Netlist) -> Result<BTreeMap<String, u64>, String> {
        let flattened = crate::netlist::flatten_netlist_with_models(netlist)
            .map_err(|err| format!("BUG 667 hierarchy flattening failed: {err}"))?;
        let mut nodesets = BTreeMap::new();
        for nodeset in netlist
            .node_sets
            .iter()
            .chain(flattened.scoped_node_sets.iter())
        {
            if !nodeset.voltage.is_finite() || nodeset.voltage_expr.is_some() {
                return Err(format!(
                    "BUG 667 effective NODESET '{}' is nonfinite or remains deferred",
                    nodeset.node
                ));
            }
            let node = if nodeset.node.contains([':', '.']) {
                Engine::resolve_hierarchical_node_name(netlist, &nodeset.node).ok_or_else(|| {
                    format!(
                        "BUG 667 hierarchical NODESET target '{}' does not resolve through the parsed instance tree",
                        nodeset.node
                    )
                })?
            } else {
                nodeset.node.clone()
            }
            .replace(':', ".")
            .to_ascii_lowercase();
            if nodesets
                .insert(node.clone(), nodeset.voltage.to_bits())
                .is_some()
            {
                return Err(format!(
                    "BUG 667 effective NODESET map contains duplicate node '{node}'"
                ));
            }
        }
        Ok(nodesets)
    }

    fn validate_bug667_nodeset_statement_envelope(source: &str) -> Result<(), String> {
        let body = source.split_once('\n').map_or("", |(_, body)| body);
        let mut counts = BTreeMap::<String, usize>::new();
        for line in Self::logical_netlist_lines(body) {
            let statement = Self::strip_netlist_comment(&line).trim();
            if statement.is_empty() {
                continue;
            }
            let head = statement
                .split_ascii_whitespace()
                .next()
                .unwrap_or_default()
                .to_ascii_lowercase();
            let key = if head.starts_with('.') {
                match head.as_str() {
                    ".tran" | ".print" | ".nodeset" | ".subckt" | ".ends" | ".end" => head,
                    _ => return Err(format!("unrelated directive '{head}' in BUG 667 pair")),
                }
            } else {
                match head.as_bytes().first().map(u8::to_ascii_lowercase) {
                    Some(b'r') => "r".to_string(),
                    Some(b'c') => "c".to_string(),
                    Some(b'v') => "v".to_string(),
                    Some(b'x') => "x".to_string(),
                    _ => return Err(format!("unrelated element '{head}' in BUG 667 pair")),
                }
            };
            *counts.entry(key).or_default() += 1;
        }
        for (key, expected) in [
            ("r", 9),
            ("c", 3),
            ("v", 3),
            ("x", 1),
            (".tran", 1),
            (".print", 1),
            (".nodeset", 2),
            (".subckt", 1),
            (".ends", 1),
            (".end", 1),
        ] {
            if counts.remove(key) != Some(expected) {
                return Err(format!(
                    "BUG 667 statement count for '{key}' must be {expected}"
                ));
            }
        }
        if !counts.is_empty() {
            return Err(format!("BUG 667 source has extra statements: {counts:?}"));
        }
        Ok(())
    }

    fn validate_bug655_continuation_source_pair(
        owner_source: &str,
        reference_source: &str,
    ) -> Result<(), String> {
        let normalize = |source: &str, role: &str| {
            if !source.is_ascii() {
                return Err(format!("BUG 655 {role} source must be ASCII"));
            }
            let normalized = source.replace("\r\n", "\n");
            if normalized.contains('\r') {
                return Err(format!(
                    "BUG 655 {role} source contains a noncanonical bare carriage return"
                ));
            }
            Ok(normalized)
        };
        let owner = normalize(owner_source, "owner")?;
        let reference = normalize(reference_source, "reference")?;
        if owner != XYCE_BUG655_CANONICAL_OWNER_SOURCE {
            return Err("BUG 655 owner source is not the canonical continuation deck".into());
        }
        let mut expected_reference_lines = XYCE_BUG655_CANONICAL_OWNER_SOURCE
            .lines()
            .map(str::to_string)
            .collect::<Vec<_>>();
        for (line_index, spaces) in [(11usize, 2usize), (13, 1), (14, 3)] {
            expected_reference_lines[line_index] = format!(
                "{}{}",
                " ".repeat(spaces),
                expected_reference_lines[line_index]
            );
        }
        let expected_reference = format!("{}\n", expected_reference_lines.join("\n"));
        if reference != expected_reference {
            return Err(
                "BUG 655 reference source is not the canonical 2/1/3-space continuation variant"
                    .into(),
            );
        }

        let owner_lines = owner.lines().collect::<Vec<_>>();
        let reference_lines = reference.lines().collect::<Vec<_>>();
        if owner_lines.len() != 21 || reference_lines.len() != 21 {
            return Err(format!(
                "BUG 655 siblings must each contain exactly 21 physical lines, got owner={} reference={}",
                owner_lines.len(),
                reference_lines.len()
            ));
        }
        for line_index in 0..21 {
            if matches!(line_index, 11 | 13 | 14) {
                let expected_spaces = match line_index {
                    11 => 2,
                    13 => 1,
                    14 => 3,
                    _ => unreachable!(),
                };
                if !owner_lines[line_index].starts_with('+')
                    || reference_lines[line_index]
                        .len()
                        .saturating_sub(reference_lines[line_index].trim_start().len())
                        != expected_spaces
                    || reference_lines[line_index].trim_start() != owner_lines[line_index]
                {
                    return Err(format!(
                        "BUG 655 line {} does not preserve the exact leading-whitespace-only continuation difference",
                        line_index + 1
                    ));
                }
            } else if owner_lines[line_index] != reference_lines[line_index] {
                return Err(format!(
                    "BUG 655 siblings differ outside continuation lines 12, 14, and 15 at physical line {}",
                    line_index + 1
                ));
            }
        }
        Ok(())
    }

    fn validate_bug655_continuation_member(
        plan: &XyceStaticDcPlan,
        netlist: &Netlist,
        role: XyceBug655ContinuationRole,
    ) -> Result<(), String> {
        let requires_wrapper = role == XyceBug655ContinuationRole::ColumnZeroOwner;
        let expected_contract = if requires_wrapper {
            XyceStaticDcContract::WrapperDefault
        } else {
            XyceStaticDcContract::PlainStatic
        };
        if Self::static_dc_contract_for_print_format(
            requires_wrapper,
            plan.print_format.as_deref(),
        )? != expected_contract
        {
            return Err(format!(
                "BUG 655 {role:?} does not map to the required {expected_contract:?} DC contract"
            ));
        }
        if plan.execution_dir.is_some()
            || plan.dc_data.is_some()
            || plan.print_format.is_some()
            || !plan.steps.is_empty()
            || !plan.diagnostics.is_empty()
            || plan.dc.sweep2.is_some()
            || !matches!(plan.dc.mode, crate::netlist::DcSweepMode::Linear)
            || !plan.dc.source.eq_ignore_ascii_case("I1")
            || plan.dc.start.to_bits() != (-100.0f64 * 1.0e-6).to_bits()
            || plan.dc.stop.to_bits() != (100.0f64 * 1.0e-6).to_bits()
            || plan.dc.step.to_bits() != (10.0f64 * 1.0e-6).to_bits()
            || plan
                .print
                .probes
                .iter()
                .map(|probe| Self::normalize_probe(probe))
                .ne(["i(i1)", "v(3)"])
        {
            return Err(format!(
                "BUG 655 member requires one diagnostic-free I1 -100u:10u:100u DC sweep and ordered default I(I1), V(3) output; actual execution_dir={:?} dc_data={} format={:?} steps={} diagnostics={:?} source={} mode={:?} start={} stop={} step={} sweep2={} probes={:?}",
                plan.execution_dir,
                plan.dc_data.is_some(),
                plan.print_format,
                plan.steps.len(),
                plan.diagnostics,
                plan.dc.source,
                plan.dc.mode,
                plan.dc.start,
                plan.dc.stop,
                plan.dc.step,
                plan.dc.sweep2.is_some(),
                plan.print.probes
            ));
        }
        if netlist.analyses.len() != 1
            || !matches!(netlist.analyses[0], AnalysisCommand::Dc { .. })
            || netlist.elements.len() != 5
            || netlist.models.len() != 1
            || !netlist.subcircuits.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
            || !netlist.params.all_params().is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(
                "BUG 655 member admits exactly VCC, I1, R1, R2, Q1, one NPN model, and one DC analysis"
                    .into(),
            );
        }
        let actual = Self::bug655_continuation_snapshot(netlist)?;
        let expected = Self::bug655_expected_continuation_snapshot();
        if actual != expected {
            return Err(format!(
                "BUG 655 canonical circuit/model fingerprint changed: actual={actual:?}"
            ));
        }
        Ok(())
    }

    fn validate_bug655_continuation_semantic_identity(
        owner: &Netlist,
        reference: &Netlist,
    ) -> Result<(), String> {
        let owner = Self::bug655_continuation_snapshot(owner)?;
        let reference = Self::bug655_continuation_snapshot(reference)?;
        if owner != reference {
            return Err(format!(
                "BUG 655 continuation parsing produced different logical circuits: owner={owner:?} reference={reference:?}"
            ));
        }
        Ok(())
    }

